INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('2ca80f97-1cc7-5326-a5d5-2c17b99547e2'::uuid, 1, 'redaction', $exo${"titre":"La Princesse de Clèves : l'essentiel","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Donne l'autrice, la date et les conditions de publication de *La Princesse de Clèves*.\n2. Où et quand se déroule l'action ? Pourquoi peut-on dire que la cour n'est pas un simple décor ?\n3. Résume la **scène de l'aveu** : qui avoue quoi, à qui, et qui en est témoin ?\n4. Que décide la princesse à la fin du roman, et pour quelles **deux raisons** ?","bareme":[{"critere":"Autrice, date 1678 et publication anonyme","points":4},{"critere":"Cour d'Henri II en 1558-1559, présentée comme un système d'observation et de calcul","points":5},{"critere":"Aveu au mari d'un amour pour un autre homme, sans le nommer, entendu par Nemours caché","points":6},{"critere":"Refus d'épouser Nemours ; devoir envers le mort et certitude que la passion ne durerait pas","points":5}],"dureeMin":7,"corrige":"1. Le roman est de **Marie-Madeleine de Lafayette** ; il paraît **anonymement** en **1678**. C'est le premier grand roman d'analyse français.\n2. L'action se déroule à la **cour d'Henri II**, en **1558-1559**, reconstituée avec une précision d'historienne (bals, tournois, mariages politiques). La cour n'est pas un décor mais un **système** : on y est **observé en permanence**, on y calcule, on y ment.\n3. La princesse **avoue à son mari**, le prince de Clèves, qu'elle **aime un autre homme**, **sans le nommer**, et lui demande de quitter la cour. Le **duc de Nemours**, **caché**, entend toute la scène.\n4. Devenue libre après la mort de son mari, elle **refuse d'épouser Nemours** et se retire entre un couvent et sa maison. Deux raisons : le **devoir envers le mort** et la **certitude que la passion de Nemours ne durerait pas**."}$exo$::jsonb),
  ('2ca80f97-1cc7-5326-a5d5-2c17b99547e2'::uuid, 2, 'redaction', $exo${"titre":"Un roman qui regarde à l'intérieur","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en t'appuyant sur le cours.","enonce":"**Texte (inventé pour l'exercice, écrit à la manière du roman d'analyse)**\n\n> Elle rougit en le voyant entrer, et cette rougeur, qu'elle ne put cacher, lui fit une peine extrême. Elle se reprocha de n'avoir pas su se rendre maîtresse de son visage ; elle craignit que tout le monde n'eût remarqué son trouble, et elle résolut de ne plus paraître aux lieux où il pourrait se trouver. Mais cette résolution même lui fit sentir combien elle souhaitait de l'y voir.\n\n1. Relève **deux indices** qui montrent que ce passage s'intéresse aux **mouvements intérieurs** plutôt qu'à l'action extérieure.\n2. Quel rôle joue le **regard des autres** dans ce passage ? Relie ta réponse à la manière dont le cours présente la cour.\n3. Caractérise le **style** du passage (phrase, vocabulaire) et nomme le mouvement esthétique auquel il se rattache.","bareme":[{"critere":"Deux indices précis de l'analyse intérieure (rougeur, reproche, crainte, résolution contradictoire)","points":7},{"critere":"La peur d'être remarquée reliée à la cour comme lieu d'observation permanente","points":6},{"critere":"Style sobre, phrase claire, vocabulaire restreint : le classicisme","points":5},{"critere":"Réponses rédigées et appuyées sur le texte","points":2}],"dureeMin":11,"corrige":"1. Il ne se passe presque rien : un homme entre dans une pièce. Tout le reste est intérieur : la **rougeur** involontaire (« qu'elle ne put cacher »), le **reproche** qu'elle se fait (« n'avoir pas su se rendre maîtresse de son visage »), la **crainte**, puis une **résolution** qui se retourne contre elle (« cette résolution même lui fit sentir combien elle souhaitait de l'y voir »). Le narrateur entre dans la conscience et **analyse** — hésitations, rougeurs, calculs : c'est la nouveauté du roman.\n2. Elle craint « que tout le monde n'eût remarqué son trouble » : le moindre signe du corps peut la trahir. C'est la cour du roman : un **système** où l'on est **observé en permanence**, où chacun calcule. La passion y est dangereuse parce qu'elle se voit.\n3. Les phrases sont **claires**, construites, sans image ni ornement ; le vocabulaire est **restreint** et abstrait (peine, trouble, résolution). C'est le **classicisme**, qui juge que la vérité se dit sans ornement."}$exo$::jsonb),
  ('2ca80f97-1cc7-5326-a5d5-2c17b99547e2'::uuid, 3, 'redaction', $exo${"titre":"Le refus de la princesse : vertu ou liberté ?","consigne":"Rédige un paragraphe argumenté puis un plan de dissertation, en t'appuyant précisément sur l'œuvre telle que le cours la présente.","enonce":"**Sujet** : « Le refus final de la princesse de Clèves est-il seulement un acte de vertu ? »\n\n1. Rappelle en une phrase la situation de la princesse au moment où elle refuse Nemours et les deux raisons qu'elle donne.\n2. Présente les **quatre lectures possibles** de ce refus retenues par le cours, en expliquant brièvement chacune.\n3. Propose un **plan de dissertation en deux ou trois parties** répondant au sujet (une phrase-titre par partie, un argument et un élément de l'œuvre par partie).\n4. Explique en quelques lignes pourquoi le fait que le texte « laisse les lectures ouvertes » est une force du roman, et rappelle comment le public de 1678 a réagi.","bareme":[{"critere":"Situation exacte : princesse veuve et libre, devoir envers le mort, passion jugée passagère","points":3},{"critere":"Les quatre lectures (orgueil, sagesse, peur, liberté) nommées et expliquées","points":6},{"critere":"Plan cohérent qui discute la notion de vertu, avec arguments et appuis dans l'œuvre","points":7},{"critere":"Ambiguïté présentée comme une force ; scandale dès 1678","points":4}],"dureeMin":18,"corrige":"1. Après la mort de son mari, rongé par la jalousie, la princesse est **libre** d'épouser Nemours ; elle refuse au nom du **devoir envers le mort** et de la **certitude que la passion de Nemours ne durerait pas**.\n2. Quatre lectures :\n- **l'orgueil** : elle ne veut pas être un jour quittée ;\n- **la sagesse** : elle connaît la nature du désir, qui s'use ;\n- **la peur** : du monde et de la cour, où tout se voit et se juge ;\n- **la liberté** : elle choisit de ne dépendre de personne.\n3. Plan possible :\n- **I. Un refus qui a toutes les apparences de la vertu** : fidélité au mari mort, qui est mort en la croyant coupable ; écho à l'avertissement de sa mère mourante contre la passion.\n- **II. Mais un refus qui calcule aussi** : la raison du « devoir » se double d'une lucidité sur le désir (sagesse) et d'une crainte d'être abandonnée (orgueil) ; la cour, système d'observation, rend la passion dangereuse (peur).\n- **III. Un choix de liberté** : en se retirant entre un couvent et sa maison, elle refuse de dépendre d'un homme ; le roman d'analyse montre une conscience qui décide pour elle-même.\n(Un plan en deux parties bien argumenté est accepté.)\n4. Le texte **ne tranche pas** : il laisse les quatre lectures ouvertes. C'est ce qui oblige le lecteur à interpréter et fait du refus l'un des sujets de dissertation les plus fréquents. Le roman a d'ailleurs **fait scandale dès 1678** : l'aveu et le refus déconcertaient les lecteurs."}$exo$::jsonb),
  ('c214824b-08e1-5fba-b106-ad1746c0b16d'::uuid, 1, 'redaction', $exo${"titre":"Le Rouge et le Noir : repères","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne l'auteur, la date de parution et le sous-titre du roman. Quel événement a lieu la même année ?\n2. Que désignent le **rouge** et le **noir** du titre ? Pourquoi dit-on que Julien est « né trop tard » ?\n3. Cite les **deux lieux** principaux du livre premier et le lieu du livre second.\n4. Comment le roman se termine-t-il pour Julien ?","bareme":[{"critere":"Stendhal, 1830, « Chronique de 1830 », révolution de Juillet","points":5},{"critere":"Rouge = uniforme militaire de l'Empire, noir = soutane de la Restauration ; officier sous Napoléon, séminariste","points":6},{"critere":"Verrières et le séminaire de Besançon ; Paris chez le marquis de La Mole","points":4},{"critere":"Procès où il accuse la société, puis exécution par la guillotine","points":5}],"dureeMin":7,"corrige":"1. Le roman est de **Stendhal**, publié en **1830**, sous-titré « **Chronique de 1830** » ; il paraît l'année même de la **révolution de Juillet**.\n2. Le **rouge** est l'**uniforme militaire**, la carrière possible sous l'**Empire** ; le **noir** est la **soutane**, la carrière possible sous la **Restauration**. Julien est « né trop tard » : il aurait été **officier sous Napoléon**, il sera **séminariste**.\n3. Livre premier : **Verrières** (chez M. de Rênal, le maire) puis le **séminaire de Besançon**. Livre second : **Paris**, chez le **marquis de La Mole**.\n4. Après avoir tiré sur Madame de Rênal pendant la messe, Julien est emprisonné ; il **refuse de se défendre** et, devant le jury, **accuse la société** de condamner en lui un paysan qui a osé sortir de sa classe. Il est **guillotiné** ; Mathilde ensevelit sa tête."}$exo$::jsonb),
  ('c214824b-08e1-5fba-b106-ad1746c0b16d'::uuid, 2, 'redaction', $exo${"titre":"De la réussite à la chute","consigne":"Réponds en rédigeant, en t'appuyant sur les étapes de l'intrigue vues en cours.","enonce":"Voici, dans le désordre, cinq étapes du livre second :\n\n- a. Julien tire sur Madame de Rênal pendant la messe.\n- b. Julien devient secrétaire du marquis de La Mole.\n- c. Une lettre de Madame de Rênal, dictée par son confesseur, le dénonce.\n- d. Mathilde, enceinte, obtient pour Julien un titre et un régiment.\n- e. Julien et Mathilde vivent une relation qui est un duel d'amour-propre.\n\n1. Remets ces étapes dans l'ordre.\n2. Montre en quelques lignes que l'étape **d** est le sommet de l'ascension de Julien, en lien avec le titre du roman.\n3. Explique pourquoi la lettre (étape **c**) provoque l'effondrement : que retire-t-elle à Julien ?\n4. Compare l'amour de Mathilde et celui de Madame de Rênal en une ou deux phrases.","bareme":[{"critere":"Ordre exact : b, e, d, c, a","points":4},{"critere":"Titre et régiment : Julien obtient enfin le « rouge », la carrière qu'il rêvait","points":5},{"critere":"La lettre lui retire la place qu'il avait arrachée : mariage et carrière perdus","points":6},{"critere":"Mathilde : orgueil et romanesque ; Madame de Rênal : amour réel et sincère","points":5}],"dureeMin":10,"corrige":"1. Ordre : **b** (secrétaire du marquis) → **e** (duel d'amour-propre avec Mathilde) → **d** (titre et régiment) → **c** (la lettre) → **a** (le coup de feu à Verrières).\n2. Grâce à Mathilde, enceinte, le marquis donne à Julien un **titre** et un **régiment** : le fils de charpentier de Verrières, méprisé par son père, accède à la noblesse et à l'**uniforme militaire**, le « rouge » du titre, qu'il croyait réservé à l'époque de Napoléon. C'est le sommet de son ascension.\n3. La lettre de Madame de Rênal, **dictée par son confesseur**, le dénonce : le mariage et la carrière s'écroulent d'un coup. Julien perd **la place qu'il avait arrachée** à une société qui méprise les talents sans naissance ; c'est ce qui le pousse à retourner à Verrières et à tirer sur elle.\n4. **Mathilde** aime par **orgueil** et par goût du romanesque : leur relation est un duel. **Madame de Rênal** aime Julien réellement, et Julien l'aime aussi : il l'avait d'abord séduite par ambition, mais l'amour est devenu sincère. Elles ne l'aiment donc pas de la même façon."}$exo$::jsonb),
  ('c214824b-08e1-5fba-b106-ad1746c0b16d'::uuid, 3, 'redaction', $exo${"titre":"« Un miroir qu'on promène le long d'un chemin »","consigne":"Réponds aux questions puis rédige un paragraphe argumenté d'une quinzaine de lignes.","enonce":"Une formule célèbre, placée par Stendhal en épigraphe d'un chapitre du roman (il l'attribue à Saint-Réal), compare le roman à « un miroir qu'on promène le long d'un chemin ».\n\n1. Explique cette définition avec tes mots : que doit faire le roman selon elle ?\n2. Montre, à l'aide du **sous-titre** et du **titre**, que *Le Rouge et le Noir* peint une époque précise.\n3. Le cours présente trois apports du roman : le **héros ambitieux**, l'**ironie** stendhalienne, la **focalisation interne serrée**. Explique chacun en une phrase.\n4. **Paragraphe argumenté** : « *Le Rouge et le Noir* n'est-il qu'un miroir de son époque ? » Réponds en mobilisant au moins deux des trois apports et des éléments précis de l'intrigue.","bareme":[{"critere":"Définition expliquée : le roman reflète la réalité qu'il traverse","points":3},{"critere":"« Chronique de 1830 » et carrières de l'Empire et de la Restauration analysées","points":4},{"critere":"Les trois apports expliqués correctement","points":5},{"critere":"Paragraphe nuancé : miroir de l'époque, mais aussi regard ironique et conscience d'un personnage","points":6},{"critere":"Expression claire et exemples précis de l'œuvre","points":2}],"dureeMin":18,"corrige":"1. Le roman doit **refléter** la réalité : comme un miroir qu'on transporte, il montre ce qu'il rencontre sur son chemin, la société telle qu'elle est.\n2. Le sous-titre, « **Chronique de 1830** », annonce un récit de l'actualité ; le roman paraît l'année de la révolution de Juillet. Le titre oppose les deux voies d'ascension : le **rouge** de l'armée sous l'**Empire**, le **noir** de la soutane sous la **Restauration**. Le roman montre la province de Verrières, le séminaire de Besançon, le Paris du marquis de La Mole : une société où l'Église et la naissance décident.\n3. **Héros ambitieux** : Julien, fils de charpentier qui veut s'élever, devient le modèle de tout le XIXe siècle. **Ironie** : le narrateur garde une distance et commente. **Focalisation interne serrée** : le lecteur suit de près les **calculs** du personnage.\n4. Paragraphe attendu (exemple) : Le roman est bien un miroir de son temps : il peint la Restauration, où un fils de charpentier ne peut monter qu'en entrant au séminaire ou en séduisant une fille de marquis, et le procès final, où Julien accuse la société de condamner un paysan sorti de sa classe, en fait une chronique sociale. Mais le miroir n'est pas neutre. L'**ironie** du narrateur, qui garde ses distances, transforme le reflet en jugement. Surtout, la **focalisation interne** nous fait vivre de l'intérieur les calculs, l'orgueil et l'amour de Julien : le roman ne montre pas seulement une époque, il montre une conscience aux prises avec elle, jusqu'au geste de Verrières. *Le Rouge et le Noir* est donc un miroir, mais un miroir tenu par un regard et tourné aussi vers l'intérieur d'un personnage."}$exo$::jsonb),
  ('64bb365c-d4df-5458-8f9b-f559ca493f9a'::uuid, 1, 'redaction', $exo${"titre":"Les outils du vers","consigne":"Réponds à chaque question par une ou deux phrases complètes, avec le vocabulaire exact du cours.","enonce":"1. Combien de syllabes comptent un **octosyllabe**, un **décasyllabe** et un **alexandrin** ?\n2. Qu’est-ce que la **césure** ? Comment appelle-t-on les deux moitiés d’un alexandrin qu’elle sépare ?\n3. Qu’est-ce qu’un **enjambement** ? Pourquoi le cours dit-il qu’il « fait sens » ?\n4. Nomme la disposition des rimes dans ces trois schémas : **AABB**, **ABAB**, **ABBA**.\n5. Donne la structure d’un **sonnet**.","bareme":[{"critere":"Les trois mètres justes (8, 10, 12) ; césure et hémistiches définis","points":7},{"critere":"Enjambement défini ; idée que la rupture entre vers et phrase produit un effet de sens","points":5},{"critere":"Rimes plates, croisées, embrassées bien attribuées ; sonnet : deux quatrains, deux tercets","points":8}],"dureeMin":7,"corrige":"1. L’octosyllabe compte **8** syllabes, le décasyllabe **10**, l’alexandrin **12**.\n2. La **césure** est la coupe qui sépare l’alexandrin en deux moitiés, les **hémistiches** (le plus souvent 6 + 6).\n3. Il y a **enjambement** quand la phrase se poursuit au vers suivant sans pause : la phrase et le vers ne coïncident plus (le rejet et le contre-rejet sont d’autres formes de cette rupture). Cette rupture **fait sens** : elle met en relief un mot, crée une surprise ou une accélération ; ce n’est jamais un accident métrique.\n4. AABB = rimes **plates** (ou suivies) ; ABAB = rimes **croisées** ; ABBA = rimes **embrassées**.\n5. Le sonnet se compose de **deux quatrains puis deux tercets** (14 vers) ; c’est la forme reine du XIXe siècle."}$exo$::jsonb),
  ('64bb365c-d4df-5458-8f9b-f559ca493f9a'::uuid, 2, 'redaction', $exo${"titre":"Scander un quatrain et en tirer du sens","consigne":"Lis le quatrain (texte écrit pour l’exercice, il n’est d’aucun poète réel), puis réponds en justifiant chaque réponse.","enonce":"> Le vent du soir s’endort sur la colline grise,\n> Et la lampe, au lointain, tremble comme une étoile ;\n> Et mon cœur, attentif au silence, dévoile\n> Le secret que le jour cachait à chaque brise.\n\n1. Scande le vers 1 : compte ses syllabes en appliquant la règle du **e muet** au mot « colline » et à la fin du vers, et place la **césure**.\n2. Quelle est la **disposition des rimes** du quatrain ?\n3. Relève l’**enjambement** du texte et explique son effet.\n4. Nomme **deux figures de style** (vers 1 et vers 2) et donne pour chacune un **effet** et une **interprétation**.","bareme":[{"critere":"Vers 1 scandé : 12 syllabes, e muet de « colline » compté, e final non compté, césure après « s’endort »","points":5},{"critere":"Rimes embrassées ABBA identifiées (grise/brise, étoile/dévoile)","points":4},{"critere":"Enjambement des vers 3-4 relevé et effet expliqué (le « secret » mis en attente puis en relief)","points":5},{"critere":"Personnification (v. 1) et comparaison (v. 2) nommées, chacune avec un effet et une interprétation","points":6}],"dureeMin":11,"corrige":"1. Le / vent / du / soir / s’en / dort // sur / la / col / li / ne / gri(se) : **12 syllabes**, c’est un **alexandrin**. Le e de « colline » est suivi d’une consonne (« grise ») : il **compte**. Le e final de « grise », en fin de vers, **ne compte pas**. La **césure** tombe après la 6e syllabe, « s’endort » : deux hémistiches de 6.\n2. grise (A) / étoile (B) / dévoile (B) / brise (A) : rimes **embrassées** ABBA.\n3. Enjambement entre les vers 3 et 4 : « dévoile / Le secret… ». Le complément du verbe est rejeté au vers suivant : la phrase ne s’arrête pas avec le vers, le lecteur attend ce qui est dévoilé ; « Le secret » arrive en tête du vers 4 et se trouve **mis en relief**. La rupture mime l’idée d’un dévoilement progressif.\n4. Vers 1 : **personnification** (« Le vent du soir s’endort ») : le vent reçoit une action humaine ; effet d’apaisement, la nature semble vivante et accordée au soir. Vers 2 : **comparaison** avec l’outil « comme » (« la lampe… tremble comme une étoile ») : la lumière humaine rejoint le ciel ; interprétation : le petit et le grand, l’intime et le cosmos se répondent. Toute figure doit être suivie de son effet : **nommer ne suffit jamais**."}$exo$::jsonb),
  ('64bb365c-d4df-5458-8f9b-f559ca493f9a'::uuid, 3, 'redaction', $exo${"titre":"Une forme qui se libère sans cesser d’être travaillée","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en t’appuyant uniquement sur les connaissances du cours.","enonce":"**Sujet.** « Le vers libre abandonne le mètre, jamais le rythme. »\n\nEn t’appuyant sur les **trois moments** de la poésie du XIXe au XXIe siècle et sur l’évolution des **formes** (sonnet, poème en prose, vers libre), montre comment la poésie se libère des règles sans cesser d’être un travail sur le langage.\n\nTu expliqueras aussi pourquoi, à l’oral comme à l’écrit, repérer une forme ou une figure ne suffit pas.","bareme":[{"critere":"Les trois moments situés avec leurs auteurs (romantisme, symbolisme et modernité, XXe-XXIe) et ce que devient le poète","points":6},{"critere":"Les trois formes présentées et datées (sonnet, poème en prose de Baudelaire et Rimbaud, vers libre d’Apollinaire)","points":5},{"critere":"Explication de la citation : sans mètre, le rythme demeure ; la rupture fait sens","points":5},{"critere":"Copie organisée, avec une conclusion qui répond au sujet et rappelle qu’une forme repérée appelle un effet","points":4}],"dureeMin":18,"corrige":"**Introduction** : la poésie du XIXe au XXIe siècle semble abandonner peu à peu les règles (mètre, rime, forme fixe). La formule du sujet invite à nuancer : la liberté n’est pas l’absence de travail.\n\n**I. Des règles fortes au XIXe siècle.** Le **sonnet** (deux quatrains, deux tercets) est la forme reine du siècle ; l’**alexandrin** (12 syllabes, césure entre deux hémistiches) domine. Le **romantisme** (Hugo, Lamartine) fait du poète une **conscience** qui dit le moi et le monde, sans renverser ces cadres.\n\n**II. La libération des formes.** Avec le **symbolisme et la modernité** (Baudelaire, Rimbaud, Mallarmé), le poème devient une **expérience de langage**, non un message. Le **poème en prose** (Baudelaire, Rimbaud) renonce au vers ; le **vers libre** (Apollinaire, puis tout le XXe) renonce au mètre. Aux **XXe et XXIe siècles**, le poème se fait **atelier** (Ponge), cri, ou traversée intime du monde naturel (Dorion).\n\n**III. Mais le travail demeure.** Le vers libre abandonne le mètre, **jamais le rythme** : répétitions, anaphores, coupes, blancs continuent de structurer la voix. Même dans les formes régulières, l’enjambement, le rejet, le contre-rejet brisent la coïncidence vers/phrase, et cette rupture **fait sens**. C’est pourquoi **nommer ne suffit jamais** : une forme ou une figure repérée doit être suivie d’un **effet** et d’une **interprétation**.\n\n**Conclusion** : la poésie se libère des contraintes héritées mais reste un travail précis du langage ; le rythme remplace le mètre. À l’oral, cela impose de **suivre le mouvement du texte** du premier au dernier vers."}$exo$::jsonb),
  ('41813cdd-0691-5f2e-a3ec-b78150d1191c'::uuid, 1, 'redaction', $exo${"titre":"Ce que sont les Cahiers de Douai","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Pourquoi dit-on que les *Cahiers de Douai* ne sont **pas un recueil composé par l’auteur** ? Donne le nombre de poèmes, l’âge de Rimbaud, le lieu, l’année et le nom de l’ami chez qui il les recopie.\n2. Quel est le **parcours associé** à l’œuvre ?\n3. Le cours distingue **trois veines** dans le recueil. Nomme-les et donne pour chacune le titre d’un poème.\n4. Quel **événement historique** traverse le recueil ?","bareme":[{"critere":"Origine du recueil : 22 poèmes recopiés, 15-16 ans, Douai, 1870, Paul Demeny, titre posthume","points":8},{"critere":"Parcours « émancipations créatrices » et contexte de la guerre franco-prussienne","points":4},{"critere":"Les trois veines nommées, chacune avec un poème juste","points":8}],"dureeMin":7,"corrige":"1. Ce sont **vingt-deux poèmes recopiés à la main** par Rimbaud, âgé de **quinze et seize ans**, chez son ami **Paul Demeny**, à **Douai**, en **1870**, en **deux liasses**. Le titre est **posthume** (on dit aussi « recueil Demeny ») : l’auteur n’a pas composé de livre, d’où l’absence de progression narrative. Ce sont des **textes de fugue**.\n2. Le parcours est **« émancipations créatrices »**.\n3. La veine de la **fugue et de la sensation** (« Sensation », « Ma Bohème », « Au Cabaret-Vert », « Roman ») ; la veine de la **satire politique et sociale** (« Le Forgeron », « Rages de Césars », « Le Mal », « Le Dormeur du val ») ; la veine de la **provocation et du corps** (« Vénus Anadyomène », « Les Reparties de Nina », « À la Musique »). Un titre juste par veine suffit.\n4. La **guerre franco-prussienne** de 1870 et la chute du Second Empire."}$exo$::jsonb),
  ('41813cdd-0691-5f2e-a3ec-b78150d1191c'::uuid, 2, 'redaction', $exo${"titre":"Le vagabond de « Ma Bohème »","consigne":"Lis le premier quatrain du sonnet « Ma Bohème » et réponds en citant le texte.","enonce":"> Je m’en allais, les poings dans mes poches crevées ;\n> Mon paletot aussi devenait idéal ;\n> J’allais sous le ciel, Muse ! et j’étais ton féal ;\n> Oh ! là ! là ! que d’amours splendides j’ai rêvées !\n\n*(« féal » : fidèle, dévoué comme un vassal à son seigneur ; « paletot » : manteau.)*\n\n1. À quelle **veine** du recueil ce poème appartient-il ? Justifie par deux indices.\n2. Relève deux **ruptures de registre** : des mots familiers placés dans un moule noble. Quel est ce moule ?\n3. En quoi ce quatrain illustre-t-il le parcours **« émancipations créatrices »** ?","bareme":[{"critere":"Veine de la fugue et de la sensation, justifiée par deux indices (marche, errance, sous le ciel)","points":5},{"critere":"Deux mots ou expressions familiers relevés et le moule noble identifié (alexandrins d’un sonnet, adresse à la Muse)","points":7},{"critere":"Lien argumenté avec l’émancipation de l’adolescent et du poète","points":5},{"critere":"Citations exactes et intégrées aux phrases","points":3}],"dureeMin":11,"corrige":"1. Le poème relève de la veine de la **fugue et de la sensation** : le poète marche (« Je m’en allais », « J’allais »), il est sur la route, « sous le ciel », hors de toute maison ; le corps est présent (« les poings dans mes poches »). La nature remplace le foyer.\n2. Ruptures de registre : « **poches crevées** », « **paletot** », l’interjection « **Oh ! là ! là !** » sont des mots familiers ou triviaux. Ils sont placés dans un **moule noble** : des **alexandrins** d’un **sonnet**, avec une **adresse à la Muse** et le mot médiéval « féal ». Rimbaud **maîtrise** la forme classique et la **maltraite** en même temps.\n3. L’émancipation est **triple** : l’**adolescent** a quitté la famille et la province (il s’en va, pauvre, en vagabond) ; le **poète** se libère des formes héritées en mêlant le trivial au sublime ; la Muse l’accompagne sur la route plutôt qu’au salon. Le poème fait de la pauvreté une liberté (« que d’amours splendides j’ai rêvées ! ») : la création naît de la fugue."}$exo$::jsonb),
  ('41813cdd-0691-5f2e-a3ec-b78150d1191c'::uuid, 3, 'redaction', $exo${"titre":"« Le Dormeur du val », une satire en forme de sonnet","consigne":"Rédige un commentaire organisé en deux ou trois parties, avec une introduction et une conclusion. Appuie-toi sur les vers cités et sur le cours.","enonce":"**Premier quatrain**\n> C’est un trou de verdure où chante une rivière,\n> Accrochant follement aux herbes des haillons\n> D’argent ; où le soleil, de la montagne fière,\n> Luit : c’est un petit val qui mousse de rayons.\n\n**Dernier tercet**\n> Les parfums ne font pas frissonner sa narine ;\n> Il dort dans le soleil, la main sur sa poitrine\n> Tranquille. Il a deux trous rouges au côté droit.\n\n**Sujet.** Comment ce sonnet, écrit en 1870, fait-il d’une nature riante l’arme d’une dénonciation ? Tu étudieras la construction du poème, le travail de la forme (rejets, enjambements) et tu montreras en quoi il relève de l’émancipation du **citoyen** et du **poète**.","bareme":[{"critere":"Nature riante et vivante du premier quatrain analysée (personnification de la rivière, lumière)","points":4},{"critere":"Construction en chute expliquée : treize vers de paix puis les « deux trous rouges »","points":5},{"critere":"Rejets relevés (« D’argent », « Luit », « Tranquille ») et effet de chacun expliqué","points":4},{"critere":"Contexte (guerre franco-prussienne) et satire de l’armée ; émancipation du citoyen et du poète","points":4},{"critere":"Commentaire organisé, citations exactes, conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Introduction** : Rimbaud, seize ans, écrit ce sonnet pendant la **guerre franco-prussienne**. Il appartient à la veine **satirique** des *Cahiers de Douai* : l’armée y est attaquée, mais par un détour.\n\n**I. Une nature en fête.** Le premier quatrain est plein de vie : la rivière « **chante** » et accroche « **follement** » des haillons (personnification), le soleil « **luit** », le val « **mousse de rayons** » : lumière, mouvement, joie. Le dormeur semble protégé par ce décor maternel ; « Il dort dans le soleil ».\n\n**II. Une chute qui retourne tout.** Le sonnet repose sur **treize vers de nature riante**, puis la chute : « Il a **deux trous rouges** au côté droit ». Le lecteur comprend que le soldat est **mort** : il ne dort pas, les parfums ne font « pas frissonner sa narine ». Le « trou de verdure » du premier vers prend rétrospectivement le sens d’une tombe. Le rouge du sang, seul, dément tout le décor.\n\n**III. Le travail de la forme.** Rimbaud maîtrise le sonnet et les alexandrins, mais les brise : les **rejets** « **D’argent** » et « **Luit** » mettent en relief la lumière ; le rejet « **Tranquille.** » est le plus violent : un seul mot, puis un point, puis la révélation. La phrase et le vers ne coïncident plus, et cette rupture **fait sens** : elle prépare le choc.\n\n**IV. (ou dans les parties précédentes) Une émancipation.** Le **citoyen** dénonce l’ordre impérial et sa guerre sans discours frontal : le poème montre, il ne commente pas. Le **poète** s’émancipe des formes héritées en les retournant : la forme noble sert la dénonciation.\n\n**Conclusion** : la beauté du paysage rend la mort plus scandaleuse ; ce sonnet est le **modèle** du travail de Rimbaud, qui retourne une forme apaisée contre la violence de son temps."}$exo$::jsonb),
  ('1028abbf-0773-5eb2-8eb1-452e4f363721'::uuid, 1, 'redaction', $exo${"titre":"Un livre de carnets","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne la **période d’écriture** et l’**année de publication** de *La rage de l’expression* de Francis Ponge.\n2. Quelle est la **particularité** de ce livre par rapport à un recueil de poèmes ordinaire ?\n3. Cite **trois** des sept ensembles qui le composent.\n4. Que veut dire le mot « **rage** » du titre ?\n5. Quel est le **parcours associé** ?","bareme":[{"critere":"Dates justes (1938-1944, 1952) et trois ensembles cités sans erreur","points":7},{"critere":"Particularité : les brouillons publiés, datés, repris, contredits ; journal d’écriture","points":7},{"critere":"Sens de « rage » (acharnement, la langue ne rend jamais l’objet) et parcours « dans l’atelier du poète »","points":6}],"dureeMin":7,"corrige":"1. Écrit entre **1938 et 1944**, publié en **1952**.\n2. Au lieu de livrer des poèmes **finis**, Ponge publie les **brouillons** eux-mêmes, **datés, repris, contredits**. Chaque ensemble est un **journal d’écriture** : on voit le poète recommencer, rayer, dater ses séances, avouer ses échecs.\n3. Trois parmi : « Berges de la Loire », « Le Carnet du bois de pins », « La Mounine », « L’Œillet », « La Guêpe », « Le Mimosa », « Notes prises pour un oiseau ».\n4. « Rage » dit l’**acharnement** : la langue ne rend **jamais** l’objet, il faut donc reprendre sans cesse.\n5. Le parcours associé est **« dans l’atelier du poète »**."}$exo$::jsonb),
  ('1028abbf-0773-5eb2-8eb1-452e4f363721'::uuid, 2, 'redaction', $exo${"titre":"Le carnet de la bouilloire","consigne":"Lis ce journal d’écriture, écrit pour l’exercice à la manière de Ponge (ce n’est pas un texte de Ponge), puis réponds en citant le texte.","enonce":"> **12 mars.** — La bouilloire. Surtout, ne pas dire qu’elle chante : elle ne chante pas, elle ne se réjouit de rien. Elle chauffe. Première définition : « récipient qui fait passer l’eau d’un état à un autre ». Trop sec. Mauvais.\n> **13 mars.** — Reprendre. Ouvert le Littré : *bouillir* vient du latin *bullire*, faire des bulles. Voilà : la bouilloire est une fabrique de bulles. Mieux, mais encore trop joli.\n> **14 mars.** — Échec d’hier. Il me faudrait un mot qui n’existe pas : la bouilloire est *bullissante*. Je l’écris, je le raye, je le garde.\n\n1. Relève **trois indices** qui font de ce texte un **journal d’écriture**.\n2. Quelle phrase montre le **refus d’humaniser** l’objet ? Pourquoi ce refus ?\n3. Relève deux **outils** de l’écriture pongienne présents ici.\n4. Quel « je » parle ici : un « je » sentimental ou technicien ? Justifie.","bareme":[{"critere":"Trois indices du journal d’écriture (dates, reprises, jugements « Mauvais », aveu d’échec)","points":5},{"critere":"Refus d’humaniser relevé (« ne pas dire qu’elle chante ») et expliqué : la chose comme défi au langage","points":5},{"critere":"Deux outils identifiés parmi dictionnaire et étymologie, définitions successives, néologisme","points":5},{"critere":"« Je » technicien justifié : un ouvrier au travail, sans épanchement","points":5}],"dureeMin":11,"corrige":"1. Le texte est **daté** (12, 13, 14 mars) comme des séances ; le poète **reprend** (« Reprendre », « Mieux, mais encore trop joli ») ; il **juge et rature** ses essais (« Trop sec. Mauvais », « je le raye ») ; il **avoue ses échecs** (« Échec d’hier »). L’échec est intégré à l’œuvre : c’en est le sujet.\n2. « **Surtout, ne pas dire qu’elle chante** : elle ne chante pas, elle ne se réjouit de rien. » Comme Ponge, le texte refuse d’**humaniser** ou de **symboliser** l’objet : la chose n’est pas un **miroir des sentiments** (comme dans le lyrisme romantique) mais un **défi posé au langage**. Il faut se laisser corriger par l’objet, non par la rhétorique.\n3. L’**étymologie et le dictionnaire** (« Ouvert le Littré : *bouillir* vient du latin *bullire* ») ; les **définitions successives**, dont aucune n’est la bonne ; le **néologisme** (« bullissante ») quand la langue manque. Deux suffisent.\n4. Un « je » **technicien** : il n’exprime aucun état d’âme, il décrit son travail (« J’écris, je le raye, je le garde »), comme un **ouvrier** dans l’atelier. L’objet choisi est **modeste** : c’est la leçon de modestie de l’œuvre."}$exo$::jsonb),
  ('1028abbf-0773-5eb2-8eb1-452e4f363721'::uuid, 3, 'redaction', $exo${"titre":"Le poème : un résultat ou un processus ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties argumentées, conclusion) en t’appuyant sur La rage de l’expression telle que le cours la présente.","enonce":"**Sujet.** « Chez Ponge, le poème n’est plus un résultat mais un processus. » Discute cette affirmation.\n\nTu t’appuieras sur :\n- le dispositif du livre (carnets, brouillons, séances datées) ;\n- le « parti pris des choses » et l’opposition avec le lyrisme romantique ;\n- le sens du mot « rage » et la place de l’échec ;\n- la place faite au **lecteur**.","bareme":[{"critere":"Problématique claire tirée du sujet et plan annoncé","points":3},{"critere":"Dispositif analysé : brouillons publiés, séances datées, reprises, prose et vers mêlés","points":5},{"critere":"Opposition au lyrisme romantique : l’objet modeste comme défi au langage, non miroir des sentiments","points":5},{"critere":"Rage, échec intégré, outils (Littré, définitions successives, néologismes) ; le lecteur placé dans l’atelier","points":5},{"critere":"Conclusion qui répond au sujet (leçon de modestie)","points":2}],"dureeMin":20,"corrige":"**Introduction** : on attend d’un recueil des poèmes achevés. *La rage de l’expression* (écrite 1938-1944, publiée en 1952) publie au contraire les **brouillons**. Problématique : que devient la poésie quand elle montre son chantier plutôt que son œuvre finie ?\n\n**I. Un livre qui montre le chantier.** Sept ensembles (« Berges de la Loire », « La Guêpe », « Le Mimosa »…) sont des **journaux d’écriture** : séances **datées**, reprises, contradictions, aveux d’échec. La prose côtoie le vers, la note brute la phrase travaillée. Le poème apparaît comme un **processus**.\n\n**II. Pourquoi ce processus : l’objet résiste.** Ponge choisit des objets **modestes** (pin, œillet, guêpe, mimosa) et veut les dire **sans les humaniser ni les symboliser**. Pour le lyrisme romantique, la chose est un **miroir** des sentiments ; pour Ponge, un **défi posé au langage**. « Berges de la Loire » l’annonce : se tenir **devant l’objet** et se laisser corriger par lui. Or la langue ne rend **jamais** l’objet : d’où la **rage**, l’acharnement. Les outils le montrent : **Littré ouvert**, étymologie, jeux sonores, **définitions successives** dont aucune n’est la bonne, **néologismes**. L’**échec** est intégré : c’est le sujet, pas l’accident.\n\n**III. Un processus qui fait œuvre.** Ce chantier n’est pas un renoncement : publié, il devient le livre. Le lecteur est **mis à la place du poète**, dans l’atelier, **devant l’objet qui résiste**. Le « je » y est **technicien**, un ouvrier au travail. L’œuvre déplace l’idée même de poème.\n\n**Conclusion** : l’affirmation est juste ; le processus est devenu le poème. C’est aussi une leçon de **modestie** : nommer une guêpe correctement est plus difficile que chanter ses états d’âme."}$exo$::jsonb),
  ('a5942c93-fe4d-5144-8d81-47a8ff180c29'::uuid, 1, 'redaction', $exo${"titre":"Situer Mes forêts","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qui a écrit *Mes forêts* ? En quelle année ? Pourquoi ce recueil marque-t-il une première au programme du bac ?\n2. Combien de **sections** composent le recueil ? Nomme-en deux avec leur motif.\n3. Quel est le **parcours associé** ?\n4. Que dit le **possessif** du titre ?","bareme":[{"critere":"Hélène Dorion, poétesse québécoise, 2021, première œuvre d’une autrice vivante au programme","points":6},{"critere":"Quatre sections (plus un poème liminaire), deux nommées avec leur motif juste","points":7},{"critere":"Parcours « la poésie, la nature, l’intime » et sens du possessif expliqué","points":7}],"dureeMin":6,"corrige":"1. *Mes forêts* est un recueil de la poétesse **québécoise Hélène Dorion**, publié en **2021**. C’est la **première œuvre d’une autrice vivante** inscrite au programme du bac de français.\n2. **Quatre sections**, précédées d’un poème liminaire : « **L’écorce incertaine** » (la forêt comme corps et mémoire), « **Une chute de galets** » (la fragilité, la perte, le deuil), « **Mes forêts sont de longues traînées de temps** » (le temps, l’enfance, la filiation), « **Le bruissement du temps** » (l’écoute, la présence au monde, l’apaisement). Deux suffisent.\n3. Le parcours est **« la poésie, la nature, l’intime »**.\n4. Le possessif (*mes* forêts) montre que le paysage est **intérieur autant qu’extérieur** : la forêt est un double du sujet, et c’est en la décrivant que le « je » se dit."}$exo$::jsonb),
  ('a5942c93-fe4d-5144-8d81-47a8ff180c29'::uuid, 2, 'redaction', $exo${"titre":"Lire un poème à la manière de Dorion","consigne":"Lis ce poème, écrit pour l’exercice à la manière d’Hélène Dorion (ce n’est pas un texte du recueil), puis réponds en citant.","enonce":"> mes forêts sont des racines\n> qui descendent vers mon père\n>\n> mes forêts sont des cernes\n> où le temps s’est posé\n> sans bruit\n>\n> sous l’écorce\n> une blessure garde la lumière\n\n1. Relève **quatre procédés** d’écriture propres au recueil (forme, ponctuation, mise en page, répétition) et donne l’**effet** de chacun.\n2. Explique ce que disent de l’humain les mots **racines**, **cernes** et **écorce**.\n3. Montre en une phrase que la forêt n’est **pas un décor**.","bareme":[{"critere":"Quatre procédés relevés : vers libres courts, absence de ponctuation, blancs, anaphore « mes forêts sont »","points":6},{"critere":"Effet de chaque procédé (lecture qui respire, sens ouvert, silence, incantation)","points":4},{"critere":"Racines = filiation, cernes = temps accumulé, écorce = protection et blessure, reliés aux vers","points":6},{"critere":"La forêt comme double du sujet, justifiée par le texte","points":4}],"dureeMin":12,"corrige":"1. **Vers libres, poèmes courts** : la lecture **respire**. **Absence de ponctuation** : aucun point ne ferme la phrase, le **sens reste ouvert**. **Blancs typographiques** entre les strophes : le **silence fait partie du texte** (« sans bruit » est isolé sur son vers). **Anaphore** « mes forêts sont » : une pulsation d’**incantation**.\n2. Les **racines** disent l’**origine, la filiation** (« qui descendent vers mon père » : la lignée, et peut-être le deuil) ; les **cernes** disent le **temps accumulé** (« où le temps s’est posé ») ; l’**écorce** dit à la fois la **protection et la blessure** (« une blessure garde la lumière »).\n3. Le possessif et les images montrent que la forêt est un **double du sujet** : en décrivant l’arbre, le « je » parle de son père, de son temps, de sa blessure ; le paysage est **intérieur autant qu’extérieur**. La langue est simple et concrète : la difficulté est dans la **densité des images**."}$exo$::jsonb),
  ('a5942c93-fe4d-5144-8d81-47a8ff180c29'::uuid, 3, 'redaction', $exo${"titre":"Renouveler le lyrisme sans le refuser","consigne":"Rédige une dissertation organisée (introduction, deux ou trois parties, conclusion) en t’appuyant sur le cours.","enonce":"**Sujet.** « Le poème ne décrit pas la nature vue par un moi, il montre un moi fait de nature. » En quoi cette formule éclaire-t-elle la manière dont *Mes forêts* renouvelle le lyrisme ?\n\nTu t’appuieras sur la composition du recueil, les images de l’arbre, l’écriture du dépouillement et les thèmes du parcours. Tu termineras par une **comparaison avec Ponge**, que le cours désigne comme le meilleur angle de dissertation.","bareme":[{"critere":"Problématique sur le lyrisme renouvelé, plan annoncé","points":3},{"critere":"La forêt double du sujet : images de l’arbre et possessif du titre analysés","points":5},{"critere":"Écriture du dépouillement (vers libres, ponctuation absente, blancs, anaphores) reliée au sens","points":4},{"critere":"Thèmes : intime (deuil du père), nature, écologie comme conscience d’appartenir au vivant et non discours militant","points":5},{"critere":"Comparaison juste avec Ponge : Dorion renouvelle le lyrisme sans le refuser","points":3}],"dureeMin":20,"corrige":"**Introduction** : le lyrisme traditionnel fait de la nature le miroir d’un moi qui la contemple. *Mes forêts* (2021) semble inverser le rapport. Problématique : comment Dorion renouvelle-t-elle le lyrisme en refusant la séparation entre le sujet et le monde ?\n\n**I. Un moi fait de nature.** La forêt n’est pas un décor mais un **double du sujet** : les **racines** disent la filiation, les **cernes** le temps accumulé, l’**écorce** la protection et la blessure, tomber et repousser la perte et le recommencement. Le **possessif** du titre fait du paysage un espace **intérieur autant qu’extérieur**.\n\n**II. Une écriture du dépouillement.** **Vers libres**, poèmes courts, absence quasi totale de **ponctuation** (le sens reste ouvert), **blancs** (le silence fait partie du texte), **anaphores** « mes forêts sont… » (une incantation). La langue est **simple, concrète** : la densité est dans les images. Le recueil **dialogue** aussi avec d’autres voix (exergues de Rilke, Char, de scientifiques).\n\n**III. Un lyrisme élargi au vivant.** L’**intime** (le deuil du père, l’enfance, le corps qui vieillit) se dit à travers la **nature** (arbre, lumière, eau, neige, oiseau). L’**écologie** n’est pas un discours militant mais une **conscience d’appartenir au vivant** : quand la forêt brûle, c’est **nous** que la perte atteint.\n\n**Comparaison** : Ponge refuse d’humaniser la chose et fait d’elle un défi au langage, avec un « je » technicien ; Dorion, elle, garde un « je » qui se dit, mais un « je » **fait de** nature. Elle **renouvelle le lyrisme sans le refuser**.\n\n**Conclusion** : la formule est juste : le recueil refuse la séparation entre le sujet et le monde."}$exo$::jsonb),
  ('bb864e16-b8f5-59ea-b4d4-1fa635c956c5'::uuid, 1, 'redaction', $exo${"titre":"Convaincre, persuader, délibérer","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Définis les trois visées d’un texte argumentatif : **convaincre**, **persuader**, **délibérer**. Pour chacune, dis à quoi elle s’adresse et donne un de ses moyens.\n2. Oppose l’**argumentation directe** et l’**argumentation indirecte** : deux formes de chacune et l’avantage de chacune.\n3. Qu’est-ce que le procédé du **regard étranger** ? Cite deux personnages du cours qui l’incarnent.","bareme":[{"critere":"Les trois visées définies (raison, émotions, jugement) avec un moyen chacune","points":8},{"critere":"Directe et indirecte : deux formes chacune et leurs avantages (clarté ; échapper à la censure, se retenir)","points":7},{"critere":"Regard étranger expliqué et illustré (le Persan, le Huron, la Péruvienne)","points":5}],"dureeMin":8,"corrige":"1. **Convaincre** s’adresse à la **raison** : thèse, arguments, exemples, connecteurs logiques. **Persuader** s’adresse aux **émotions** et à l’imagination : récit, image, ironie, apostrophe, rythme. **Délibérer** s’adresse au **jugement** : on pèse le pour et le contre, souvent par un **dialogue**, sans trancher d’avance. Un même texte fait souvent les trois : il faut repérer laquelle domine.\n2. **Directe** : essai, discours, lettre ouverte, article ; son avantage est la **clarté**. **Indirecte** : fable, conte philosophique, apologue, utopie, lettre fictive ; elle **échappe à la censure** et **se retient mieux**.\n3. Le **regard étranger** fait décrire nos usages par un personnage venu d’ailleurs : **ce que l’habitude rend invisible devient absurde vu du dehors**. Exemples : le **Persan**, le **Huron**, la **Péruvienne**."}$exo$::jsonb),
  ('bb864e16-b8f5-59ea-b4d4-1fa635c956c5'::uuid, 2, 'redaction', $exo${"titre":"La lettre du voyageur de Tamaro","consigne":"Lis cette lettre fictive (texte écrit pour l’exercice), puis réponds en citant précisément.","enonce":"*Un voyageur venu de l’île imaginaire de Tamaro écrit à son ami resté au pays.*\n\n> « Les habitants de cette grande ville sont le peuple le plus sage de la terre. Ils ont des palais de justice magnifiques, où l’on juge le pauvre en une heure et le riche en dix ans, afin sans doute de laisser au riche le temps de devenir honnête. Ils méprisent l’oisiveté : aussi les plus oisifs d’entre eux possèdent-ils les plus grandes terres, que d’autres cultivent pour eux. Qu’aurais-je à t’apprendre de plus admirable ? Chez nous, on croit naïvement qu’un homme vaut par ce qu’il fait ; ici, on sait qu’il vaut par le nom de son père. »\n\n1. S’agit-il d’une argumentation **directe** ou **indirecte** ? Quel procédé est utilisé ?\n2. Relève une **antiphrase**, une **question rhétorique** et une **antithèse**, et explique l’effet de chacune.\n3. Quelle **visée** domine ? Contre qui ce texte est-il écrit ?","bareme":[{"critere":"Argumentation indirecte (lettre fictive) et procédé du regard étranger identifiés","points":4},{"critere":"Antiphrase, question rhétorique et antithèse relevées exactement","points":6},{"critere":"Effet de chaque procédé rattaché à une visée (ridiculiser, faire douter)","points":5},{"critere":"Visée dominante justifiée et cible identifiée (justice inégale, privilège de la naissance)","points":5}],"dureeMin":12,"corrige":"1. Argumentation **indirecte** : une **lettre fictive** attribuée à un voyageur imaginaire. Procédé du **regard étranger** : le voyageur décrit des usages qu’il semble admirer, et le lecteur en voit l’absurdité.\n2. **Antiphrase** : « le peuple le plus sage de la terre », « plus admirable » : le voyageur dit le contraire de ce qu’il faut comprendre ; effet d’**ironie** qui ridiculise. **Question rhétorique** : « Qu’aurais-je à t’apprendre de plus admirable ? » : elle n’attend pas de réponse et renforce l’ironie. **Antithèse** : « le pauvre en une heure et le riche en dix ans » ou « par ce qu’il fait / par le nom de son père » : l’opposition rend visible l’**inégalité**. On accepte aussi le **modalisateur** « sans doute », faussement naïf.\n3. La visée dominante est **persuader** : l’ironie fait **rire** et indigne, elle agit sur l’émotion ; mais le texte veut aussi **convaincre** que la société est injuste (les exemples fonctionnent comme des arguments). Il vise une **justice** favorable aux riches, l’**oisiveté des privilégiés** et le **privilège de la naissance** ; il écrit pour convaincre le lecteur du pays décrit, qui ne voit plus ces injustices par habitude."}$exo$::jsonb),
  ('bb864e16-b8f5-59ea-b4d4-1fa635c956c5'::uuid, 3, 'redaction', $exo${"titre":"Le détour est-il plus efficace que l’attaque de front ?","consigne":"Rédige une dissertation organisée (introduction, deux ou trois parties, conclusion), avec des exemples tirés du cours.","enonce":"**Sujet.** « Pour agir sur son lecteur, l’argumentation indirecte est plus efficace que l’argumentation directe. » Discute cette affirmation en t’appuyant sur la littérature d’idées du XVIe au XVIIIe siècle.\n\nTu mobiliseras les trois visées (convaincre, persuader, délibérer), les formes directes et indirectes, les trois moments (humanisme, âge classique, Lumières) et au moins deux outils d’analyse (ironie, antithèse, question rhétorique…).","bareme":[{"critere":"Problématique et plan dialectique (forces de l’indirect, forces du direct, dépassement)","points":4},{"critere":"Atouts de l’indirect : censure évitée, mémoire, regard étranger, apologue ; exemples du cours","points":5},{"critere":"Atouts du direct : clarté, raisonnement, essai et discours ; exemples du cours","points":4},{"critere":"Les trois moments situés avec des auteurs et des outils d’analyse rattachés à une visée","points":4},{"critere":"Conclusion nuancée : un texte combine souvent les visées, tout dépend de qui l’on veut convaincre","points":3}],"dureeMin":20,"corrige":"**Introduction** : du XVIe au XVIIIe siècle, la littérature sert à **penser**. Faut-il attaquer de front ou passer par la fiction ? Problématique : quelle forme agit le mieux sur le lecteur ?\n\n**I. La force du détour.** L’argumentation **indirecte** (fable, conte philosophique, apologue, utopie, lettre fictive) **échappe à la censure** et **se retient mieux**. Le **regard étranger** (le Persan, le Huron, la Péruvienne) rend absurde ce que l’habitude rendait invisible. La fable de l’âge classique (La Fontaine) dit sous le masque animal ce qu’on ne peut dire en son nom. Elle **persuade** : le récit, l’image, l’**ironie** et l’**antiphrase** font rire et ridiculisent.\n\n**II. La force de l’attaque directe.** L’essai, le discours, la lettre ouverte ont la **clarté** : thèse, arguments, exemples, connecteurs logiques s’adressent à la **raison** et visent à **convaincre**. Les humanistes (Montaigne, La Boétie) examinent tout de façon critique ; les Lumières (Voltaire, Diderot, Olympe de Gouges) combattent les **préjugés** au nom de la raison. Le détour, lui, risque d’être mal lu : l’ironie peut échapper au lecteur pressé.\n\n**III. Une efficacité qui tient à la combinaison.** Un même texte fait presque toujours **les trois** (convaincre, persuader, délibérer) ; le dialogue permet de **délibérer** sans trancher d’avance. Chaque outil (hyperbole, gradation, question rhétorique, antithèse, modalisateurs, lexique péjoratif ou mélioratif) sert une **visée** : ridiculiser, émouvoir, faire douter, faire agir.\n\n**Conclusion** : l’indirect est souvent plus efficace sous la censure et pour frapper les esprits, le direct pour démontrer. La vraie question reste : **contre qui** le texte écrit-il, et **pour convaincre qui** ?"}$exo$::jsonb),
  ('857bb35f-c934-5383-a0b9-b42dd295d324'::uuid, 1, 'redaction', $exo${"titre":"La question de La Boétie","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit le *Discours de la servitude volontaire*, vers quelle date et à quel âge ? Quand a-t-il été publié ? Quel est son autre titre ?\n2. Quelle question **renversée** l’auteur pose-t-il ?\n3. Quelle **solution** propose-t-il contre le tyran ?\n4. Nomme les **trois ressorts** de l’obéissance.","bareme":[{"critere":"Auteur, vers 1548, moins de vingt ans, publication posthume, Contr’un","points":5},{"critere":"Question renversée et paradoxe de la servitude volontaire (consentie, non subie)","points":6},{"critere":"Solution (retirer son consentement, sans armes) et trois ressorts justes","points":9}],"dureeMin":7,"corrige":"1. **Étienne de La Boétie**, vers **1548**, alors qu’il n’a pas **vingt ans** ; le texte est publié **après sa mort**. Autre titre : le ***Contr’un***.\n2. Au lieu de demander comment le tyran tient le peuple, il demande **comment le peuple tient le tyran** : un homme seul ne peut rien contre des millions ; s’il domine, c’est que les dominés lui **donnent** leur force. La domination n’est pas subie, elle est **consentie** : d’où la servitude *volontaire*.\n3. Ni bataille ni armes : il suffit de **retirer son consentement**. « **Soyez résolus de ne servir plus, et vous voilà libres.** » Le tyran tombe comme un **colosse dont on a retiré le socle**.\n4. L’**habitude** (la coutume, première raison), le **divertissement** (jeux, théâtres, fêtes, distributions de blé), la **chaîne des complices** (cinq ou six, puis six cents, puis six mille)."}$exo$::jsonb),
  ('857bb35f-c934-5383-a0b9-b42dd295d324'::uuid, 2, 'redaction', $exo${"titre":"Le royaume de Vellore","consigne":"Lis ce récit (texte écrit pour l’exercice), puis analyse-le avec les idées de La Boétie.","enonce":"> Le roi de Vellore règne depuis quarante ans. Il ne quitte jamais son palais et ne commande lui-même à personne. Cinq ministres lui doivent leur fortune ; chacun a placé une centaine d’amis dans les douanes et les tribunaux, et ceux-ci ont à leur tour des milliers de protégés. Chaque printemps, le roi offre au peuple trois jours de fêtes, de courses et de pain gratuit. Les habitants, nés sous son règne, ne se souviennent d’aucun autre et disent : « Il en a toujours été ainsi. »\n\n1. Retrouve dans ce récit les **trois ressorts** de l’obéissance décrits par La Boétie. Cite le texte pour chacun.\n2. Lequel est, selon le cours, **le plus redoutable** ? Pourquoi le roi n’a-t-il « pas à agir » ?\n3. Que conseillerait La Boétie aux habitants de Vellore ? Explique l’image du **colosse**.","bareme":[{"critere":"Habitude, divertissement et chaîne des complices retrouvés chacun avec une citation","points":8},{"critere":"La chaîne des complices désignée comme la plus redoutable, pyramide d’intérêts expliquée","points":5},{"critere":"Conseil : retirer son consentement sans violence ; image du colosse sans socle expliquée","points":5},{"critere":"Réponses rédigées et vocabulaire du cours employé","points":2}],"dureeMin":12,"corrige":"1. **L’habitude** : « nés sous son règne, ne se souviennent d’aucun autre », « Il en a toujours été ainsi » : on naît sous le joug et on le croit **naturel** ; c’est la **coutume**, première raison de la servitude volontaire. **Le divertissement** : « trois jours de fêtes, de courses et de pain gratuit » : le pouvoir **amuse ceux qu’il dépouille**, comme les jeux, théâtres et distributions de blé chez La Boétie. **La chaîne des complices** : « Cinq ministres… une centaine d’amis… des milliers de protégés » : c’est la pyramide des « cinq ou six », puis six cents, puis six mille.\n2. La **chaîne des complices** est la plus redoutable : une **pyramide d’intérêts** fait tenir l’édifice **sans que le tyran ait à agir**. Le roi « ne commande lui-même à personne » : chacun obéit parce qu’il profite de la place de celui qui est au-dessus.\n3. La Boétie leur dirait : « **Soyez résolus de ne servir plus, et vous voilà libres.** » Pas besoin de bataille ni d’armes : il suffit de **retirer son consentement**. Le roi tomberait alors comme un **colosse dont on a retiré le socle** : sa force n’est que celle que lui donnent ceux qui obéissent."}$exo$::jsonb),
  ('857bb35f-c934-5383-a0b9-b42dd295d324'::uuid, 3, 'redaction', $exo${"titre":"Peut-on se libérer de la servitude ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur le Discours de la servitude volontaire tel que le cours le présente.","enonce":"**Sujet.** Le *Discours de la servitude volontaire* affirme qu’il suffit de ne plus servir pour être libre. Selon vous, l’œuvre montre-t-elle que se libérer de la servitude est **facile** ?\n\nTu analyseras le renversement de départ, la solution proposée, les trois ressorts de l’obéissance, l’écriture du texte (apostrophes, questions rhétoriques, métaphores, érudition antique) et la postérité de l’œuvre.","bareme":[{"critere":"Problématique qui oppose la simplicité de la solution et la force des ressorts de l’obéissance","points":3},{"critere":"Renversement (le peuple tient le tyran) et solution sans violence expliqués, citation exacte","points":5},{"critere":"Les trois ressorts analysés comme obstacles, la chaîne des complices comme le plus redoutable","points":5},{"critere":"Écriture analysée : apostrophes, questions rhétoriques, métaphores (colosse, chaîne, feu), érudition au service de la démonstration","points":4},{"critere":"Postérité (désobéissance civile) et conclusion nuancée","points":3}],"dureeMin":20,"corrige":"**Introduction** : vers 1548, La Boétie, qui n’a pas vingt ans, pose une question dérangeante : pourquoi obéit-on ? Problématique : si la servitude est volontaire, la liberté est-elle à portée de main ?\n\n**I. Une libération simple en droit.** Le renversement : ce n’est pas le tyran qui tient le peuple, c’est **le peuple qui tient le tyran** ; un seul ne peut rien contre des millions. La domination est **consentie**. La conséquence est désarmante : « **Soyez résolus de ne servir plus, et vous voilà libres.** » Ni bataille ni armes : **retirer son consentement** suffit, et le tyran tombe comme un **colosse dont on a retiré le socle**. Humaniste, La Boétie pose que la **liberté est naturelle** et la **servitude acquise**.\n\n**II. Une libération difficile en fait.** Trois ressorts retiennent les hommes. L’**habitude** : né sous le joug, on le croit naturel (la **coutume**, première raison). Le **divertissement** : jeux, théâtres, fêtes, distributions de blé ; le pouvoir amuse ceux qu’il dépouille. La **chaîne des complices** : cinq ou six, six cents, six mille ; cette **pyramide d’intérêts** fait tenir l’édifice sans que le tyran agisse. C’est la plus redoutable : beaucoup ont intérêt à servir.\n\n**III. Un texte qui veut réveiller.** L’écriture est **courte, orale, brûlante** : **apostrophes** au lecteur, **questions rhétoriques**, exclamations, **métaphores** frappantes (le colosse, la chaîne, le feu). L’érudition antique (Xerxès, les Spartiates, Ulysse) sert la **démonstration**. En déplaçant la **responsabilité politique** vers le peuple, l’œuvre a servi tous les camps : protestants au XVIe, révolutionnaires, puis théoriciens de la **désobéissance civile** au XXe.\n\n**Conclusion** : se libérer est simple dans son principe, difficile dans les faits, car il faut vaincre l’habitude, le divertissement et l’intérêt. Le *Discours* ne promet pas la facilité : il rend chacun **responsable**."}$exo$::jsonb),
  ('1dc17334-17d3-5e0e-a23c-d9805ad384c2'::uuid, 1, 'redaction', $exo${"titre":"Six soirs pour comprendre le ciel","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit les *Entretiens sur la pluralité des mondes* et en quelle année ? Quel genre l’ouvrage invente-t-il presque ?\n2. Décris le **dispositif** : qui parle, où, combien de soirs ?\n3. Quel **système astronomique** est enseigné ? Que dit-il ?\n4. Comment Fontenelle présente-t-il l’idée de **mondes habités** ?","bareme":[{"critere":"Fontenelle, 1686, vulgarisation scientifique","points":5},{"critere":"Dispositif : un philosophe et une marquise, le parc du château, six soirs et six leçons","points":6},{"critere":"Copernic (la Terre tourne autour du Soleil et sur elle-même) ; pluralité des mondes comme conjecture, non dogme","points":9}],"dureeMin":7,"corrige":"1. **Bernard Le Bouyer de Fontenelle**, en **1686**. L’ouvrage invente presque la **vulgarisation scientifique** moderne.\n2. Un **philosophe** séjourne chez une **marquise** ; chaque soir, dans le **parc du château**, ils regardent le ciel et conversent : **six soirs, six leçons**. Les objections de la marquise sont celles du lecteur, qui part de zéro comme elle.\n3. Le **système de Copernic** : la Terre tourne **autour du Soleil** et **sur elle-même**. L’ouvrage montre aussi que l’univers est immense et que les planètes sont des **mondes**, pas des points lumineux.\n4. La **pluralité des mondes habités** (les étoiles fixes vues comme autant de soleils) est présentée comme une **conjecture raisonnable**, **jamais comme un dogme** : la prudence est une méthode."}$exo$::jsonb),
  ('1dc17334-17d3-5e0e-a23c-d9805ad384c2'::uuid, 2, 'redaction', $exo${"titre":"La marquise ne sent rien","consigne":"Lis ce dialogue, écrit pour l’exercice à la manière de Fontenelle (ce n’est pas le texte original), puis réponds en citant.","enonce":"> LA MARQUISE. — Vous voulez que la Terre tourne ; mais je ne sens rien, et mes orangers restent bien tranquilles dans leurs caisses.\n> LE PHILOSOPHE. — Madame, lorsque vous descendez la rivière dans votre bateau, sentez-vous qu’il avance ? Il vous semble plutôt que ce sont les rives qui s’en vont. Nous sommes tous passagers d’un grand vaisseau, qui nous emporte si doucement que nous l’oublions.\n> LA MARQUISE. — Voilà une comparaison bien flatteuse pour mon bateau.\n> LE PHILOSOPHE. — Elle l’est moins que celles que mérite une personne qui comprend si vite.\n\n1. Quel rôle joue l’**objection** de la marquise dans le dialogue ?\n2. Quelle **analogie** le philosophe emploie-t-il ? Quelle notion rend-elle claire ? D’où est-elle tirée ?\n3. Relève une marque du **ton galant**. Est-ce une faiblesse du texte ? Justifie avec le cours.","bareme":[{"critere":"L’objection est celle du lecteur ; elle fait progresser la compréhension par étapes","points":5},{"critere":"Analogie du vaisseau expliquée : le mouvement qu’on ne sent pas ; image prise dans le monde de la marquise","points":7},{"critere":"Marque de galanterie relevée (compliment final) et interprétée comme stratégie de diffusion","points":6},{"critere":"Citations exactes","points":2}],"dureeMin":11,"corrige":"1. L’objection « je ne sens rien » est **celle du lecteur** : la marquise part de zéro, comme lui. Le dialogue rend visible le **chemin** de la compréhension, pas seulement le résultat : chaque résistance appelle une explication nouvelle.\n2. L’analogie du **bateau** puis du **vaisseau** (« Nous sommes tous passagers d’un grand vaisseau ») explique **le mouvement de la Terre qu’on ne sent pas** : comme dans un bateau, on croit que ce sont les rives qui bougent. L’image est tirée du **monde familier de la marquise** (sa promenade sur la rivière) : chaque notion difficile est rendue par une analogie du monde mondain.\n3. Marque de galanterie : le compliment final (« une personne qui comprend si vite »), l’esprit de la réplique sur le bateau. Ce n’est **pas une faiblesse** : le badinage est une **stratégie de diffusion** pour un public mondain, largement féminin, exclu du latin et des académies ; et il a une portée **politique**, car il suppose que la science **n’est pas réservée aux savants**."}$exo$::jsonb),
  ('1dc17334-17d3-5e0e-a23c-d9805ad384c2'::uuid, 3, 'redaction', $exo${"titre":"Rendre la science accessible sans la déformer","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur l’œuvre telle que le cours la présente.","enonce":"**Sujet.** « Rendre accessible, c’est simplifier ; simplifier, c’est risquer de déformer. » Les *Entretiens sur la pluralité des mondes* échappent-ils à ce risque ?\n\nTu t’appuieras sur le dispositif du dialogue, les notions enseignées, les images (opéra, vaisseau, horloge, voisins), le ton galant et la prudence de Fontenelle. Tu montreras enfin en quoi l’ouvrage annonce les Lumières.","bareme":[{"critere":"Problématique claire sur la tension accessibilité / exactitude","points":3},{"critere":"Le dialogue : objections de la marquise, progression par étapes, chemin rendu visible","points":4},{"critere":"Les images analysées, notamment l’opéra (effets et machines), et leur limite possible","points":5},{"critere":"Prudence : hypothèses et non vérités assénées (pluralité des mondes comme conjecture) ; ton galant comme stratégie","points":5},{"critere":"Ouverture sur les Lumières : diffuser les savoirs contre les préjugés","points":3}],"dureeMin":20,"corrige":"**Introduction** : en 1686, Fontenelle écrit pour un public mondain l’astronomie de Copernic. Problématique : peut-on rendre la science accessible sans la trahir ?\n\n**I. Simplifier : les moyens de l’accessibilité.** Le **dialogue** sur six soirs fait progresser par étapes ; la marquise pose les **objections** du lecteur. Les **images** rendent les notions familières : l’**opéra** (le spectateur voit les effets, le philosophe cherche les machines et les cordes derrière le décor), la Terre comme **vaisseau** (le mouvement qu’on ne sent pas), l’univers comme **horloge** (un mécanisme réglé), les autres mondes comme **voisins** pas encore visités. Le ton **galant** retient un public exclu du latin.\n\n**II. Le risque de déformer.** Une analogie n’est pas une preuve ; l’image peut faire croire qu’on a compris ce qu’on a seulement visualisé. L’idée de **mondes habités** pourrait passer pour une certitude.\n\n**III. La réponse de Fontenelle : dialogue et prudence.** Le **dialogue** corrige la simplification : la marquise objecte, le philosophe reprend. La **prudence** est une méthode : la pluralité des mondes est une **conjecture raisonnable, jamais un dogme** ; Fontenelle propose des hypothèses, non des vérités assénées. Le badinage est une **stratégie de diffusion**, pas une faiblesse ; il a une portée **politique** : la science n’est pas réservée aux savants.\n\n**Conclusion** : l’œuvre n’échappe pas totalement au risque, mais elle le maîtrise en montrant le **chemin** plutôt que le résultat. Elle annonce les Lumières : **diffuser les savoirs est déjà une manière de combattre les préjugés**."}$exo$::jsonb),
  ('b361d7d1-33bc-5fa5-9659-c55bb6cde75f'::uuid, 1, 'redaction', $exo${"titre":"L’histoire de Zilia","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit les *Lettres d’une Péruvienne* ? En quelles années paraissent la première édition et l’édition augmentée ? À quel genre romanesque l’œuvre appartient-elle ?\n2. Résume le destin de **Zilia** jusqu’à son arrivée en France (Aza, les conquistadors, les Français, Déterville).\n3. Sur quoi écrit-elle ses premières lettres, puis en quelle langue ?\n4. Comment le roman se termine-t-il ?","bareme":[{"critere":"Françoise de Graffigny, 1747 et 1752, roman épistolaire","points":4},{"critere":"Étapes justes : promise à Aza, enlevée le jour des noces, capturée en mer par des Français, recueillie par Déterville","points":7},{"critere":"Quipus puis français ; dénouement : refus des deux prétendants, choix de l’amitié et de l’étude","points":9}],"dureeMin":7,"corrige":"1. **Françoise de Graffigny** ; première édition en **1747**, édition augmentée en **1752**. C’est un **roman épistolaire**, l’un des plus grands succès du siècle.\n2. **Zilia**, jeune Inca promise à **Aza**, est enlevée par les **conquistadors** le jour de ses noces ; en mer, elle est capturée par des **Français** ; en France, elle est recueillie par le chevalier **Déterville**. Elle ignore tout : langue, usages, religion, place des femmes.\n3. Elle écrit d’abord sur des **quipus**, cordelettes nouées des Incas ; quand ils sont épuisés, elle écrit **en français**, qu’elle a appris.\n4. Aza, retrouvé, s’est converti et va épouser une Espagnole ; Déterville l’aime et espère. Zilia **refuse les deux** : elle choisit l’**amitié**, l’**étude** et la retraite dans la maison offerte par Déterville. Ce refus du mariage est impensable dans le roman de l’époque."}$exo$::jsonb),
  ('b361d7d1-33bc-5fa5-9659-c55bb6cde75f'::uuid, 2, 'redaction', $exo${"titre":"Une étrangère regarde l’éducation des filles","consigne":"Lis cette lettre, écrite pour l’exercice à la manière de Graffigny (ce n’est pas le texte du roman), puis réponds en citant.","enonce":"> « Ici, mon cher Aza, on apprend aux filles à danser, à chanter, à se tenir droites devant un miroir et à parler de ce qu’elles ignorent. On ne leur apprend ni à penser ni à juger. Quand elles ont grandi, on s’étonne qu’elles n’aient que des ornements dans l’esprit, et on les méprise pour ce qu’on a fait d’elles. J’ai demandé à une dame pourquoi on ne leur enseignait pas les sciences : elle a ri, comme si j’avais demandé qu’on apprenne aux oiseaux à nager. »\n\n1. Montre que ce texte utilise le **regard étranger**. Qu’est-ce qui permet à Zilia de « tout décrire » ?\n2. Quelle **critique** est portée ? Relève deux procédés qui la rendent frappante.\n3. En quoi l’acte même d’**écrire** cette lettre montre-t-il que Zilia apprend ? Appuie-toi sur les trois étapes du cours.","bareme":[{"critere":"Regard étranger : elle ne comprend pas les usages, donc les décrit sans l’excuse de l’habitude","points":5},{"critere":"Critique de l’éducation des femmes réduite aux ornements, privée de savoir","points":5},{"critere":"Deux procédés relevés et analysés (énumération, antithèse, paradoxe du mépris, comparaison des oiseaux)","points":5},{"critere":"Récit d’apprentissage : écrire pour survivre, comprendre, exister par soi-même","points":5}],"dureeMin":12,"corrige":"1. Zilia est une étrangère qui **ignore les usages** : ne rien comprendre lui permet de **tout décrire sans l’excuse de l’habitude**. Elle rapporte naïvement ce qu’elle voit et la réaction de la dame (« elle a ri »), ce qui rend la coutume française **absurde vue du dehors**.\n2. La lettre critique l’**éducation des femmes**, **réduite à des ornements** et **privée de savoir** (« ni à penser ni à juger », « que des ornements dans l’esprit »). Procédés : l’**énumération** des talents inutiles (danser, chanter, se tenir droites devant un miroir) ; l’**antithèse** entre ce qu’on leur apprend et ce qu’on leur refuse ; le **paradoxe** : on les méprise « pour ce qu’on a fait d’elles », ce qui retourne l’accusation contre la société ; la **comparaison** avec les oiseaux, qui montre que le refus paraît « naturel » aux Français alors qu’il est un choix.\n3. Écrire, pour Zilia, c’est d’abord **survivre**, puis **comprendre**, enfin **exister par soi-même**. Ici, elle **juge** : elle ne se contente plus de décrire, elle analyse et critique. La lettre montre une femme qui s’en sort **par le langage**, exactement ce que la société refuse aux Françaises."}$exo$::jsonb),
  ('b361d7d1-33bc-5fa5-9659-c55bb6cde75f'::uuid, 3, 'redaction', $exo${"titre":"Plus qu’une satire","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur l’œuvre telle que le cours la présente.","enonce":"**Sujet.** Les *Lettres d’une Péruvienne* ne sont-elles qu’une **satire** de la société française ?\n\nTu analyseras le regard étranger et ses cibles, le récit d’apprentissage de Zilia, le dénouement et le rôle de la forme épistolaire.","bareme":[{"critere":"Problématique et plan : satire, puis construction d’un sujet féminin autonome","points":3},{"critere":"La satire : regard étranger et ses cibles (miroirs, carrosses, religion, politesse, éducation des femmes)","points":5},{"critere":"Le récit d’apprentissage en trois étapes : survivre, comprendre, exister par soi-même","points":4},{"critere":"Le dénouement sans mariage analysé comme le geste le plus radical","points":4},{"critere":"Rôle de la forme épistolaire qui unit les deux visées ; conclusion","points":4}],"dureeMin":20,"corrige":"**Introduction** : le roman de Françoise de Graffigny (1747) fait décrire la France par une jeune Inca. Problématique : l’œuvre se contente-t-elle de critiquer, ou construit-elle autre chose ?\n\n**I. Une satire par le regard étranger.** Zilia, qui ignore tout, décrit **sans l’excuse de l’habitude**. Les **miroirs** et les carrosses dévoilent la **vanité** ; les rites **religieux**, l’**hypocrisie** ; la **politesse mondaine**, la **superficialité** ; l’**éducation des femmes**, réduite à des ornements et **privée de savoir** : c’est la charge la plus directe du livre.\n\n**II. Un récit d’apprentissage.** Le roman suit une héroïne qui apprend : écrire est d’abord **survivre** (les quipus), puis **comprendre** (le français appris), enfin **exister par soi-même**. La critique ne vient pas d’une étrangère figée mais d’une conscience qui se forme.\n\n**III. Un dénouement radical.** Aza, converti, va épouser une Espagnole ; Déterville espère. Zilia **refuse les deux** et choisit l’**amitié**, l’**étude** et la retraite. Dans le roman de l’époque, l’héroïne finit **mariée ou morte** : ce refus est **impensable** et c’est le geste le plus radical du livre.\n\n**IV. (ou en synthèse) La forme épistolaire.** Elle fait tenir ensemble la **satire** de la société d’accueil et la **construction d’un sujet féminin autonome** : la lettre est à la fois regard sur les autres et parole à soi.\n\n**Conclusion** : non, l’œuvre n’est pas qu’une satire. Elle ne se contente pas de **critiquer** la condition des femmes : elle **montre une femme qui, page après page, s’en sort par le langage**."}$exo$::jsonb),
  ('cc899fa0-5d9d-54ab-8133-bc73f95e75b6'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire du récit","consigne":"Réponds à chaque question par une définition précise.","enonce":"1. Définis les trois types de **narrateurs** : interne, externe, omniscient.\n2. Définis les trois **focalisations** : interne, zéro, externe.\n3. Associe chaque procédé à sa définition : **sommaire**, **scène**, **ellipse**, **pause**, **analepse**, **prolepse**.\n   - a. On saute un moment de l’histoire.\n   - b. Retour en arrière.\n   - c. Le temps du récit épouse celui de l’histoire.\n   - d. Beaucoup de temps résumé en peu de lignes.\n   - e. Annonce de l’avenir.\n   - f. La description arrête l’action.\n4. Qu’est-ce qu’un récit **enchâssé** ?","bareme":[{"critere":"Narrateurs et focalisations définis sans confusion","points":8},{"critere":"Les six procédés correctement associés","points":8},{"critere":"Récit enchâssé défini et son effet (distance, fiabilité du témoin)","points":4}],"dureeMin":8,"corrige":"1. Narrateur **interne** : il dit « je », il est personnage. Narrateur **externe** : il n’est pas personnage de l’histoire. Narrateur **omniscient** : il entre dans les consciences et sait tout.\n2. Focalisation **interne** : on voit par les yeux d’un personnage. Focalisation **zéro** : savoir total. Focalisation **externe** : on filme du dehors, sans entrer dans les consciences.\n3. Sommaire = **d** ; scène = **c** ; ellipse = **a** ; pause = **f** ; analepse = **b** ; prolepse = **e**.\n4. Un récit **enchâssé** est un récit rapporté à l’intérieur d’un autre récit. Il installe une **distance** et pose la question de la **fiabilité du témoin**."}$exo$::jsonb),
  ('cc899fa0-5d9d-54ab-8133-bc73f95e75b6'::uuid, 2, 'redaction', $exo${"titre":"Le retour de Julien","consigne":"Lis cet extrait (texte écrit pour l’exercice), puis réponds en citant.","enonce":"> Les trois années qui suivirent passèrent sans que Julien revît la mer : il apprit le métier de son oncle, perdit sa mère, se maria. Puis, un matin d’octobre, il reprit la route de Dieppe. Il marchait vite. Le vent lui fouettait le visage, et il sentait monter en lui, à chaque pas, la peur de ne rien reconnaître. Il se souvint soudain du jour où, enfant, il avait vu partir le bateau de son père. « Tu reviendras ? » avait-il crié. Personne ne lui avait répondu.\n\n1. Qui raconte ? Justifie. Quelle **focalisation** domine dans la seconde partie ? Relève un indice.\n2. Relève un **sommaire** et une **analepse**.\n3. Compare le temps de l’histoire et le temps du récit : qu’est-ce que le texte **résume**, qu’est-ce qu’il **étire** ? Qu’en conclure ?","bareme":[{"critere":"Narrateur externe (troisième personne) et focalisation interne sur Julien justifiée par un indice","points":6},{"critere":"Sommaire (trois années en une phrase) et analepse (le souvenir d’enfance) relevés","points":6},{"critere":"Comparaison des durées : trois ans résumés, le retour étiré ; ce qui est étiré est jugé important","points":6},{"critere":"Citations exactes","points":2}],"dureeMin":11,"corrige":"1. Le récit est à la **troisième personne** : le narrateur est **externe**, il n’est pas personnage. Dans la seconde partie, la focalisation est **interne** : on accède aux sensations et aux pensées de Julien (« il sentait monter en lui… la peur de ne rien reconnaître », « Il se souvint »).\n2. **Sommaire** : « Les trois années qui suivirent passèrent… il apprit le métier de son oncle, perdit sa mère, se maria » : trois ans et trois événements majeurs en une phrase. **Analepse** : « Il se souvint soudain du jour où, enfant, il avait vu partir le bateau de son père » : retour en arrière, avec une courte **scène** dialoguée (« Tu reviendras ? »).\n3. Le texte **résume** trois années et des événements pourtant importants (un deuil, un mariage), mais **étire** une seule matinée de marche et un souvenir. **Ce qu’un roman étire, il le juge important** : le cœur du passage est le retour vers la mer et la blessure de l’enfance (le père parti sans réponse), plus que la vie sociale de Julien."}$exo$::jsonb),
  ('cc899fa0-5d9d-54ab-8133-bc73f95e75b6'::uuid, 3, 'redaction', $exo${"titre":"Pourquoi le roman aime-t-il les personnages en marge ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) avec les connaissances du cours.","enonce":"**Sujet.** « Le roman a très tôt cherché ses figures hors des normes. » Pourquoi, selon vous, le roman choisit-il si souvent des personnages en marge, et comment le lecteur doit-il les lire ?\n\nTu t’appuieras sur les grandes étapes de l’histoire du roman, sur les outils d’analyse du personnage (actes, paroles, portrait et nom, regard du narrateur) et sur les choix de narration (qui raconte, d’où, quand).","bareme":[{"critere":"Problématique claire, plan annoncé","points":3},{"critere":"Grandes étapes du roman situées (Moyen Âge, XVIIe, XVIIIe, XIXe, XXe-XXIe) avec auteurs ou œuvres","points":5},{"critere":"Raison du choix : rendre visible ce que la société veut ignorer ; figures (criminels, courtisanes, déclassés, antihéros)","points":4},{"critere":"Méthode de lecture : actes, paroles, portrait et nom, regard du narrateur ; rôle de la narration (récit rétrospectif, enchâssé)","points":5},{"critere":"Conclusion : on ne juge pas moralement, on demande ce que le récit fait du personnage","points":3}],"dureeMin":20,"corrige":"**Introduction** : né en vers au Moyen Âge, le roman s’est souvent tourné vers des personnages **hors des normes**. Problématique : pourquoi ce choix, et comment lire ces personnages sans les juger ?\n\n**I. Un genre qui se transforme.** Moyen Âge : roman en **vers**, chevaleresque et courtois (Chrétien de Troyes). XVIIe : roman d’**analyse** (*La Princesse de Clèves*). XVIIIe : **mémoires** et **lettres fictives** donnent l’illusion du vrai (*Manon Lescaut*, *Les Liaisons dangereuses*). XIXe : **réalisme** (Balzac, Stendhal, Flaubert) puis **naturalisme** (Zola), science de la société. XXe-XXIe : le récit se **fragmente** (Proust, Céline, Nouveau Roman), puis le **récit intime** revient (Colette, Duras, Ernaux).\n\n**II. Pourquoi la marge.** Héros, **antihéros**, personnages **en marge** — criminels, courtisanes, déclassés — **rendent visible ce que la société veut ignorer**. Le roman, qui se veut parfois science de la société, trouve dans la marge le révélateur des normes.\n\n**III. Comment les lire.** Par leurs **actes** (ce qu’ils font, pas ce qu’ils disent faire), leurs **paroles** (registre, adresse, silences), leur **portrait** et leur **nom** (jamais neutres), et surtout **la manière dont le narrateur en parle** : c’est là que se cache le jugement. La narration compte : un récit **rétrospectif** comme celui de Des Grieux, ou **enchâssé**, pose la question de la **fiabilité du témoin**. La **durée** aussi : ce qu’un roman étire, il le juge important.\n\n**Conclusion** : le personnage en marge éclaire la société qui l’exclut. Une dissertation **ne juge jamais un personnage moralement** : elle demande **ce que le récit fait de lui**."}$exo$::jsonb),
  ('5543e7c3-0644-5939-90a1-25a6911df05c'::uuid, 1, 'redaction', $exo${"titre":"Un récit dans un récit","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Donne le **titre complet** du roman, son auteur et sa date. Quel est le **parcours associé** ?\n2. Qui est le **narrateur premier** ? Où croise-t-il Manon, puis où retrouve-t-il Des Grieux ?\n3. Qui raconte donc l’essentiel du roman, et **quand** ?\n4. Pourquoi est-ce « le point à ne jamais oublier » ?","bareme":[{"critere":"Titre complet, abbé Prévost, 1731, parcours « personnages en marge, plaisirs du romanesque »","points":6},{"critere":"Renoncour, Pacy (convoi de déportées), Calais deux ans plus tard","points":6},{"critere":"Des Grieux raconte à la première personne, après coup ; Manon vue par l’homme qui l’aime et se justifie","points":8}],"dureeMin":6,"corrige":"1. *Histoire du chevalier Des Grieux et de Manon Lescaut*, de l’**abbé Prévost**, publiée en **1731**. Parcours : **« personnages en marge, plaisirs du romanesque »**.\n2. Le narrateur premier est le **marquis de Renoncour**. Il croise à **Pacy** un convoi de filles qu’on **déporte en Amérique**, parmi lesquelles Manon ; **deux ans plus tard, à Calais**, il retrouve Des Grieux et recueille son récit.\n3. Tout le roman est **la parole de Des Grieux**, à la **première personne**, **après coup** (récit rétrospectif, enchâssé dans celui de Renoncour).\n4. Nous ne voyons Manon **que par les yeux de l’homme qui l’aime et qui se justifie** : Manon n’est jamais analysée de l’intérieur, et le récit de Des Grieux n’est pas neutre."}$exo$::jsonb),
  ('5543e7c3-0644-5939-90a1-25a6911df05c'::uuid, 2, 'redaction', $exo${"titre":"Reconstituer la chute","consigne":"Remets les épisodes dans l’ordre, puis réponds aux questions en t’appuyant sur le cours.","enonce":"Voici cinq épisodes du récit de Des Grieux, dans le désordre :\n- **A.** Manon vient l’arracher à Saint-Sulpice le jour de sa thèse.\n- **B.** Après l’escroquerie de G… M…, il est enfermé à Saint-Lazare, elle à l’Hôpital.\n- **C.** À Amiens, il rencontre Manon qu’on envoie au couvent, et ils s’enfuient.\n- **D.** Au désert de Louisiane, Manon meurt ; il l’enterre de ses mains.\n- **E.** À Paris, la misère arrive ; Manon accepte la protection de M. de B…\n\n1. Remets les épisodes dans l’ordre chronologique.\n2. Quel âge a Des Grieux au début, et à quoi était-il promis ?\n3. Quel est le rôle de **Tiberge** ? Pourquoi le cours dit-il qu’il est « toujours écouté, jamais suivi » ?\n4. Comment Des Grieux présente-t-il sa propre déchéance ? Qu’est-ce que cela révèle ?","bareme":[{"critere":"Ordre juste : C, E, A, B, D","points":5},{"critere":"Dix-sept ans, promis à l’ordre de Malte","points":3},{"critere":"Tiberge : ami fidèle, voix de la morale, jamais suivi","points":5},{"critere":"Déchéance présentée comme une fatalité ; lecture critique d’un narrateur qui se justifie","points":7}],"dureeMin":11,"corrige":"1. **C** (Amiens, rencontre et fuite) → **E** (Paris, misère, M. de B…, Des Grieux trahi entre à Saint-Sulpice) → **A** (Manon l’arrache à sa vocation le jour de sa thèse ; vie de jeu avec Lescaut) → **B** (escroquerie de G… M…, Saint-Lazare et l’Hôpital, évasion, mort de Lescaut) → **D** (Louisiane : paix, duel avec Synnelet, fuite au désert, mort de Manon).\n2. Des Grieux a **dix-sept ans** ; il est promis à l’**ordre de Malte**.\n3. **Tiberge** est l’**ami fidèle**, la **voix de la morale** : il avertit, aide, conseille. Des Grieux l’écoute mais retombe toujours dans sa passion : il est **toujours écouté, jamais suivi**.\n4. Des Grieux, noble, brillant, sincère, est aussi **menteur, tricheur, voleur, presque assassin**. Il raconte sa déchéance en la présentant comme une **fatalité** : la passion l’aurait entraîné malgré lui. Cela révèle un **narrateur qui se justifie** : le lecteur doit lire le récit à distance, puisque tout passe par sa parole rétrospective."}$exo$::jsonb),
  ('5543e7c3-0644-5939-90a1-25a6911df05c'::uuid, 3, 'redaction', $exo${"titre":"Le plaisir du romanesque empêche-t-il de juger ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur Manon Lescaut tel que le cours le présente.","enonce":"**Sujet.** « Le récit tient par une accélération constante, qui ne laisse jamais le temps de juger. » Dans quelle mesure *Manon Lescaut* empêche-t-il le lecteur de juger ses personnages ?\n\nTu t’appuieras sur le dispositif narratif (récit enchâssé, rétrospectif), sur les personnages (Des Grieux, Manon, Tiberge) et sur les ressorts du romanesque.","bareme":[{"critere":"Problématique et plan annoncé","points":3},{"critere":"Le romanesque analysé : coups de théâtre, évasions, duels, déguisements, exil, accélération","points":5},{"critere":"Le dispositif : parole de Des Grieux après coup, Manon jamais vue de l’intérieur, fatalité invoquée","points":5},{"critere":"Les indices qui permettent malgré tout de juger : actes de Des Grieux, voix de Tiberge, récit enchâssé","points":4},{"critere":"Conclusion nuancée qui répond au sujet","points":3}],"dureeMin":20,"corrige":"**Introduction** : le roman de l’abbé Prévost (1731) raconte une passion faite de fautes. Problématique : le lecteur, emporté, peut-il encore juger ?\n\n**I. Un romanesque qui emporte.** Coups de théâtre, évasions, duels, déguisements, larmes, exil, mort au désert : Amiens, Paris, Saint-Sulpice, Saint-Lazare, la Louisiane. Le récit tient par une **accélération constante** : c’est le « plaisir du romanesque » du parcours, qui ne laisse pas le temps de s’arrêter pour condamner.\n\n**II. Un dispositif qui désarme le jugement.** Tout le roman est **la parole de Des Grieux**, après coup : il présente sa déchéance comme une **fatalité**. Manon n’est **jamais analysée de l’intérieur** : insaisissable, tendre et infidèle, incapable de supporter la pauvreté, elle échappe au lecteur. On ne la voit que par les yeux de l’homme qui l’aime et se justifie.\n\n**III. Mais le texte donne de quoi juger.** Les **actes** parlent plus que le discours : Des Grieux est menteur, tricheur, voleur, presque assassin. **Tiberge**, voix de la morale, toujours écouté et jamais suivi, offre un contrepoint. Le **récit enchâssé** (Renoncour recueille le récit) installe une distance et pose la question de la **fiabilité du témoin**. Enfin, il ne s’agit pas de juger moralement mais de voir **ce que le récit fait du personnage** : un personnage **en marge** qui rend visible ce que la société veut ignorer.\n\n**Conclusion** : le romanesque retarde le jugement sans l’abolir ; le lecteur attentif lit à travers la parole de Des Grieux."}$exo$::jsonb),
  ('5e533eb3-48e0-5a8e-82e7-10fc36ceea98'::uuid, 1, 'redaction', $exo${"titre":"Le talisman de Raphaël","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. En quelle année paraît *La Peau de chagrin* ? Dans quel ensemble de *La Comédie humaine* ? Quel est le parcours associé ?\n2. Nomme les **trois parties** du roman et résume chacune en une phrase.\n3. Quel est le **pacte** de la peau ?\n4. Recopie l’**inscription** de la peau telle que le cours la donne.","bareme":[{"critere":"1831, Études philosophiques, parcours « les romans de l’énergie : création et destruction »","points":5},{"critere":"Les trois parties nommées et résumées justement","points":8},{"critere":"Pacte (exauce, rétrécit, la vie avec) et inscription exacte","points":7}],"dureeMin":7,"corrige":"1. **1831** ; le roman ouvre les **Études philosophiques** de *La Comédie humaine*. Parcours : **« les romans de l’énergie : création et destruction »**.\n2. **Le Talisman** : Raphaël de Valentin, ruiné, perd son dernier napoléon au jeu et va se noyer ; il entre chez un antiquaire qui lui montre une peau d’onagre. **La Femme sans cœur** : récit rétrospectif de sa vie d’étudiant pauvre, du travail acharné, de l’amour pour Fœdora, de la ruine. **L’Agonie** : devenu riche, il voit la peau rétrécir, tente de ne plus rien vouloir ; Pauline réapparaît ; en la désirant, il meurt.\n3. La peau **exauce tous les souhaits**, mais elle **rétrécit à chaque vœu**, et la vie de son possesseur avec elle.\n4. « **Si tu me possèdes, tu posséderas tout, mais ta vie m’appartiendra.** »"}$exo$::jsonb),
  ('5e533eb3-48e0-5a8e-82e7-10fc36ceea98'::uuid, 2, 'redaction', $exo${"titre":"Les figures autour de Raphaël","consigne":"Réponds en rédigeant, avec le vocabulaire du cours.","enonce":"1. Associe chaque personnage à ce qu’il représente, en une phrase chacun : **Raphaël de Valentin**, **Fœdora**, **Pauline**, **l’antiquaire**, **Rastignac**.\n2. Pourquoi le cours dit-il que l’antiquaire est « le **contre-modèle exact** » de Raphaël ?\n3. Juste après avoir saisi la peau, Raphaël souhaite un banquet et le trouve en sortant. Pourquoi le cours dit-il que « le piège est refermé dans la même page » ?\n4. Qu’appelle-t-on ici **réalisme fantastique** ? Donne deux lieux de Paris minutieusement décrits.","bareme":[{"critere":"Les cinq personnages justement caractérisés","points":6},{"critere":"L’antiquaire : survie par l’absence de désir, opposé à Raphaël","points":4},{"critere":"Le banquet : premier vœu exaucé, le pacte déjà en marche","points":4},{"critere":"Réalisme fantastique défini (objet impossible dans un monde documenté) avec deux lieux justes","points":6}],"dureeMin":12,"corrige":"1. **Raphaël** : l’intelligence et l’ambition, **brûlées par l’envie de vivre**. **Fœdora** : « la femme sans cœur », la société parisienne **séduisante et vide**. **Pauline** : l’amour désintéressé, **longtemps ignoré parce que pauvre**. **L’antiquaire** : le vieillard qui a survécu **en ne désirant rien**. **Rastignac** : l’ami cynique qui enseigne l’art de réussir.\n2. L’antiquaire a vécu longtemps parce qu’il **ne désire rien** ; Raphaël, lui, veut tout et en meurt. Il incarne exactement l’inverse de la conduite du héros.\n3. Le premier souhait (le banquet, offert par ses amis) est exaucé aussitôt : Raphaël a déjà utilisé la peau et commencé à **payer de sa vie**. Le pacte fonctionne dès le premier désir, sans délai : le héros est pris.\n4. Le **réalisme fantastique** place un **objet impossible** (le talisman, emprunté au conte) dans un **monde parfaitement documenté**, ce qui rend la fable **d’autant plus dure**. Lieux : la maison de jeu du **Palais-Royal**, le **magasin d’antiquités**, l’orgie chez **Taillefer**, les **salles de rédaction** (deux suffisent)."}$exo$::jsonb),
  ('5e533eb3-48e0-5a8e-82e7-10fc36ceea98'::uuid, 3, 'redaction', $exo${"titre":"Une fable d’autant plus dure","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en t’appuyant sur le cours.","enonce":"**Sujet.** « Si tu me possèdes, tu posséderas tout, mais ta vie m’appartiendra. »\n\nEn quoi cette inscription contient-elle toute la loi de *La Peau de chagrin* ? Montre comment la structure en trois parties, le système des personnages et le mélange du fantastique et du réalisme la mettent en œuvre.","bareme":[{"critere":"Inscription expliquée : posséder et vivre s’excluent ; « vouloir, c’est vivre ; vivre, c’est se consumer »","points":5},{"critere":"Structure en trois parties reliée au mécanisme (avant, pendant, fin du pacte)","points":4},{"critere":"Personnages organisés autour du désir : Raphaël, l’antiquaire contre-modèle, Fœdora et Pauline","points":5},{"critere":"Réalisme fantastique analysé : un objet impossible dans un Paris documenté rend la fable plus dure","points":4},{"critere":"Organisation et conclusion","points":2}],"dureeMin":18,"corrige":"**Introduction** : *La Peau de chagrin* (1831) repose sur un pacte gravé sur une peau d’onagre. Problématique : comment cette phrase commande-t-elle tout le roman ?\n\n**I. La loi du pacte.** La peau exauce **tous** les souhaits (« tu posséderas tout ») mais **rétrécit à chaque vœu**, et la vie avec elle (« ta vie m’appartiendra »). La loi : **vouloir, c’est vivre ; vivre, c’est se consumer**. Désirer et durer deviennent incompatibles.\n\n**II. Une structure qui déroule la loi.** **Le Talisman** : ruiné, Raphaël va se noyer ; il saisit la peau et souhaite un banquet, qu’il trouve aussitôt : le piège se referme dans la même page. **La Femme sans cœur** : le récit rétrospectif explique d’où vient ce désir (l’étudiant pauvre, le travail, Fœdora, la ruine). **L’Agonie** : riche, Raphaël tente de **ne plus rien vouloir** ; Pauline revient ; en la désirant, il meurt.\n\n**III. Des personnages placés par rapport au désir.** Raphaël, l’ambition **brûlée par l’envie de vivre** ; l’**antiquaire**, survivant parce qu’il ne désire rien, **contre-modèle exact** ; **Fœdora**, la société séduisante et vide qui attise un désir vain ; **Pauline**, l’amour désintéressé, longtemps ignoré parce que pauvre, dont le désir est fatal ; **Rastignac**, l’art cynique de réussir.\n\n**IV. (ou en synthèse) Le réalisme fantastique.** Le talisman, emprunté au conte, évolue dans un Paris **minutieusement décrit** (maison de jeu du Palais-Royal, magasin d’antiquités, orgie chez Taillefer, salles de rédaction). Parce que le monde est vrai, la fable est **d’autant plus dure** : elle parle de notre réalité.\n\n**Conclusion** : l’inscription est la loi du roman ; chaque partie, chaque personnage et chaque décor la vérifient."}$exo$::jsonb),
  ('268285b6-96b8-59a5-92b8-fb6eded739ca'::uuid, 1, 'redaction', $exo${"titre":"Vouloir, pouvoir, savoir","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Par la bouche de quel personnage Balzac formule-t-il la thèse du roman ?\n2. Complète : **VOULOIR** … ; **POUVOIR** … ; **SAVOIR** … (donne l’effet de chaque verbe sur la vie).\n3. Montre en deux phrases comment la vie de Raphaël passe du **savoir** au **vouloir**.\n4. Le roman **condamne**-t-il l’énergie ? Justifie avec le cours.","bareme":[{"critere":"L’antiquaire ; les trois verbes et leurs effets justes (brûle, détruit, conserve)","points":8},{"critere":"Trajectoire de Raphaël : la mansarde et le travail, puis tout misé sur le désir","points":6},{"critere":"Le roman ne condamne pas l’énergie : elle ne se divise pas, génie et ruine ont la même source","points":6}],"dureeMin":7,"corrige":"1. Par la bouche de l’**antiquaire**.\n2. **VOULOIR** **brûle** la vie ; **POUVOIR** la **détruit** ; **SAVOIR** la **conserve** : « Vouloir nous brûle et Pouvoir nous détruit ; mais SAVOIR laisse notre faible organisation dans un perpétuel état de calme. »\n3. Jeune, Raphaël passe sa jeunesse à travailler dans une **mansarde** : c’est le temps du **savoir**. Puis il mise tout sur le **désir** (vouloir) : il meurt de n’avoir pas pu **s’empêcher de désirer**. Il apprend la leçon **trop tard**.\n4. **Non** : le roman ne condamne pas l’énergie, il montre qu’elle **ne se divise pas**. La même force pousse Raphaël à écrire une *Théorie de la volonté* (création) et à l’orgie, au jeu, à la passion (destruction) : **le génie et la ruine ont la même source**."}$exo$::jsonb),
  ('268285b6-96b8-59a5-92b8-fb6eded739ca'::uuid, 2, 'redaction', $exo${"titre":"Une énergie qui crée et qui détruit","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Classe ces actions de Raphaël en deux colonnes, **création** et **destruction** : écrire une *Théorie de la volonté* dans le dénuement ; jouer ; se jeter dans l’orgie ; aimer passionnément Fœdora ; travailler dans la mansarde.\n2. Que tente Raphaël pour ne plus faire rétrécir la peau ? Que font le **physicien**, le **chimiste** et le **mécanicien** ? Qu’en conclut Balzac sur la science moderne ?\n3. En quoi la société de **1830** ressemble-t-elle à Raphaël ?\n4. Relève deux **contrastes** par lesquels le roman avance.","bareme":[{"critere":"Classement juste : création (Théorie de la volonté, mansarde) ; destruction (jeu, orgie, Fœdora)","points":5},{"critere":"Mesurer la peau, ne plus rien vouloir ; échec des savants ; science impuissante","points":6},{"critere":"Société de 1830 : spéculation, arrivisme, journalisme, révolution industrielle, une époque qui se brûle","points":5},{"critere":"Deux contrastes justes (orgie/mansarde, Fœdora/Pauline, Paris/Auvergne)","points":4}],"dureeMin":11,"corrige":"1. **Création** : écrire une *Théorie de la volonté* dans le dénuement ; travailler dans la mansarde. **Destruction** : jouer ; se jeter dans l’orgie ; la passion pour Fœdora. C’est **la même force** qui pousse vers les deux.\n2. Raphaël **mesure la peau au crayon** (elle rétrécit quand même) et tente de **ne plus rien désirer**. Le **physicien**, le **chimiste**, le **mécanicien** **échouent tous** à l’étirer ou à l’altérer. Balzac fait de la **science moderne** un personnage **impuissant** : elle ne peut rien contre le destin.\n3. La société de 1830 vit de **spéculation**, d’**arrivisme**, de **journalisme**, de **révolution industrielle** : comme Raphaël, c’est **une époque qui se brûle à sa propre vitesse**.\n4. Contrastes : **l’orgie et la mansarde**, **Fœdora et Pauline**, **Paris et l’Auvergne** (deux suffisent)."}$exo$::jsonb),
  ('268285b6-96b8-59a5-92b8-fb6eded739ca'::uuid, 3, 'redaction', $exo${"titre":"Le désir, force de vie ou de mort ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) sur La Peau de chagrin telle que le cours la présente.","enonce":"**Sujet.** Dans *La Peau de chagrin*, le désir est-il une force de **vie** ou une force de **mort** ?\n\nTu t’appuieras sur la thèse de l’antiquaire (vouloir, pouvoir, savoir), sur la trajectoire de Raphaël, sur le rôle du fantastique et de la science, et sur l’image de la société de 1830. Tu pourras évoquer la question de la **liberté** du personnage.","bareme":[{"critere":"Problématique et plan qui refuse une réponse simple","points":3},{"critere":"Le désir comme force de vie et de création (Théorie de la volonté, envie de vivre)","points":4},{"critere":"Le désir comme force de mort : thèse de l’antiquaire, peau qui rétrécit, mort de Raphaël en désirant Pauline","points":5},{"critere":"L’énergie qui ne se divise pas ; échec des savants ; liberté perdue (il choisit la peau puis ne peut plus choisir)","points":5},{"critere":"Conclusion : le roman refuse de choisir, le désir est les deux","points":3}],"dureeMin":20,"corrige":"**Introduction** : dans le roman de Balzac, chaque désir fait rétrécir la peau et la vie de Raphaël. Problématique : le désir fait-il vivre ou fait-il mourir ?\n\n**I. Le désir fait vivre et créer.** Sans désir, pas d’énergie : c’est la même force qui pousse Raphaël, dans le dénuement de sa mansarde, à écrire une *Théorie de la volonté*. L’envie de vivre fait l’**intelligence et l’ambition** du héros. Vouloir, **c’est vivre**.\n\n**II. Le désir tue.** L’antiquaire le dit : « Vouloir nous brûle et Pouvoir nous détruit ; mais SAVOIR laisse notre faible organisation dans un perpétuel état de calme. » Chaque vœu fait rétrécir la peau ; Raphaël tente de ne plus rien vouloir, mais meurt en **désirant Pauline**. Le fantastique **rend visible un processus invisible** : l’usure de la vie par le désir. La science ne peut rien : le physicien, le chimiste, le mécanicien **échouent tous**. Vivre, **c’est se consumer**.\n\n**III. Une seule énergie.** Le roman **ne condamne pas** le désir : il montre qu’il **ne se divise pas**. Le génie et la ruine ont la **même source** ; la société de 1830 (spéculation, arrivisme) se brûle de la même façon. La liberté elle-même y est prise : Raphaël **choisit** la peau, puis ne peut **plus rien** choisir.\n\n**Conclusion** : le roman **refuse de choisir** : le désir est à la fois force de vie et force de mort, et c’est cette ambivalence qui fait la loi du « roman de l’énergie »."}$exo$::jsonb),
  ('6106cd81-6bc9-5c86-8240-d07a338b4574'::uuid, 1, 'redaction', $exo${"titre":"Deux livres réunis","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Quels sont les deux textes réunis dans le volume de Colette ? Donne leurs dates. Quel est le **parcours associé** ?\n2. Nomme les **trois parties** de *Sido* et la figure que porte chacune ; donne pour chacune un détail retenu par le cours.\n3. Pourquoi *Sido* n’est-il **ni un roman ni une autobiographie suivie** ?","bareme":[{"critere":"Les Vrilles de la vigne (1908), Sido (1930), parcours « la célébration du monde »","points":6},{"critere":"Les trois parties avec leur figure et un détail juste chacune","points":9},{"critere":"Récit de mémoire, non chronologique ni complet","points":5}],"dureeMin":7,"corrige":"1. *Les Vrilles de la vigne* (**1908**) et *Sido* (**1930**) : quinze ans les séparent. Parcours : **« la célébration du monde »**.\n2. **Sido** : la mère, **Sidonie Landoy** ; elle guette les orages, **sauve les chenilles**, connaît chaque plante, refuse de quitter son jardin même pour voir sa fille. **Le Capitaine** : le père, ancien militaire amputé, **poète sans œuvre** : à sa mort, ses volumes reliés sont **blancs**, sauf la dédicace à sa femme. **Les Sauvages** : les frères et la sœur, silencieux, indépendants, à peine domestiqués.\n3. Parce que c’est un **récit de mémoire** : Colette ne suit pas une chronologie complète, elle fait revivre des figures et des moments choisis."}$exo$::jsonb),
  ('6106cd81-6bc9-5c86-8240-d07a338b4574'::uuid, 2, 'redaction', $exo${"titre":"Écrire par les sens","consigne":"Lis ce passage, écrit pour l’exercice à la manière de Colette (ce n’est pas un texte de l’œuvre), puis réponds en citant.","enonce":"> Le jardin, après l’orage, sentait la terre ouverte, la feuille de noyer froissée et le chocolat que ma mère faisait tiédir sur le fourneau. Les pivoines lourdes penchaient leurs têtes mouillées ; une chenille rayée, que personne n’aurait osé écraser devant elle, remontait patiemment la tige d’un rosier. La chatte, assise sur le mur, observait tout cela avec la gravité d’une personne qui connaît le prix d’une belle journée.\n\n1. Relève des **notations sensorielles** : au moins une par sens (odorat, vue, toucher ou goût).\n2. Relève une **énumération** et dis son effet.\n3. Quelle place ont la **chenille** et la **chatte** ? Relie ta réponse à ce que le cours dit de l’animal chez Colette.\n4. Qui est le personnage évoqué par « devant elle » ? Qu’apprend-elle à sa fille ?","bareme":[{"critere":"Notations sensorielles relevées pour au moins trois sens, citations exactes","points":6},{"critere":"Énumération relevée (les odeurs) et effet expliqué (abondance, précision du concret)","points":4},{"critere":"L’animal a le même statut que l’humain : chatte grave, chenille qu’on respecte","points":5},{"critere":"Sido, la mère, qui sauve les chenilles et apprend à regarder ; ce regard devient un style","points":5}],"dureeMin":12,"corrige":"1. **Odorat** : « sentait la terre ouverte, la feuille de noyer froissée et le chocolat ». **Vue** : « les pivoines lourdes penchaient leurs têtes », « une chenille rayée ». **Toucher** : « têtes mouillées », « faisait tiédir ». **Goût** (suggéré) : le chocolat. Colette écrit par **sensations** ; les notations concrètes l’emportent sur l’abstraction.\n2. Énumération des odeurs : « la terre ouverte, la feuille de noyer froissée et le chocolat » : elle rend l’abondance du monde et sa **précision** ; la phrase est ample, rythmée par l’énumération.\n3. La chenille est **respectée** (personne n’ose l’écraser) ; la chatte est décrite comme **une personne** grave. Chez Colette, **l’animal a le même statut que l’humain** : c’est un être à part entière, pas un décor.\n4. « Devant elle » désigne la **mère**, **Sido**, qui **sauve les chenilles** et voue un **culte au vivant**. Elle transmet à sa fille l’**art de regarder** : c’est elle qui apprend à sa fille à regarder, et **ce regard deviendra un style**."}$exo$::jsonb),
  ('6106cd81-6bc9-5c86-8240-d07a338b4574'::uuid, 3, 'redaction', $exo${"titre":"Sido, personnage ou manière de voir ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur le cours.","enonce":"**Sujet.** Le cours affirme que Sido est « une manière de voir plus qu’une personne ». Discute cette affirmation.\n\nTu t’appuieras sur le portrait de Sido et sur ce qu’elle transmet, sur les deux autres figures de *Sido*, sur les textes des *Vrilles de la vigne* et sur les conditions d’écriture (Colette écrit à cinquante-sept ans, après la mort de sa mère).","bareme":[{"critere":"Problématique et plan annoncé","points":3},{"critere":"Sido comme personne : portrait concret (orages, chenilles, plantes, jardin qu’elle refuse de quitter)","points":4},{"critere":"Sido comme regard transmis : l’art de regarder, liberté, culte du vivant, devenu le style de Colette","points":5},{"critere":"Écriture des sens et place de l’animal dans les deux livres (Toby-Chien, Kiki-la-Doucette)","points":4},{"critere":"Acte de mémoire écrit du côté de la perte ; conclusion","points":4}],"dureeMin":20,"corrige":"**Introduction** : *Sido* (1930) porte le nom de la mère de Colette, Sidonie Landoy. Problématique : Colette fait-elle le portrait d’une femme, ou transmet-elle une façon de regarder le monde ?\n\n**I. Une personne bien réelle.** Sido est décrite par des gestes précis : elle **guette les orages**, **sauve les chenilles**, connaît chaque plante, **refuse de quitter son jardin** même pour voir sa fille. Elle est **indifférente aux convenances, à la religion, à l’argent**. Autour d’elle, le **Capitaine**, poète sans œuvre aux volumes blancs, et les **Sauvages**, à peine domestiqués.\n\n**II. Mais surtout un regard.** Sido est le personnage central des **deux** livres. Elle transmet l’**art de regarder**, attentive aux **signes du temps**, une **liberté**, et le **respect de ce qui pousse et de ce qui rampe**. C’est elle qui apprend à sa fille à regarder, et **ce regard deviendra un style** : une écriture par **sensations** (odeurs, couleurs, textures, bruits), des énumérations, des notations concrètes. Dans *Les Vrilles de la vigne*, l’animal a le même statut que l’humain : Toby-Chien et Kiki-la-Doucette dialoguent.\n\n**III. Un regard né de la perte.** Colette écrit *Sido* à **cinquante-sept ans**, longtemps après la mort de sa mère : c’est un **acte de mémoire**, écrit **du côté de la perte**. D’où la lumière du livre : **on ne célèbre bien que ce qu’on n’a plus**. Sido devient la source d’une écriture plus qu’un modèle à peindre.\n\n**Conclusion** : Sido est une personne, mais le livre la transforme en **manière de voir** ; c’est ainsi qu’elle survit, dans le style de sa fille."}$exo$::jsonb),
  ('e258a28c-4c3c-5fe8-aac0-14ba6ece8272'::uuid, 1, 'redaction', $exo${"titre":"Célébrer n’est pas embellir","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Pour Colette, **célébrer**, est-ce décrire ? Est-ce idéaliser ? Que faut-il faire à la place ? Donne un exemple du cours.\n2. Cite trois choses **célébrées** et trois choses **perdues** dans l’œuvre.\n3. Pourquoi *Les Vrilles de la vigne* est-il un livre important dans la **vie d’écrivaine** de Colette ?","bareme":[{"critere":"Célébrer = nommer avec exactitude, ni décrire ni idéaliser, exemple juste (souci, pivoine, angélique, pluie sur la poussière)","points":7},{"critere":"Trois choses célébrées et trois choses perdues justes","points":6},{"critere":"Premier livre signé « Colette » seule, après Willy, le music-hall et le divorce","points":7}],"dureeMin":7,"corrige":"1. Célébrer n’est **ni décrire, ni idéaliser** : c’est **nommer** avec exactitude. Colette n’écrit pas « une fleur » mais un **souci**, une **pivoine**, un pied d’**angélique** ; pas « le printemps » mais l’odeur exacte de la **première pluie sur la poussière chaude**. L’émerveillement naît de l’**exactitude** : c’est un lyrisme sans grandiloquence.\n2. **Célébrés** : le jardin, la maison, les saisons (et le père, les frères). **Perdus** : la **mère morte**, l’**enfance enfuie**, la **maison vendue** (et le père sans œuvre, les frères devenus silencieux).\n3. Colette a d’abord publié sous le nom de son mari, **Willy** ; elle est montée sur scène au **music-hall** pour vivre ; elle a **divorcé**. *Les Vrilles de la vigne* est le **premier livre signé « Colette » seule**."}$exo$::jsonb),
  ('e258a28c-4c3c-5fe8-aac0-14ba6ece8272'::uuid, 2, 'redaction', $exo${"titre":"Deux façons de dire un jardin","consigne":"Compare les deux phrases (écrites pour l’exercice), puis réponds en t’appuyant sur le cours.","enonce":"> **Phrase A** : « Oh ! le merveilleux jardin de mon enfance, paradis de fleurs et de parfums où tout était beauté ! »\n> **Phrase B** : « Au pied du mur, les soucis tenaient bon dans la poussière, et l’angélique sentait encore l’eau du matin. »\n\n1. Laquelle des deux phrases est écrite **à la manière de Colette** ? Justifie par deux différences précises.\n2. Pourquoi le cours dit-il que la lumière du livre tient à une **tension** ? Explique ce qu’on écrit « du côté de la perte ».\n3. Pourquoi le **rossignol** du texte liminaire des *Vrilles de la vigne* est-il une figure d’émancipation **autobiographique** ?","bareme":[{"critere":"Phrase B identifiée, justifiée par deux différences (noms précis contre mots vagues, concret contre effusion)","points":7},{"critere":"Tension entre ce qui est célébré et ce qui est perdu ; on regarde si bien parce qu’on a perdu","points":6},{"critere":"Rossignol qui chante pour ne plus être ligoté, relié au parcours de Colette (Willy, divorce, signature seule)","points":7}],"dureeMin":11,"corrige":"1. C’est la **phrase B**. La phrase A use de mots **vagues** et généraux (« fleurs », « parfums », « beauté ») et d’une **effusion** (« Oh ! », « merveilleux », « paradis ») : elle **idéalise**. La phrase B **nomme** avec exactitude (les **soucis**, l’**angélique**, le mur, la poussière) et donne une sensation précise (l’odeur de « l’eau du matin ») : l’émerveillement vient de l’**exactitude**, c’est un **lyrisme sans grandiloquence**, ancré dans le concret.\n2. Ce qui est célébré (le jardin, la maison, les saisons) est aussi ce qui est **perdu** (la mère morte, l’enfance enfuie, la maison vendue) ; dans *Les Vrilles de la vigne*, plusieurs textes disent l’insomnie, la tristesse, la séparation. On écrit **du côté de la perte** : c’est **pour cela qu’on regarde si bien**.\n3. Le rossignol, pris dans les vrilles de la vigne, **chante pour ne plus être ligoté**. Or Colette a publié d’abord sous le nom de **Willy**, puis a gagné son autonomie (music-hall, **divorce**) : *Les Vrilles de la vigne* est le **premier livre signé « Colette » seule**. Le chant de l’oiseau, c’est son écriture qui la libère."}$exo$::jsonb),
  ('e258a28c-4c3c-5fe8-aac0-14ba6ece8272'::uuid, 3, 'redaction', $exo${"titre":"Célébrer le monde, est-ce l’embellir ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur le cours.","enonce":"**Sujet.** « Célébrer le monde, est-ce l’embellir ? » Tu répondras en t’appuyant sur *Sido* et *Les Vrilles de la vigne*.\n\nTu examineras le travail de la précision, la place de la perte, le statut de l’animal et du végétal, la question de la **fidélité** du souvenir et la **double focale** de l’enfant et de l’adulte.","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"La précision remplace l’idéalisation : nommer, sensation exacte, lyrisme sans grandiloquence","points":5},{"critere":"La perte présente au cœur de la célébration (mère, enfance, maison, père sans œuvre)","points":4},{"critere":"Souvenir composé, sélectionné, inventé : vérité de la sensation ; double focale enfant/adulte","points":5},{"critere":"Vivant non humain comme société ; conclusion qui répond au sujet","points":3}],"dureeMin":20,"corrige":"**Introduction** : célébrer semble vouloir dire embellir. Problématique : la célébration chez Colette est-elle une idéalisation du passé ?\n\n**I. Célébrer n’est pas embellir : la précision.** Colette **nomme** : un souci, une pivoine, un pied d’angélique, l’odeur de la première pluie sur la poussière chaude. L’émerveillement naît de l’**exactitude**, non de l’effusion : **lyrisme sans grandiloquence**.\n\n**II. Une célébration qui ne cache pas la perte.** Le jardin, la maison, les saisons sont célébrés, mais la **mère est morte**, l’**enfance enfuie**, la **maison vendue**, le père est **sans œuvre**, les frères **silencieux** ; *Les Vrilles de la vigne* disent l’insomnie et la séparation. La lumière du livre tient à cette **tension** : on écrit du côté de la perte.\n\n**III. Pourtant, le souvenir est composé.** Colette **compose, sélectionne, invente** : le vrai y est de l’ordre de la **sensation**, non du document. Le regard de l’**enfant** et celui de l’**adulte** qui se souvient **se superposent** : cette double focale donne l’émotion. En ce sens, la célébration transforme, sans mentir.\n\n**IV. (ou en synthèse) Un monde élargi.** Le vivant non humain n’est pas un décor mais une **société** : Sido sauve une chenille, Colette prête la parole à ses bêtes ; geste **écologique avant la lettre**. C’est aussi un **art poétique** : le style naît d’une manière de regarder héritée de la mère.\n\n**Conclusion** : non, célébrer n’est pas embellir : c’est regarder avec précision ce qu’on va perdre ou qu’on a perdu ; le souvenir est recomposé, mais vrai par la sensation."}$exo$::jsonb),
  ('bb2441b0-6fb1-5b02-ba3d-00a6cb4949a1'::uuid, 1, 'redaction', $exo${"titre":"Les mots du théâtre","consigne":"Réponds à chaque question par une définition précise.","enonce":"1. Définis : **tirade**, **monologue**, **stichomythie**, **aparté**.\n2. Que sont les **didascalies** ?\n3. Qu’est-ce que la **double énonciation** ? Quel effet rend-elle possible ?\n4. Quelles sont les **trois unités** du théâtre classique ? Quelle autre règle les accompagne ?","bareme":[{"critere":"Tirade, monologue, stichomythie, aparté définis sans confusion","points":8},{"critere":"Didascalies et double énonciation définies ; ironie dramatique expliquée","points":7},{"critere":"Action, lieu, temps et la bienséance","points":5}],"dureeMin":7,"corrige":"1. **Tirade** : longue prise de parole (domination, plaidoyer). **Monologue** : un personnage seul en scène parle ; il dit ce qu’on cache. **Stichomythie** : échange de répliques très brèves qui s’enchaînent ; elle crée de la **tension**. **Aparté** : parole dite **au public**, censée ne pas être entendue de l’interlocuteur.\n2. Les **didascalies** sont les indications scéniques de l’auteur : lieu, ton, gestes.\n3. La **double énonciation** : ce qu’un personnage dit à un autre est **en même temps dit au public**. Elle rend possible l’**ironie dramatique** : le spectateur **en sait plus** que le personnage.\n4. Unité d’**action**, de **lieu**, de **temps** ; elles s’accompagnent de la **bienséance** (ne pas choquer le public)."}$exo$::jsonb),
  ('bb2441b0-6fb1-5b02-ba3d-00a6cb4949a1'::uuid, 2, 'redaction', $exo${"titre":"La scène de la clé","consigne":"Lis cette scène (écrite pour l’exercice), puis réponds en citant.","enonce":"*Un salon. LUCILE cache une clé dans sa main. Entre son père, M. BERNARD.*\n\n> M. BERNARD. — Tu es seule ?\n> LUCILE. — Seule.\n> M. BERNARD. — Personne n’est venu ?\n> LUCILE. — Personne.\n> M. BERNARD. — Et cette porte ouverte ?\n> LUCILE. — Le vent.\n> M. BERNARD, *s’approchant*. — Le vent a bon dos.\n> LUCILE, *à part*. — S’il ouvre ma main, tout est perdu.\n> M. BERNARD, *riant soudain*. — Allons, j’ai l’air d’un gendarme ! Garde tes secrets, ma fille.\n\n1. Relève une **stichomythie**, un **aparté** et deux **didascalies**. Quel est le rôle de chacun ?\n2. Montre que la scène crée une **ironie dramatique**.\n3. Où se situe le **basculement de registre** ? Qui a le pouvoir de la parole, et quand le perd-il ?","bareme":[{"critere":"Stichomythie, aparté et deux didascalies relevés avec leur rôle","points":7},{"critere":"Ironie dramatique expliquée par la double énonciation (le public sait pour la clé)","points":5},{"critere":"Basculement de la tension au comique repéré au rire du père","points":4},{"critere":"Analyse du pouvoir de la parole : le père interroge et domine, puis y renonce","points":4}],"dureeMin":12,"corrige":"1. **Stichomythie** : l’échange « Tu es seule ? / Seule. / Personne n’est venu ? / Personne. / … / Le vent. » : répliques très brèves qui créent la **tension** d’un interrogatoire. **Aparté** : « S’il ouvre ma main, tout est perdu » : Lucile parle **au public**, son père n’entend pas. **Didascalies** : « *Un salon. LUCILE cache une clé dans sa main* », « *s’approchant* », « *à part* », « *riant soudain* » : elles donnent le lieu, le geste décisif, le ton.\n2. Grâce à la **double énonciation**, le spectateur sait, par la didascalie initiale et l’aparté, que Lucile cache une clé et ment ; le père l’ignore. Le spectateur **en sait plus** que le personnage : c’est l’**ironie dramatique**.\n3. Le basculement a lieu au « *riant soudain* » : la tension presque **dramatique** retombe dans le **comique** (« j’ai l’air d’un gendarme ! »). Le père a d’abord le **pouvoir de la parole** : il pose les questions, Lucile ne répond que d’un mot. Il le **perd**, ou y renonce, quand il rit : Lucile garde son secret."}$exo$::jsonb),
  ('bb2441b0-6fb1-5b02-ba3d-00a6cb4949a1'::uuid, 3, 'redaction', $exo${"titre":"Une pièce n’existe pleinement que jouée","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) avec les connaissances du cours.","enonce":"**Sujet.** « Une pièce n’est pas un roman en dialogues : c’est une partition. » Expliquez et discutez cette affirmation en vous appuyant sur l’histoire du théâtre du XVIIe au XXIe siècle.\n\nTu mobiliseras : les formes de parole, les didascalies et la double énonciation, les genres (tragédie, comédie, drame romantique, théâtre du XXe), la structure d’une pièce et les registres. Tu montreras enfin comment un **choix de mise en scène** se justifie.","bareme":[{"critere":"Problématique claire et plan annoncé","points":3},{"critere":"Texte comme partition : formes de parole, didascalies (Sarraute, Corneille), double énonciation","points":5},{"critere":"Genres et leurs règles : tragédie classique, comédie, drame romantique, XXe (Beckett, Sarraute)","points":5},{"critere":"Structure et registres : basculements repérés, ressorts (quiproquo, aveu, dénouement)","points":4},{"critere":"Mise en scène justifiée par le texte ; conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : un texte de théâtre se lit, mais il est fait pour être dit, entendu et vu. Problématique : en quoi le texte théâtral appelle-t-il la scène ?\n\n**I. Un texte écrit pour des voix et des corps.** Les formes de parole (tirade, monologue, **stichomythie**, aparté) règlent le rythme et le rapport de force. Les **didascalies** indiquent lieu, ton, gestes : **cœur du texte** chez Sarraute, **presque absentes** chez Corneille. La **double énonciation** fait qu’on parle toujours aussi au public : d’où l’**ironie dramatique**.\n\n**II. Des genres qui pensent la scène.** La **tragédie classique** : personnages de haut rang, fatalité, mort, **trois unités** et **bienséance**. La **comédie** corrige les mœurs en faisant rire (comique de mots, gestes, situation, caractère, répétition). Le **drame romantique** (Hugo, Musset) refuse les règles et mêle les tons. Au **XXe**, plus d’intrigue chez Beckett, plus de personnage chez Sarraute : **la parole devient l’action**.\n\n**III. Une structure et des registres qui se jouent.** Exposition, nœud, péripéties, **coup de théâtre**, dénouement ; **quiproquo**, **scène d’aveu**, dénouement ouvert ou refermé. Les registres (comique, tragique, pathétique, lyrique, ironique, polémique) se mêlent : l’analyse repère le **moment exact** où le rire devient grinçant.\n\n**IV. (ou en synthèse) La mise en scène.** Décor, costumes, rythme, jeu des corps : une pièce **n’existe pleinement que jouée**. Mentionner un ton, un silence, un déplacement est valorisé **à condition de le justifier par le texte**.\n\n**Conclusion** : le texte théâtral est une partition ; lire une scène, c’est se demander **qui a le pouvoir de la parole, et qui le perd**."}$exo$::jsonb),
  ('b5767a1a-a811-556f-bd86-84d89e7326c4'::uuid, 1, 'redaction', $exo${"titre":"Les mensonges de Dorante","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit *Le Menteur* ? En quelle année, en combien d’actes, en vers ou en prose ? De quelle pièce s’inspire-t-il ?\n2. Cite **trois mensonges** de Dorante.\n3. Sur quel **quiproquo** repose l’intrigue ? Quel danger fait-il courir à Dorante ?\n4. Comment la pièce se **termine**-t-elle ? Pourquoi ce dénouement est-il discuté ?","bareme":[{"critere":"Corneille, 1644, cinq actes en vers, d’après La Verdad sospechosa d’Alarcón","points":5},{"critere":"Trois mensonges justes (héros de guerre, fête sur la Seine, déjà marié à Poitiers)","points":6},{"critere":"Quiproquo Clarice/Lucrèce et duel avec Alcippe ; dénouement : mariage avec Lucrèce, menteur ni puni ni corrigé","points":9}],"dureeMin":7,"corrige":"1. **Corneille**, l’auteur du *Cid*, en **1644** ; comédie en **cinq actes et en vers**, adaptée de *La Verdad sospechosa* de **Juan Ruiz de Alarcón**.\n2. Dorante se présente aux Tuileries comme un **héros de guerre** revenu d’Allemagne après quatre ans ; il invente une **fête somptueuse** offerte sur la Seine ; face au mariage préparé par son père Géronte, il se dit **déjà marié à Poitiers** (séduction, nuit surprise, grossesse).\n3. Dorante croit que celle qu’il aime, **Clarice**, s’appelle **Lucrèce**. Ce **quiproquo de noms** gouverne toute la pièce et manque de le faire **tuer en duel** par **Alcippe**, l’amoureux de Clarice.\n4. Démasqué par son père et humilié, Dorante **retombe sur ses pieds** : il aime en réalité la femme qui s’appelle bien Lucrèce, et il l’épouse. La comédie finit sur un mariage, mais le menteur n’est **ni puni, ni corrigé** : c’est le point le plus discuté."}$exo$::jsonb),
  ('b5767a1a-a811-556f-bd86-84d89e7326c4'::uuid, 2, 'redaction', $exo${"titre":"Les quatre rires du Menteur","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Associe chaque moment au **type de comique** qu’il illustre (situation, caractère, mots, répétition), en justifiant :\n   - a. Dorante croit courtiser Lucrèce alors qu’il s’agit de Clarice.\n   - b. Dorante, pour sortir d’un mensonge, doit en inventer un nouveau.\n   - c. Dorante décrit sa fête sur la Seine dans une tirade débordante d’hyperboles.\n   - d. Dorante, le menteur, est pris à son propre piège.\n2. Quel est le rôle de **Cliton** ?\n3. Pourquoi le cours dit-il que **Géronte** apporte « la seule gravité de la pièce » ?\n4. D’où vient le **rythme** de la pièce, et pourquoi le spectateur « admire autant qu’il rit » ?","bareme":[{"critere":"Quatre associations justes et justifiées (a situation, b répétition, c mots, d caractère)","points":8},{"critere":"Cliton : valet lucide, commente, relais du spectateur","points":4},{"critere":"Géronte : père noble dont l’honneur est blessé","points":3},{"critere":"Fuite en avant, mensonges jamais identiques, improvisations d’artiste","points":5}],"dureeMin":11,"corrige":"1. **a** : comique de **situation** (le quiproquo des noms). **b** : comique de **répétition** (chaque mensonge en exige un nouveau). **c** : comique de **mots** (tirades d’invention virtuoses et hyperboliques). **d** : comique de **caractère** (le menteur pris à son propre piège).\n2. **Cliton**, le valet, est **lucide** : stupéfait, il tente de suivre, il **commente** et sert de **relais au spectateur**.\n3. **Géronte**, le père noble, voit son **honneur blessé** quand il découvre les mensonges de son fils : c’est le seul moment où la pièce n’est plus un jeu.\n4. Le rythme vient d’une **fuite en avant** : le mensonge appelle le mensonge, et Dorante, **jamais pris de court**, ne ment **jamais deux fois de la même manière**. Ses mensonges sont des **improvisations d’artiste** : le spectateur admire la virtuosité autant qu’il rit."}$exo$::jsonb),
  ('b5767a1a-a811-556f-bd86-84d89e7326c4'::uuid, 3, 'redaction', $exo${"titre":"Une comédie immorale ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur Le Menteur tel que le cours le présente.","enonce":"**Sujet.** On a souvent reproché au *Menteur* de s’achever sur un menteur « ni puni, ni corrigé ». Cette comédie est-elle pour autant **immorale** ?\n\nTu analyseras l’intrigue et le dénouement, les personnages (Dorante, Cliton, Géronte, Clarice et Lucrèce), les formes du comique et la place du spectateur. Tu pourras réfléchir au sens du parcours **« mensonge et comédie »**.","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Arguments pour l’immoralité : dénouement heureux, mensonge récompensé, spectateur complice","points":4},{"critere":"Contrepoids : Géronte et l’honneur blessé, Cliton lucide, humiliation et danger du duel","points":5},{"critere":"Le mensonge comme art et moteur comique (quatre comiques, fuite en avant, improvisation)","points":5},{"critere":"Conclusion qui répond en reliant mensonge et théâtre","points":3}],"dureeMin":20,"corrige":"**Introduction** : en 1644, Corneille fait rire avec un jeune homme qui ment sans cesse. Problématique : une comédie qui ne punit pas son menteur est-elle immorale ?\n\n**I. Un mensonge récompensé.** Dorante invente un passé de héros de guerre, une fête sur la Seine, un mariage à Poitiers ; démasqué, il **retombe sur ses pieds** et épouse Lucrèce. Le dénouement est heureux ; le menteur est **ni puni, ni corrigé**. Le spectateur **admire autant qu’il rit** : il devient complice.\n\n**II. Des contrepoids moraux.** **Géronte**, père noble, a l’**honneur blessé** : la seule gravité de la pièce. **Cliton**, valet lucide, commente et met à distance. Le mensonge a un prix : le **quiproquo** (Clarice prise pour Lucrèce) manque de faire tuer Dorante en duel par **Alcippe**, et il est **humilié** devant son père. Clarice et Lucrèce, que le quiproquo échange, montrent le désordre qu’il crée.\n\n**III. Le mensonge, matière de la comédie.** Le mensonge est le moteur du comique : de **situation** (quiproquo), de **caractère** (le menteur pris à son piège), de **mots** (tirades virtuoses et hyperboliques), de **répétition** (chaque mensonge en exige un nouveau). Dorante est un **artiste de l’improvisation** : il ment pour exister. Le théâtre, lui-même fiction, célèbre ici l’invention plus qu’il ne juge.\n\n**Conclusion** : la pièce n’enseigne pas le mensonge, elle en fait un spectacle ; son « immoralité » est celle du rire, qui suspend le jugement sans l’abolir, puisque Géronte et Cliton font entendre la mesure."}$exo$::jsonb),
  ('50413656-ba7d-519d-856e-d8d3792deaeb'::uuid, 1, 'redaction', $exo${"titre":"Un proverbe qui finit mal","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Dans quel recueil et en quelle année paraît *On ne badine pas avec l’amour* ? Quel **genre** Musset revendique-t-il ? Pour quoi la pièce était-elle faite ?\n2. Résume l’intrigue en cinq étapes : le projet, le refus, la riposte, le piège, le retournement.\n3. Que signifie « **badiner** » ? Quelle est la morale annoncée par le titre ?","bareme":[{"critere":"Un spectacle dans un fauteuil, 1834, proverbe en trois actes, écrit pour être lu","points":5},{"critere":"Les cinq étapes de l’intrigue justes, jusqu’à la mort de Rosette","points":10},{"critere":"Badiner = plaisanter, jouer avec les mots ; la parole amoureuse n’est jamais un jeu sans conséquence","points":5}],"dureeMin":8,"corrige":"1. Paru en **1834** dans *Un spectacle dans un fauteuil* ; c’est un **proverbe** en trois actes, **pas destiné à la scène** : Musset l’écrit après l’échec de sa première pièce, **pour être lu**.\n2. **Le projet** : Perdican, docteur revenu de Paris, doit épouser sa cousine Camille, sortie du couvent ; le baron a tout arrangé. **Le refus** : marquée par les confidences amères des religieuses, Camille craint l’infidélité des hommes et veut retourner au couvent. **La riposte** : blessé, Perdican courtise **Rosette**, paysanne et sœur de lait de Camille, et annonce qu’il l’épousera. **Le piège** : Camille cache Rosette pour lui faire entendre les aveux de Perdican. **Le retournement** : les deux orgueils s’affrontent ; au moment de l’aveu, un cri : **Rosette est morte**.\n3. « Badiner » signifie **plaisanter, jouer avec les mots**. Le proverbe énonce la morale par avance : la **parole amoureuse n’est jamais un jeu sans conséquence**."}$exo$::jsonb),
  ('50413656-ba7d-519d-856e-d8d3792deaeb'::uuid, 2, 'redaction', $exo${"titre":"Rire, aimer, mourir","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Associe chaque élément à son **registre** (comique, lyrique, tragique) et justifie :\n   - a. Les querelles du baron, de Blazius, de Bridaine et de dame Pluche.\n   - b. « On est souvent trompé en amour, souvent blessé et souvent malheureux ; mais on aime. »\n   - c. « Elle est morte. Adieu, Perdican ! »\n2. Quel est l’effet de ce **mélange des registres** ? À quel mouvement appartient-il ?\n3. Pourquoi le cours souligne-t-il que **Rosette** est « la seule qui ne joue pas » ?\n4. Caractérise **Perdican** et **Camille** en deux adjectifs chacun, tirés du cours.","bareme":[{"critere":"Trois associations justes : a comique (chœur grotesque), b lyrique, c tragique","points":6},{"critere":"Effet du mélange : le drame naît d’un jeu que personne n’a vu venir ; drame romantique","points":5},{"critere":"Rosette : innocente, sincère, victime du badinage des autres","points":5},{"critere":"Perdican sincère et cruel ; Camille intelligente, orgueilleuse, terrifiée","points":4}],"dureeMin":11,"corrige":"1. **a** : **comique** : les adultes ridicules forment un **chœur comique** grotesque face au drame des jeunes gens. **b** : **lyrique** : Perdican défend l’amour humain contre le renoncement, dans une déclaration où le « je » et l’émotion dominent. **c** : **tragique** : c’est le dénouement ; la mort d’une innocente sépare pour toujours les amants.\n2. Ce mélange, marque du **drame romantique**, n’est pas un ornement : il fait sentir que **le drame naît d’un jeu**, et que **personne ne l’a vu venir**. Le rire rend la chute plus brutale.\n3. Camille et Perdican jouent avec la parole amoureuse par orgueil ; **Rosette**, elle, croit aux mots qu’on lui dit : elle **ne joue pas**, et c’est **elle qui meurt**. Le badinage a fait une **victime innocente**.\n4. **Perdican** : **sincère et cruel**. **Camille** : **intelligente, orgueilleuse**, **terrifiée** par ce qu’on lui a appris (deux adjectifs suffisent)."}$exo$::jsonb),
  ('50413656-ba7d-519d-856e-d8d3792deaeb'::uuid, 3, 'redaction', $exo${"titre":"Qui a tué Rosette ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur la pièce telle que le cours la présente.","enonce":"**Sujet.** « Un badinage a fait une victime — et elle est innocente. » Qui est responsable de la mort de Rosette dans *On ne badine pas avec l’amour* ?\n\nTu examineras le rôle de Perdican, celui de Camille et de ce qu’on lui a appris, celui des adultes, et tu montreras ce que le titre et le mélange des registres disent de cette responsabilité. Tu relieras ta réflexion au parcours **« les jeux du cœur et de la parole »**.","bareme":[{"critere":"Problématique et plan annoncé","points":3},{"critere":"Responsabilité de Perdican : riposte par orgueil, Rosette utilisée","points":4},{"critere":"Responsabilité de Camille et des confidences des religieuses : refus, piège où elle cache Rosette","points":4},{"critere":"Les adultes grotesques et le baron qui a tout arrangé ; personne n’a vu venir le drame","points":4},{"critere":"La parole comme vraie coupable (titre, jeux du cœur et de la parole) ; conclusion","points":5}],"dureeMin":20,"corrige":"**Introduction** : la pièce s’achève sur « Elle est morte. Adieu, Perdican ! ». Problématique : qui porte la faute de cette mort ?\n\n**I. Perdican, l’orgueil blessé.** Refusé par Camille, Perdican **courtise Rosette** et annonce qu’il l’épousera, pour se venger ; sincère **et** cruel, il fait d’une paysanne un instrument de son jeu avec Camille.\n\n**II. Camille et ce qu’on lui a appris.** Intelligente et orgueilleuse, Camille est **terrifiée** par les confidences amères des religieuses : elle craint l’infidélité des hommes et refuse Perdican. Puis elle **cache Rosette** pour lui faire entendre les aveux de Perdican : le piège expose la jeune fille. Mais Camille est aussi victime d’une éducation.\n\n**III. Les adultes absents du vrai drame.** Le **baron** a tout arrangé ; Blazius, Bridaine, dame Pluche forment un **chœur comique** grotesque. Occupés de leurs ridicules, ils ne voient rien : le drame naît d’un jeu que **personne n’a vu venir**.\n\n**IV. (ou en synthèse) La parole coupable.** « Badiner », c’est jouer avec les mots : le titre énonce la morale par avance, **la parole amoureuse n’est jamais un jeu sans conséquence**. Le mélange du comique, du lyrique et du tragique fait sentir ce passage du jeu à la mort. L’amour est reconnu **au moment exact où il devient impossible** ; Rosette, la seule qui ne joue pas, paie pour les autres.\n\n**Conclusion** : la responsabilité est partagée entre deux orgueils et un monde qui ne voit rien ; mais la vraie coupable est la parole prise pour un jeu."}$exo$::jsonb),
  ('35cb59fb-de68-5acd-b6af-9e4577c08fd3'::uuid, 1, 'redaction', $exo${"titre":"Une amitié brisée pour presque rien","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit *Pour un oui ou pour un non*, en quelle année, à quel âge ? Quel est le parcours associé ?\n2. Qui sont les personnages ? Pourquoi n’ont-ils pas de nom ?\n3. Quelle phrase a déclenché la rupture, et qu’est-ce qui a blessé ?\n4. Qu’appelle-t-on les **tropismes** chez Sarraute ?","bareme":[{"critere":"Nathalie Sarraute, 1982, quatre-vingt-deux ans, parcours « théâtre et dispute »","points":5},{"critere":"H1 et H2, personnages sans nom : des positions, pas des individus","points":4},{"critere":"« C’est bien… ça » avec une suspension, accent de condescendance","points":5},{"critere":"Tropismes : mouvements intérieurs infimes qui précèdent la parole, mot emprunté à la biologie","points":6}],"dureeMin":7,"corrige":"1. **Nathalie Sarraute**, en **1982**, à **quatre-vingt-deux ans**. Parcours : **« théâtre et dispute »**.\n2. Pour l’essentiel, deux personnages sans nom : **H1** et **H2**. L’**absence de noms propres** fait d’eux des **positions**, pas des individus.\n3. Un jour, H1 a dit à H2 « **C’est bien… ça** », avec une **suspension** dans la voix, un accent de **condescendance**. Rien d’autre : c’est ce presque-rien que la pièce fait exister.\n4. Les **tropismes** (mot emprunté à la **biologie**) sont les **mouvements intérieurs infimes** — attraction, recul, méfiance — qui **précèdent la parole** et que la conversation polie recouvre."}$exo$::jsonb),
  ('35cb59fb-de68-5acd-b6af-9e4577c08fd3'::uuid, 2, 'redaction', $exo${"titre":"Rejouer la phrase","consigne":"Lis ce dialogue, écrit pour l’exercice à la manière de Sarraute (ce n’est pas le texte de la pièce), puis réponds en citant.","enonce":"> H1. — Mais enfin… qu’est-ce que j’ai dit ?\n> H2. — Rien… Justement. Presque rien.\n> H1. — Presque rien… Et pour ce presque rien, tu…\n> H2. — Tu as dit : « C’est bien… ça. » Avec ce petit… ce petit temps, là, avant le « ça ».\n> H1, *riant*. — Un temps ! Tu comptes mes silences, maintenant ?\n> H2. — Oui. Je les compte. Et toi, tu ne t’entends pas.\n\n1. Relève trois marques de l’**écriture** de Sarraute : suspension, reprises, syntaxe orale. Quel est leur effet ?\n2. Quel **tropisme** ce dialogue rend-il visible ? Que recouvre la politesse ?\n3. Quelle est la seule **didascalie** ? Pourquoi est-elle décisive ?\n4. Qui a le **pouvoir de la parole** au début, puis à la fin de l’extrait ?","bareme":[{"critere":"Trois marques d’écriture relevées (points de suspension, reprises « presque rien », phrases inachevées) et leur effet","points":6},{"critere":"Tropisme identifié : blessure devant une intonation condescendante, sous la banalité des mots","points":5},{"critere":"Didascalie « riant » : elle porte le ton, un rire qui peut blesser à nouveau","points":4},{"critere":"Renversement du pouvoir de la parole expliqué","points":5}],"dureeMin":12,"corrige":"1. **Suspension** permanente : points de suspension (« Mais enfin… », « Rien… Justement ») ; **reprises** : « presque rien » repris par H1, « Je les compte » ; phrases **inachevées** (« tu… ») et **syntaxe orale**. Effet : rien ne se dit d’un bloc ; on voit la parole se chercher, la **pression monter** sous des mots banals.\n2. Le dialogue rend visible le **recul blessé** de H2 devant une **intonation** : « ce petit temps, là, avant le ça », signe de **condescendance**. La conversation polie recouvre une **lutte réelle sous la banalité des mots**.\n3. La seule didascalie est « *riant* ». Elle est **rare mais décisive** : elle **porte le ton**. Le rire de H1 peut être lu comme une nouvelle condescendance, qui confirme la blessure.\n4. Au début, H1 **interroge** et semble mener l’échange. À la fin, H2 prend le dessus : « Je les compte. Et toi, tu ne t’entends pas » : il accuse et juge. Le langage **n’accompagne pas l’action, il est l’action**."}$exo$::jsonb),
  ('35cb59fb-de68-5acd-b6af-9e4577c08fd3'::uuid, 3, 'redaction', $exo${"titre":"La violence du langage ordinaire","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur la pièce telle que le cours la présente.","enonce":"**Sujet.** « Une intonation suffit à classer quelqu’un, à l’humilier, à briser vingt ans d’amitié. » En quoi *Pour un oui ou pour un non* montre-t-il que le langage ordinaire peut être une **violence** ?\n\nTu étudieras le point de départ, les tropismes, la mécanique de la dispute (témoins imaginaires, vie réussie ou ratée), l’écriture et le sens du titre.","bareme":[{"critere":"Problématique claire et plan annoncé","points":3},{"critere":"Le presque-rien initial et les tropismes : ce que la politesse recouvre","points":4},{"critere":"Mécanique de la dispute : scène rejouée, témoins imaginaires, vie réussie ou ratée, écart social et condescendance","points":5},{"critere":"Écriture : suspension, reprises, didascalies rares, absence de noms, silences qui portent le sens","points":5},{"critere":"Titre expliqué (pour rien, pour tout) et conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : la pièce de Sarraute (1982) met en scène deux amis, H1 et H2, séparés par une phrase. Problématique : comment un mot presque neutre devient-il une arme ?\n\n**I. Un presque-rien qui blesse.** H1 a dit « **C’est bien… ça** » avec une **suspension**, un accent de **condescendance**. Rien d’autre. Les **tropismes**, mouvements intérieurs infimes qui précèdent la parole, révèlent ce que la conversation polie recouvre : il y a une **lutte réelle sous la banalité des mots**.\n\n**II. Une dispute qui dévoile la vraie blessure.** Les deux hommes **rejouent la scène**, s’accusent, se réconcilient, repartent ; ils appellent des **témoins imaginaires** (un couple de voisins qui juge) ; ils invoquent la vie **réussie** de l’un et la vie « **ratée** » de l’autre. La blessure apparaît : l’**écart social** et la **condescendance**. La **rupture est consommée** sans qu’aucun fait ne l’explique.\n\n**III. Une écriture qui fait entendre la violence.** Ni intrigue, ni décor, ni psychologie classique : une **pression qui monte**. **Suspension** permanente, **reprises**, phrases inachevées, didascalies **rares mais décisives**, personnages sans nom (des **positions**). Ce sont les **blancs** qui portent le sens ; le langage **est** l’action.\n\n**Conclusion** : la pièce prend au sérieux ce que la vie sociale traite comme négligeable et montre la **violence du langage ordinaire**. On se sépare « pour un oui ou pour un non » : **pour rien**, c’est-à-dire **pour tout**."}$exo$::jsonb),
  ('5593f9c3-ddac-51da-a68c-442f9305db5c'::uuid, 1, 'redaction', $exo${"titre":"L’intrigue de Phèdre","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Donne la date, le genre et la forme de *Phèdre* de Racine.\n2. Qui sont **Phèdre**, **Hippolyte**, **Aricie**, **Œnone**, **Thésée** et **Théramène** ?\n3. Résume l’intrigue depuis la fausse mort de Thésée jusqu’à la mort de Phèdre.","bareme":[{"critere":"1677, tragédie en cinq actes et en vers","points":3},{"critere":"Les six personnages justement identifiés","points":7},{"critere":"Étapes de l’intrigue justes : aveu, déclaration repoussée, retour de Thésée, calomnie, Neptune, mort de Phèdre","points":10}],"dureeMin":8,"corrige":"1. Tragédie en **cinq actes et en vers**, créée en **1677**.\n2. **Phèdre** : épouse de Thésée, fille de Minos et de Pasiphaé. **Hippolyte** : fils de Thésée et d’une Amazone. **Aricie** : princesse d’une famille ennemie, aimée d’Hippolyte. **Œnone** : la nourrice de Phèdre. **Thésée** : roi d’Athènes. **Théramène** : celui qui fait le récit de la mort d’Hippolyte.\n3. Thésée est **réputé mort**. Phèdre avoue à Œnone son amour pour Hippolyte, qui aime Aricie. Elle se déclare ; Hippolyte la **repousse avec horreur**. **Thésée reparaît** : il n’était pas mort. **Œnone accuse Hippolyte** d’avoir voulu séduire Phèdre. Thésée appelle **Neptune** : un **monstre marin** tue Hippolyte, et Théramène en fait le récit. Phèdre **avoue la vérité** et meurt **empoisonnée**."}$exo$::jsonb),
  ('5593f9c3-ddac-51da-a68c-442f9305db5c'::uuid, 2, 'redaction', $exo${"titre":"Vénus tout entière","consigne":"Réponds en rédigeant et en citant le vers donné.","enonce":"> « C’est Vénus tout entière à sa proie attachée. »\n\n1. Qui est la « **proie** » ? Que dit ce vers de la **passion** de Phèdre ?\n2. Quels autres éléments, selon le cours, **condamnent** Phèdre avant même qu’elle agisse ?\n3. La mort d’Hippolyte est **racontée** par Théramène au lieu d’être montrée. Quelle **règle** classique l’explique ?\n4. Le cours dit que la pièce « avance par la parole qui échappe ». Montre-le avec les **aveux** successifs de Phèdre.","bareme":[{"critere":"La proie est Phèdre ; passion subie comme une maladie, non un choix","points":5},{"critere":"Hérédité et sang : petite-fille du Soleil, fille de Pasiphaé","points":4},{"critere":"Bienséance expliquée","points":4},{"critere":"Les aveux (à Œnone, à Hippolyte, à Thésée) comme moteur de l’action","points":7}],"dureeMin":11,"corrige":"1. La « proie » est **Phèdre** elle-même, **persécutée par Vénus**. L’image de la bête attachée à sa proie montre une passion **subie**, qui la dévore : Racine peint la passion comme une **maladie**, **non comme un choix**.\n2. Phèdre est **petite-fille du Soleil** et fille de **Pasiphaé** : le **sang** et l’**hérédité** la condamnent. Culpabilité et innocence y sont **inséparables** (c’est ce qu’a souligné la lecture janséniste).\n3. La **bienséance** interdit de montrer la mort sur scène : la mort d’Hippolyte est **racontée, jamais montrée**. La pièce respecte aussi les **trois unités** (lieu, temps, action).\n4. Les grandes scènes sont des **aveux** : Phèdre avoue d’abord son amour à **Œnone** ; puis, croyant Thésée mort, elle se déclare à **Hippolyte**, qui la repousse ; enfin elle avoue la vérité à **Thésée** avant de mourir. Chaque aveu fait basculer l’action : la parole **échappe** à Phèdre et produit la catastrophe."}$exo$::jsonb),
  ('5593f9c3-ddac-51da-a68c-442f9305db5c'::uuid, 3, 'redaction', $exo${"titre":"Coupable ou innocente ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur Phèdre telle que le cours la présente.","enonce":"**Sujet.** Phèdre est-elle **coupable** ou **innocente** ?\n\nTu t’appuieras sur la fatalité (hérédité, Vénus), sur les actes et les paroles de Phèdre, sur le rôle d’Œnone, sur la lecture janséniste et sur l’art racinien (aveux, images, bienséance).","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Innocence : passion subie, Vénus, sang et hérédité","points":5},{"critere":"Culpabilité : déclaration à Hippolyte, silence pendant la calomnie d’Œnone, mort d’Hippolyte","points":5},{"critere":"Dépassement : culpabilité et innocence inséparables (lecture janséniste) ; aveu final","points":4},{"critere":"Art racinien mobilisé (aveux, images du feu et du sang, bienséance) ; conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : Phèdre aime Hippolyte, le fils de son époux. Problématique : peut-on juger coupable une femme que les dieux et le sang condamnent ?\n\n**I. Une innocente persécutée.** Phèdre est **petite-fille du Soleil** et fille de **Pasiphaé** : le **sang** et l’**hérédité** la condamnent. **Vénus** la poursuit : « C’est **Vénus tout entière à sa proie attachée** ». Racine peint la passion comme une **maladie subie**, non comme un choix.\n\n**II. Une coupable qui parle et laisse faire.** Elle **avoue** son amour à Œnone puis se **déclare** à Hippolyte, qui la repousse. Au retour de Thésée, **Œnone accuse Hippolyte** ; Phèdre laisse la calomnie agir, et Thésée appelle Neptune : Hippolyte meurt. La parole qui échappe produit la catastrophe.\n\n**III. Inséparables.** La lecture **janséniste** l’a souligné : **culpabilité et innocence sont inséparables**. Phèdre sait sa faute et ne peut s’en délivrer. Son **aveu final** à Thésée, avant de mourir **empoisonnée**, rétablit la vérité. L’art racinien sert ce déchirement : des **aveux** successifs, des **images fixes** (le feu, le sang, le jour, l’ombre), un vers simple au vocabulaire restreint, la **bienséance** qui fait raconter la mort d’Hippolyte par Théramène.\n\n**Conclusion** : Phèdre est à la fois coupable et innocente ; c’est cette tension qui fait d’elle une héroïne tragique."}$exo$::jsonb),
  ('99b52475-ba68-55a1-8752-11aca4c944d4'::uuid, 1, 'redaction', $exo${"titre":"La folle journée","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Donne le **titre complet** de la pièce, son auteur, son nombre d’actes et sa date de création. Pourquoi a-t-elle attendu ?\n2. Qui Figaro veut-il épouser ? Quel est l’**obstacle** ?\n3. Que découvre-t-on au **procès** ?\n4. Comment la pièce se **termine**-t-elle ? Combien de temps dure l’action ?","bareme":[{"critere":"La Folle Journée ou Le Mariage de Figaro, Beaumarchais, cinq actes, 1784, trois ans d’interdiction","points":6},{"critere":"Suzanne ; le comte et le droit du seigneur qu’il a lui-même aboli","points":5},{"critere":"Marceline mère de Figaro ; dénouement du jardin, pardon, mariage ; une seule journée","points":9}],"dureeMin":7,"corrige":"1. *La Folle Journée ou Le Mariage de Figaro*, de **Beaumarchais**, comédie en **cinq actes**, créée en **1784** après **trois ans d’interdiction** par Louis XVI.\n2. Figaro, valet du **comte Almaviva**, veut épouser **Suzanne**, camériste de la comtesse. L’obstacle : le comte veut faire valoir sur Suzanne un « **droit du seigneur** » qu’il a pourtant **aboli** lui-même.\n3. Au **procès burlesque**, **Marceline**, qui réclamait Figaro en mariage, découvre qu’elle est **sa mère**.\n4. Dans le jardin, le comte **courtise sa propre femme** déguisée en Suzanne ; démasqué, il **demande pardon**, et le mariage a lieu. L’action tient en **une seule journée**."}$exo$::jsonb),
  ('99b52475-ba68-55a1-8752-11aca4c944d4'::uuid, 2, 'redaction', $exo${"titre":"Une comédie qui attaque","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Pour chaque cible, indique **comment** la pièce l’attaque : les **privilèges**, la **censure**, la **justice vénale**, la condition des **femmes**.\n2. Explique la formule de Figaro sur le comte : il s’est « donné la peine de naître, et rien de plus ».\n3. Louis XVI aurait dit qu’« il faudrait détruire la Bastille pour que la représentation de cette pièce ne fût pas une inconséquence dangereuse ». Qu’a-t-il compris de la pièce ?\n4. Cite deux **ressorts** du rythme de la pièce.","bareme":[{"critere":"Quatre cibles reliées à leur moyen (monologue et renversement, Figaro auteur censuré, procès de l’acte III, tirade de Marceline)","points":8},{"critere":"Formule expliquée : la naissance seule fait la différence, pas le mérite","points":5},{"critere":"Citation de Louis XVI interprétée : pièce dangereuse pour l’ordre des privilèges, cinq ans avant 1789","points":4},{"critere":"Deux ressorts du rythme (quiproquos, cachettes, déguisements, rebondissements)","points":3}],"dureeMin":12,"corrige":"1. **Privilèges** : attaqués par le **monologue** de Figaro et le **renversement des rôles** (le valet déjoue le maître). **Censure** : Figaro l’a **subie comme auteur**. **Justice vénale** : le **procès de l’acte III**, burlesque. **Femmes** : la **tirade de Marceline**.\n2. Le comte n’a d’autre mérite que sa **naissance** : son rang ne lui a rien coûté, alors que Figaro a dû se battre pour tout. La formule oppose le **privilège** hérité au **mérite** : c’est un des textes politiques les plus célèbres du siècle.\n3. Louis XVI a compris que la pièce **ébranle l’ordre des privilèges** : la jouer, c’était laisser attaquer publiquement la société d’Ancien Régime, symbolisée par la Bastille. La pièce est créée **cinq ans avant 1789**.\n4. Ressorts : **cinq actes, une seule journée**, des dizaines de **rebondissements**, des **quiproquos**, des **cachettes** (le fauteuil, le cabinet, les marronniers), des **déguisements** (deux suffisent)."}$exo$::jsonb),
  ('99b52475-ba68-55a1-8752-11aca4c944d4'::uuid, 3, 'redaction', $exo${"titre":"Une comédie de divertissement ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur le cours.","enonce":"**Sujet.** *Le Mariage de Figaro* n’est-il qu’une **comédie de divertissement** ?\n\nTu t’appuieras sur l’intrigue et son rythme, sur le personnage de Figaro, sur les cibles politiques de la pièce, sur son histoire (interdiction, création) et sur l’art de Beaumarchais (comique de situation et satire, langue propre à chaque personnage).","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Divertissement : rythme, une journée, quiproquos, cachettes, déguisements, procès burlesque","points":5},{"critere":"Portée politique : Figaro maître du jeu, monologue de l’acte V, privilèges, censure, justice, femmes","points":6},{"critere":"Contexte : trois ans d’interdiction, mot de Louis XVI, cinq ans avant 1789","points":3},{"critere":"Conclusion : le rire au service de la satire","points":3}],"dureeMin":20,"corrige":"**Introduction** : *La Folle Journée* promet le rire dès son titre. Problématique : la gaieté de la pièce cache-t-elle une portée politique ?\n\n**I. Une mécanique comique éblouissante.** **Cinq actes, une seule journée**, des dizaines de rebondissements : **quiproquos**, **cachettes** (le fauteuil, le cabinet, les marronniers), **déguisements**, billets truqués, rendez-vous piégé. Chérubin, page amoureux de toutes les femmes, multiplie les contretemps ; le procès burlesque révèle que Marceline est la mère de Figaro ; au dénouement, le comte courtise sa propre femme. Beaumarchais donne à **chaque personnage une langue propre**.\n\n**II. Une comédie politique.** Figaro n’est pas un valet ordinaire : il **conduit** l’intrigue, raisonne, écrit, argumente. Son **monologue de l’acte V** reproche au comte de s’être « **donné la peine de naître, et rien de plus** ». La pièce attaque les **privilèges**, la **censure**, la **justice vénale** (le procès), la condition des **femmes** (la tirade de Marceline). Le comte qui réclame un droit du seigneur qu’il a aboli montre l’arbitraire du maître.\n\n**III. Un rire jugé dangereux.** La pièce attend **trois ans** l’autorisation de Louis XVI, qui aurait dit qu’il faudrait « détruire la Bastille » pour que sa représentation ne soit pas une inconséquence dangereuse. Créée en **1784**, **cinq ans avant 1789**.\n\n**Conclusion** : la pièce n’est pas qu’un divertissement ; elle mêle **comique de situation** et **satire** : le rire y est le véhicule de la critique."}$exo$::jsonb),
  ('923ec51e-464b-5ffd-a962-af9cc8ac55e9'::uuid, 1, 'redaction', $exo${"titre":"Petite histoire du valet de théâtre","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Quelle est la place du valet chez **Plaute** et **Molière** ? Donne deux noms de valets cités par le cours.\n2. Qu’apporte **Marivaux** ? Quelle pièce le montre ?\n3. Qu’est-ce qui est **neuf** chez Beaumarchais ? Donne quatre signes que Figaro devient le protagoniste.\n4. Où se déroule l’**acte V** et que s’y passe-t-il ?","bareme":[{"critere":"Plaute et Molière : valet adjuvant de la ruse du maître ; deux valets cités (Scapin, Sganarelle, Dubois)","points":6},{"critere":"Marivaux : égal à égal, L’Île des esclaves","points":4},{"critere":"Beaumarchais : titre, initiative, monologue, dernière chanson ; acte V dans le jardin la nuit","points":10}],"dureeMin":7,"corrige":"1. Chez **Plaute** et **Molière**, le valet est un **adjuvant** : il sert la ruse du maître ou de l’amoureux. Exemples cités : **Scapin**, **Sganarelle**, **Dubois**.\n2. Chez **Marivaux**, le valet parle **d’égal à égal** avec le maître : *L’Île des esclaves*.\n3. Chez **Beaumarchais**, le valet **prend la place du protagoniste** : il a le **titre**, l’**initiative**, le **monologue**, la **dernière chanson**.\n4. L’acte V se déroule **dans le jardin, la nuit** : Figaro, seul dans le noir, prononce son grand monologue ; puis les quiproquos s’y enchaînent en cascade, avec déguisements et apartés, jusqu’au piège final."}$exo$::jsonb),
  ('923ec51e-464b-5ffd-a962-af9cc8ac55e9'::uuid, 2, 'redaction', $exo${"titre":"Le monologue et le piège du jardin","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Quelles étapes de sa vie Figaro passe-t-il en revue dans son **monologue de l’acte V** ? Cite-en au moins cinq.\n2. Qu’est-ce qui rend ce monologue **unique** : sa longueur, son ton, son objet ?\n3. Le cours dit que l’égalité est montrée « **en actes, pas en discours** ». Montre-le avec Suzanne, la comtesse et Marceline.\n4. Relève deux **objets** et deux **cachettes** qui servent de ressorts comiques.","bareme":[{"critere":"Au moins cinq étapes de la vie de Figaro justes","points":5},{"critere":"Unicité : plus long monologue, de la colère à la mélancolie, la naissance comme seule différence","points":5},{"critere":"Égalité en actes : Suzanne mène le comte, la comtesse s’allie à sa servante, Marceline dénonce ; les femmes organisent le piège","points":6},{"critere":"Objets (ruban, épingle, billet) et cachettes (fauteuil, cabinet, marronniers) justes","points":4}],"dureeMin":11,"corrige":"1. Figaro fait le **bilan d’une vie** : **enfant trouvé**, **chirurgien**, **auteur dramatique censuré**, **journaliste interdit**, **joueur**, **banquier ruiné**, **barbier**.\n2. C’est le **plus long monologue** du théâtre français classique ; son ton va **de la colère à la mélancolie** ; son objet est la **naissance**, seule différence entre lui et le comte.\n3. **Suzanne** mène le comte **par le bout du nez** ; la **comtesse** s’allie **à sa servante** contre son mari ; **Marceline** dénonce le sort des femmes **séduites puis abandonnées**. Ce sont **les femmes qui organisent le piège final** : le renversement est social **et** féminin, et il passe par l’action.\n4. Objets : le **ruban**, l’**épingle**, le **billet**. Cachettes : le **fauteuil** (acte I), le **cabinet** (acte II), les **marronniers** (acte V)."}$exo$::jsonb),
  ('923ec51e-464b-5ffd-a962-af9cc8ac55e9'::uuid, 3, 'redaction', $exo${"titre":"Qui mène vraiment le jeu ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur le cours.","enonce":"**Sujet.** Dans *Le Mariage de Figaro*, le valet est-il vraiment le **maître du jeu** ?\n\nTu situeras Figaro dans l’histoire du valet de théâtre, tu analyseras son monologue, puis le rôle de Suzanne, de la comtesse et de Marceline. Tu te demanderas enfin si Figaro est **libre** à la fin de la pièce, en lien avec le parcours **« la comédie du valet »**.","bareme":[{"critere":"Problématique et plan annoncé","points":3},{"critere":"Figaro protagoniste, comparé aux valets de Plaute, Molière, Marivaux","points":4},{"critere":"Monologue de l’acte V analysé (bilan, ton, naissance)","points":4},{"critere":"Figaro échoue souvent : Suzanne et la comtesse mènent le piège final ; Marceline","points":5},{"critere":"Liberté limitée (marié mais au service du comte) ; le rire comme arme politique ; conclusion","points":4}],"dureeMin":20,"corrige":"**Introduction** : la pièce porte le nom du valet. Problématique : Figaro mène-t-il réellement l’intrigue ?\n\n**I. Un valet devenu protagoniste.** Chez Plaute et Molière, le valet est un **adjuvant** (Scapin, Sganarelle) ; chez Marivaux, il parle d’**égal à égal** (*L’Île des esclaves*) ; chez Beaumarchais, il a le **titre**, l’**initiative**, le **monologue**, la **dernière chanson**. Il raisonne, écrit, argumente.\n\n**II. La voix de la pièce.** Dans son **monologue de l’acte V**, seul dans le noir, Figaro fait le bilan de sa vie (enfant trouvé, auteur censuré, journaliste interdit, barbier) ; de la **colère** à la **mélancolie**, il désigne la **naissance** comme seule différence entre lui et le comte : c’est lui qui pense la pièce.\n\n**III. Mais ce sont les femmes qui gagnent.** Figaro **échoue souvent** : ce sont **Suzanne et la comtesse** qui organisent le piège final dans le jardin, où le comte courtise sa propre femme. Suzanne mène le comte par le bout du nez ; la comtesse s’allie à sa servante ; **Marceline** dénonce le sort des femmes séduites puis abandonnées. Le renversement est **social** et **féminin**.\n\n**IV. (ou en synthèse) Une liberté limitée.** À la fin, Figaro se marie mais **reste au service du comte** : la hiérarchie demeure. Pourtant, le rire est une **arme politique** : la Révolution a suivi de peu, et Beaumarchais a cru que la comédie pouvait changer la société.\n\n**Conclusion** : Figaro est la voix et la conscience du jeu, mais pas son seul maître ; la vraie victoire revient aux femmes."}$exo$::jsonb),
  ('84abfe68-00de-5933-b567-ddd00497084b'::uuid, 1, 'redaction', $exo${"titre":"Winnie dans son mamelon","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit *Oh, les beaux jours !* ? Sous quel titre et en quelle langue la pièce est-elle d’abord créée ? En quelle année est-elle créée en français ?\n2. Décris la situation de **Winnie** à l’acte I, puis à l’acte II.\n3. Qui est **Willie** et comment se comporte-t-il ?\n4. Quelle **formule** Winnie répète-t-elle, et pourquoi est-elle ironique ?","bareme":[{"critere":"Samuel Beckett, Happy Days en anglais (1961), en français en 1963","points":5},{"critere":"Acte I enterrée jusqu’à la taille, acte II jusqu’au cou","points":6},{"critere":"Willie : le mari qui rampe, lit son journal, répond par monosyllabes","points":4},{"critere":"Formule « Oh, le beau jour que ça aura été » dite depuis la terre qui l’engloutit","points":5}],"dureeMin":7,"corrige":"1. **Samuel Beckett** ; créée d’abord en **anglais**, sous le titre ***Happy Days***, en 1961, puis en **français** en **1963**. Pièce en **deux actes**.\n2. **Acte I** : Winnie est **enterrée jusqu’à la taille** dans un mamelon de terre desséchée, sous une lumière aveuglante. **Acte II** : elle est **enterrée jusqu’au cou** ; elle ne peut plus bouger la tête ni atteindre son sac.\n3. **Willie** est son **mari** : derrière le mamelon, il rampe, lit son journal, répond par **monosyllabes**, ou ne répond pas.\n4. Winnie répète « Encore un jour divin », « **Oh, le beau jour que ça aura été** ». La formule est **ironique** parce qu’elle est prononcée **depuis la terre qui l’engloutit** : la joie affirmée contredit la situation."}$exo$::jsonb),
  ('84abfe68-00de-5933-b567-ddd00497084b'::uuid, 2, 'redaction', $exo${"titre":"Ce qui remplace l’intrigue","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. « **Rien n’arrive.** » Qu’est-ce qui remplace l’intrigue dans la pièce ? Cite quatre **rituels** et ce que chacun occupe.\n2. Que représente le **revolver** dans le sac ?\n3. D’où vient le **comique** de la pièce ? Pourquoi le rire la rend-il à la fois **supportable** et **plus cruelle** ?\n4. Complète et explique : ce qui **reste** / ce qui **se défait**.","bareme":[{"critere":"Quatre rituels cités avec ce qu’ils occupent (sonnerie, prière et brosse à dents, citations, espoir que Willie réponde)","points":6},{"critere":"Revolver : une possibilité jamais choisie","points":3},{"critere":"Comique hérité du burlesque ; rire supportable et cruel (on rit d’une femme qui disparaît)","points":6},{"critere":"Reste une voix et un langage ; se défont le corps et le temps ; la parole comme preuve d’existence","points":5}],"dureeMin":11,"corrige":"1. La pièce est faite de **rituels** : la **sonnerie** qui réveille règle le jour ; la **prière**, la **brosse à dents**, le **peigne** occupent le temps ; les **citations à moitié oubliées** disent la mémoire qui s’effrite ; l’**espoir que Willie réponde** est l’adresse à l’autre.\n2. Le **revolver** dans le sac est **une possibilité jamais choisie** : la mort volontaire reste là, à portée, et Winnie ne la prend pas.\n3. La situation est **atroce**, mais le jeu est **comique** : Beckett vient du **burlesque** (gestes précis, ratés, pauses). Le rire rend la pièce **supportable**, et en même temps **plus cruelle** : le spectateur **rit d’une femme qui disparaît**.\n4. Ce qui **reste** : une **voix**, un **langage** qui tourne à vide et **tient debout**. Ce qui **se défait** : un **corps** qui se dégrade, un **temps** qui n’avance pas. Winnie est **quelqu’un qui continue** : la **parole** est la seule preuve d’existence."}$exo$::jsonb),
  ('84abfe68-00de-5933-b567-ddd00497084b'::uuid, 3, 'redaction', $exo${"titre":"Peut-on rire d’une femme qui disparaît ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur la pièce telle que le cours la présente.","enonce":"**Sujet.** Dans *Oh, les beaux jours !*, le **rire** trahit-il la gravité de la situation ou la rend-il plus forte ?\n\nTu t’appuieras sur le dispositif des deux actes, les rituels, la formule répétée de Winnie, l’héritage burlesque et ce que la pièce dit de la condition humaine (parcours **« un théâtre de la condition humaine »**).","bareme":[{"critere":"Problématique et plan annoncé","points":3},{"critere":"Gravité du dispositif : l’enfouissement de l’acte I à l’acte II, corps qui se dégrade, temps immobile","points":4},{"critere":"Sources du rire : burlesque, rituels dérisoires, ironie de la formule, Willie","points":5},{"critere":"Le rire rend la pièce supportable et plus cruelle ; Winnie quelqu’un qui continue","points":5},{"critere":"Conclusion sur la condition humaine : la parole comme seule preuve d’existence","points":3}],"dureeMin":20,"corrige":"**Introduction** : Winnie, enterrée dans un mamelon, trouve la journée belle. Problématique : faut-il rire, et que produit ce rire ?\n\n**I. Une situation atroce.** À l’acte I, Winnie est **enterrée jusqu’à la taille** sous une lumière aveuglante ; à l’acte II, **jusqu’au cou** : elle ne peut plus bouger la tête ni atteindre son sac. Le **corps se dégrade**, le **temps** n’avance pas ; **rien n’arrive**. Le revolver est là, possibilité jamais choisie.\n\n**II. Un comique constant.** Beckett vient du **burlesque** : gestes précis, ratés, pauses. Les **rituels** (sonnerie, prière, brosse à dents, peigne, citations à moitié oubliées) sont dérisoires. Willie rampe, lit son journal, répond par monosyllabes. La formule « **Oh, le beau jour que ça aura été** », dite depuis la terre qui l’engloutit, est le **cœur ironique** du texte.\n\n**III. Un rire qui renforce la gravité.** Le rire rend la pièce **supportable** et, en même temps, **plus cruelle** : le spectateur **rit d’une femme qui disparaît**, et s’en aperçoit. Winnie n’est pas une héroïne : elle est **quelqu’un qui continue**. Le rire nous fait partager cette obstination.\n\n**Conclusion** : le rire ne trahit pas la gravité, il la rend plus aiguë. Il reste une **voix** et un **langage** qui tiennent debout : la **parole** comme seule preuve d’existence, image de la condition humaine."}$exo$::jsonb),
  ('093b4756-43e7-5d6a-8f9f-9be32e3fdf23'::uuid, 1, 'redaction', $exo${"titre":"Ce que Beckett retire au théâtre","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Le cours dit que la pièce « enlève au théâtre presque tout ce qui le définissait ». Pour l’**intrigue**, le **personnage**, l’**espace** et le **temps**, dis ce qui disparaît et ce qu’il en reste.\n2. Que reste-t-il à Winnie à l’**acte II** ?\n3. Quelle est la particularité des **didascalies** de Beckett ?","bareme":[{"critere":"Les quatre éléments retirés, avec ce qu’il en reste (rien ne se noue, passé ignoré, mamelon et ciel vide, sonnerie d’un jour qui recommence)","points":10},{"critere":"Acte II : la parole et le souvenir, plus les mains ni les objets","points":5},{"critere":"Didascalies d’une précision extrême : pauses, regards, gestes comptés","points":5}],"dureeMin":7,"corrige":"1. **Intrigue** : rien ne se noue ni ne se dénoue. **Personnage** psychologique : on ignore le passé de Winnie, sa profession, son histoire. **Espace** vraisemblable : il reste un mamelon, une lumière crue, un ciel vide. **Temps** : une **sonnerie** règle un jour qui **recommence**. Ce qui reste, et c’est le sujet, c’est une **voix qui refuse de s’arrêter**.\n2. À l’acte II, Winnie ne peut plus utiliser ses mains, ses objets, ses rituels : il ne lui reste que la **parole** et le **souvenir**.\n3. Beckett écrit des indications d’une **précision extrême** : durée exacte des **pauses**, direction du **regard**, **gestes comptés**. Le texte est aussi une **partition de mise en scène**."}$exo$::jsonb),
  ('093b4756-43e7-5d6a-8f9f-9be32e3fdf23'::uuid, 2, 'redaction', $exo${"titre":"Une partition de mise en scène","consigne":"Lis cet extrait, écrit pour l’exercice à la manière de Beckett (ce n’est pas le texte de la pièce), puis réponds en citant.","enonce":"> WINNIE, *regard fixe devant elle*. — Encore un jour divin. *(Pause. Elle tente de tourner la tête vers la gauche, n’y parvient pas.)* La brosse… où ai-je… *(Pause.)* Qu’importe. *(Sourire.)* Il y avait un bal, autrefois… un bal… *(Pause longue.)* Willie ? *(Pause.)* Tu m’entends, Willie ? *(Pause. Sourire qui s’éteint.)*\n\n1. À quel **acte** cet extrait pourrait-il appartenir ? Justifie par deux indices.\n2. Relève trois **didascalies** et dis ce qu’elles imposent au comédien. Pourquoi le cours parle-t-il d’une **partition** ?\n3. Quels **objets de mémoire** apparaissent ici, et dans quel état ?\n4. L’optimisme de Winnie est-il naïf ? Réponds avec le cours.","bareme":[{"critere":"Acte II justifié : tête immobile, objets hors d’atteinte, reste la parole et le souvenir","points":5},{"critere":"Trois didascalies relevées ; précision qui impose pauses, regards et gestes ; partition","points":5},{"critere":"Souvenir de bal incomplet, brosse perdue, adresse à Willie sans réponse","points":4},{"critere":"Optimisme comme stratégie de survie, ni naïveté ni aveuglement ; tendresse et ironie","points":6}],"dureeMin":12,"corrige":"1. L’extrait correspond à l’**acte II** : Winnie **ne peut plus tourner la tête** (« n’y parvient pas »), elle n’atteint plus ses objets (« La brosse… où ai-je… Qu’importe »). Il ne lui reste que la **parole** et le **souvenir** (« Il y avait un bal, autrefois »).\n2. Didascalies : « *regard fixe devant elle* », « *Pause* », « *Pause longue* », « *Sourire qui s’éteint* ». Elles fixent la **durée des pauses**, la **direction du regard**, les **gestes comptés** : le comédien n’a presque pas de liberté. C’est une **partition** : comme en musique, le texte note les silences et les rythmes, et il **refuse au metteur en scène la liberté d’interpréter**.\n3. La **brosse** (qu’elle ne trouve plus), le souvenir d’un **bal** **incomplet** (« un bal… »), l’**adresse à Willie** qui reste sans réponse : les supports de la mémoire s’effritent.\n4. Non. « Encore un jour divin » n’est **ni naïveté ni aveuglement** : c’est une **stratégie de survie**. La pièce la traite avec un mélange de **tendresse et d’ironie** (le sourire qui s’éteint) qui **interdit de trancher**."}$exo$::jsonb),
  ('093b4756-43e7-5d6a-8f9f-9be32e3fdf23'::uuid, 3, 'redaction', $exo${"titre":"Que reste-t-il de l’humain quand tout est ôté ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur la pièce telle que le cours la présente.","enonce":"**Sujet.** Winnie est-elle **courageuse** ou **aveugle** ?\n\nTu t’appuieras sur ce que Beckett retire au théâtre, sur le mouvement de la pièce (le corps disparaît, le langage continue), sur l’optimisme de Winnie et ses objets, sur le rôle des didascalies, et tu montreras ce que la pièce dit de ce qui reste de l’humain.","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Lecture « aveugle » : formule répétée malgré l’enfouissement, objets qui s’effacent, citations perdues","points":4},{"critere":"Lecture « courageuse » : parole qui continue, stratégie de survie, héroïsme de l’optimisme","points":5},{"critere":"Le texte ne tranche pas : tendresse et ironie ; didascalies qui fixent ce double jeu","points":4},{"critere":"Ce qui reste : une voix, une adresse à l’autre, un rituel ; conclusion","points":4}],"dureeMin":20,"corrige":"**Introduction** : enterrée jusqu’au cou, Winnie dit encore « Encore un jour divin ». Problématique : son optimisme est-il héroïsme ou aveuglement ?\n\n**I. Une femme qui refuse de voir ?** Beckett retire au théâtre l’intrigue, le personnage psychologique, l’espace vraisemblable, le temps : restent un mamelon, une lumière crue, une sonnerie. Winnie parle pourtant de beau jour. Ses objets se défont : une **brosse à dents** dont l’inscription **s’efface**, un souvenir de **bal** incomplet, une **citation** à moitié perdue. On pourrait y voir un aveuglement.\n\n**II. Une femme qui continue.** Le mouvement de la pièce est implacable : **le corps disparaît, le langage continue**. À l’acte II, il ne reste que la **parole** et le **souvenir** ; Winnie parle quand même. Son optimisme n’est **ni naïveté ni aveuglement** : c’est une **stratégie de survie**, un héroïsme discret. L’humain tient **moins à ce qu’il peut faire qu’à ce qu’il peut encore dire**, et il y tient **jusqu’au bout**.\n\n**III. Un texte qui ne tranche pas.** La pièce traite Winnie avec un mélange de **tendresse et d’ironie** qui **interdit de trancher**, et c’est ce qui la rend forte. Les **didascalies**, d’une précision extrême (pauses, regards, gestes comptés), fixent ce double jeu : une **partition** qui refuse au metteur en scène la liberté d’interpréter.\n\n**Conclusion** : Winnie est peut-être les deux. Quand tout est ôté, il reste une **voix**, une **adresse à l’autre**, un **rituel** ; au théâtre, **la parole est l’action**, et le rire et le désespoir sont **indissociables**."}$exo$::jsonb),
  ('efd45025-e850-5788-a424-671236edf444'::uuid, 1, 'redaction', $exo${"titre":"Montaigne et ses Essais","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Quand paraissent les *Essais* ? Jusqu’à quand Montaigne les augmente-t-il ?\n2. Que signifie le mot « **essai** » ? En quoi ce genre s’oppose-t-il à un **traité** ?\n3. Quels chapitres le programme retient-il, avec quel parcours ?\n4. Quelle est la thèse célèbre de « Des Cannibales » ?","bareme":[{"critere":"À partir de 1580, augmentés jusqu’à la mort de Montaigne en 1592","points":4},{"critere":"Essai = tentative, pensée qui avance, se contredit, digresse ; opposé au traité","points":6},{"critere":"« Des Cannibales » (I, 31), « Des Coches » (III, 6), parcours « notre monde vient d’en trouver un autre »","points":5},{"critere":"« Chacun appelle barbarie ce qui n’est pas de son usage »","points":5}],"dureeMin":7,"corrige":"1. Les *Essais* paraissent à partir de **1580** et sont augmentés jusqu’à la mort de Montaigne, en **1592**.\n2. « Essai » veut dire **tentative**, pesée, mise à l’épreuve. Montaigne n’écrit pas un **traité** (démonstration close) : il **pense en avançant**, se **contredit**, revient, cite, **digresse**. « Je ne peins pas l’être, je peins le **passage**. »\n3. **« Des Cannibales »** (I, 31) et **« Des Coches »** (III, 6), avec le parcours **« notre monde vient d’en trouver un autre »**.\n4. « **Chacun appelle barbarie ce qui n’est pas de son usage.** » Le mot barbare cesse de désigner l’autre : il désigne le **jugement de celui qui le prononce**."}$exo$::jsonb),
  ('efd45025-e850-5788-a424-671236edf444'::uuid, 2, 'redaction', $exo${"titre":"Qui sont les barbares ?","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Qui Montaigne a-t-il rencontré à **Rouen** ?\n2. Complète la comparaison de « Des Cannibales » : chez « eux », … ; chez « nous », … Que cherche à montrer ce rapprochement ?\n3. Explique en quoi, après ce chapitre, le mot **barbare** « désigne le jugement de celui qui le prononce ».\n4. Dans « **Des Coches** », que dénonce Montaigne ? Quel **écart** souligne-t-il chez les conquérants ? Que regrette-t-il ?","bareme":[{"critere":"Des Tupinambas du Brésil amenés en France","points":3},{"critere":"Anthropophagie rituelle sur un ennemi mort contre torture de vivants au nom de la religion ; retournement du reproche","points":6},{"critere":"Barbare : notion relative à l’usage, qui révèle celui qui juge","points":4},{"critere":"Des Coches : villes rasées, nations exterminées ; supériorité technique et infériorité morale ; un échange devenu massacre","points":7}],"dureeMin":11,"corrige":"1. Des **Tupinambas** du **Brésil**, amenés en France.\n2. Chez « eux » : l’**anthropophagie rituelle** sur un ennemi **mort** ; chez « nous » : la **torture de vivants**, au nom de la **religion**. Le rapprochement retourne le reproche : ceux qui accusent les autres de barbarie pratiquent pire.\n3. Puisque chacun appelle barbarie **ce qui n’est pas de son usage**, le mot ne décrit pas une réalité mais une **habitude** : il dit surtout le point de vue, et les préjugés, de celui qui juge.\n4. Montaigne dénonce la **destruction des civilisations américaines** : « **tant de villes rasées, tant de nations exterminées** ». Il souligne l’écart entre la **supériorité technique** et l’**infériorité morale** des conquérants, qui ont gagné par les armes, non par la valeur. Il regrette que cette rencontre, **qui aurait pu être un échange**, ait été un **massacre**."}$exo$::jsonb),
  ('efd45025-e850-5788-a424-671236edf444'::uuid, 3, 'redaction', $exo${"titre":"Retourner le regard contre l’Europe","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur les deux chapitres tels que le cours les présente.","enonce":"**Sujet.** Le cours présente les *Essais* comme « le premier grand texte européen à retourner le regard ethnographique contre l’Europe elle-même ». Explique et justifie cette affirmation.\n\nTu t’appuieras sur « Des Cannibales », sur « Des Coches », sur la nature du genre de l’essai et sur l’écriture de Montaigne (phrase, citations, anecdotes, ironie, usage du « je »).","bareme":[{"critere":"Problématique et plan annoncé","points":3},{"critere":"« Des Cannibales » : rencontre des Tupinambas, comparaison des pratiques, sens nouveau de « barbare »","points":5},{"critere":"« Des Coches » : conquête dénoncée, écart technique/moral, échange manqué","points":5},{"critere":"L’essai et l’écriture : pensée en mouvement, citations, anecdotes, ironie douce, « je » qui relativise","points":4},{"critere":"Conclusion qui répond au sujet","points":3}],"dureeMin":20,"corrige":"**Introduction** : au XVIe siècle, l’Europe découvre des peuples qu’elle décrit comme sauvages. Montaigne inverse l’observation. Problématique : comment les *Essais* font-ils de l’Europe l’objet du regard critique ?\n\n**I. « Des Cannibales » : qui est barbare ?** Montaigne a rencontré à **Rouen** des **Tupinambas**. Il compare l’**anthropophagie rituelle** sur un ennemi mort à la **torture de vivants** au nom de la religion, pratiquée en Europe. Conclusion : « **Chacun appelle barbarie ce qui n’est pas de son usage.** » Le mot barbare désigne désormais le **jugement de celui qui le prononce**.\n\n**II. « Des Coches » : la conquête jugée.** Le chapitre glisse du luxe des princes à la **conquête du Nouveau Monde** : « **tant de villes rasées, tant de nations exterminées** ». Les conquérants ont une **supériorité technique** mais une **infériorité morale** : ils ont gagné par les armes, non par la valeur. Une rencontre qui aurait pu être un **échange** a été un **massacre**.\n\n**III. Une écriture faite pour douter.** L’**essai** est une **tentative** : Montaigne pense en avançant, se contredit, digresse ; « je peins le **passage** ». Sa phrase est **longue et mobile**, nourrie de **citations antiques**, d’**anecdotes**, de comparaisons concrètes ; l’**ironie** est constante mais **douce** ; le « je » sert à **relativiser**. Le sujet est lui-même, mais comme **instrument** pour examiner l’homme en général.\n\n**Conclusion** : l’affirmation est juste : l’observateur européen devient l’observé, et la critique porte sur ceux qui se croyaient civilisés."}$exo$::jsonb),
  ('17aa74fc-6fd2-58ee-a5bd-8582b4a1b214'::uuid, 1, 'redaction', $exo${"titre":"Le doute de Montaigne","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. De qui est la formule « notre monde vient d’en trouver un autre » ? Dans quel chapitre ?\n2. Pourquoi la découverte de **1492** ébranle-t-elle l’autorité des **Anciens** ?\n3. Quelle **méthode** Montaigne en tire-t-il ? Quelle est sa **devise** ?\n4. Comment s’appellent les **ajouts** successifs de Montaigne à son texte ? Que montrent-ils ?","bareme":[{"critere":"Formule de Montaigne, dans « Des Coches »","points":3},{"critere":"1492 : un continent qu’aucun savoir (Bible, Aristote, Ptolémée) n’avait prévu ; doute sur les autres certitudes","points":6},{"critere":"Doute comme discipline de la pensée, « Que sais-je ? »","points":6},{"critere":"Les allongeails ; une pensée qui bouge","points":5}],"dureeMin":7,"corrige":"1. La formule est **de Montaigne lui-même**, dans **« Des Coches »**.\n2. En **1492**, l’Europe apprend qu’il existe un continent que **ni la Bible, ni Aristote, ni Ptolémée** n’avaient prévu. Si l’on a pu ignorer **un monde entier**, que vaut le reste de nos certitudes ?\n3. Montaigne en tire une méthode : le **doute**, non par scepticisme paresseux, mais comme **discipline de la pensée**. Sa devise est une question : « **Que sais-je ?** »\n4. Ce sont les « **allongeails** », ajouts d’une édition à l’autre. Avec les digressions et le refus de conclure, ils montrent que **la forme dit la thèse** : une pensée honnête est une pensée qui **bouge**."}$exo$::jsonb),
  ('17aa74fc-6fd2-58ee-a5bd-8582b4a1b214'::uuid, 2, 'redaction', $exo${"titre":"« Pour Montaigne, tout se vaut » : corrige l’erreur","consigne":"Lis la phrase d’une copie d’élève (inventée pour l’exercice), puis réponds en t’appuyant sur le cours.","enonce":"> *Extrait d’une copie :* « Montaigne est relativiste : pour lui, toutes les coutumes se valent, donc il refuse de juger qui que ce soit. Sa description des Tupinambas est un reportage exact sur leur société. »\n\n1. Qu’est-ce que Montaigne **déplace** vraiment ? Donne les deux idées du cours sur la **nature** et la **barbarie**.\n2. Montre que Montaigne **juge** : que condamne-t-il fermement ?\n3. La description des Tupinambas est-elle un « reportage exact » ? Quelle est sa **fonction** ?\n4. Réécris la phrase de l’élève en deux ou trois phrases justes.","bareme":[{"critere":"Ce qu’il déplace : nature = souvent habitude ; barbarie = usage d’un autre","points":5},{"critere":"Il juge : torture, avidité, cruauté des conquérants ; relativisme comme instrument critique","points":5},{"critere":"Description idéalisée, utopie critique, miroir tendu à une France des guerres de religion","points":6},{"critere":"Réécriture juste et nuancée","points":4}],"dureeMin":12,"corrige":"1. Montaigne montre que ce que nous appelons **nature** n’est souvent que l’**habitude**, et que ce que nous appelons **barbarie** n’est que l’**usage d’un autre**.\n2. Mais il **ne dit pas que tout se vaut** : il **juge**, et condamne fermement la **torture**, l’**avidité**, la **cruauté** des conquérants. Son relativisme est un **instrument critique**, **pas une démission morale** : il **déplace le tribunal**.\n3. Non. La société **sans commerce, sans écriture, sans magistrature, sans propriété** qu’il décrit est **idéalisée**, et Montaigne le sait à demi. Elle sert d’**utopie critique** : elle rend visibles, **par contraste**, les vices d’une France déchirée par les **guerres de religion**. C’est un **miroir tendu à l’Europe**, pas une ethnographie (mythe du bon sauvage, avant Rousseau).\n4. Exemple : « Montaigne montre que nos jugements dépendent de nos habitudes, mais il ne renonce pas à juger : il condamne la torture et la cruauté des conquérants. Sa description idéalisée des Tupinambas est un miroir critique tendu à l’Europe, non un reportage. »"}$exo$::jsonb),
  ('17aa74fc-6fd2-58ee-a5bd-8582b4a1b214'::uuid, 3, 'redaction', $exo${"titre":"L’autre nous apprend-il sur lui ou sur nous ?","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur les Essais tels que le cours les présente.","enonce":"**Sujet.** Dans les *Essais*, la rencontre de l’autre nous apprend-elle davantage **sur lui** ou **sur nous** ?\n\nTu t’appuieras sur le choc de 1492 et le doute, sur le relativisme et ses limites, sur le mythe du bon sauvage, et sur l’écriture de l’essai (digressions, allongeails, refus de conclure, écrire sur soi).","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Ce que l’on apprend de l’autre : une société différente, une découverte qui ébranle les savoirs","points":4},{"critere":"Ce que l’on apprend sur nous : habitude prise pour nature, barbarie retournée, miroir tendu à l’Europe des guerres de religion","points":6},{"critere":"Relativisme sans démission morale ; description idéalisée assumée","points":4},{"critere":"Écriture de l’essai et « je » instrument ; conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : « notre monde vient d’en trouver un autre », écrit Montaigne dans « Des Coches ». Problématique : cette rencontre éclaire-t-elle l’autre ou nous-mêmes ?\n\n**I. Découvrir l’autre.** 1492 révèle un continent que ni la Bible, ni Aristote, ni Ptolémée n’avaient prévu : c’est une connaissance nouvelle, qui **ébranle l’autorité des Anciens**. Montaigne décrit les Tupinambas, une société sans commerce, sans écriture, sans magistrature, sans propriété.\n\n**II. Mais surtout se découvrir.** Cette description est **idéalisée**, et Montaigne le sait à demi : c’est une **utopie critique**, un **miroir tendu à l’Europe** déchirée par les **guerres de religion**. La rencontre montre que ce que nous croyons **nature** n’est qu’**habitude**, et que la **barbarie** est souvent chez nous. Le texte penche nettement vers « **sur nous** ».\n\n**III. Un savoir sur nous qui n’abolit pas le jugement.** Le relativisme n’est **pas une démission morale** : Montaigne condamne la torture, l’avidité, la cruauté des conquérants ; il **déplace le tribunal**. Sa méthode est le **doute** (« **Que sais-je ?** »), discipline de la pensée. L’écriture le montre : digressions, **allongeails**, **refus de conclure** ; **la forme dit la thèse**. Et écrire sur soi, dès l’avis au lecteur, sert à examiner l’homme en général.\n\n**Conclusion** : l’autre nous apprend quelque chose de lui, mais bien plus sur nous ; c’est là la leçon critique des *Essais*."}$exo$::jsonb),
  ('6668b03c-9c51-573f-8996-0abd1c5cae8e'::uuid, 1, 'redaction', $exo${"titre":"Les Fables des livres VII à XI","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Quels livres des *Fables* le programme retient-il ? À partir de quelle année paraissent-ils ? Quand avait paru le premier recueil ?\n2. À quels auteurs antiques La Fontaine emprunte-t-il ?\n3. Quels **vers** emploie-t-il et quel effet produisent-ils ?\n4. Recopie le principe par lequel La Fontaine justifie le récit (« une morale nue… »).\n5. En quoi le second recueil diffère-t-il du premier ?","bareme":[{"critere":"Livres VII à XI, 1678 ; premier recueil I à VI en 1668","points":5},{"critere":"Ésope et Phèdre ; vers libres (alexandrins et octosyllabes) qui épousent le rythme du récit","points":6},{"critere":"Principe exact et second recueil plus sombre, philosophique, adressé à la cour","points":9}],"dureeMin":7,"corrige":"1. Les **livres VII à XI**, publiés à partir de **1678** ; le premier recueil (livres I à VI) datait de **1668**.\n2. À **Ésope** et à **Phèdre**.\n3. Des **vers libres** : alexandrins et octosyllabes alternés ; le mètre **épouse le rythme du récit**.\n4. « **Une morale nue apporte de l’ennui : le conte fait passer le précepte avec lui.** »\n5. Le second recueil est **plus sombre**, **plus philosophique**, souvent **adressé à la cour**."}$exo$::jsonb),
  ('6668b03c-9c51-573f-8996-0abd1c5cae8e'::uuid, 2, 'redaction', $exo${"titre":"Puissant ou misérable","consigne":"Réponds en rédigeant et en citant les vers donnés.","enonce":"> « Selon que vous serez puissant ou misérable,\n> Les jugements de cour vous rendront blanc ou noir. »\n> (« Les Animaux malades de la peste »)\n\n1. Relève les **antithèses** de ces deux vers. Qu’expriment-elles sur la **justice** ?\n2. Quelle est la place de cette **morale** dans la fable ? Pourquoi est-elle frappante à cet endroit ?\n3. Qui représente le **roi** dans les fables de cour ? Comment la **cour** est-elle montrée ?\n4. Pourquoi l’**apologue** animal permet-il à La Fontaine de dire ces choses ?","bareme":[{"critere":"Antithèses puissant/misérable et blanc/noir relevées ; justice réglée sur la force","points":6},{"critere":"Morale finale, en chute nette : effet de sentence","points":4},{"critere":"Le lion = le roi ; la cour, théâtre d’hypocrisie","points":5},{"critere":"Le masque animal permet de dire ce qu’un sujet de Louis XIV ne pouvait dire en son nom","points":5}],"dureeMin":11,"corrige":"1. Deux **antithèses** : « **puissant** / **misérable** » et « **blanc** / **noir** ». Le parallélisme associe le puissant au blanc (innocenté) et le misérable au noir (condamné) : la **justice se règle sur la force**, non sur la faute.\n2. C’est une **morale en fin de fable**, explicite : elle tombe comme une **chute nette**, après le récit, et frappe comme une sentence qu’on retient.\n3. Le **lion** représente le **roi** ; la **cour** est un **théâtre d’hypocrisie**, où les puissants se justifient et où l’on accable le plus faible.\n4. L’**apologue** permet de dire, **sous le masque animal**, ce qu’un sujet de Louis XIV **ne pouvait pas dire en son nom** : c’est une argumentation indirecte, qui plaît pour instruire."}$exo$::jsonb),
  ('6668b03c-9c51-573f-8996-0abd1c5cae8e'::uuid, 3, 'redaction', $exo${"titre":"Plaire pour instruire","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur les Fables telles que le cours les présente.","enonce":"**Sujet.** « Une morale nue apporte de l’ennui : le conte fait passer le précepte avec lui. » Le plaisir du récit est-il seulement un moyen de faire passer la morale dans les *Fables* de La Fontaine ?\n\nTu t’appuieras sur l’art de la fable (vers libres, dialogues, changements de ton, chute), sur la satire de la cour, et sur les différentes places de la morale.","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Le récit comme moyen : conte qui fait passer le précepte, chute, morale explicite","points":4},{"critere":"L’art de la fable pour lui-même : vers libres, dialogues, changements de ton du burlesque au grave","points":5},{"critere":"Satire de la cour sous le masque animal (lion, justice selon la force, citation)","points":4},{"critere":"Morale absente, ironique ou contredite : la liberté du lecteur ; conclusion","points":4}],"dureeMin":20,"corrige":"**Introduction** : La Fontaine formule lui-même le principe de la fable : plaire pour instruire. Problématique : le récit n’est-il qu’un habillage de la morale ?\n\n**I. Le récit au service de la morale.** « **Une morale nue apporte de l’ennui : le conte fait passer le précepte avec lui.** » La fable emprunte à Ésope et à Phèdre ; la **chute**, nette, souvent en un vers, fixe la leçon. La morale, en **tête** ou en **fin**, est souvent **explicite**.\n\n**II. Un art qui vaut par lui-même.** Les **vers libres** (alexandrins et octosyllabes alternés) épousent le rythme du récit ; les **dialogues** font de la fable une petite scène ; les **changements de ton** vont du burlesque au grave. Le second recueil (livres VII à XI, 1678), plus sombre et philosophique, fait penser autant qu’il enseigne.\n\n**III. Une morale qui exige un lecteur.** Sous le masque animal, la fable est **satire** : le **lion** est le **roi**, la **cour** un théâtre d’**hypocrisie**, la **justice** se règle sur la **force** : « Selon que vous serez puissant ou misérable, / Les jugements de cour vous rendront blanc ou noir. » Surtout, la morale est parfois **absente** ou **ironique** (le lecteur doit conclure lui-même), voire **contredite par le récit** : la fable devient un **piège à lecture rapide**.\n\n**Conclusion** : le plaisir du récit n’est pas un simple emballage ; il ménage au lecteur une **part de liberté**, et c’est ce qui fait que ces fables **ne vieillissent pas**."}$exo$::jsonb),
  ('c01c222d-5a80-5e80-b212-19611e82b25d'::uuid, 1, 'redaction', $exo${"titre":"Deux Persans à Paris","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qui a écrit les *Lettres persanes* ? Où, quand et comment l’œuvre est-elle publiée ? À quel genre appartient-elle ?\n2. Qui sont **Usbek** et **Rica** ? D’où partent-ils ?\n3. Combien de lettres compte le roman ? À qui sont-elles adressées ?\n4. Quelle période historique découvrent-ils à Paris ?","bareme":[{"critere":"Montesquieu, Amsterdam, 1721, anonymement, roman épistolaire","points":6},{"critere":"Deux Persans partis d’Ispahan ; Rica jeune et moqueur, Usbek grave","points":5},{"critere":"161 lettres, une quinzaine de correspondants (amis, eunuques, femmes du sérail)","points":5},{"critere":"Fin du règne de Louis XIV puis la Régence","points":4}],"dureeMin":6,"corrige":"1. **Montesquieu** ; publié **anonymement** à **Amsterdam** en **1721** ; c’est un **roman épistolaire**.\n2. **Usbek** et **Rica** sont deux **Persans** partis d’**Ispahan** pour voyager en Europe. Rica est jeune, **gai, moqueur** ; Usbek est **grave**.\n3. **161 lettres** croisées, d’une quinzaine de correspondants : leurs **amis**, leurs **eunuques**, leurs **femmes restées au sérail**.\n4. Ils découvrent Paris, la cour de **Louis XIV** puis la **Régence** : la mode, la religion, les académies, les cafés, les femmes libres de leurs mouvements."}$exo$::jsonb),
  ('c01c222d-5a80-5e80-b212-19611e82b25d'::uuid, 2, 'redaction', $exo${"titre":"Le roi magicien","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"Rica décrit le roi de France comme « un grand magicien » qui fait croire que « le papier est de l’argent », et le pape comme « un autre magicien » qui fait croire que « trois ne font qu’un ».\n\n1. Explique le **procédé** utilisé. Pourquoi ces descriptions sont-elles comiques et critiques à la fois ?\n2. Quelles **institutions** sont visées par ces deux images ?\n3. Explique le retournement de la formule : « Comment peut-on être Persan ? »\n4. Compare **Rica** et **Usbek** : âge, ton, sujets.","bareme":[{"critere":"Regard éloigné : décrire nos usages par qui ne les comprend pas ; effet comique et critique","points":6},{"critere":"Cibles : le pouvoir royal (et sa monnaie) et l’Église (le dogme)","points":4},{"critere":"Formule expliquée : les Parisiens trouvent l’autre étrange sans voir leur propre étrangeté","points":5},{"critere":"Rica jeune, gai, portraits satiriques ; Usbek grave, lois, justice, religion, despotisme","points":5}],"dureeMin":11,"corrige":"1. C’est le **regard éloigné** : faire décrire **nos** usages par quelqu’un **qui ne les comprend pas**. Rica prend au pied de la lettre ce que l’habitude rendait normal : il ne voit que de la « magie ». C’est **comique** par la naïveté apparente, et **critique** parce que le lecteur voit soudain ces usages comme des tours de passe-passe fondés sur la crédulité.\n2. Le **roi** et son pouvoir (faire accepter du papier comme de l’argent) ; le **pape** et l’**Église** (faire croire que trois ne font qu’un).\n3. Les Parisiens, apprenant que Rica est persan, s’étonnent : « **Ah ! ah ! Monsieur est Persan ? C’est une chose bien extraordinaire ! Comment peut-on être Persan ?** » La formule se retourne contre eux : ils trouvent l’autre étrange sans voir que leurs propres usages le sont tout autant. C’est toute la leçon du regard éloigné.\n4. **Rica** : jeune, **gai, moqueur**, auteur de **portraits satiriques** de la société française. **Usbek** : **grave**, il réfléchit sur les **lois**, la **justice**, la **religion**, le **despotisme**."}$exo$::jsonb),
  ('c01c222d-5a80-5e80-b212-19611e82b25d'::uuid, 3, 'redaction', $exo${"titre":"Satire et tragédie","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur l’œuvre telle que le cours la présente.","enonce":"**Sujet.** Les *Lettres persanes* ne sont-elles qu’une **satire amusante** de la société française ?\n\nTu t’appuieras sur le dispositif du roman, sur le regard éloigné et ses cibles, sur les deux voix de Rica et d’Usbek, et sur « l’autre roman » : celui du sérail et de la dernière lettre de Roxane.","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"La satire : regard éloigné, roi et pape magiciens, « Comment peut-on être Persan ? »","points":5},{"critere":"Deux voix : Rica satirique, Usbek grave qui réfléchit au despotisme","points":4},{"critere":"Le sérail : révolte des femmes, dernière lettre de Roxane (trahison, poison, jamais aimé)","points":5},{"critere":"Leçon : le penseur de la liberté est un tyran chez lui ; satire et tragédie unies ; conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : publié anonymement en 1721, le roman de Montesquieu fait rire de Paris à travers deux Persans. Problématique : ce rire est-il tout le livre ?\n\n**I. Une satire brillante.** Le **regard éloigné** fait décrire nos usages par qui ne les comprend pas : le roi, « un grand **magicien** » qui fait croire que le papier est de l’argent ; le pape, qui fait croire que trois ne font qu’un. La formule « **Comment peut-on être Persan ?** » retourne l’étrangeté contre les Parisiens. **Rica**, jeune et moqueur, multiplie les portraits satiriques.\n\n**II. Une réflexion politique.** **Usbek**, grave, réfléchit sur les **lois**, la justice, la religion, le **despotisme**. Le roman ne fait pas seulement rire, il fait penser.\n\n**III. L’autre roman : le sérail.** Pendant que les voyageurs **philosophent sur la liberté**, les femmes d’Usbek **se révoltent** à Ispahan. La **dernière lettre** est celle de **Roxane** : elle a trahi, elle s’est **empoisonnée**, elle **n’a jamais aimé** son maître. Usbek, qui dénonce le despotisme, **l’incarne dans sa propre maison**, sans le voir.\n\n**Conclusion** : la leçon est cinglante : **le penseur de la liberté était un tyran chez lui**. Le roman fait tenir ensemble **satire** et **tragédie** : il n’est donc pas qu’une satire amusante."}$exo$::jsonb),
  ('4d643ae0-554c-5aed-a48f-6b4926c13f31'::uuid, 1, 'redaction', $exo${"titre":"Pourquoi passer par la fiction ?","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. En **1721**, à quoi s’expose un auteur qui attaque de front la monarchie, l’Église ou la justice ?\n2. Donne les **trois avantages** du détour par la fiction, avec leur explication.\n3. Cite **quatre cibles** des *Lettres persanes* et ce qui est dénoncé pour chacune.","bareme":[{"critere":"Censure et Bastille","points":3},{"critere":"Trois avantages : désavouer ses personnages, l’habitude ne protège plus, ce dont on rit cesse d’être sacré","points":9},{"critere":"Quatre cibles avec ce qui est dénoncé (monarchie, Église, justice, mode, démographie, fanatisme)","points":8}],"dureeMin":7,"corrige":"1. Il s’expose à la **censure** et à la **Bastille**.\n2. **Échapper à la censure** : l’auteur peut **désavouer ses personnages**. **Dépayser** le lecteur : l’**habitude ne protège plus** les institutions. **Faire rire** : or **ce dont on rit cesse d’être sacré**.\n3. La **monarchie absolue** (la vanité de la cour) ; l’**Église** (ses querelles théologiques, son intolérance) ; la **justice** (sa lenteur et sa vénalité) ; la **mode** (l’inconstance parisienne) ; la **démographie** (Usbek s’interroge sur la dépopulation) ; le **fanatisme** religieux. Quatre suffisent."}$exo$::jsonb),
  ('4d643ae0-554c-5aed-a48f-6b4926c13f31'::uuid, 2, 'redaction', $exo${"titre":"L’apologue des Troglodytes","consigne":"Réponds en rédigeant et en t’appuyant sur le cours.","enonce":"1. Où se trouve l’**apologue des Troglodytes** dans le roman ? Qu’est-ce qu’un récit inséré ?\n2. Résume ses **trois étapes** : le peuple égoïste, la communauté vertueuse, la suite.\n3. Pourquoi la communauté vertueuse finit-elle par **demander un roi** ? Qu’est-ce que cela suggère sur la vertu ?\n4. Quelle **question** cet apologue pose-t-il ? Dans quel ouvrage Montesquieu la reprendra-t-il, et en quelle année ?","bareme":[{"critere":"Lettres XI à XIV, récit inséré dans le roman","points":4},{"critere":"Trois étapes justes : égoïstes qui s’autodétruisent, vertueux qui prospèrent, demande d’un roi","points":6},{"critere":"La vertu jugée trop exigeante : on préfère obéir à un roi","points":5},{"critere":"Quelles institutions rendent la liberté possible ? De l’esprit des lois, 1748","points":5}],"dureeMin":11,"corrige":"1. Les lettres **XI à XIV** forment un **récit inséré** : une petite histoire racontée à l’intérieur du roman, qui fonctionne comme un **conte politique**.\n2. Un peuple **égoïste** **s’autodétruit** ; une petite communauté **vertueuse** **prospère** ; puis elle **demande un roi**.\n3. Elle demande un roi parce que la vertu est **trop exigeante** : obéir à un maître est plus facile que se gouverner soi-même par la vertu. L’apologue suggère que la vertu seule ne suffit pas à fonder durablement une société libre.\n4. Il pose la question qui occupera Montesquieu toute sa vie : **quelles institutions rendent la liberté possible ?** Il la reprendra dans ***De l’esprit des lois***, en **1748**."}$exo$::jsonb),
  ('4d643ae0-554c-5aed-a48f-6b4926c13f31'::uuid, 3, 'redaction', $exo${"titre":"La fiction contre le despotisme","consigne":"Rédige une dissertation (introduction avec problématique, deux ou trois parties, conclusion) en t’appuyant sur les Lettres persanes telles que le cours les présente.","enonce":"**Sujet.** La **fiction** sert-elle mieux la critique du pouvoir que le **traité** ?\n\nTu t’appuieras sur les avantages du détour, les cibles de la satire, l’apologue des Troglodytes, le sérail comme laboratoire du despotisme, la question de la **neutralité** du regard étranger, et tu pourras comparer avec *De l’esprit des lois*.","bareme":[{"critere":"Problématique et plan dialectique","points":3},{"critere":"Avantages du détour : censure, dépaysement, rire ; cibles de la satire","points":5},{"critere":"Troglodytes et sérail : fiction qui pense (vertu, institutions ; despotisme sans lois, peur, effondrement)","points":5},{"critere":"Regard étranger non neutre : Usbek juge et est jugé ; sa contradiction","points":4},{"critere":"Limites et comparaison avec De l’esprit des lois (1748) ; conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : Montesquieu a critiqué le pouvoir par un roman épistolaire (1721), puis par un traité (*De l’esprit des lois*, 1748). Problématique : la fiction est-elle l’arme la plus efficace ?\n\n**I. Les forces du détour.** Attaquer de front, en 1721, expose à la **censure** et à la **Bastille**. La fiction permet de **désavouer ses personnages**, de **dépayser** (l’habitude ne protège plus les institutions) et de **faire rire** (ce dont on rit cesse d’être sacré). Elle vise la **monarchie absolue**, l’**Église**, la **justice**, la **mode**, le **fanatisme**.\n\n**II. Une fiction qui pense.** L’**apologue des Troglodytes** (lettres XI à XIV) montre des égoïstes qui s’autodétruisent, des vertueux qui prospèrent puis demandent un roi : **quelles institutions rendent la liberté possible ?** Le **sérail** est un **modèle réduit** du pouvoir absolu : surveillance, eunuques, punitions ; l’obéissance par la **peur** ; faute de **lois**, l’**effondrement final**. Le regard étranger n’est **pas neutre** : Usbek juge, et il est jugé ; il dénonce le despotisme et l’**exerce** : c’est la **trouvaille du livre**.\n\n**III. Les limites.** La fiction suggère plus qu’elle ne démontre ; le traité, lui, peut construire une théorie des institutions. Montesquieu y viendra avec *De l’esprit des lois*.\n\n**Conclusion** : la fiction sert remarquablement la critique, car elle fait rire, émeut et montre les contradictions de l’intérieur ; le traité la prolonge en démontrant. Les deux sont complémentaires."}$exo$::jsonb),
  ('2360d954-43fc-5b0a-a5bd-355b790bd3c4'::uuid, 1, 'redaction', $exo${"titre":"Julien Sorel, un héros ni bon ni mauvais","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. Cite **deux actes condamnables** de Julien Sorel et **deux qualités** qui le grandissent.\n2. Quel mot le cours emploie-t-il pour qualifier ce personnage ? Explique ce qu'il signifie et ce qu'on ressent en le lisant.\n3. Quelle période politique le roman peint-il, et quel sort cette société fait-elle aux talents sans naissance ?","bareme":[{"critere":"Deux actes condamnables et deux qualités exacts (mensonge, trahison, coup de feu / courage, loyauté, sincérité, grandeur)","points":8},{"critere":"Personnage ambivalent : on épouse son point de vue sans l'approuver","points":6},{"critere":"Restauration finissante en 1830, mépris des talents sans naissance, société bloquée","points":6}],"dureeMin":7,"corrige":"1. Actes condamnables : Julien **ment**, calcule et séduit **par ambition** ; il **trahit** ; il **tire sur une femme qu'il aime** (Madame de Rênal). Qualités : il est **courageux**, **loyal** envers l'abbé Pirard, **sincère** avec son ami Fouqué, et il atteint une **grandeur** que personne autour de lui n'atteint.\n2. Julien est un personnage **ambivalent**, ni bon ni mauvais. Le roman **refuse de trancher** : le lecteur **épouse son point de vue sans l'approuver**. C'est une révolution esthétique : le héros n'est plus un modèle.\n3. Le roman peint la **Restauration finissante**, en **1830** : noblesse revenue, cléricalisme, congrégation. Cette société a du **mépris pour les talents sans naissance** : c'est une **société bloquée**, où l'énergie individuelle n'a plus d'issue légitime."}$exo$::jsonb),
  ('2360d954-43fc-5b0a-a5bd-355b790bd3c4'::uuid, 2, 'redaction', $exo${"titre":"Entendre la pensée de Julien","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour l'exercice, à la manière du roman)**\n\n> Julien sortit du salon le cœur battant. Le maire l'avait traité comme un domestique, devant ses enfants. Eh bien ! il saurait se venger. Il serait plus poli que jamais, plus savant que tous ces messieurs réunis ; un jour, c'est lui qu'on attendrait. Notre héros, qui se croyait fort habile, oubliait seulement qu'il tremblait encore.\n\n1. Relève la phrase qui fait entendre la **pensée de Julien** sans guillemets ni verbe introducteur. Nomme ce procédé et explique son effet.\n2. Relève la phrase où le **narrateur** reprend la parole. Quel ton adopte-t-il ? Nomme ce trait de l'écriture de Stendhal.\n3. En quoi ce court passage illustre-t-il le rapport du lecteur à un personnage **ambivalent** ?","bareme":[{"critere":"Repérage d'une phrase au discours indirect libre (« Eh bien ! il saurait se venger » ou suivantes) et nom exact du procédé","points":6},{"critere":"Effet expliqué : la pensée du personnage entendue dans le récit","points":3},{"critere":"Dernière phrase identifiée ; ironie stendhalienne, distance du narrateur","points":6},{"critere":"Lien avec l'ambivalence : on partage son point de vue sans l'approuver","points":5}],"dureeMin":10,"corrige":"1. « Eh bien ! il saurait se venger. Il serait plus poli que jamais, plus savant que tous ces messieurs réunis ; un jour, c'est lui qu'on attendrait. » C'est le **discours indirect libre** : pas de guillemets ni de « il pensa que », mais l'exclamation et le conditionnel font entendre la voix de Julien **à l'intérieur du récit**. Le lecteur est placé au plus près de ses **calculs** (focalisation interne).\n2. « Notre héros, qui se croyait fort habile, oubliait seulement qu'il tremblait encore. » Le narrateur **commente** et prend ses distances : « notre héros », « se croyait fort habile » disent le contraire de ce qu'ils montrent. C'est l'**ironie stendhalienne**.\n3. Le passage mêle les deux voix : on vit l'humiliation et l'orgueil de Julien de l'intérieur, donc on le comprend ; mais l'ironie du narrateur nous empêche de l'admirer sans réserve. On **épouse son point de vue sans l'approuver** : c'est la définition du personnage ambivalent."}$exo$::jsonb),
  ('2360d954-43fc-5b0a-a5bd-355b790bd3c4'::uuid, 3, 'redaction', $exo${"titre":"Un personnage de roman doit-il être un modèle ?","consigne":"Construis une réflexion de type dissertation en t'appuyant uniquement sur Le Rouge et le Noir et sur les notions du cours.","enonce":"**Sujet** : « Un personnage de roman doit-il être un modèle ? » Tu répondras à partir du *Rouge et le Noir* (parcours : le personnage de roman, esthétiques et valeurs).\n\n1. Rédige une **introduction** courte : amorce, reformulation du sujet en problématique, annonce du plan.\n2. Propose un **plan en deux ou trois parties**, chacune avec une idée directrice, un argument et un exemple précis tiré du roman.\n3. Rédige **entièrement une sous-partie** (une dizaine de lignes) sur le rôle de la **focalisation interne** et du **discours indirect libre**.\n4. Réponds en deux phrases : l'**ambition** de Julien est-elle présentée comme une valeur ou comme un défaut ?","bareme":[{"critere":"Introduction avec problématique claire sur l'exemplarité du personnage","points":3},{"critere":"Plan cohérent et progressif, arguments justes, exemples précis du roman","points":7},{"critere":"Sous-partie rédigée expliquant comment focalisation interne et discours indirect libre font s'attacher à un personnage immoral","points":6},{"critere":"Ambition analysée comme une énergie que la société gâche","points":2},{"critere":"Expression correcte et vocabulaire d'analyse","points":2}],"dureeMin":20,"corrige":"1. Introduction possible : Longtemps, le héros de roman a été proposé à l'admiration. Avec Julien Sorel, Stendhal crée en 1830 un personnage qui ment, trahit et tire sur la femme qu'il aime, et qui pourtant nous attache. **Problématique** : un personnage doit-il être exemplaire pour avoir une valeur, ou sa force tient-elle à ses contradictions ? Nous verrons que Julien n'est pas un modèle, puis que c'est justement ce qui fait sa valeur romanesque et critique.\n2. Plan possible :\n- **I. Julien n'est pas un modèle moral** : il ment, calcule, séduit Madame de Rênal par ambition et orgueil de classe, trahit ; son crime à Verrières est condamnable.\n- **II. Mais il n'est pas non plus un repoussoir** : courage, loyauté envers Pirard, sincérité avec Fouqué, grandeur finale devant le jury ; le roman refuse de trancher : personnage **ambivalent**.\n- **III. Sa valeur est ailleurs : révéler une société** : la Restauration méprise les talents sans naissance ; son crime est aussi le geste d'un homme à qui l'on retire la place qu'il avait arrachée. L'**ironie** du narrateur vise Verrières (province vénale), le séminaire (hypocrisie), le faubourg Saint-Germain (ennui doré).\n3. Sous-partie attendue : Stendhal suit Julien en **focalisation interne serrée** : le lecteur voit le monde par ses yeux et connaît ses calculs. Le **discours indirect libre** fait entendre sa pensée dans le récit, sans guillemets. Nous partageons ainsi ses humiliations et ses ambitions, et nous finissons par nous attacher à un personnage que nous n'approuvons pas. La technique romanesque crée l'adhésion là où la morale la refuserait ; l'ironie du narrateur maintient pourtant une distance critique.\n4. L'ambition de Julien est une **énergie** : c'est une force, pas seulement un défaut. Mais c'est une énergie **que la société gâche**, faute d'issue légitime pour un fils de charpentier."}$exo$::jsonb),
  ('28e61bf4-ac4c-530e-9568-c9471421c5fd'::uuid, 1, 'redaction', $exo${"titre":"Mémoires d'Hadrien : la forme du livre","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne l'autrice et la date de publication de *Mémoires d'Hadrien*.\n2. Quelle est la **forme** du livre ? Qui écrit, à qui, et dans quelle situation ?\n3. Combien de sections compte le livre ? En quelle langue sont leurs titres ? Que signifie *Animula vagula blandula* et d'où viennent ces mots ?\n4. Qui est **Antinoüs**, et que lui arrive-t-il ?","bareme":[{"critere":"Marguerite Yourcenar, 1951 ; longue lettre d'Hadrien malade et proche de la mort à Marc Aurèle adolescent","points":8},{"critere":"Six sections aux titres latins ; « petite âme vagabonde et charmante », début du poème d'Hadrien mourant","points":6},{"critere":"Antinoüs, jeune Bithynien aimé d'Hadrien, noyé dans le Nil en 130, puis divinisé","points":6}],"dureeMin":7,"corrige":"1. Le livre est de **Marguerite Yourcenar** ; il paraît en **1951**.\n2. C'est un roman qui a la forme d'une **longue lettre** : l'empereur **Hadrien**, **malade et proche de la mort**, écrit à son petit-fils adoptif **Marc Aurèle**, alors **adolescent**. Le récit est **rétrospectif** : Hadrien reprend toute sa vie.\n3. Le livre compte **six sections**, aux titres **latins**. *Animula vagula blandula* signifie « **petite âme vagabonde et charmante** » : ce sont les **premiers mots du poème d'Hadrien mourant**.\n4. **Antinoüs** est le jeune **Bithynien** aimé d'Hadrien. Il meurt **noyé dans le Nil en 130** — mort peut-être volontaire, jamais élucidée. Hadrien le **divinise**, fonde une ville en son nom et ne s'en console pas."}$exo$::jsonb),
  ('28e61bf4-ac4c-530e-9568-c9471421c5fd'::uuid, 2, 'redaction', $exo${"titre":"L'empereur et l'homme","consigne":"Lis le passage, puis réponds en rédigeant et en t'appuyant sur le cours.","enonce":"**Texte (inventé pour l'exercice, à la manière de Yourcenar)**\n\n> J'ai renoncé aux conquêtes de mon prédécesseur, non par faiblesse, mais parce qu'un empire trop vaste s'use à ses bords comme un manteau trop grand. J'ai préféré les murs aux batailles et les villes aux trophées. Aujourd'hui, mon cher Marc, c'est une tasse d'eau fraîche qui me paraît la plus haute des victoires.\n\n1. Quelle **politique impériale** évoque la première phrase ? Rattache-la aux faits historiques du cours (prédécesseur, frontières, mur).\n2. Relève une phrase de **ton aphoristique** et explique ce que cela signifie.\n3. La dernière phrase appartient à un autre registre du livre : lequel ? Qu'apporte-t-il par rapport aux « grandes fresques » ?","bareme":[{"critere":"Arrêt de l'expansion après Trajan, consolidation des frontières, mur en Bretagne","points":7},{"critere":"Phrase aphoristique repérée et notion expliquée (formule générale, frappante, grave)","points":6},{"critere":"Notation intime (goût de l'eau, corps malade) opposée aux grandes fresques ; méditation sur le corps et la mort","points":7}],"dureeMin":10,"corrige":"1. Hadrien, qui succède à **Trajan**, **arrête l'expansion militaire** et **consolide les frontières** : « J'ai préféré les murs aux batailles » renvoie au **mur** construit en **Bretagne**. « Les villes aux trophées » rappelle qu'il voyage sans relâche, restaure Athènes, construit la Villa Adriana et le Panthéon.\n2. « Un empire trop vaste s'use à ses bords comme un manteau trop grand » (ou « J'ai préféré les murs aux batailles et les villes aux trophées ») : c'est une formule **aphoristique**, brève et générale, qui a valeur de vérité. La phrase ample, au rythme latin, donne au texte sa **gravité**.\n3. La dernière phrase est une **notation intime** : le goût de l'eau, le corps d'un homme malade. Le livre ne se contente pas des **grandes fresques** (guerres, voyages, réformes) : il montre un **corps qui lâche**. C'est ce qui en fait autant une **méditation** sur le pouvoir, le corps et la mort qu'un roman historique."}$exo$::jsonb),
  ('28e61bf4-ac4c-530e-9568-c9471421c5fd'::uuid, 3, 'redaction', $exo${"titre":"« Un pied dans l'érudition, l'autre dans la magie »","consigne":"Réponds aux questions, puis rédige un paragraphe argumenté d'une quinzaine de lignes.","enonce":"Dans les *Carnets de notes* qui accompagnent le roman, Marguerite Yourcenar résume sa méthode : « Un pied dans l'érudition, l'autre dans la magie. »\n\n1. Explique ce que désigne l'**érudition** dans ce livre, avec deux exemples de faits historiques réels qu'il utilise.\n2. Explique ce que désigne la **magie** : quel est le « pari » du livre ? Pourquoi la **première personne** est-elle audacieuse ici ?\n3. Montre que la **composition en six sections** sert à la fois l'histoire et la vie intérieure (appuie-toi sur au moins trois titres).\n4. **Paragraphe argumenté** : « *Mémoires d'Hadrien* est-il une biographie ou un roman ? » Réponds en utilisant tes réponses précédentes.","bareme":[{"critere":"Érudition : sources historiques réelles, deux faits exacts (Trajan, mur, Panthéon, Antinoüs en 130…)","points":4},{"critere":"Magie : faire parler à la première personne la conscience d'un homme mort depuis dix-huit siècles ; près de trente ans de travail","points":4},{"critere":"Trois titres de sections expliqués et reliés au parcours de vie (de la jeunesse à la mort)","points":4},{"critere":"Paragraphe nuancé : ni biographie savante sans fiction, ni pure invention","points":6},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. L'**érudition**, ce sont les **sources historiques réelles** : Hadrien (**76-138**) succède à **Trajan**, arrête l'expansion, fait bâtir le **mur** en Bretagne, restaure Athènes, construit la **Villa Adriana** et le **Panthéon** ; Antinoüs meurt **noyé dans le Nil en 130**.\n2. La **magie**, c'est la part d'invention : écrire à la **première personne** la conscience d'un homme **mort depuis dix-huit siècles**. Aucune source ne donne ses pensées intimes : Yourcenar doit les imaginer de façon crédible. Elle a mis **près de trente ans** à y parvenir.\n3. Les titres latins suivent une vie : *Varius multiplex multiformis* (la jeunesse et ses visages), *Tellus stabilita* (la terre pacifiée, la politique), *Saeculum aureum* (le siècle d'or et Antinoüs), *Disciplina augusta* (l'ordre impérial), *Patientia* (la maladie et la mort), après *Animula vagula blandula*, qui ouvre sur l'âme du mourant. La composition mêle donc l'**histoire publique** et la **vie intérieure** (bonheur, deuil, corps).\n4. Paragraphe attendu (exemple) : Le livre a l'exactitude d'une biographie : il s'appuie sur des faits vérifiables, de la succession de Trajan au mur de Bretagne. Mais ce n'est pas une biographie savante sans fiction : la forme de la lettre à Marc Aurèle, la première personne, les notations intimes — le goût de l'eau, la fatigue, les chevaux — relèvent de l'invention romanesque. Surtout, le livre fait entendre une conscience qui médite sur le pouvoir, l'art, le corps et la mort, ce que ne fait pas l'histoire. C'est donc un **roman historique**, et plus encore une méditation, qui tient « un pied dans l'érudition, l'autre dans la magie »."}$exo$::jsonb),
  ('46bdc52b-5a4e-5a5c-9667-fe6e4b302d88'::uuid, 1, 'redaction', $exo${"titre":"Le Nouveau Roman en quelques repères","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. À quelle période et chez quel éditeur paraissent la plupart des auteurs du Nouveau Roman ? Cite **trois** de ces auteurs.\n2. Le Nouveau Roman est-il une école organisée ? Justifie avec la formule du cours.\n3. Cite les **quatre éléments** du roman traditionnel que ces auteurs refusent.\n4. Associe chaque titre à son auteur et à sa date : *L'Ère du soupçon*, *Pour un nouveau roman*, *La Modification*.","bareme":[{"critere":"1950-1970, Éditions de Minuit, trois auteurs exacts ; pas d'école mais un air de famille et un refus commun","points":7},{"critere":"Personnage, intrigue, psychologie, auteur omniscient","points":6},{"critere":"Sarraute 1956, Robbe-Grillet 1963, Butor 1957","points":7}],"dureeMin":7,"corrige":"1. Les auteurs du Nouveau Roman publient dans les années **1950-1970**, la plupart aux **Éditions de Minuit** : **Robbe-Grillet**, **Sarraute**, **Butor**, **Claude Simon**, **Pinget**, **Duras** (trois suffisent).\n2. Non : ce n'est **pas une école organisée** avec un chef et un programme, mais un **air de famille** et un **refus commun**.\n3. Ils refusent le **personnage** (nom, portrait, biographie), l'**intrigue** (chronologie claire, dénouement), la **psychologie** (motivations expliquées) et l'**auteur omniscient**.\n4. *L'Ère du soupçon* : **Nathalie Sarraute**, **1956** (manifeste). *Pour un nouveau roman* : **Alain Robbe-Grillet**, **1963** (manifeste). *La Modification* : **Michel Butor**, **1957**, écrit à la deuxième personne du pluriel."}$exo$::jsonb),
  ('46bdc52b-5a4e-5a5c-9667-fe6e4b302d88'::uuid, 2, 'redaction', $exo${"titre":"L'école du regard","consigne":"Lis le passage, puis réponds en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour l'exercice, à la manière du Nouveau Roman)**\n\n> Sur la table, la tasse. Blanche, cylindrique, huit centimètres de haut. L'anse forme un demi-cercle presque parfait, légèrement aplati vers le bas. Le café a laissé sur la paroi intérieure une ligne brune, horizontale, à deux centimètres du bord. Vous posez la main à côté. Vous ne la prenez pas. La ligne brune est toujours à deux centimètres du bord.\n\n1. Relève **trois** détails qui montrent une description **géométrique et sans métaphore**. Pourquoi parle-t-on d'« école du regard » ?\n2. Que devient la **psychologie** du personnage ? Pourquoi ne prend-il pas la tasse ?\n3. Relève un procédé de **composition** du passage et un procédé d'**énonciation** qui rappellent des auteurs du cours.","bareme":[{"critere":"Trois détails géométriques précis (mesures, formes, positions) ; description des objets à la place de la psychologie","points":7},{"critere":"Aucune motivation expliquée : le lecteur reconstitue et accepte de ne pas savoir","points":6},{"critere":"Répétition de la ligne brune (Simon, Butor) et « vous » de La Modification","points":7}],"dureeMin":10,"corrige":"1. « cylindrique, huit centimètres de haut », « un demi-cercle presque parfait, légèrement aplati vers le bas », « une ligne brune, horizontale, à deux centimètres du bord ». L'objet est décrit **géométriquement**, par des mesures et des formes, **sans métaphore**. Comme chez Robbe-Grillet, la **description** des objets remplace la psychologie : d'où le nom d'**école du regard**.\n2. La psychologie disparaît : on ne sait ni ce que le personnage pense ni pourquoi il ne prend pas la tasse. Les motivations expliquées cèdent aux **objets** et aux gestes. C'est au **lecteur** de faire le travail : reconstituer, hésiter, **accepter de ne pas savoir**.\n3. Composition : la **répétition** de « la ligne brune est toujours à deux centimètres du bord », qui revient avec une variation — la répétition et la variation sont des principes de composition chez **Simon** et **Butor**. Énonciation : le récit à la **deuxième personne du pluriel** (« Vous posez la main »), comme dans ***La Modification*** de Butor."}$exo$::jsonb),
  ('46bdc52b-5a4e-5a5c-9667-fe6e4b302d88'::uuid, 3, 'redaction', $exo${"titre":"Le Nouveau Roman détruit-il le roman ?","consigne":"Construis une réflexion argumentée de type dissertation à partir des notions du cours.","enonce":"**Sujet** : « En refusant le personnage et l'intrigue, le Nouveau Roman détruit-il le roman ? »\n\n1. Explique la formule de Sarraute, « l'**ère du soupçon** » : de quoi le lecteur se met-il à douter ?\n2. Présente en un paragraphe **ce que le Nouveau Roman refuse** et **ce qu'il met à la place** (au moins trois éléments de chaque côté).\n3. Propose un **plan en deux ou trois parties** qui réponde au sujet.\n4. Rédige la **conclusion** : en quoi le Nouveau Roman est-il à la fois une **esthétique** et une **vision du monde** ?","bareme":[{"critere":"Ère du soupçon : le lecteur ne croit plus au personnage comme à une personne","points":3},{"critere":"Refus et remplacements exacts (personnage, intrigue, psychologie, omniscience / description, répétition-variation, lecteur actif)","points":6},{"critere":"Plan dialectique cohérent aboutissant au déplacement de la question","points":6},{"critere":"Conclusion : montrer la convention comme telle, réel d'objets, de perceptions et d'incertitude","points":5}],"dureeMin":18,"corrige":"1. Pour Sarraute (*L'Ère du soupçon*, **1956**), le lecteur **ne croit plus au personnage comme à une personne** : il sait que le nom, le portrait, la biographie sont des conventions. L'auteur et le lecteur se soupçonnent mutuellement.\n2. Le Nouveau Roman refuse le **personnage** (parfois sans nom, sans portrait), l'**intrigue** (plus de chronologie claire ni de dénouement : le récit tourne, répète, se contredit), la **psychologie** (remplacée par les sensations, les objets, les tropismes) et l'**auteur omniscient**. À la place : une **description** poussée à un degré inédit, géométrique et sans métaphore (la tomate, la gomme, la jalousie de fenêtre chez Robbe-Grillet) ; la **répétition** et la **variation** comme principes de composition (Simon, Butor) ; un **lecteur** qui fait le travail.\n3. Plan possible :\n- **I. Une entreprise de destruction apparente** : disparition du personnage, de l'intrigue, de la psychologie, de l'omniscience.\n- **II. Mais une reconstruction sur d'autres bases** : description, composition par répétition et variation, deuxième personne de *La Modification*, lecteur actif (« école du regard »).\n- **III. Un roman qui déplace la question** : le personnage classique était une convention ; la montrer comme telle est encore une façon de dire le réel.\n4. Conclusion attendue : Le Nouveau Roman ne détruit pas le roman, il **déplace la question**. En montrant la convention comme telle, il reste fidèle au réel — un réel fait d'**objets**, de **perceptions** et d'**incertitude**, tel que le XXe siècle l'a rendu. C'est une **esthétique** (une manière d'écrire) et une **vision du monde** (un monde que personne ne domine plus)."}$exo$::jsonb),
  ('c68f0059-2698-5608-b26c-386783ade93a'::uuid, 1, 'redaction', $exo${"titre":"L'architecture des Contemplations","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quand et dans quelles circonstances Hugo publie-t-il *Les Contemplations* ?\n2. Quels sont les **deux ensembles** du recueil, et quel événement les sépare ? Donne le lieu, la date et l'âge de la victime.\n3. Donne le titre des **quatre livres** au programme et, pour chacun, son thème principal.","bareme":[{"critere":"1856, pendant l'exil à Guernesey","points":4},{"critere":"Autrefois / Aujourd'hui séparés par la mort de Léopoldine, noyée à Villequier en 1843 à dix-neuf ans","points":7},{"critere":"Aurore, L'Âme en fleur, Les Luttes et les Rêves, Pauca meae avec leurs thèmes","points":9}],"dureeMin":7,"corrige":"1. Hugo publie *Les Contemplations* en **1856**, pendant son **exil** à **Guernesey**.\n2. Le recueil est construit en deux ensembles, **Autrefois** (livres I à III) et **Aujourd'hui** (livres IV à VI). Entre les deux : la mort de **Léopoldine**, la fille aînée du poète, **noyée à Villequier en 1843**, à **dix-neuf ans**, quelques mois après son mariage.\n3. **I — Aurore** : l'enfance, l'école, la nature, la bataille romantique. **II — L'Âme en fleur** : l'amour, la sensualité, la nature complice. **III — Les Luttes et les Rêves** : la misère, l'injustice, l'enfance exploitée, la révolte, le doute. **IV — Pauca meae** : le **livre du deuil**."}$exo$::jsonb),
  ('c68f0059-2698-5608-b26c-386783ade93a'::uuid, 2, 'redaction', $exo${"titre":"« Quand je vous parle de moi, je vous parle de vous »","consigne":"Réponds en rédigeant, en t'appuyant sur les citations de la préface et sur le cours.","enonce":"Voici deux phrases de la préface des *Contemplations* :\n\n> « Ce livre doit être lu comme on lirait le livre d'un mort. »\n\n> « Quand je vous parle de moi, je vous parle de vous. Ah ! insensé, qui crois que je ne suis pas toi ! »\n\n1. Explique la première phrase en la reliant à l'**architecture** du recueil.\n2. Explique la seconde : quel rapport entre le « je » du poète et le lecteur établit-elle ?\n3. Le parcours s'intitule « **Mémoires d'une âme** ». Montre, à l'aide du cours, que le recueil n'est pas une autobiographie de faits.","bareme":[{"critere":"Première phrase reliée à la coupure Autrefois / Aujourd'hui et au deuil de Léopoldine","points":6},{"critere":"Le « je » offert au lecteur comme un miroir : livre universel","points":7},{"critere":"Récit d'une vie intérieure (joie, amour, révolte, deuil, foi) et non de faits","points":7}],"dureeMin":11,"corrige":"1. Le recueil est coupé en deux par la mort de **Léopoldine** (1843) : **Autrefois** et **Aujourd'hui**. Le poète d'Autrefois, heureux, est comme mort avec sa fille ; celui d'Aujourd'hui écrit depuis le deuil. Lire le livre « comme le livre d'un mort », c'est le lire comme le bilan d'une vie achevée, que la douleur a brisée.\n2. Hugo refuse que son « je » soit seulement personnel : ses joies, ses révoltes et ses deuils sont ceux de tout homme. Le « je » est **offert au lecteur comme un miroir** ; « insensé, qui crois que je ne suis pas toi » accuse le lecteur qui se croirait étranger à ce qu'il lit. Le recueil devient **universel**.\n3. « Mémoires d'une âme » : le recueil ne raconte pas des faits datés comme une autobiographie, mais le récit d'une **vie intérieure** — la **joie** de l'enfance (*Aurore*), l'**amour** (*L'Âme en fleur*), la **révolte** contre la misère (*Les Luttes et les Rêves*), le **deuil** et la question adressée à Dieu (*Pauca meae*), puis la **foi**."}$exo$::jsonb),
  ('c68f0059-2698-5608-b26c-386783ade93a'::uuid, 3, 'redaction', $exo${"titre":"« Demain, dès l'aube… » : un voyage vers une tombe","consigne":"Lis le poème, puis réponds aux questions d'analyse avant de rédiger un paragraphe de commentaire.","enonce":"**Victor Hugo, « Demain, dès l'aube… », *Les Contemplations*, livre IV, *Pauca meae***\n\n> Demain, dès l'aube, à l'heure où blanchit la campagne,\n> Je partirai. Vois-tu, je sais que tu m'attends.\n> J'irai par la forêt, j'irai par la montagne.\n> Je ne puis demeurer loin de toi plus longtemps.\n>\n> Je marcherai les yeux fixés sur mes pensées,\n> Sans rien voir au dehors, sans entendre aucun bruit,\n> Seul, inconnu, le dos courbé, les mains croisées,\n> Triste, et le jour pour moi sera comme la nuit.\n>\n> Je ne regarderai ni l'or du soir qui tombe,\n> Ni les voiles au loin descendant vers Harfleur,\n> Et quand j'arriverai, je mettrai sur ta tombe\n> Un bouquet de houx vert et de bruyère en fleur.\n\n1. À qui le poète s'adresse-t-il ? Quel mot du dernier vers le révèle, et pourquoi cette révélation est-elle retardée ?\n2. Relève dans la deuxième strophe les éléments qui montrent un homme **coupé du monde**.\n3. Dans la troisième strophe, que refuse de regarder le poète ? Quel effet produit ce refus ?\n4. **Paragraphe de commentaire** : montre que ce poème illustre le passage de *Pauca meae* du récit intime au deuil, et qu'il peut parler à tout lecteur (pense à la préface).","bareme":[{"critere":"Destinataire : Léopoldine morte ; « tombe » (v. 11) retarde la révélation après un départ qui ressemble à un rendez-vous","points":5},{"critere":"Isolement : yeux fixés sur ses pensées, sans rien voir, sans entendre, seul, dos courbé, jour comme la nuit","points":4},{"critere":"Refus de la beauté du paysage (or du soir, voiles vers Harfleur) : le monde n'existe plus pour l'endeuillé","points":4},{"critere":"Paragraphe : livre du deuil, lien au recueil (Villequier, 1843) et universalité du « je »","points":5},{"critere":"Citations précises et expression","points":2}],"dureeMin":20,"corrige":"1. Le poète tutoie quelqu'un (« Vois-tu », « tu m'attends », « loin de toi ») : on croit d'abord à un rendez-vous amoureux. Le mot « **tombe** » (v. 11) révèle que la destinataire est morte : c'est **Léopoldine**, noyée à Villequier en 1843. La révélation est retardée jusqu'à la dernière strophe pour que le lecteur éprouve le choc, et pour montrer que le père parle à sa fille comme si elle était vivante.\n2. « les yeux fixés sur mes pensées », « **Sans rien voir** au dehors, **sans entendre aucun bruit** », « **Seul, inconnu**, le dos courbé, les mains croisées », « le jour pour moi sera comme la nuit » : le marcheur est enfermé dans sa douleur, courbé comme un homme en prière ou accablé.\n3. Il refuse de regarder « l'or du soir qui tombe » et « les voiles au loin descendant vers Harfleur » : la négation « ne… ni… ni » écarte la beauté du paysage. Le monde ne compte plus pour l'endeuillé ; le seul geste qui reste est de déposer « un bouquet de houx vert et de bruyère en fleur », un reste de vie offert à la morte.\n4. Paragraphe attendu : Placé dans *Pauca meae*, le **livre du deuil**, le poème passe du **récit intime** (un voyage, une marche) au **deuil** : tout converge vers la tombe. Le « je » n'y dit pourtant jamais le nom de sa fille : chacun peut y reconnaître sa propre perte. C'est ce qu'annonce la préface : « Quand je vous parle de moi, je vous parle de vous. » Les *Contemplations* sont les **Mémoires d'une âme** : le poème ne raconte pas un fait, il donne à vivre une douleur que le lecteur partage."}$exo$::jsonb),
  ('b59ac516-6963-5ba9-a644-76e6bd504e4a'::uuid, 1, 'redaction', $exo${"titre":"Les Fleurs du mal : le recueil et son procès","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que se passe-t-il en **1857**, l'année de la publication ? Et en **1861** ?\n2. Cite dans l'ordre les **six sections** de l'édition de 1861. Laquelle a été ajoutée cette année-là ?\n3. Définis le **spleen** et les **correspondances** chez Baudelaire.","bareme":[{"critere":"Condamnation pour outrage à la morale publique, six pièces retranchées ; seconde édition augmentée et réorganisée","points":6},{"critere":"Six sections dans l'ordre, Tableaux parisiens ajoutée en 1861","points":7},{"critere":"Spleen : angoisse sans objet, ennui métaphysique ; correspondances : parfums, couleurs et sons se répondent, forêt de symboles","points":7}],"dureeMin":7,"corrige":"1. En **1857**, *Les Fleurs du mal* est **condamné** pour **outrage à la morale publique** : **six pièces** sont retranchées. En **1861** paraît une **seconde édition**, augmentée et réorganisée.\n2. **Spleen et Idéal**, **Tableaux parisiens**, **Le Vin**, **Fleurs du mal**, **Révolte**, **La Mort**. La section **Tableaux parisiens** a été ajoutée en 1861.\n3. Le **spleen** est une **angoisse sans objet**, un **ennui métaphysique**, le sentiment d'un temps qui écrase (« Quand le ciel bas et lourd pèse comme un couvercle… »). Les **correspondances** : le monde est « une forêt de symboles » où **parfums, couleurs et sons se répondent** ; le poète est celui qui **déchiffre** ce langage."}$exo$::jsonb),
  ('b59ac516-6963-5ba9-a644-76e6bd504e4a'::uuid, 2, 'redaction', $exo${"titre":"Un itinéraire en six étapes","consigne":"Réponds en rédigeant, en t'appuyant sur l'architecture du recueil.","enonce":"On dit souvent que *Les Fleurs du mal* n'est pas une simple collection de poèmes mais un **itinéraire**.\n\n1. Présente en une phrase le rôle de chacune des six sections, dans l'ordre.\n2. Montre que la section **Spleen et Idéal** repose sur une **tension**. Entre quels deux pôles ?\n3. Le dernier vers du recueil est : « Au fond de l'Inconnu pour trouver du nouveau ! » En quoi conclut-il cet itinéraire ?\n4. Explique pourquoi l'on peut dire que les sections 3 à 5 (Le Vin, Fleurs du mal, Révolte) sont des **tentatives d'évasion**.","bareme":[{"critere":"Rôle de chaque section exact et dans l'ordre","points":6},{"critere":"Tension entre élévation (art, beauté, amour) et enlisement (ennui, angoisse, temps)","points":5},{"critere":"La Mort, dernier voyage et seul espoir : départ vers l'Inconnu","points":4},{"critere":"Ivresse, transgression, blasphème comme échappatoires successives","points":5}],"dureeMin":12,"corrige":"1. **Spleen et Idéal**, la plus longue, met en tension élévation et enlisement ; **Tableaux parisiens** peint la ville moderne (foules, vieillards, mendiantes, cygnes exilés) ; **Le Vin** propose l'ivresse comme échappatoire ; **Fleurs du mal** explore la transgression, la volupté, la damnation ; **Révolte** passe au blasphème ; **La Mort** est le dernier voyage, seul espoir.\n2. *Spleen et Idéal* oppose l'**élévation** — l'art, la beauté, l'amour — et l'**enlisement** — l'ennui, l'angoisse, le temps. Le poète est tiré entre les deux, sans pouvoir s'arracher au spleen.\n3. Le vers appartient à « Le Voyage », dans **La Mort**. Après l'échec de toutes les échappatoires, la mort devient un **voyage** vers « l'Inconnu » : le seul espoir est de trouver « du nouveau ». L'itinéraire s'achève donc sur un départ, pas sur un repos.\n4. Chaque section essaie une sortie du spleen : l'**ivresse** (Le Vin), la **transgression** et la volupté (Fleurs du mal), le **blasphème** (Révolte). Aucune ne suffit, ce qui mène à la dernière section : la mort comme ultime voyage."}$exo$::jsonb),
  ('b59ac516-6963-5ba9-a644-76e6bd504e4a'::uuid, 3, 'redaction', $exo${"titre":"Classique de facture, révolutionnaire de matière","consigne":"Lis le document, réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"**Charles Baudelaire, « Correspondances », premier quatrain (*Les Fleurs du mal*)**\n\n> La Nature est un temple où de vivants piliers\n> Laissent parfois sortir de confuses paroles ;\n> L'homme y passe à travers des forêts de symboles\n> Qui l'observent avec des regards familiers.\n\n1. Quel est le **vers** employé ? Justifie par le décompte d'un vers. Quelle est la disposition des **rimes** ?\n2. Explique l'image de la Nature comme « temple » : que doit faire le poète face à ces « confuses paroles » ?\n3. Le cours dit que Baudelaire reste « classique de facture » mais qu'il est « révolutionnaire de matière ». Explique cette opposition avec des exemples de sujets du recueil.\n4. **Paragraphe argumenté** : « Pourquoi *Les Fleurs du mal* a-t-il fait scandale en 1857, et en quoi ce scandale fonde-t-il la modernité poétique ? »","bareme":[{"critere":"Alexandrin justifié par un décompte juste ; rimes embrassées (abba)","points":4},{"critere":"Image du temple : le monde comme langage de symboles que le poète déchiffre","points":4},{"critere":"Facture classique (sonnets, alexandrins, rimes) / matière nouvelle (charogne, vieillesse, ville sale, prostituée)","points":5},{"critere":"Paragraphe : condamnation de 1857, six pièces retranchées, contraste qui fonde la modernité","points":5},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. Ce sont des **alexandrins** (12 syllabes) : « La / Na / tu / re est / un / tem / ple où / de / vi / vants / pi / liers » — 12 syllabes (« Nature est » et « temple où » s'élident). Les rimes **piliers / familiers** et **paroles / symboles** sont **embrassées** (abba). Le poème est un **sonnet**.\n2. La Nature est un « temple » : un lieu sacré qui **parle**, mais par des « confuses paroles ». Le monde est « une **forêt de symboles** » où tout signifie. Le poète est celui qui **déchiffre** ce langage : c'est la théorie des **correspondances**.\n3. **Classique de facture** : Baudelaire garde les formes régulières — sonnets, alexandrins, rimes régulières — comme dans ce quatrain. **Révolutionnaire de matière** : il fait entrer dans le poème ce que la poésie excluait — une charogne, la vieillesse, la ville sale, la prostituée.\n4. Paragraphe attendu : En 1857, le recueil est **condamné pour outrage à la morale publique** et **six pièces** sont retranchées. Ce qui choquait, c'était le **contraste** : des sujets jugés immoraux ou répugnants, traités dans les formes les plus nobles de la tradition. Or c'est ce contraste qui fonde la **modernité poétique** : le beau n'est plus réservé aux beaux sujets, il naît du travail de la forme sur n'importe quelle matière. Le scandale révèle ainsi la nouveauté du recueil."}$exo$::jsonb),
  ('24bfbdc9-9d9d-5226-a43a-51b047a75d88'::uuid, 1, 'redaction', $exo${"titre":"La boue et l'or : les notions clés","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite la formule de Baudelaire qui donne son nom au parcours et explique la comparaison avec l'**alchimiste**.\n2. Où se trouve la beauté selon cette alchimie : dans l'objet choisi ou ailleurs ?\n3. Qu'est-ce que la « **double postulation** » ? Donne la phrase de Baudelaire et ses deux directions.","bareme":[{"critere":"« Tu m'as donné ta boue et j'en ai fait de l'or » ; le poète transforme le laid, le banal, l'immoral en beau comme l'alchimiste le plomb en or","points":8},{"critere":"La beauté est dans la forme, dans le travail du langage, pas dans l'objet","points":5},{"critere":"Deux postulations simultanées, l'une vers Dieu, l'autre vers Satan ; tension jamais résolue","points":7}],"dureeMin":7,"corrige":"1. « **Tu m'as donné ta boue et j'en ai fait de l'or.** » (projet d'épilogue). L'alchimiste transforme le **plomb en or** ; le poète transforme la **matière du monde** : ce qui est **laid, banal, malade ou immoral** devient beau **par le travail du langage**.\n2. La beauté n'est **pas dans l'objet** : elle est dans la **forme** que le poète lui donne. C'est le renversement décisif de la poésie moderne.\n3. « Il y a dans tout homme, à toute heure, **deux postulations simultanées**, l'une **vers Dieu**, l'autre **vers Satan**. » Le recueil ne choisit pas : spleen **et** idéal, boue **et** or, damnation **et** élévation. Cette **tension jamais résolue** structure le livre."}$exo$::jsonb),
  ('24bfbdc9-9d9d-5226-a43a-51b047a75d88'::uuid, 2, 'redaction', $exo${"titre":"« Une Charogne », le poème matriciel","consigne":"Réponds en rédigeant, en t'appuyant sur le cours.","enonce":"Le cours présente « Une Charogne » comme le **poème matriciel** du parcours « alchimie poétique, la boue et l'or ».\n\n1. Résume les **deux étapes** du poème : ce que découvrent les promeneurs, puis ce que promet la chute.\n2. En quoi ce poème est-il une **démonstration** de l'alchimie poétique ? Explique le mot « matriciel ».\n3. On entend parfois : « Baudelaire préfère la laideur à la beauté. » Réfute cette affirmation en deux ou trois phrases.","bareme":[{"critere":"Découverte d'un cadavre d'animal en décomposition, décrit avec précision ; chute : promesse d'immortalité à la femme aimée","points":7},{"critere":"Démonstration : le sujet le plus repoussant produit un des plus beaux poèmes ; poème qui contient tout le principe du recueil","points":7},{"critere":"Réfutation : esthétique de la transformation, non de la laideur","points":6}],"dureeMin":10,"corrige":"1. Au cours d'une **promenade**, le poète et la femme aimée découvrent un **cadavre d'animal en décomposition**, décrit avec une précision **insoutenable**. La **chute** retourne le poème : le poète promet à la femme une **immortalité** — la pourriture attendra son corps, mais lui aura gardé « la forme et l'essence divine » de ses amours.\n2. La démonstration est faite : **le sujet le plus repoussant produit l'un des plus beaux poèmes du recueil**. La beauté ne vient donc pas de l'objet mais de la **forme**, du travail du langage. Le poème est « matriciel » parce qu'il contient, comme une matrice, le principe de tout le parcours : transformer la boue en or.\n3. C'est faux : la modernité baudelairienne n'est pas une **esthétique de la laideur** mais une **esthétique de la transformation**. Baudelaire ne préfère pas le laid ; il montre que le poète peut en tirer de la beauté. Le laid est la matière, le beau est le résultat."}$exo$::jsonb),
  ('24bfbdc9-9d9d-5226-a43a-51b047a75d88'::uuid, 3, 'redaction', $exo${"titre":"« À une passante » : la beauté dans le passage","consigne":"Lis les tercets, réponds aux questions, puis rédige un paragraphe de commentaire.","enonce":"**Charles Baudelaire, « À une passante », tercets (*Tableaux parisiens*)** — le poète vient de croiser une inconnue dans une rue bruyante de Paris.\n\n> Un éclair… puis la nuit ! — Fugitive beauté\n> Dont le regard m'a fait soudainement renaître,\n> Ne te verrai-je plus que dans l'éternité ?\n>\n> Ailleurs, bien loin d'ici ! trop tard ! jamais peut-être !\n> Car j'ignore où tu fuis, tu ne sais où je vais,\n> Ô toi que j'eusse aimée, ô toi qui le savais !\n\n1. Relève les mots qui disent la **brièveté** de la rencontre. Quelle image résume le premier vers ?\n2. Analyse la ponctuation du deuxième tercet : quel état du poète traduit-elle ?\n3. Explique en quoi ce poème illustre le regard du **flâneur** et la ville comme « matière » de la poésie.\n4. **Paragraphe de commentaire** : montre que ce poème transforme une scène banale de la rue en poème de l'amour perdu, et relie-le à l'alchimie baudelairienne.","bareme":[{"critere":"Mots de la brièveté (éclair, nuit, fugitive, soudainement, trop tard) ; image de l'éclair suivi de la nuit","points":4},{"critere":"Exclamations, points de suspension, apostrophes : émotion, regret, désarroi","points":4},{"critere":"Flâneur : beauté trouvée dans le passage, au cœur de la ville moderne (Tableaux parisiens)","points":4},{"critere":"Paragraphe : scène banale transformée, amour possible et perdu à jamais, alchimie de la forme","points":6},{"critere":"Citations précises et expression","points":2}],"dureeMin":18,"corrige":"1. « éclair », « nuit », « **Fugitive** beauté », « **soudainement** », « **trop tard** », « jamais peut-être ». Le premier vers, « Un éclair… puis la nuit ! », résume la rencontre : une lumière d'une seconde, puis l'obscurité — l'inconnue disparaît.\n2. Le vers « Ailleurs, bien loin d'ici ! trop tard ! jamais peut-être ! » accumule les **exclamations** brèves ; le premier tercet contient des **points de suspension**, un tiret et une **question** sans réponse ; le dernier vers est une double **apostrophe** (« Ô toi… ô toi… »). La ponctuation traduit le **désarroi**, le **regret** et l'élan brisé du poète.\n3. Le poème appartient aux **Tableaux parisiens** : sa matière est la **ville**, la rue bruyante et anonyme. Le **flâneur** baudelairien est celui qui trouve la beauté **dans le passage** : une inconnue croisée **une seconde**, aimée, **perdue à jamais**.\n4. Paragraphe attendu : La scène est banale — une femme croise un homme dans la rue. Baudelaire en fait le poème d'un **amour possible et perdu** : le conditionnel passé (« que j'eusse aimée ») dit ce qui aurait pu être, « ô toi qui le savais » suggère une complicité d'un regard. La forme régulière du sonnet et le travail de la ponctuation donnent à cet instant fugitif une valeur d'**éternité**. C'est l'**alchimie** : la matière urbaine, fugace, ordinaire, devient or par le langage."}$exo$::jsonb),
  ('08373edb-806d-59f0-8190-945154a17b68'::uuid, 1, 'redaction', $exo${"titre":"Alcools : repères et geste célèbre","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne l'auteur et la date d'*Alcools*. Sur combien d'années les poèmes ont-ils été écrits ?\n2. Quel **geste** Apollinaire fait-il sur les épreuves du recueil ? Quelle justification donne-t-il ?\n3. Quel poème **ouvre** le recueil et quel poème le **clôt** ? Quelle particularité a le poème d'ouverture ?\n4. Que suggère le **titre** *Alcools* ?","bareme":[{"critere":"Apollinaire, 1913, quinze ans","points":4},{"critere":"Suppression de la ponctuation ; le rythme et la coupe des vers sont la vraie ponctuation","points":6},{"critere":"« Zone » (écrit en dernier) ouvre, « Vendémiaire » clôt","points":5},{"critere":"Ce qui enivre, brûle, distille : vies et villes distillées, joie et douleur","points":5}],"dureeMin":7,"corrige":"1. *Alcools* est publié en **1913** par **Guillaume Apollinaire** ; il rassemble des poèmes écrits sur **quinze ans**.\n2. Sur les épreuves, Apollinaire **supprime toute la ponctuation**. Il explique : « Le rythme même et la coupe des vers, voilà la véritable ponctuation. » Le vers devient ambigu et le lecteur doit choisir où respirer.\n3. Le recueil s'ouvre sur « **Zone** », qui a pourtant été **écrit en dernier**, et se clôt sur « **Vendémiaire** ». L'ordre n'est ni chronologique ni thématique.\n4. *Alcools*, c'est ce qui **enivre**, ce qui **brûle**, ce qui **distille** : le recueil est fait de **vies et de villes distillées** en poèmes courts, et l'ivresse y est aussi bien **joie** que **douleur d'amour**."}$exo$::jsonb),
  ('08373edb-806d-59f0-8190-945154a17b68'::uuid, 2, 'redaction', $exo${"titre":"« Zone », un poème qui mêle tout","consigne":"Réponds en rédigeant, en t'appuyant sur le cours et sur les vers cités.","enonce":"Le premier vers de « Zone » est : « À la fin tu es las de ce monde ancien ». Le dernier est : « Soleil cou coupé ».\n\n1. Qui est le « **tu** » du premier vers ? Quel effet produit ce choix de pronom ?\n2. Cite **quatre éléments** que le poème mêle, dont au moins deux signes de la **modernité**.\n3. Pourquoi est-il significatif que « Zone », écrit **en dernier**, soit placé **en ouverture** ? Que dit ce choix de l'ordre du recueil ?","bareme":[{"critere":"« Tu » : le poète se parle à lui-même ; dédoublement, distance","points":5},{"critere":"Quatre éléments exacts dont deux modernes (affiches, prospectus, tour Eiffel bergère, hangars de Port-Aviation…)","points":6},{"critere":"Ouverture programmatique : congé au « monde ancien » ; ordre ni chronologique ni thématique, désordre choisi qui crée des échos","points":7},{"critere":"Réponses rédigées et précises","points":2}],"dureeMin":11,"corrige":"1. Le « je » y devient « **tu** » : **le poète se parle à lui-même**. Ce dédoublement crée une distance : le poète se regarde comme un autre, à la fois lassé et interpellé.\n2. « Zone » mêle l'**aube parisienne**, les **affiches** et les **prospectus**, la **tour Eiffel** « bergère », les **hangars de Port-Aviation**, l'**émigration**, la **religion de l'enfance**, les **voyages**, l'**amour perdu**. Les signes de la modernité : les affiches, les prospectus, l'aviation, la tour Eiffel.\n3. « Zone » est le poème le plus récent, et il annonce le congé au « **monde ancien** » : placé en tête, il donne le ton moderne à tout le recueil, même aux poèmes plus anciens et plus traditionnels. Ce choix confirme que l'ordre d'*Alcools* n'est **ni chronologique ni thématique** : le **désordre est un choix**, qui fait entendre des **échos** plutôt qu'une progression."}$exo$::jsonb),
  ('08373edb-806d-59f0-8190-945154a17b68'::uuid, 3, 'redaction', $exo${"titre":"« Le Pont Mirabeau » : moderne ou traditionnel ?","consigne":"Lis la strophe et le refrain, réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"**Guillaume Apollinaire, « Le Pont Mirabeau », première strophe et refrain (*Alcools*)**\n\n> Sous le pont Mirabeau coule la Seine\n> Et nos amours\n> Faut-il qu'il m'en souvienne\n> La joie venait toujours après la peine\n>\n> Vienne la nuit sonne l'heure\n> Les jours s'en vont je demeure\n\n1. Relève ce qui relève de la **tradition** : forme, sonorités, genre auquel le poème fait penser.\n2. Relève ce qui relève de l'**invention** : quel effet produit l'absence de ponctuation sur le deuxième vers ? Propose deux lectures de « Sous le pont Mirabeau coule la Seine / Et nos amours ».\n3. Montre que le refrain oppose deux mouvements. Lesquels ?\n4. **Paragraphe argumenté** : « Pourquoi le parcours s'intitule-t-il « Modernité poétique ? » avec un point d'interrogation ? » Appuie-toi sur ce poème et sur ce que tu sais de « Zone ».","bareme":[{"critere":"Tradition : rimes, régularité, refrain de chanson ou complainte","points":4},{"critere":"Absence de ponctuation et deux lectures du v. 2 (les amours coulent comme la Seine / les amours sont sous le pont)","points":5},{"critere":"Refrain : le temps qui passe (la nuit, l'heure, les jours s'en vont) / le poète qui demeure","points":4},{"critere":"Paragraphe : modernité comme alliage de tradition et d'invention, pas table rase","points":5},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. **Tradition** : des **rimes** (Seine / souvienne / peine ; heure / demeure), un vers d'une régularité parfaite (« Sous le pont Mirabeau coule la Seine »), un **refrain** repris comme dans une **chanson** ou une **complainte**. Le thème — le temps qui emporte l'amour — est lui aussi traditionnel.\n2. **Invention** : il n'y a **aucune ponctuation**. Le vers 2, « Et nos amours », peut se lire de deux façons : **nos amours coulent** comme la Seine (ils passent, emportés par le temps), ou **nos amours sont sous le pont** avec la Seine (ils sont un souvenir attaché au lieu). Le lecteur doit **choisir où respirer** : le vers devient **ambigu**.\n3. Le refrain oppose le **temps qui passe** — « Vienne la nuit sonne l'heure / Les jours s'en vont » — et le **poète qui reste** — « je demeure ». Le mouvement de l'eau et des jours s'oppose à l'immobilité de celui qui se souvient.\n4. Paragraphe attendu : Le point d'interrogation signale que la modernité d'Apollinaire n'est pas évidente. « Zone » fait entrer l'aviation, les affiches, la ville industrielle et congédie le « monde ancien » ; mais « Le Pont Mirabeau » est une chanson rimée, régulière, que tout le monde retient. La modernité n'est **pas la table rase** : elle est un **alliage**. Le geste moderne est ici discret — la suppression de la ponctuation — mais il transforme la lecture d'un poème traditionnel. Le recueil pose donc la question plus qu'il ne la tranche."}$exo$::jsonb),
  ('e3cadf7e-9dbc-54c1-a2bc-9aafdc09226e'::uuid, 1, 'redaction', $exo${"titre":"Trois ruptures fondatrices","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que signifie « **moderne** » appliqué à la poésie, selon le cours ?\n2. Pour chacun des trois poètes suivants, indique ce qu'il change et cite sa formule : **Baudelaire** (1857), **Rimbaud** (1871), **Mallarmé**.\n3. Complète : « Est moderne un poème qui prend le langage … »","bareme":[{"critere":"Moderne = une manière de traiter le langage, pas « récent »","points":4},{"critere":"Baudelaire : fin du beau sujet ; Rimbaud : voyant, dérèglement de tous les sens ; Mallarmé : vers faits avec des mots, non des idées","points":12},{"critere":"« … pour sujet autant que pour outil »","points":4}],"dureeMin":7,"corrige":"1. « Moderne » ne désigne **pas** « récent » : c'est une **manière de traiter le langage**.\n2. **Baudelaire** (1857) : la ville, la laideur, le transitoire entrent dans le poème ; **le beau sujet cesse d'exister**. **Rimbaud** (1871) : le poète doit se faire « **voyant** », par « un long, immense et raisonné **dérèglement de tous les sens** » ; la poésie doit être « **en avant** ». **Mallarmé** : tout se déplace du côté du langage — « Ce n'est point avec des **idées** que l'on fait des vers, c'est avec des **mots** » ; le poème ne transmet plus un message, il crée un **objet verbal**.\n3. Est moderne un poème qui prend le langage **pour sujet autant que pour outil**."}$exo$::jsonb),
  ('e3cadf7e-9dbc-54c1-a2bc-9aafdc09226e'::uuid, 2, 'redaction', $exo${"titre":"Reconnaître un poème moderne","consigne":"Lis le poème, puis réponds en t'appuyant sur les notions du cours.","enonce":"**Poème (inventé pour l'exercice)**\n\n> Gare du soir un ticket froissé dort\n> sur le quai la lune est un prospectus\n> qu'on distribue aux trains qui ne s'arrêtent plus\n> et ma main reste ouverte\n\n1. Quelles **formes** de la modernité poétique repères-tu (vers, ponctuation) ?\n2. Quels **sujets** entrent ici dans le poème ? Rappelle ce que le cours dit du sujet dans la poésie moderne.\n3. Analyse l'image « **la lune est un prospectus** » : en quoi est-elle une image moderne plutôt qu'une comparaison classique ?\n4. Quel rôle ce poème donne-t-il au **lecteur** ?","bareme":[{"critere":"Vers libre (longueurs inégales, pas de rime régulière) et absence de ponctuation","points":5},{"critere":"Gare, ticket, prospectus : plus rien n'est indigne du poème","points":5},{"critere":"Image qui rapproche deux réalités éloignées au lieu de comparer deux choses connues","points":6},{"critere":"Lecteur actif qui choisit un sens parmi plusieurs","points":4}],"dureeMin":10,"corrige":"1. Les vers sont de longueurs **inégales**, sans rime régulière : c'est du **vers libre**. Il n'y a **aucune ponctuation** (ni virgule ni point), comme dans *Alcools*.\n2. Une **gare**, un **ticket froissé**, un **prospectus**, des trains : des objets banals de la ville. Dans la poésie moderne, **plus rien n'est indigne** du poème : ni un urinoir, ni un prospectus, ni une gare. Depuis Baudelaire, le beau sujet cesse d'exister.\n3. Une comparaison classique rapproche deux choses connues et proches (la lune et un visage pâle, par exemple). Ici, l'image **rapproche deux réalités éloignées** : un astre et un papier publicitaire qu'on distribue. Le rapprochement surprend et crée un sens nouveau (la lune dégradée, offerte à des trains qui passent sans la voir). Les surréalistes systématiseront ce type d'image après 1920.\n4. Sans ponctuation, le lecteur doit **choisir** où couper (« dort / sur le quai » ou « sur le quai la lune »), et interpréter le dernier vers (attente, don, abandon). Il devient **actif** : il choisit un sens parmi plusieurs."}$exo$::jsonb),
  ('e3cadf7e-9dbc-54c1-a2bc-9aafdc09226e'::uuid, 3, 'redaction', $exo${"titre":"La modernité poétique a-t-elle perdu le lecteur ?","consigne":"Construis une réflexion argumentée de type dissertation à partir des notions du cours et de tes connaissances sur Alcools.","enonce":"**Sujet** : « À force de travailler la langue, la poésie moderne a-t-elle perdu son lecteur ? »\n\n1. Explique le **risque** que le cours associe à la modernité poétique, et pourquoi le parcours s'écrit « modernité poétique **?** ».\n2. Présente **quatre changements concrets** apportés par la modernité (forme, sujet, image, lecteur).\n3. Propose un **plan en deux ou trois parties** qui réponde au sujet, avec au moins un exemple par partie (Baudelaire, Rimbaud, Mallarmé, Apollinaire).\n4. Rédige la **conclusion** en t'appuyant sur l'exemple d'Apollinaire.","bareme":[{"critere":"Risque de l'hermétisme : le poème perd le lecteur qu'il voulait libérer ; le « ? » invite à peser ce risque","points":4},{"critere":"Quatre changements exacts (vers libre, poème en prose, calligrammes / tout sujet / image qui rapproche l'éloigné / lecteur actif)","points":5},{"critere":"Plan dialectique avec exemples précis des poètes du cours","points":7},{"critere":"Conclusion : les modernes, Apollinaire compris, écrivent aussi des chansons retenues par cœur","points":4}],"dureeMin":18,"corrige":"1. À force de travailler la langue, le poème peut devenir **hermétique** : il **perd le lecteur qu'il voulait libérer**. Le point d'interrogation de « modernité poétique ? » invite précisément à **peser ce risque** : la modernité est-elle un progrès ou une impasse ?\n2. **Forme** : abandon du vers régulier, poème en prose, vers libre, disparition de la ponctuation, calligrammes. **Sujet** : plus rien n'est indigne du poème. **Image** : elle rapproche deux réalités éloignées au lieu de comparer deux choses connues. **Lecteur** : il devient actif et doit choisir un sens parmi plusieurs.\n3. Plan possible :\n- **I. Oui, la modernité rend la lecture difficile** : chez Mallarmé, le poème ne transmet plus un message mais crée un objet verbal (« ce n'est point avec des idées que l'on fait des vers, c'est avec des mots ») ; l'image qui rapproche des réalités éloignées déroute ; sans ponctuation, le vers devient ambigu.\n- **II. Mais elle fait du lecteur un partenaire** : il choisit où respirer, quel sens retenir ; Baudelaire fait entrer la ville et le quotidien, donc un monde que le lecteur connaît ; Rimbaud veut une poésie « en avant ».\n- **III. Et elle n'a pas rompu avec la tradition** : chez Apollinaire, la modernité est un alliage ; « Le Pont Mirabeau » garde rimes et refrain.\n4. Conclusion attendue : La modernité a pris un risque réel, celui de l'hermétisme. Mais elle n'a pas perdu son lecteur : elle lui a demandé davantage. Et les modernes les plus radicaux, **Apollinaire compris**, ont continué d'écrire des **chansons que tout le monde retient par cœur**, comme « Le Pont Mirabeau ». La modernité n'est pas un refus du lecteur, c'est une autre manière de lui parler."}$exo$::jsonb),
  ('5585a654-ad52-5d66-a990-c91129b629c0'::uuid, 1, 'redaction', $exo${"titre":"Le Malade imaginaire : l'intrigue","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne le genre exact de la pièce, sa date et son nombre d'actes. Que se passe-t-il pour Molière lors de la quatrième représentation ?\n2. Quel est le **projet** d'Argan pour sa fille Angélique, et pourquoi ? Quel est l'**obstacle** ?\n3. Quel **stratagème** Toinette et Béralde organisent-ils, et que révèle-t-il ?\n4. Comment la pièce se termine-t-elle ?","bareme":[{"critere":"Comédie-ballet en trois actes, 1673 ; Molière meurt le soir de la quatrième représentation après avoir joué Argan","points":5},{"critere":"Mariage avec Thomas Diafoirus pour avoir un médecin dans la famille ; Angélique aime Cléante","points":5},{"critere":"Argan joue la comédie de sa mort : Béline se réjouit, Angélique pleure","points":6},{"critere":"Cérémonie burlesque où Argan est reçu médecin en latin de fantaisie","points":4}],"dureeMin":7,"corrige":"1. C'est une **comédie-ballet** en **trois actes**, créée en **1673**. Molière **meurt le soir de la quatrième représentation**, après avoir joué **Argan**.\n2. Argan veut marier **Angélique** à **Thomas Diafoirus**, fils de médecin, **pour avoir un médecin dans la famille**. L'obstacle : Angélique aime **Cléante**.\n3. **Toinette**, la servante, et **Béralde**, le frère d'Argan, font jouer à Argan la **comédie de sa propre mort**. L'épreuve révèle la vérité : **Béline**, la seconde épouse, **se réjouit** devant le corps ; **Angélique pleure**.\n4. Argan comprend. Une **cérémonie burlesque** le reçoit **médecin** en latin de fantaisie : « Dignus, dignus est intrare… »"}$exo$::jsonb),
  ('5585a654-ad52-5d66-a990-c91129b629c0'::uuid, 2, 'redaction', $exo${"titre":"Jouer un rôle pour atteindre la vérité","consigne":"Réponds en rédigeant, en t'appuyant sur le cours (parcours : spectacle et comédie).","enonce":"Le cours affirme : « **Jouer un rôle est le moyen d'accéder à la vérité.** »\n\n1. Cite les **trois scènes de théâtre dans le théâtre** de la pièce et dis qui y joue.\n2. Pour **deux** d'entre elles, explique quelle vérité le jeu permet de révéler ou d'exprimer.\n3. Pourquoi peut-on parler de **spectacle total** ? Donne trois éléments qui le prouvent.","bareme":[{"critere":"Opéra improvisé (Cléante et Angélique), déguisement de Toinette en médecin, mort jouée par Argan","points":6},{"critere":"Deux vérités expliquées (amour déclaré devant Argan ; vrais sentiments de Béline et d'Angélique…)","points":8},{"critere":"Prologue chanté, trois intermèdes dansés, musique de Charpentier, écrit pour la cour","points":6}],"dureeMin":10,"corrige":"1. **Un opéra improvisé** devant Argan, où **Cléante et Angélique** jouent ; **un déguisement en médecin de passage**, joué par **Toinette** ; **le mort joué**, par **Argan** lui-même.\n2. Exemples attendus (deux au choix) :\n- dans l'**opéra improvisé**, Cléante et Angélique **se déclarent leur amour** sous les yeux d'Argan, qui ne comprend pas : la fiction permet de dire la vérité interdite ;\n- la **mort jouée** d'Argan révèle les **vrais sentiments** : Béline, l'hypocrite intéressée, se réjouit ; Angélique pleure sincèrement ; Argan découvre qui l'aime ;\n- le **déguisement de Toinette** en médecin ridiculise la médecine et montre à quel point Argan est crédule.\n3. La pièce est une **comédie-ballet** : **prologue chanté**, **trois intermèdes dansés**, **musique de Marc-Antoine Charpentier** ; elle est écrite pour la **cour**. Musique, danse et théâtre s'y mêlent : c'est un **spectacle total**, qui s'achève d'ailleurs par une cérémonie chantée."}$exo$::jsonb),
  ('5585a654-ad52-5d66-a990-c91129b629c0'::uuid, 3, 'redaction', $exo${"titre":"Molière contre la médecine ?","consigne":"Lis l'extrait, réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"**Extrait (inventé pour l'exercice, dans l'esprit de la pièce)**\n\n> THOMAS DIAFOIRUS. — Monsieur, je viens honorer, admirer, vénérer et célébrer en vous la plus illustre des maladies, comme les Anciens l'enseignent et comme mon père me l'a fait apprendre.\n> ARGAN, *à Toinette*. — Que dis-tu de cela ?\n> TOINETTE. — Qu'il parle comme un livre, Monsieur. Il ne lui manque que de savoir ce qu'il dit.\n\n1. Quel trait de **Thomas Diafoirus**, présenté dans le cours, cet extrait illustre-t-il ? Relève deux indices.\n2. Quel rôle joue **Toinette** dans cet échange ? Rattache ta réponse à sa fonction dans la pièce.\n3. Présente les **trois figures** de médecins de la pièce et ce que chacune incarne, puis la critique formulée par **Béralde**.\n4. **Paragraphe argumenté** : « Molière attaque-t-il la médecine ? » Réponds en nuançant, à l'aide de la formule du cours sur la médecine comme **pouvoir**.","bareme":[{"critere":"Thomas, pédant qui récite un compliment appris par cœur : accumulation de verbes, formule ampoulée","points":4},{"critere":"Toinette : insolence et intelligence pratique, moteur de l'action et regard critique","points":4},{"critere":"Purgon (autorité, menace), Diafoirus (latin creux, pédantisme), Fleurant (saignées, lavements) ; Béralde : la nature guérit, les médecins font des cérémonies","points":5},{"critere":"Paragraphe nuancé : pas la médecine comme science mais comme pouvoir qui parle une langue que le patient ne comprend pas","points":5},{"critere":"Expression et appui sur la pièce","points":2}],"dureeMin":18,"corrige":"1. L'extrait illustre **Thomas Diafoirus**, le **pédant récitant son compliment appris par cœur**. Indices : l'accumulation mécanique de verbes (« honorer, admirer, vénérer et célébrer »), l'éloge absurde de « la plus illustre des maladies », l'appel à l'autorité des Anciens et de son père (savoir appris, non compris) ; Toinette souligne qu'il « parle comme un livre » sans savoir ce qu'il dit.\n2. **Toinette** ridiculise Thomas par une réplique insolente : elle incarne l'**intelligence pratique** et l'**insolence**, c'est le **moteur de l'action** et la voix du bon sens face à la crédulité d'Argan.\n3. **Purgon** incarne l'**autorité** et la **menace** ; **Diafoirus** père et fils, le **latin creux** et le **pédantisme** ; **Fleurant**, les **saignées** et les **lavements**. **Béralde**, voix de la raison, formule la critique : la **nature guérit**, les médecins **font des cérémonies**.\n4. Paragraphe attendu : Molière semble attaquer la médecine, puisque tous les médecins de la pièce sont ridicules et qu'Argan est finalement reçu médecin dans une cérémonie burlesque en faux latin. Pourtant, ce n'est **pas la médecine comme science** qui est visée, mais la **médecine comme pouvoir** : celle qui impose ses remèdes par l'autorité (Purgon), se cache derrière le latin (Diafoirus) et parle une **langue que le patient ne comprend pas**. La satire vise aussi Argan lui-même, égoïste et terrifié par la mort, qui se livre à ce pouvoir. Molière attaque donc un usage de la médecine plus que la médecine."}$exo$::jsonb),
  ('7b99faf2-7229-5b90-b384-981a12ad3a7b'::uuid, 1, 'redaction', $exo${"titre":"Les Fausses Confidences : qui fait quoi ?","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne le genre, la forme, le nombre d'actes et la date de la pièce.\n2. Présente **Dorante**, **Araminte** et **Dubois** : leur situation et leur lien.\n3. Quelle est la **première fausse confidence** de Dubois à Araminte ?\n4. Comment la pièce se termine-t-elle, et pourquoi ce dénouement est-il un « scandale de comédie » ?","bareme":[{"critere":"Comédie en trois actes et en prose, 1737","points":4},{"critere":"Dorante jeune homme ruiné, Araminte riche veuve, Dubois ancien valet de Dorante au service d'Araminte qui le fait intendant","points":6},{"critere":"Dorante fou d'amour pour elle depuis qu'il l'a vue à l'Opéra","points":4},{"critere":"Aveu d'Araminte et mariage avec un homme sans fortune ni titre","points":6}],"dureeMin":7,"corrige":"1. C'est une **comédie** en **trois actes** et **en prose**, créée en **1737**.\n2. **Dorante** est un jeune homme **ruiné** qui aime en secret **Araminte**, une **riche veuve**. **Dubois**, son **ancien valet**, désormais au service d'Araminte, lui obtient la place d'**intendant** chez elle et organise le stratagème.\n3. Dubois révèle « en confidence » à Araminte que Dorante est **fou d'amour pour elle depuis qu'il l'a vue à l'Opéra**.\n4. Araminte finit par **avouer** son amour : elle épousera Dorante, **sans fortune ni titre**. C'est un **scandale de comédie**, car dans ce monde l'argent et le rang comptent partout : Madame Argante voulait pour sa fille un grand nom."}$exo$::jsonb),
  ('7b99faf2-7229-5b90-b384-981a12ad3a7b'::uuid, 2, 'redaction', $exo${"titre":"Une vérité fabriquée","consigne":"Réponds en rédigeant, en t'appuyant sur le cours et sur la citation.","enonce":"Dès le début de la pièce, Dubois dit à Dorante : « Nous sommes convenus de nos faits. »\n\n1. Que révèle cette réplique sur le **stratagème** ?\n2. Le cours affirme que la confidence initiale est « **vraie** » mais « **fabriquée** ». Explique ce paradoxe.\n3. Cite **trois** autres étapes du stratagème après la première confidence.\n4. D'après le cours, le stratagème crée-t-il l'amour d'Araminte ou le révèle-t-il ? Justifie.","bareme":[{"critere":"Le plan est concerté d'avance entre Dubois et Dorante","points":4},{"critere":"Paradoxe : Dubois ne ment presque jamais mais choisit quand et comment dire la vérité, pour installer l'idée","points":6},{"critere":"Trois étapes exactes (portrait, fausse lettre, jalousie de Marton, lettre dictée…)","points":5},{"critere":"L'amour existait peut-être déjà ; le stratagème le rend visible à elle-même","points":5}],"dureeMin":10,"corrige":"1. La réplique montre que tout est **concerté d'avance** : Dubois et Dorante ont un plan, et le spectateur est mis dans la confidence dès le début.\n2. La confidence est **vraie** : Dorante aime réellement Araminte. Mais elle est **fabriquée** : Dubois choisit **quand** et **comment** la dire, pour **installer l'idée** dans l'esprit d'Araminte. Il **ne ment presque jamais** ; il met en scène la vérité.\n3. Le **portrait** d'Araminte trouvé chez Dorante, la **fausse lettre**, la **jalousie de Marton** ; puis l'épreuve où Araminte **dicte à Dorante une lettre** annonçant son propre mariage.\n4. Selon le cours, l'amour d'Araminte **existait peut-être déjà** ; le stratagème le **rend visible à elle-même**. Tout le théâtre de Marivaux pose cette question : peut-on provoquer un sentiment sans le fabriquer de toutes pièces ?"}$exo$::jsonb),
  ('7b99faf2-7229-5b90-b384-981a12ad3a7b'::uuid, 3, 'redaction', $exo${"titre":"Le marivaudage, langue de l'aveu retardé","consigne":"Lis l'extrait, réponds aux questions, puis rédige un paragraphe d'analyse.","enonce":"**Extrait (inventé pour l'exercice, dans l'esprit de la scène de la lettre dictée)**\n\n> ARAMINTE. — Écrivez, Dorante. « Je vous annonce, Monsieur, que mon mariage est décidé. »\n> DORANTE. — Décidé, Madame ?\n> ARAMINTE. — Vous hésitez ? Votre main tremble.\n> DORANTE. — Ce n'est rien. La plume.\n> ARAMINTE. — La plume… Continuez. « Il se fera bientôt. »\n> DORANTE. — Bientôt.\n\n1. Qui **mène** l'échange ? Que cherche Araminte en dictant cette lettre ?\n2. Relève **deux** procédés du **marivaudage** (répliques, reprises, silences) et explique leur effet.\n3. Pourquoi le cours juge-t-il cette scène « **cruelle** » ?\n4. **Paragraphe d'analyse** : montre que, dans cette scène, les personnages « parlent pour ne pas dire », et que l'aveu est retardé par l'amour-propre et par l'ordre social (argent, rang).","bareme":[{"critere":"Araminte mène : elle éprouve Dorante pour vérifier son amour","points":4},{"critere":"Deux procédés repérés (répliques brèves, reprise des mots, silence et prétexte de la plume) et effets expliqués","points":5},{"critere":"Cruauté : Dorante doit écrire la perte de celle qu'il aime","points":3},{"critere":"Paragraphe : aveu retardé, amour-propre, argent et rang qui empêchent de dire","points":6},{"critere":"Appui précis sur l'extrait","points":2}],"dureeMin":18,"corrige":"1. C'est **Araminte** qui mène : elle dicte, interroge, relève le tremblement. En faisant écrire à Dorante l'annonce de son propre mariage, elle **l'éprouve** : elle veut voir s'il l'aime vraiment. Elle devient **actrice** du stratagème.\n2. Procédés :\n- les **répliques brèves** (« Décidé, Madame ? », « Bientôt. ») : les silences deviennent décisifs ;\n- la **reprise des mots** de l'autre (« La plume… », « Bientôt ») : chacun se surveille ;\n- le **prétexte** (« Ce n'est rien. La plume. ») : Dorante parle pour ne pas dire son trouble.\n3. La scène est **cruelle** : Dorante, qui aime Araminte, doit écrire de sa main l'annonce qu'il la perd, et elle le sait.\n4. Paragraphe attendu : Ni Araminte ni Dorante ne disent ce qu'ils éprouvent : elle ne dit pas qu'elle l'aime, il ne dit pas qu'il souffre. Le marivaudage est cette **langue de l'aveu retardé** : les personnages **parlent pour ne pas dire**, se contredisent et se surveillent. L'**amour-propre** retient Araminte, qui ne veut pas avouer la première ; l'**ordre social** pèse plus encore : elle est riche, il est intendant et sans fortune, et sa mère veut un grand nom. La difficulté n'est pas de s'aimer, c'est de **pouvoir le dire**."}$exo$::jsonb),
  ('63aa2eda-1a17-5b08-8b5a-bec9f432c7ef'::uuid, 1, 'redaction', $exo${"titre":"Une machine parfaitement réglée","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Associe chaque acte à la révélation que Dubois y organise.\n2. Définis l'**ironie dramatique** et explique comment elle fonctionne dans la pièce.\n3. Pour chacun des personnages suivants, indique son intérêt lié à l'**argent** : Araminte, Dorante, Marton, Madame Argante, le comte.","bareme":[{"critere":"Acte I confidence, acte II portrait puis fausse lettre, acte III scène du jardin","points":6},{"critere":"Ironie dramatique : le spectateur connaît le stratagème avant Araminte, dès la première scène","points":6},{"critere":"Cinq intérêts exacts (riche, pauvre, dot, titre, procès en dot)","points":8}],"dureeMin":7,"corrige":"1. **Acte I** : la **confidence** initiale. **Acte II** : le **portrait**, puis la **fausse lettre**. **Acte III** : la scène du **jardin**.\n2. L'**ironie dramatique**, c'est quand le spectateur en sait plus que le personnage. Mis dans la confidence **dès la première scène**, le spectateur connaît le stratagème avant Araminte et **jouit de voir le piège se refermer**.\n3. **Araminte** est **riche** ; **Dorante** ne l'est **pas** ; **Marton** espère une **dot** ; **Madame Argante** veut un **titre** pour sa fille ; le **comte** apporte un **procès** en dot. L'amour n'est jamais hors du système social."}$exo$::jsonb),
  ('63aa2eda-1a17-5b08-8b5a-bec9f432c7ef'::uuid, 2, 'redaction', $exo${"titre":"Dubois, valet metteur en scène","consigne":"Réponds en rédigeant, en t'appuyant sur le cours.","enonce":"Le cours affirme que Dubois « occupe la place de l'**auteur** ».\n\n1. Cite **quatre** gestes de Dubois qui en font un metteur en scène.\n2. Pourquoi peut-on dire que, grâce à lui, le **théâtre parle de lui-même** ?\n3. Au troisième acte, qui mène l'action ? Que change ce constat à l'image d'Araminte ?","bareme":[{"critere":"Distribue les rôles, choisit les entrées, ménage ses effets, commente ; n'improvise pas","points":7},{"critere":"Stratagème comme image du théâtre : la pièce montre la fabrique d'un spectacle","points":6},{"critere":"Araminte mène l'acte III : actrice plus que victime","points":7}],"dureeMin":10,"corrige":"1. Dubois **n'improvise pas** : il **distribue les rôles** (à Dorante, à Marton, au comte sans qu'ils le sachent), **choisit les entrées**, **ménage ses effets** (une révélation par acte, au bon moment) et **commente** ce qu'il fait.\n2. Dubois fait ce que fait un auteur : il écrit une intrigue et la fait jouer. Le spectateur, qui connaît le plan, regarde une pièce se construire devant lui. Le **stratagème** devient une **image du théâtre** : la pièce parle de son propre art de faire croire.\n3. Au troisième acte, c'est **Araminte elle-même** qui mène l'action (elle dicte la lettre, éprouve Dorante, décide d'avouer). Elle n'est donc pas seulement une **victime** manipulée : elle est aussi **actrice** de son destin."}$exo$::jsonb),
  ('63aa2eda-1a17-5b08-8b5a-bec9f432c7ef'::uuid, 3, 'redaction', $exo${"titre":"Le stratagème est-il une manipulation ?","consigne":"Construis une réflexion de type dissertation sur Les Fausses Confidences.","enonce":"**Sujet** : « Dans *Les Fausses Confidences*, le stratagème est-il une manipulation ? »\n\n1. Rédige une **introduction** (amorce, problématique, annonce du plan).\n2. Présente **trois arguments** en faveur de la lecture « manipulation » et **trois arguments** en faveur de la lecture « révélation ».\n3. Propose un **plan en deux ou trois parties**.\n4. Rédige la **conclusion** : la pièce tranche-t-elle ? Quelle place l'**ordre social** occupe-t-il dans ta réponse ?","bareme":[{"critere":"Introduction avec problématique claire","points":3},{"critere":"Trois arguments « manipulation » et trois arguments « révélation » exacts","points":7},{"critere":"Plan dialectique cohérent","points":5},{"critere":"Conclusion : la pièce donne des arguments aux deux camps ; le stratagème lève les obstacles sociaux","points":5}],"dureeMin":20,"corrige":"1. Introduction possible : Chez Marivaux, l'amour a souvent besoin d'un coup de pouce. Dans *Les Fausses Confidences* (1737), Dubois organise un piège pour qu'une riche veuve épouse un jeune homme ruiné. **Problématique** : ce stratagème trompe-t-il Araminte ou l'aide-t-il à découvrir ce qu'elle ressent ? Nous verrons qu'il a tout d'une manipulation, puis qu'il révèle un amour déjà là, avant de montrer qu'il combat surtout un ordre social.\n2. **Manipulation** : Araminte est **trompée, surveillée, poussée** pendant trois actes ; Dubois **exploite sa générosité et sa curiosité** ; Dorante **ment par omission**. **Révélation** : **rien n'est inventé**, Dorante l'aime vraiment ; Araminte l'aime **déjà**, sans se l'avouer ; le stratagème **lève les obstacles** posés par la société et l'amour-propre.\n3. Plan possible : **I. Une mécanique de manipulation** (une révélation par acte, ironie dramatique, Dubois auteur). **II. Mais une manipulation qui ne ment pas** (confidence vraie, amour préexistant, Araminte mène l'acte III). **III. Un stratagème contre l'ordre social** (argent partout, mère qui veut un titre, comte et son procès ; seul le détour permet de dire l'amour).\n4. Conclusion attendue : La pièce **ne tranche pas** : elle **donne des arguments aux deux camps**, et c'est ce qui en fait un excellent sujet. Mais la manipulation vise moins Araminte que les obstacles : chez Marivaux, l'amour n'est jamais hors du système social, et la difficulté n'est pas de s'aimer mais de **pouvoir le dire**. Le stratagème est le moyen de rendre dicible un mariage que l'argent et le rang interdisent."}$exo$::jsonb),
  ('4bed4876-8d60-5da7-ad5b-c6545cb63202'::uuid, 1, 'redaction', $exo${"titre":"Juste la fin du monde : la situation","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qui a écrit *Juste la fin du monde*, quand, et dans quelles circonstances personnelles ?\n2. Qui est **Louis** ? Pourquoi revient-il, et après combien de temps d'absence ?\n3. Présente en une phrase chacun des **quatre** autres personnages.\n4. Quelle est la **structure** de la pièce, et comment se termine-t-elle ?","bareme":[{"critere":"Jean-Luc Lagarce, 1990, atteint du sida, mort en 1995","points":4},{"critere":"Louis, 34 ans, revient après douze ans pour annoncer sa mort prochaine","points":5},{"critere":"La Mère, Antoine, Suzanne, Catherine correctement présentés","points":6},{"critere":"Prologue, deux parties, intermède, épilogue ; Louis repart sans rien dire","points":5}],"dureeMin":7,"corrige":"1. La pièce est écrite en **1990** par **Jean-Luc Lagarce**, alors **atteint du sida**, dont il mourra en **1995**.\n2. **Louis**, **trente-quatre ans**, revient dans sa famille après **douze ans** d'absence pour **annoncer sa mort prochaine**.\n3. **La Mère** parle beaucoup et organise le dimanche comme si de rien n'était ; **Antoine**, le frère cadet resté au pays, colérique et blessé, reproche à Louis son départ et son silence ; **Suzanne**, la sœur, ne connaît son frère que par les « petits mots » qu'il envoyait ; **Catherine**, la belle-sœur, ne l'a jamais vu et parle avec une politesse gênée.\n4. Un **prologue**, deux parties séparées par un **intermède**, un **épilogue**. À la fin, Louis **repart sans avoir rien dit** ; l'épilogue raconte, au conditionnel, un cri qu'il n'a jamais poussé."}$exo$::jsonb),
  ('4bed4876-8d60-5da7-ad5b-c6545cb63202'::uuid, 2, 'redaction', $exo${"titre":"Une parole qui se corrige en direct","consigne":"Lis la réplique, puis réponds en rédigeant et en citant le texte.","enonce":"**Réplique (inventée pour l'exercice, à la manière de Lagarce)**\n\n> SUZANNE. — Tu envoyais des petits mots, des cartes, pas des lettres, je ne dis pas des lettres, des petits mots, c'est différent, c'est ce que je voulais dire, pas des reproches, je ne fais pas de reproches, je dis seulement que c'était peu, que c'était trop peu, voilà.\n\n1. Relève **deux** reprises ou corrections de la phrase par elle-même. Comment le cours décrit-il cette langue ?\n2. Qu'est-ce que Suzanne **reproche** à Louis, et comment le fait-elle sans le dire franchement ?\n3. Explique pourquoi cette manière de parler « **dit exactement le sujet** » de la pièce.","bareme":[{"critere":"Deux reprises ou corrections citées ; parole reprise, corrigée, réajustée en direct, qui cherche le mot juste et le manque","points":7},{"critere":"Reproche de l'absence et du peu de nouvelles, adouci par les corrections (« pas des reproches »)","points":6},{"critere":"On parle sans arrêt pour ne pas dire l'essentiel","points":7}],"dureeMin":10,"corrige":"1. « pas des lettres, je ne dis pas des lettres, des petits mots » ; « c'est ce que je voulais dire » ; « pas des reproches, je ne fais pas de reproches » ; « que c'était peu, que c'était trop peu ». La phrase se **reprend, se corrige, se réajuste en direct** : la parole avance **en tâtonnant**, se rature, **cherche le mot juste et le manque**.\n2. Suzanne reproche à Louis son **absence** et le **peu** qu'il donnait de lui : de simples « petits mots ». Mais elle nie faire des reproches au moment même où elle en fait ; chaque correction adoucit puis durcit (« peu », puis « trop peu »). Le reproche passe par les détours de la phrase.\n3. Dans cette famille, **on parle sans arrêt pour ne pas dire l'essentiel** : Suzanne parle beaucoup mais ne dit ni son amour ni sa blessure, et Louis, qui écoute, ne dit pas qu'il va mourir. La langue de Lagarce, qui tourne autour de son objet sans l'atteindre, montre ce sujet même : l'histoire d'un **aveu qui n'aura pas lieu**."}$exo$::jsonb),
  ('4bed4876-8d60-5da7-ad5b-c6545cb63202'::uuid, 3, 'redaction', $exo${"titre":"« Juste » la fin du monde","consigne":"Réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"Dans le prologue, Louis dit au spectateur : « Plus tard, l'année d'après — j'allais mourir à mon tour. »\n\n1. Que change pour le spectateur le fait de connaître le projet de Louis **dès le prologue** ?\n2. Le cours dit qu'« **il ne se passe rien** ». Cite ce qui se passe pourtant, et explique pourquoi ce n'est « rien ».\n3. Analyse le **titre** : quel est le rôle du mot « juste » ?\n4. **Paragraphe argumenté** : « En quoi *Juste la fin du monde* est-elle l'histoire d'un aveu qui n'aura pas lieu ? » Appuie-toi sur la structure, la langue et l'épilogue.","bareme":[{"critere":"Le spectateur sait ce que les autres ignorent : attente, tension de chaque échange","points":3},{"critere":"Déjeuner, disputes, évocation du passé, promenade proposée : aucun événement ne dit l'essentiel","points":4},{"critere":"« Juste » minimise une immense catastrophe individuelle, jamais prononcée","points":4},{"critere":"Paragraphe : structure, langue qui se reprend, départ silencieux, épilogue au conditionnel","points":7},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. Le spectateur **sait** d'emblée ce que la famille ignore : Louis va mourir et vient pour le dire. Chaque réplique devient alors une **occasion manquée** : on attend l'aveu, et l'attente crée la tension.\n2. On **déjeune**, on **se dispute**, on **évoque le passé**, quelqu'un **propose une promenade en voiture**. Ce n'est « rien » parce qu'aucun de ces moments n'est un événement dramatique : il n'y a pas de coup de théâtre, et l'essentiel n'est jamais dit.\n3. « La fin du monde » dit l'**immense catastrophe individuelle** : la mort de Louis. Le mot « **juste** » la **minimise**, comme on dit « ce n'est rien ». Le titre reproduit la façon de parler de la pièce : réduire l'essentiel à une formule — une phrase qui, dans la pièce, n'est **jamais prononcée**.\n4. Paragraphe attendu : Tout est en place pour l'aveu : le **prologue** l'annonce, Louis revient après douze ans, la famille est réunie un dimanche. Mais la parole des autres occupe tout l'espace : la Mère organise le dimanche comme si de rien n'était, Antoine reproche, Suzanne parle des petits mots, Catherine reste polie. La **langue** se reprend et se corrige sans atteindre son objet, et Louis **écoute**. À la fin, il **repart sans avoir rien dit**, et l'**épilogue** raconte **au conditionnel** un cri qu'il n'a jamais poussé. La pièce est donc bien l'histoire d'un aveu qui n'aura pas lieu : son sujet est ce qui ne se dit pas."}$exo$::jsonb),
  ('eba13f91-0448-55e1-9652-c396c6a593ad'::uuid, 1, 'redaction', $exo${"titre":"Deux crises qui n'en font qu'une","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle est la **crise personnelle** de Louis ? Pourquoi annoncer sa mort revient-il à « demander quelque chose » ?\n2. Quel **reproche** chacun des trois personnages suivants adresse-t-il à Louis ou quel comportement adopte-t-il : Antoine, Suzanne, La Mère ?\n3. Cite **deux** éléments qui rapprochent la pièce de la **tragédie**.","bareme":[{"critere":"Louis sait qu'il va mourir ; annoncer, c'est demander attention, pardon, amour, ce qu'il n'a jamais fait","points":7},{"critere":"Antoine : le préféré qui a pu partir, se dit « brutal » ; Suzanne : absence et mystère ; La Mère rejoue le dimanche d'autrefois","points":8},{"critere":"Deux éléments tragiques (destin annoncé au prologue, unité de lieu, unité de temps, héros prisonnier de ce qu'il est)","points":5}],"dureeMin":7,"corrige":"1. Louis **sait** qu'il va mourir ; il a préparé et répété son annonce. Mais annoncer sa mort, c'est **demander quelque chose** : de l'attention, du pardon, de l'amour. Or Louis est **parti**, il n'a envoyé que des « petits mots » : il n'a **jamais rien demandé**.\n2. **Antoine** reproche à Louis d'avoir été le **préféré**, celui qui a **pu partir**, celui qui écrit ; il crie et se déclare « **brutal** », parce que c'est la place qu'on lui a laissée. **Suzanne** lui reproche l'**absence** et le **mystère**. **La Mère** **rejoue le dimanche d'autrefois** pour empêcher que le pire arrive.\n3. Un **destin connu d'avance** (le prologue annonce la mort de Louis) ; l'**unité de lieu** (la maison) ; l'**unité de temps** (un dimanche) ; un héros qui **ne peut échapper à ce qu'il est**."}$exo$::jsonb),
  ('eba13f91-0448-55e1-9652-c396c6a593ad'::uuid, 2, 'redaction', $exo${"titre":"Des monologues qui ne se répondent pas","consigne":"Lis l'échange, puis réponds en rédigeant.","enonce":"**Échange (inventé pour l'exercice, à la manière de Lagarce)**\n\n> ANTOINE. — Toi, tu es parti, tu as toujours pu partir, c'est ça, toujours, et nous on restait, je ne me plains pas, je dis.\n> LA MÈRE. — Le dimanche, on allait au bord de l'eau, en voiture, avec le pique-nique, vous vous souvenez, vous étiez petits.\n> LOUIS. — Oui.\n\n1. Les répliques d'Antoine et de la Mère se **répondent-elles** ? Justifie. Quel constat du cours cela illustre-t-il ?\n2. Quel **rôle** joue chaque réplique dans la crise familiale (reproche, esquive) ?\n3. Que révèle la réplique de **Louis** ? Explique pourquoi la pièce est à la fois **bavarde** et centrée sur le **silence**.","bareme":[{"critere":"Les répliques ne se répondent pas : les monologues coexistent plus qu'ils ne dialoguent, personne n'écoute vraiment","points":7},{"critere":"Antoine règle ses comptes (le préféré qui a pu partir) ; la Mère rejoue le dimanche d'autrefois pour éviter le pire","points":7},{"critere":"Louis écoute et se tait : paradoxe d'une pièce bavarde où le silence est central","points":6}],"dureeMin":10,"corrige":"1. Non : Antoine accuse, et la Mère parle d'autre chose, des dimanches d'autrefois, sans lui répondre. Les **monologues coexistent** plus qu'ils ne dialoguent : **personne n'écoute vraiment**.\n2. Antoine **règle ses comptes** : Louis a été celui qui a **pu partir**, les autres sont restés ; « je ne me plains pas, je dis » est une correction typique qui nie le reproche en le faisant. La Mère **esquive** : elle **rejoue le dimanche d'autrefois** pour empêcher que le pire arrive, c'est-à-dire la dispute ou la vérité.\n3. Louis ne dit que « Oui » : il **écoute**, il n'entre pas dans le conflit et ne dit rien de lui. C'est le **paradoxe** de la pièce : elle est **bavarde**, tout le monde parle, et pourtant le **silence** y est central, car l'essentiel — la mort de Louis — n'est jamais dit. Chez Lagarce, la langue **échoue en parlant**, et c'est cet échec qui émeut."}$exo$::jsonb),
  ('eba13f91-0448-55e1-9652-c396c6a593ad'::uuid, 3, 'redaction', $exo${"titre":"Louis est-il lâche ?","consigne":"Construis une réflexion de type dissertation à partir de la pièce.","enonce":"**Sujet** : « Louis, qui repart sans avoir rien dit, est-il un lâche ? »\n\n1. Rédige une **problématique** et annonce un plan.\n2. Développe **deux arguments** qui pourraient faire juger Louis lâche.\n3. Développe **deux arguments** qui montrent que son silence a d'autres causes (lui-même, sa famille).\n4. Explique, en quelques lignes, en quoi la pièce peut être lue comme une **tragédie moderne** et ce que cela change au jugement porté sur Louis.\n5. **Conclusion** : que fait le texte face à cette question ?","bareme":[{"critere":"Problématique et plan cohérents","points":3},{"critere":"Deux arguments pour la lâcheté (fuite, silence, annonce préparée et abandonnée)","points":4},{"critere":"Deux arguments contraires : silence prolongement d'une vie tenue à distance, famille qui empêche de parler, protection des siens","points":5},{"critere":"Tragédie moderne : destin annoncé, unités, héros prisonnier de ce qu'il est, catastrophe intérieure","points":5},{"critere":"Conclusion : le texte refuse de trancher","points":3}],"dureeMin":20,"corrige":"1. Problématique possible : le silence de Louis est-il une faiblesse morale, ou le résultat d'une situation — une vie et une famille — qui rendait la parole impossible ? Plan : I. Les apparences d'une lâcheté ; II. Un silence produit par une vie et par une famille ; III. Un héros tragique plutôt qu'un lâche.\n2. **Lâcheté** : Louis a **préparé** et **répété** son annonce, il le dit lui-même, et il y renonce ; il **repart** comme il était parti douze ans plus tôt, fuyant encore sa famille et laissant les siens dans l'ignorance.\n3. **Autres causes** : le silence final n'est **pas un accident**, c'est le **prolongement logique d'une vie tenue à distance** : celui qui envoyait des « petits mots » n'a jamais rien demandé, et annoncer sa mort serait demander de l'attention, du pardon, de l'amour. La **famille** empêche de parler : chacun règle ses comptes (Antoine), la Mère rejoue le dimanche d'autrefois, personne n'écoute. On peut aussi penser qu'il **protège les siens** d'une nouvelle qui les briserait.\n4. **Tragédie moderne** : le destin est connu d'avance (le prologue), l'action tient en un lieu (la maison) et un temps (un dimanche), et le héros **ne peut échapper à ce qu'il est**. Ce qui manque, c'est le geste : la **catastrophe est un non-événement**, intérieure. Si Louis est un héros tragique, son silence relève moins d'une faute morale que d'un destin.\n5. Conclusion : le texte **refuse de trancher** entre lâcheté et protection des siens. Il montre plutôt comment une crise personnelle et une crise familiale n'en font qu'une, et laisse le spectateur juger."}$exo$::jsonb),
  ('6781922a-51da-570b-b31f-c643352d5b32'::uuid, 1, 'redaction', $exo${"titre":"Gargantua : le prologue et le récit","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Sous quel **pseudonyme** et en quelle année Rabelais publie-t-il *Gargantua* ? Que raconte ce livre par rapport à *Pantagruel* ?\n2. Explique l'image des **Silènes** et celle du **chien avec l'os** dans le prologue. Qu'est-ce que la « **substantifique moelle** » ?\n3. Résume en une phrase chacun de ces épisodes : la **naissance** de Gargantua, la **guerre picrocholine**, l'**abbaye de Thélème**.","bareme":[{"critere":"Alcofribas Nasier, anagramme, 1534 ; second livre écrit, qui raconte la vie du père de Pantagruel","points":5},{"critere":"Silènes grotesques contenant des drogues précieuses ; briser l'os pour la moelle : sens profond sous la farce","points":7},{"critere":"Naissance par l'oreille et cri « À boire ! » ; querelle de fouaces et Picrochole empereur rêvé ; Thélème, « Fais ce que voudras »","points":8}],"dureeMin":8,"corrige":"1. Rabelais publie *Gargantua* en **1534** sous le pseudonyme d'**Alcofribas Nasier**, **anagramme** de François Rabelais. C'est le **second livre écrit** par Rabelais, mais il raconte la vie du **père** de Pantagruel.\n2. Les **Silènes** étaient des boîtes **grotesques** qui contenaient des **drogues précieuses** : l'apparence comique cache un contenu de valeur. Le lecteur doit faire comme le **chien avec l'os** : **briser la coquille** pour en tirer la **substantifique moelle**, c'est-à-dire le **sens profond caché sous la farce**. Mais Rabelais ajoute que tout cela n'était peut-être qu'un jeu : l'ambiguïté est volontaire.\n3. **Naissance** : après un repas de tripes, Gargamelle accouche par l'**oreille**, et l'enfant crie « **À boire !** ». **Guerre picrocholine** : une querelle de **marchands de fouaces** déclenche une guerre absurde ; **Picrochole** se rêve **empereur du monde**. **Thélème** : Gargantua offre à Frère Jean une abbaye mixte, riche, sans horloge ni contrainte, dont la seule règle est « **Fais ce que voudras** »."}$exo$::jsonb),
  ('6781922a-51da-570b-b31f-c643352d5b32'::uuid, 2, 'redaction', $exo${"titre":"Deux éducations face à face","consigne":"Réponds en rédigeant, en t'appuyant sur le tableau du cours.","enonce":"Gargantua reçoit successivement **deux éducations**.\n\n1. Nomme les maîtres de chacune.\n2. Compare les **méthodes** et le **ressort** de ces deux éducations (au moins trois différences).\n3. Explique comment le **rire** sert ici la démonstration : que rend-il ridicule, et que rend-il désirable ?","bareme":[{"critere":"Sorbonnards Thubal Holoferne et Jobelin Bridé / l'humaniste Ponocrates","points":4},{"critere":"Trois différences exactes : par cœur, livres inutiles / journée réglée, exercice, lectures commentées, observation ; contrainte / plaisir","points":9},{"critere":"Rire : désacralise la scolastique et rend le savoir humaniste joyeux","points":7}],"dureeMin":10,"corrige":"1. Première éducation : les maîtres **sorbonnards**, **Thubal Holoferne** et **Jobelin Bridé**. Seconde : le précepteur **humaniste Ponocrates**.\n2. Chez les sorbonnards, on apprend **par cœur** des **livres inutiles**, pendant des **dizaines d'années** : le ressort est la **contrainte**. Chez Ponocrates, la journée est **réglée**, elle mêle **exercice physique**, **lectures commentées**, **hygiène** et **observation directe** ; le ressort est l'**apprentissage par le plaisir**. L'une ignore le corps, l'autre l'entretient ; l'une répète, l'autre fait comprendre.\n3. Le **rire** (noms parlants, énumérations, durées absurdes) **désacralise** l'autorité de la **scolastique** : on ne respecte plus un savoir dont on rit. En même temps, il rend le **savoir humaniste joyeux** et désirable. Le rire est une **méthode**, pas une pause."}$exo$::jsonb),
  ('6781922a-51da-570b-b31f-c643352d5b32'::uuid, 3, 'redaction', $exo${"titre":"Sous la farce, cherchez le sens","consigne":"Lis le passage, réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"**Passage (inventé pour l'exercice, à la manière de Rabelais)**\n\n> Le roi Picrochole, ayant reçu trois fouaces en moins, jura par tous ses ancêtres qu'il en tirerait vengeance, et commanda sur l'heure qu'on levât une armée de dix mille fantassins, huit mille cavaliers, trois mille arquebusiers, quatre cents canons, soixante-douze tambours, dix-neuf trompettes et un moine pour bénir le tout.\n\n1. Relève **deux procédés comiques** du passage (énumération, gigantisme, disproportion…) et explique leur effet.\n2. Quelle **cible** la satire vise-t-elle ici ? Rattache-la à l'épisode de la guerre picrocholine.\n3. Explique le rapport entre ce passage et l'invitation du prologue à chercher la « **substantifique moelle** ». Pourquoi le prologue reste-t-il **ambigu** ?\n4. **Paragraphe argumenté** : « Chez Rabelais, le rire est-il un simple divertissement ? »","bareme":[{"critere":"Deux procédés comiques identifiés et expliqués (énumération vertigineuse, disproportion fouaces / armée, chute du moine)","points":4},{"critere":"Cible : la guerre de conquête absurde (querelle de fouaces, Picrochole empereur rêvé)","points":4},{"critere":"Sens caché sous la farce ; ambiguïté constante et volontaire (peut-être un jeu)","points":4},{"critere":"Paragraphe : le rire comme méthode qui désacralise autorité, scolastique, guerre, religion formaliste et rend le savoir joyeux","points":6},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. **Énumération vertigineuse** et chiffrée (fantassins, cavaliers, canons, tambours, trompettes) : elle crée un effet de **gigantisme** et de démesure. **Disproportion** entre la cause (trois fouaces) et la réponse (une armée entière) : l'absurdité fait rire. La **chute** (« un moine pour bénir le tout ») ajoute une pointe contre la religion qui cautionne la guerre.\n2. La cible est la **guerre de conquête** : comme dans l'épisode de la **guerre picrocholine**, une querelle de marchands de fouaces déclenche une guerre absurde, et Picrochole se rêve **empereur du monde**.\n3. Sous la **farce** (l'armée ridicule), il y a un **sens** : la guerre naît souvent de causes dérisoires et de l'orgueil des princes. C'est la « **substantifique moelle** » qu'il faut tirer de l'os. Mais le prologue ajoute que tout cela n'était peut-être qu'un jeu : l'**ambiguïté est constante et volontaire**, et le lecteur doit décider lui-même.\n4. Paragraphe attendu : Le rire de Rabelais n'est pas une récréation. Gigantisme, énumérations, latin de cuisine et noms parlants sont une **méthode** : le rire **désacralise** l'autorité, la **scolastique** des sorbonnards, la **guerre de conquête** de Picrochole et la **religion formaliste**. Il rend en même temps le **savoir humaniste joyeux**, comme l'éducation par le plaisir de Ponocrates. Rire d'une autorité, c'est déjà s'en libérer : le rire est chez Rabelais une manière de penser."}$exo$::jsonb),
  ('a7519845-d929-557e-b605-5bf2f238560a'::uuid, 1, 'redaction', $exo${"titre":"Rire et savoir : les notions","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Complète le tableau du programme de Ponocrates : contre l'apprentissage par cœur, contre le mépris du corps, contre le latin scolastique, contre la répétition — que propose-t-il ?\n2. Qui est **Janotus de Bragmardo** et que ridiculise son discours ?\n3. Qu'est-ce que le rire **carnavalesque** ? Qui a proposé ce terme ?","bareme":[{"critere":"Observation, gymnastique et natation, langues anciennes lues dans le texte, conversation et commentaire","points":8},{"critere":"Janotus vient réclamer les cloches ; discours d'ivrogne plein de fausse logique : satire de la Sorbonne et de la scolastique","points":6},{"critere":"Rire par le corps qui renverse les hiérarchies le temps d'une fête ; Bakhtine","points":6}],"dureeMin":7,"corrige":"1. Contre l'apprentissage **par cœur** : l'**observation**. Contre le **mépris du corps** : la **gymnastique** et la **natation**. Contre le **latin scolastique** : les **langues anciennes lues dans le texte**. Contre la **répétition** : la **conversation** et le **commentaire**. C'est le rêve humaniste de l'homme complet, capable de juger par lui-même.\n2. **Janotus de Bragmardo** vient réclamer les **cloches** (de Notre-Dame) ; il prononce un **discours d'ivrogne** bourré de **fausse logique**. Il ridiculise la **Sorbonne** et sa **scolastique**.\n3. Le rire **carnavalesque** est un rire **par le corps** (nourriture, boisson, sexe, excréments) qui **renverse les hiérarchies** le temps d'une fête. Le terme vient de **Bakhtine**."}$exo$::jsonb),
  ('a7519845-d929-557e-b605-5bf2f238560a'::uuid, 2, 'redaction', $exo${"titre":"Picrochole et Grandgousier","consigne":"Réponds en rédigeant, en t'appuyant sur le cours.","enonce":"La guerre picrocholine oppose deux rois.\n\n1. Quelle **faute** Picrochole commet-il avant même de combattre ? Quel rôle jouent ses conseillers ?\n2. Quelle position **Grandgousier** défend-il ? Quelle page du livre le cours met-il en valeur ?\n3. Quelle opposition l'épisode de **Frère Jean** établit-il entre deux manières d'être religieux ?\n4. Que montre cet ensemble sur ce que vise la **satire** de Rabelais ?","bareme":[{"critere":"Picrochole partage le monde avant d'avoir gagné une bataille ; conseillers flatteurs","points":5},{"critere":"Grandgousier plaide pour la paix ; page sur la responsabilité du prince","points":5},{"critere":"Moines qui prient sans agir / Frère Jean qui agit et défend l'abbaye","points":5},{"critere":"Cibles : guerre de conquête, religion formaliste ; satire au service de l'humanisme","points":5}],"dureeMin":11,"corrige":"1. Picrochole **partage le monde avant d'avoir gagné une bataille** : il se voit déjà empereur. Ses **conseillers le flattent** au lieu de le raisonner, et nourrissent son rêve de conquête.\n2. **Grandgousier plaide pour la paix**. Le cours souligne sa page sur la **responsabilité du prince**, rarement égalée dans le siècle : un roi doit protéger ses sujets, non les sacrifier à son ambition.\n3. Les moines **prient sans agir** pendant qu'on pille ; **Frère Jean agit** et défend l'abbaye à coups de bâton de croix. Rabelais oppose une **religion formaliste** (rites vides) et une foi active.\n4. La satire vise la **guerre de conquête** et la **religion formaliste** (comme ailleurs la Sorbonne et la justice). Elle sert l'**humanisme** : un prince responsable, une religion vivante, un homme capable de juger par lui-même."}$exo$::jsonb),
  ('a7519845-d929-557e-b605-5bf2f238560a'::uuid, 3, 'redaction', $exo${"titre":"Thélème, une utopie enviable ?","consigne":"Construis une réflexion de type dissertation sur Gargantua.","enonce":"**Sujet** : « L'abbaye de Thélème est-elle une utopie enviable ? »\n\n1. Décris l'abbaye de Thélème : ce qui en fait un « anti-monastère » et sa règle unique.\n2. Explique la **clause d'entrée** de Thélème et pourquoi le cours la juge problématique.\n3. Propose un **plan en deux ou trois parties** avec un argument et un exemple par partie.\n4. **Conclusion** : relie la réponse au lien entre **liberté** et **éducation** dans l'ensemble de l'œuvre (Ponocrates).","bareme":[{"critere":"Anti-monastère mixte, riche, beau, sans horloge ni contrainte ; « Fais ce que voudras »","points":4},{"critere":"Gens bien nés, bien instruits, capables de vouloir le bien : utopie élitiste","points":5},{"critere":"Plan dialectique argumenté avec exemples de l'œuvre","points":7},{"critere":"Conclusion : liberté fruit de l'éducation, pas un droit ; lien avec Ponocrates","points":4}],"dureeMin":18,"corrige":"1. Thélème est offerte par Gargantua à **Frère Jean**. C'est un **anti-monastère** : **mixte**, **riche**, **beau**, **sans horloge ni contrainte**, à l'opposé des couvents réglés par les heures et les vœux. Sa seule règle : « **Fais ce que voudras** ».\n2. « Fais ce que voudras » suppose des gens « **bien nés, bien instruits** », **capables de vouloir le bien**. Seuls ceux-là y entrent : c'est une **utopie élitiste**, où la liberté est le **fruit de l'éducation**, **pas un droit**.\n3. Plan possible :\n- **I. Une utopie séduisante** : liberté totale, beauté, absence de contrainte, contre-modèle des monastères qui prient sans agir.\n- **II. Mais une utopie réservée** : la clause d'entrée exclut ceux qui ne sont ni bien nés ni instruits ; la liberté n'est pas donnée à tous.\n- **III. Une utopie qui prolonge le rêve humaniste** : la liberté suppose l'éducation, comme celle de Ponocrates qui forme un homme complet capable de juger par lui-même.\n4. Conclusion attendue : Thélème est enviable pour qui y entre, mais son exclusivité pose problème. Elle éclaire tout le livre : chez Rabelais, on n'est libre que si l'on a été **éduqué** à bien vouloir. L'éducation de Ponocrates prépare le Thélémite ; la liberté n'est pas un point de départ, c'est un résultat."}$exo$::jsonb),
  ('956e7f5a-1592-5ce3-b2cc-a2e81d96916e'::uuid, 1, 'redaction', $exo${"titre":"Les Caractères : forme et programme","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne l'auteur, la date de première publication et la date de la dernière augmentation des *Caractères*. Comment l'œuvre se présente-t-elle d'abord ?\n2. Cite **quatre formes** employées par La Bruyère et l'usage de chacune.\n3. Quels livres le programme retient-il ? Cite le titre de **trois** d'entre eux.\n4. Pourquoi La Bruyère donne-t-il des **noms grecs** à ses personnages ?","bareme":[{"critere":"La Bruyère, 1688, augmentée jusqu'en 1696 ; d'abord une traduction de Théophraste","points":5},{"critere":"Maxime (frapper), portrait (montrer), dialogue ou anecdote (faire entendre), réflexion (développer)","points":6},{"critere":"Livres V à X, trois titres exacts","points":5},{"critere":"Se protéger, alors que la cour reconnaissait ses modèles (clés)","points":4}],"dureeMin":7,"corrige":"1. *Les Caractères ou les Mœurs de ce siècle* de **Jean de La Bruyère** paraissent en **1688** et sont augmentés jusqu'en **1696**. L'œuvre se présente d'abord comme une **traduction de Théophraste**, avant de devenir une œuvre autonome.\n2. La **maxime brève**, pour **frapper** ; le **portrait**, pour **montrer** ; le **dialogue** et l'**anecdote**, pour **faire entendre** ; la **réflexion** d'une page, pour **développer**.\n3. Les **livres V à X** : *De la société et de la conversation*, *Des biens de fortune*, *De la ville*, *De la cour*, *Des grands*, *Du souverain ou de la république* (trois suffisent).\n4. Il nomme ses figures par des **noms grecs** (Giton, Phédon, Ménalque) **pour se protéger**. Mais la cour de Louis XIV **s'y reconnaissait** : des « **clés** » circulaient pour identifier les modèles."}$exo$::jsonb),
  ('956e7f5a-1592-5ce3-b2cc-a2e81d96916e'::uuid, 2, 'redaction', $exo${"titre":"Montrer au lieu de démontrer","consigne":"Lis le portrait, puis réponds en rédigeant et en citant le texte.","enonce":"**Portrait (inventé pour l'exercice, à la manière de La Bruyère)**\n\n> Arcas entre chez le ministre comme on entre dans un temple : il se courbe dès la porte, sourit à l'huissier, rit avant que le ministre ait fini sa phrase, et approuve ce qu'il n'a pas entendu. Sorti, il se redresse, parle haut, tutoie son cocher. Il a deux dos : l'un pour la cour, l'autre pour la ville.\n\n1. Relève **trois gestes** qui suffisent à peindre ce caractère. Que révèle chacun ?\n2. Explique pourquoi on peut dire que La Bruyère **montre** au lieu de **démontrer**.\n3. Explique la **dernière phrase** : quelle forme brève y reconnais-tu ? Quel regard sur la cour exprime-t-elle ?","bareme":[{"critere":"Trois gestes relevés et interprétés (courbette, rire anticipé, approbation sans écoute, redressement, tutoiement)","points":7},{"critere":"Un geste, un vêtement, une manière de parler suffisent : pas de raisonnement ni de thèse énoncée","points":6},{"critere":"Formule brève de maxime ; comédie sociale : chacun joue un rôle selon le public, cour comme théâtre","points":7}],"dureeMin":10,"corrige":"1. « il se courbe dès la porte » : la servilité ; « rit avant que le ministre ait fini sa phrase » et « approuve ce qu'il n'a pas entendu » : la flatterie, qui n'écoute pas ; « se redresse, parle haut, tutoie son cocher » : l'arrogance envers les inférieurs.\n2. La Bruyère n'explique pas que le courtisan est hypocrite : il le **fait voir** par des **gestes** et des **manières de parler**. Comme le dit le cours, un geste, un vêtement, une manière de parler suffisent à faire un caractère. Le lecteur tire lui-même la leçon.\n3. « Il a deux dos : l'un pour la cour, l'autre pour la ville » est une **formule brève et frappante**, proche de la **maxime**. Elle montre que le courtisan **joue un rôle** différent selon son public : la société est une **comédie**, et la cour un **théâtre** aux mœurs codées."}$exo$::jsonb),
  ('956e7f5a-1592-5ce3-b2cc-a2e81d96916e'::uuid, 3, 'redaction', $exo${"titre":"Le corps dit la condition sociale","consigne":"Réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"Dans le livre VI, *Des biens de fortune*, La Bruyère oppose deux portraits : **Giton**, le riche, et **Phédon**, le pauvre.\n\n**Deux portraits (inventés pour l'exercice, à la manière de La Bruyère)**\n\n> Clitandre a la voix pleine, le pas large ; il s'assied le premier, parle le dernier, et l'on rit de ce qu'il dit. Il est riche.\n\n> Érophile marche le long des murs, parle bas, cède le passage ; il s'excuse d'éternuer. Il est pauvre.\n\n1. Compare les deux portraits : relève pour chacun **trois** indices physiques ou de comportement.\n2. Pourquoi la condition sociale n'est-elle révélée qu'**à la fin** de chaque portrait ? Quel effet cela produit-il ?\n3. Quelle thèse du cours sur Giton et Phédon ces portraits illustrent-ils ?\n4. **Paragraphe argumenté** : « En quoi *Les Caractères* font-ils de la société une comédie ? » Appuie-toi sur la méthode de La Bruyère, sur les formes brèves et sur au moins deux livres du programme.","bareme":[{"critere":"Trois indices pour chaque portrait, opposés terme à terme","points":4},{"critere":"Chute retardée : le lecteur devine avant la révélation, effet de surprise et de démonstration","points":4},{"critere":"Le corps même dit la condition sociale","points":3},{"critere":"Paragraphe : comédie sociale, rôles joués, deux livres exacts (société et conversation, ville, cour, grands…)","points":7},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. **Clitandre** : « la voix pleine », « le pas large », « s'assied le premier, parle le dernier », on rit de ce qu'il dit. **Érophile** : « marche le long des murs », « parle bas », « cède le passage », « s'excuse d'éternuer ». Tout s'oppose : occupation de l'espace, voix, attention des autres.\n2. La **chute** (« Il est riche. », « Il est pauvre. ») arrive après la description : le lecteur a déjà deviné. L'effet est à la fois **frappant** et **démonstratif** : les gestes suffisaient, la condition sociale était écrite dans le corps.\n3. Ils illustrent la thèse du portrait de Giton et Phédon : **le corps même dit la condition sociale**. L'argent ne se voit pas seulement dans les biens, il façonne les gestes, la voix, la place qu'on prend.\n4. Paragraphe attendu : La Bruyère **montre** au lieu de démontrer : chaque personnage se réduit à des gestes et à des manières, comme un rôle de théâtre. Dans *De la société et de la conversation*, la parole est une **parade** de vaniteux ; dans *De la ville*, la **bourgeoisie singe la cour** ; dans *De la cour*, chef-d'œuvre du livre, la cour est décrite comme un **pays étranger** aux mœurs codées. Les **formes brèves** — maximes et portraits — figent ces rôles. Et les noms grecs, derrière lesquels la cour se reconnaissait, font du lecteur un spectateur. La société entière devient une **comédie sociale**."}$exo$::jsonb),
  ('b199ad65-bc32-53d9-a241-05269915211a'::uuid, 1, 'redaction', $exo${"titre":"La Déclaration d'Olympe de Gouges : structure","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quand la *Déclaration des droits de la femme et de la citoyenne* est-elle publiée, et à quel texte répond-elle ?\n2. Présente les **cinq parties** du texte en une phrase chacune.\n3. Cite l'**article X** et explique son argument.\n4. Qui était Olympe de Gouges (nom de naissance, lieu, date) et quel fut son sort ?","bareme":[{"critere":"Septembre 1791, réponse à la Déclaration de 1789 dont les femmes étaient absentes","points":4},{"critere":"Dédicace à Marie-Antoinette, préambule calqué, dix-sept articles, postambule, contrat social","points":7},{"critere":"Article X cité et expliqué : punies comme citoyennes, elles doivent être représentées","points":5},{"critere":"Marie Gouze, Montauban, 1748 ; guillotinée le 3 novembre 1793","points":4}],"dureeMin":8,"corrige":"1. Elle paraît en **septembre 1791** et répond **directement** à la *Déclaration des droits de l'homme et du citoyen* de **1789**, dont les femmes étaient **absentes**.\n2. La **dédicace** à la reine **Marie-Antoinette**, appelée à soutenir la cause des femmes ; le **préambule**, **calqué** sur celui de 1789 ; les **dix-sept articles**, dans l'ordre exact de 1789, réécrits pour inclure les femmes ; le **postambule**, d'un ton tout différent (« Femme, réveille-toi… ») ; le **contrat social** entre l'homme et la femme (mariage, biens, enfants naturels).\n3. « **La femme a le droit de monter sur l'échafaud ; elle doit avoir également celui de monter à la tribune.** » Argument : la **loi punit** les femmes comme des citoyennes ; elle doit donc les **représenter** comme telles.\n4. Olympe de Gouges est née **Marie Gouze**, à **Montauban**, en **1748**. Autrice de théâtre et révolutionnaire modérée (girondine), elle est **guillotinée le 3 novembre 1793**."}$exo$::jsonb),
  ('b199ad65-bc32-53d9-a241-05269915211a'::uuid, 2, 'redaction', $exo${"titre":"Le pastiche rend l'oubli visible","consigne":"Compare les deux textes, puis réponds en rédigeant.","enonce":"**Document 1 — *Déclaration des droits de l'homme et du citoyen*, 1789, article premier**\n\n> Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l'utilité commune.\n\n**Document 2 — Olympe de Gouges, *Déclaration des droits de la femme et de la citoyenne*, 1791, article premier**\n\n> La femme naît libre et demeure égale à l'homme en droits. Les distinctions sociales ne peuvent être fondées que sur l'utilité commune.\n\n1. Relève ce qui est **identique** et ce qui **change** d'un texte à l'autre.\n2. Comment appelle-t-on ce procédé d'écriture ? Explique pourquoi il est efficace.\n3. Que révèle la modification sur le sens réel du mot « hommes » dans le texte de 1789 ?","bareme":[{"critere":"Identique : structure, deuxième phrase mot pour mot ; changé : « la femme », « égale à l'homme »","points":6},{"critere":"Pastiche : reprendre mot pour mot le texte fondateur rend l'oubli visible sans avoir à le démontrer","points":8},{"critere":"« Les hommes » de 1789 ne désignaient en fait que les hommes : les femmes étaient absentes","points":6}],"dureeMin":10,"corrige":"1. **Identique** : la construction (« naît/naissent… et demeure(nt)… en droits »), et la **deuxième phrase**, reprise **mot pour mot** (« Les distinctions sociales ne peuvent être fondées que sur l'utilité commune »). **Changé** : « Les hommes » devient « **La femme** », et « égaux en droits » devient « **égale à l'homme** en droits ».\n2. C'est un **pastiche** : Olympe de Gouges reprend la **forme du texte adverse** au lieu de le réfuter. C'est efficace parce que le lecteur **reconnaît immédiatement le modèle** et **fait lui-même la comparaison** : l'ajout suffit à **rendre l'oubli visible sans avoir à le démontrer**.\n3. En écrivant « la femme » là où 1789 écrivait « les hommes », elle montre que le texte de 1789, qui prétendait parler de tous, avait **oublié les femmes** : ses droits ne leur étaient pas accordés. Le pastiche révèle l'exclusion cachée sous l'universel."}$exo$::jsonb),
  ('b199ad65-bc32-53d9-a241-05269915211a'::uuid, 3, 'redaction', $exo${"titre":"Du juridique au polémique","consigne":"Réponds aux questions, puis rédige un paragraphe argumenté.","enonce":"Le postambule de la *Déclaration* s'ouvre sur ces mots :\n\n> « Femme, réveille-toi ; le tocsin de la raison se fait entendre dans tout l'univers ; reconnais tes droits. »\n\n1. Relève **trois** procédés de cette phrase (mode des verbes, apostrophe, image) et nomme le **registre**.\n2. Compare ce ton à celui des **dix-sept articles**. Pourquoi Olympe de Gouges change-t-elle de registre ? À qui s'adresse désormais le texte ?\n3. Explique l'image du « **tocsin de la raison** ».\n4. **Paragraphe argumenté** : « Un texte sans effet légal peut-il être utile ? » Appuie-toi sur la stratégie d'écriture d'Olympe de Gouges et sur ce que l'on sait de la suite (droit de vote des femmes).","bareme":[{"critere":"Impératifs, apostrophe « Femme », métaphore du tocsin ; registre polémique ou appel direct","points":4},{"critere":"Articles juridiques pour les législateurs / postambule pour convaincre les femmes elles-mêmes : la loi ne suffit pas","points":5},{"critere":"Tocsin : cloche d'alarme, appel à se lever au nom de la raison","points":3},{"critere":"Paragraphe nuancé : aucun effet légal immédiat, vote en 1944, mais texte qui change ce qui peut être dit","points":6},{"critere":"Expression et précision","points":2}],"dureeMin":18,"corrige":"1. Les **impératifs** (« réveille-toi », « reconnais »), l'**apostrophe** (« Femme »), la **métaphore** du « tocsin de la raison ». Le ton est celui de l'**appel direct** : c'est le registre **polémique** (ou lyrique et exhortatif), avec apostrophes et exclamations.\n2. Les articles parlent la langue **juridique** des législateurs, sobre et impersonnelle. Le postambule change de registre parce que **la loi ne suffit pas** : il faut aussi **convaincre les femmes elles-mêmes** de réclamer leurs droits. Le texte ne s'adresse plus aux législateurs mais **aux femmes**.\n3. Le **tocsin** est la cloche qu'on sonne pour donner l'**alarme** et appeler la population à se lever. Le « tocsin de la raison » signifie que la raison des Lumières sonne l'alerte : il est temps que les femmes se réveillent et revendiquent leurs droits, partout (« dans tout l'univers »).\n4. Paragraphe attendu : La *Déclaration* n'a eu **aucun effet légal immédiat** : ignorée en 1791, elle n'a pas empêché que les femmes attendent le **droit de vote** jusqu'en **1944**, cent cinquante-trois ans plus tard. Pourtant, elle n'est pas inutile. Par le **pastiche**, elle rend visible l'exclusion des femmes ; par le **postambule**, elle appelle les femmes à se réveiller. Un texte ne change pas directement la loi, mais il **change ce qui peut être dit** : il fait exister une revendication. Ignoré en son temps, il est aujourd'hui au programme."}$exo$::jsonb),
  ('22812fc6-a156-5bcc-b9bc-9d3e813162dc'::uuid, 1, 'redaction', $exo${"titre":"Trois registres, trois publics","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Pour chacune des trois parties suivantes, donne son **registre** et son **public** : les dix-sept articles, le postambule, le contrat social.\n2. Cite les **quatre égalités** que réclame le texte, avec un exemple pour chacune.\n3. Quand ce programme sera-t-il réalisé ?","bareme":[{"critere":"Articles juridiques pour les législateurs, postambule polémique pour les femmes, contrat social didactique pour tous","points":9},{"critere":"Égalités politique, civile, d'expression, de statut avec un exemple chacune","points":8},{"critere":"Au XXe siècle","points":3}],"dureeMin":7,"corrige":"1. Les **dix-sept articles** : registre **juridique**, pour les **législateurs** — ils parlent leur langue, donc sont irréfutables dans leurs termes. Le **postambule** : registre **polémique**, pour les **femmes** (apostrophes, questions, impératifs, ironie). Le **contrat social** : registre **didactique**, pour **tous** (solutions concrètes : biens communs, enfants naturels, droit de nommer le père).\n2. Égalité **politique** : voter, être élue, participer à la loi. **Civile** : propriété, héritage, mariage. D'**expression** : parler en public, publier. De **statut** : être **sujet de droit**, et non protégée.\n3. Ce programme complet ne sera réalisé qu'**au XXe siècle**."}$exo$::jsonb),
  ('22812fc6-a156-5bcc-b9bc-9d3e813162dc'::uuid, 2, 'redaction', $exo${"titre":"Les limites d'un texte engagé","consigne":"Réponds en rédigeant, en t'appuyant sur le cours.","enonce":"Un bon devoir sur la *Déclaration* d'Olympe de Gouges mentionne ses **tensions** et ses **limites**.\n\n1. Présente **trois** tensions ou limites du texte relevées par le cours.\n2. Pour chacune, explique ce qu'elle **révèle** sur le texte et son époque.\n3. Ces limites affaiblissent-elles le texte ? Réponds en justifiant, avec la formule du cours.","bareme":[{"critere":"Trois limites exactes : dédicace à une reine que la Révolution jugera, vocabulaire de la nature et de la sensibilité féminine, public de femmes instruites","points":9},{"critere":"Ce que chacune révèle (catégories de son temps, portée sociale limitée)","points":6},{"critere":"Elles ne l'affaiblissent pas comme document : elles le situent dans son époque","points":5}],"dureeMin":10,"corrige":"1. Le texte s'adresse à une **reine**, Marie-Antoinette, que la Révolution **jugera** ; il conserve un vocabulaire de la « **nature** » et de la « **sensibilité** » féminine ; il vise d'abord les **femmes instruites**.\n2. La dédicace révèle une stratégie risquée et une situation politique mouvante. Le vocabulaire de la nature montre qu'Olympe de Gouges **pense encore avec les catégories de son temps**, qui attribuent aux femmes une nature propre. Le public de femmes instruites montre que sa **portée sociale est limitée**.\n3. Non : ces tensions **ne l'affaiblissent pas comme document**, elles le **situent dans son époque**. Un texte de 1791 ne peut pas penser comme aujourd'hui ; le mentionner montre qu'on le lit avec précision, sans le trahir."}$exo$::jsonb),
  ('22812fc6-a156-5bcc-b9bc-9d3e813162dc'::uuid, 3, 'redaction', $exo${"titre":"L'écriture est-elle un combat ?","consigne":"Construis une réflexion de type dissertation à partir de l'œuvre d'Olympe de Gouges.","enonce":"**Sujet** : « Écrire pour l'égalité, est-ce déjà combattre ? » Tu t'appuieras sur la *Déclaration des droits de la femme et de la citoyenne* (parcours : écrire et combattre pour l'égalité).\n\n1. Rédige une **introduction** (amorce, problématique, annonce du plan).\n2. Montre, dans une première partie, que l'écriture est une **arme** : analyse la stratégie du **pastiche** et celle des **trois registres**.\n3. Nuance, dans une deuxième partie : que **ne peut pas** faire une déclaration sans pouvoir ?\n4. Dans une troisième partie, montre ce que le **prix payé par l'autrice** et la postérité du texte apportent à la réponse.\n5. **Conclusion** en deux ou trois phrases.","bareme":[{"critere":"Introduction avec problématique sur l'efficacité d'une déclaration sans pouvoir","points":3},{"critere":"Partie I : pastiche (démonstration par la forme) et trois registres pour trois publics","points":6},{"critere":"Partie II : aucun effet légal immédiat, texte ignoré en 1791, limites du texte","points":4},{"critere":"Partie III : guillotinée en 1793, article X prophétique, texte aujourd'hui au programme","points":5},{"critere":"Conclusion cohérente","points":2}],"dureeMin":20,"corrige":"1. Introduction possible : En 1791, deux ans après la Déclaration des droits de l'homme, Olympe de Gouges en publie une réécriture qui y fait entrer les femmes. **Problématique** : que peut faire une déclaration sans pouvoir ? Écrire suffit-il à combattre ? Nous verrons que l'écriture est une arme, qu'elle ne change pourtant pas la loi, mais qu'elle peut coûter et rapporter bien plus qu'un effet immédiat.\n2. **I. L'écriture comme arme** : le **pastiche** reprend la forme du texte adverse — préambule, articles, numérotation — et ajoute « et la citoyenne » : le lecteur fait lui-même la comparaison, l'**exclusion devient criante**, c'est une **démonstration par la forme**. Les **trois registres** visent trois publics : **juridique** pour les législateurs (irréfutable dans leurs termes), **polémique** pour les femmes (« Femme, réveille-toi »), **didactique** pour tous (le contrat social).\n3. **II. Les limites d'une déclaration sans pouvoir** : le texte n'a eu **presque aucun effet** en 1791 ; il ne change **pas directement la loi** ; le droit de vote n'arrivera qu'en **1944**. Il a aussi ses limites : public de femmes instruites, vocabulaire de la « nature » féminine.\n4. **III. Un combat réel** : l'article X — « La femme a le droit de monter sur l'échafaud ; elle doit avoir également celui de monter à la tribune » — devient **tragiquement prophétique** : Olympe de Gouges est **guillotinée le 3 novembre 1793**. Écrire pouvait coûter la vie. Et le texte change **ce qui peut être dit** : ignoré en 1791, il est aujourd'hui au programme du bac.\n5. Conclusion : écrire pour l'égalité, c'est déjà combattre, non parce que le texte change la loi, mais parce qu'il rend l'injustice visible et impose une parole nouvelle. Le **prix payé par l'autrice** montre que ce combat était bien réel."}$exo$::jsonb),
  ('79385c1a-3f42-53cb-8eb1-8d521c164577'::uuid, 1, 'redaction', $exo${"titre":"Simple ou complexe ?","consigne":"Pour chaque phrase, compte les verbes conjugués et justifie ta réponse en une ligne.","enonce":"Pour chacune des phrases suivantes, indique le **nombre de verbes conjugués**, puis dis si la phrase est **simple**, **complexe** ou **averbale**.\n\n1. Le jour se lève.\n2. Il sort acheter du pain.\n3. Quelle horreur !\n4. Elle avait fini son travail quand la cloche a sonné.\n5. Sors !\n6. Le vent tombait, la mer se calmait, le jour finissait.\n\nPuis donne la **définition** d'une proposition.","bareme":[{"critere":"Nombre de verbes conjugués juste pour les six phrases (1, 1, 0, 2, 1, 3)","points":9},{"critere":"Type de phrase juste pour les six phrases, pièges justifiés (infinitif, temps composé, averbale, sujet sous-entendu)","points":8},{"critere":"Définition : ensemble organisé autour d'un verbe conjugué","points":3}],"dureeMin":7,"corrige":"1. **1** verbe conjugué (se lève) : phrase **simple**.\n2. **1** verbe conjugué (sort) ; « acheter » est un **infinitif**, non conjugué : phrase **simple**.\n3. **0** verbe : phrase **averbale**, aucune proposition.\n4. **2** verbes conjugués : « avait fini » (un **temps composé** compte pour **un seul** verbe) et « a sonné » : phrase **complexe**.\n5. **1** verbe conjugué (sors), sujet **sous-entendu** à l'impératif : c'est bien une proposition, phrase **simple**.\n6. **3** verbes conjugués (tombait, se calmait, finissait) : phrase **complexe**, trois propositions juxtaposées.\n\nUne **proposition** est un ensemble organisé autour d'**un verbe conjugué**."}$exo$::jsonb),
  ('79385c1a-3f42-53cb-8eb1-8d521c164577'::uuid, 2, 'redaction', $exo${"titre":"Découper une phrase en propositions","consigne":"Applique la méthode du cours : souligne (cite) les verbes conjugués, repère les mots subordonnants, puis nomme.","enonce":"Pour chaque phrase : compte les verbes conjugués, délimite les propositions, puis indique la **relation** entre elles (juxtaposition, coordination, subordination) et, s'il y a lieu, la **principale** et la **subordonnée**.\n\n1. Il pleuvait ; nous sommes restés à la maison.\n2. Je sais que tu viendras, mais je crains le retard.\n3. Le train qui partait à midi est arrivé en retard.","bareme":[{"critere":"Verbes conjugués correctement comptés dans les trois phrases (2, 3, 2)","points":5},{"critere":"Phrase 1 : deux indépendantes juxtaposées par le point-virgule","points":4},{"critere":"Phrase 2 : principale, subordonnée introduite par « que », proposition coordonnée par « mais »","points":6},{"critere":"Phrase 3 : subordonnée « qui partait à midi » insérée dans la principale","points":5}],"dureeMin":10,"corrige":"1. Deux verbes conjugués : **pleuvait**, **sommes restés** (temps composé : un seul verbe). Deux propositions **indépendantes** : [Il pleuvait] ; [nous sommes restés à la maison]. Relation : **juxtaposition**, marquée par le **point-virgule** ; elles sont de même rang.\n2. Trois verbes conjugués : **sais**, **viendras**, **crains**, donc trois propositions. [Je sais] est la **principale** ; [que tu viendras] est une **subordonnée** introduite par le subordonnant « que », qui dépend de « sais » (**subordination**). [mais je crains le retard] est reliée à ce qui précède par la conjonction « mais » : **coordination**.\n3. Deux verbes conjugués : **partait**, **est arrivé**. La **principale** est [Le train … est arrivé en retard] ; la **subordonnée** [qui partait à midi], introduite par le subordonnant « qui », est **insérée** à l'intérieur de la principale et en dépend (**subordination**)."}$exo$::jsonb),
  ('79385c1a-3f42-53cb-8eb1-8d521c164577'::uuid, 3, 'redaction', $exo${"titre":"Analyser la syntaxe d'un poème de Hugo","consigne":"Analyse chaque phrase selon la méthode du cours, puis interprète ce que la syntaxe apporte au poème.","enonce":"**Victor Hugo, « Demain, dès l'aube… », première strophe (*Les Contemplations*, 1856)**\n\n> Demain, dès l'aube, à l'heure où blanchit la campagne,\n> Je partirai. Vois-tu, je sais que tu m'attends.\n> J'irai par la forêt, j'irai par la montagne.\n> Je ne puis demeurer loin de toi plus longtemps.\n\n1. Cette strophe compte **quatre phrases**. Pour chacune, relève les verbes conjugués et donne le nombre de propositions.\n2. Phrase 1 : délimite la principale et la subordonnée. Quel **piège** présente le sujet de la subordonnée ?\n3. Phrase 2 : analyse les relations entre ses propositions.\n4. Phrase 4 : pourquoi est-ce une phrase simple malgré ses deux verbes ?\n5. **Interprétation** : que produisent les propositions courtes et juxtaposées de la phrase 3 ? Et la seule subordination de la phrase 2 ?","bareme":[{"critere":"Verbes conjugués et nombre de propositions justes pour les quatre phrases (2, 3, 2, 1)","points":5},{"critere":"Phrase 1 : principale « Demain… je partirai », subordonnée « où blanchit la campagne », sujet inversé","points":4},{"critere":"Phrase 2 : « Vois-tu » juxtaposée, principale « je sais », subordonnée « que tu m'attends » ; phrase 3 : deux indépendantes juxtaposées","points":4},{"critere":"Phrase 4 : « demeurer » est un infinitif, un seul verbe conjugué","points":3},{"critere":"Interprétation : rythme décidé, résolution de la marche ; certitude du lien avec la destinataire","points":4}],"dureeMin":18,"corrige":"1. Phrase 1 : **blanchit**, **partirai** → 2 propositions. Phrase 2 : **vois**, **sais**, **attends** → 3 propositions. Phrase 3 : **irai**, **irai** → 2 propositions. Phrase 4 : **puis** → 1 proposition.\n2. Principale : [Demain, dès l'aube, à l'heure …, je partirai]. Subordonnée : [où blanchit la campagne], introduite par le subordonnant « où », qui dépend de « l'heure ». Piège : le sujet est **inversé** : « la campagne » est le sujet de « blanchit », placé après le verbe.\n3. [Vois-tu] est une proposition **juxtaposée** au reste par la virgule (sujet inversé dans la question). [je sais] est la **principale** ; [que tu m'attends] est une **subordonnée** introduite par « que », qui dépend de « sais ».\n   Phrase 3 : deux propositions **indépendantes** **juxtaposées** par la virgule.\n4. « demeurer » est un **infinitif**, non conjugué : seul « puis » est conjugué. La phrase est **simple**.\n5. La phrase 3 aligne deux propositions courtes, de même rang, avec la reprise « j'irai… j'irai » : le rythme est **décidé**, il mime la **marche** et la résolution du père, que rien n'arrête. La seule subordination de la strophe, « je sais que tu m'attends », fait dépendre toute la marche d'une **certitude** : le lien avec la destinataire, que le poète tient pour sûr."}$exo$::jsonb),
  ('e1bc8318-64df-5245-9fef-fd77e0c21bbb'::uuid, 1, 'redaction', $exo${"titre":"Juxtaposées ou coordonnées ?","consigne":"Réponds en une ou deux lignes pour chaque phrase.","enonce":"Pour chaque phrase, dis si les propositions sont **juxtaposées** ou **coordonnées**, relève ce qui les relie et indique le **rapport logique** exprimé ou suggéré.\n\n1. Il pleuvait, mais nous sommes sortis.\n2. Il pleuvait, nous sommes restés.\n3. Nous sommes restés, car il pleuvait.\n4. Il pleuvait ; nous sommes, cependant, sortis.\n\nPuis explique la différence grammaticale entre « **car** » et « **parce que** ».","bareme":[{"critere":"Quatre identifications justes avec l'outil de liaison (mais, virgule, car, cependant)","points":8},{"critere":"Rapports logiques justes (opposition, conséquence implicite, cause, opposition)","points":6},{"critere":"« Car » coordonne (même rang), « parce que » subordonne (dépendance)","points":6}],"dureeMin":7,"corrige":"1. **Coordonnées** par la conjonction « **mais** » : rapport d'**opposition**, explicite.\n2. **Juxtaposées** par une **virgule** : le lien est **implicite** ; le lecteur reconstitue une **conséquence** (il pleuvait, donc nous sommes restés).\n3. **Coordonnées** par la conjonction « **car** » : rapport de **cause**, explicite.\n4. **Coordonnées** par l'**adverbe de liaison** « **cependant** », qui exprime l'**opposition** (il se déplace à l'intérieur de la proposition, ce n'est pas une conjonction ; le point-virgule marque la séparation).\n\n« **Car** » est une conjonction de **coordination** : les deux propositions restent **de même rang**. « **Parce que** » est une conjonction de **subordination** : la proposition qu'elle introduit **dépend** de la principale."}$exo$::jsonb),
  ('e1bc8318-64df-5245-9fef-fd77e0c21bbb'::uuid, 2, 'redaction', $exo${"titre":"Rendre explicite un lien implicite","consigne":"Transforme les phrases selon la consigne et justifie chaque choix avec le vocabulaire du cours.","enonce":"1. Transforme chaque phrase juxtaposée en phrase **coordonnée** qui explicite le lien logique indiqué entre parenthèses :\n   - a. Il avait trop couru, il s'effondra sur le banc. (conséquence)\n   - b. Elle n'a pas répondu, elle était absente. (cause)\n   - c. Le soleil brillait, l'air restait glacé. (opposition)\n2. Dans la phrase « Paul et Marie sont arrivés, et la fête a commencé », les deux « **et** » ont-ils le même rôle ? Justifie.\n3. Déplace l'adverbe « **pourtant** » dans la phrase « Il était fatigué ; pourtant, il continua. » Que prouve cette manipulation ?","bareme":[{"critere":"Trois transformations correctes avec une conjonction ou un adverbe de liaison adapté (donc, car, mais…)","points":9},{"critere":"Premier « et » relie deux noms, second relie deux propositions : seul le second concerne l'analyse","points":5},{"critere":"« Il continua pourtant » : l'adverbe de liaison se déplace, ce n'est pas une conjonction","points":6}],"dureeMin":10,"corrige":"1. a. « Il avait trop couru, **donc** il s'effondra sur le banc. » (ou l'adverbe de liaison « ainsi »). b. « Elle n'a pas répondu, **car** elle était absente. » c. « Le soleil brillait, **mais** l'air restait glacé. » (ou « pourtant », « cependant »). Chaque fois, le lien devient **explicite** : la coordination **construit** le raisonnement, là où la juxtaposition le **suggérait**.\n2. Non. Le premier « et » relie deux **noms** (Paul et Marie), deux sujets : ce n'est pas une relation entre propositions. Le second relie deux **propositions** ([Paul et Marie sont arrivés] et [la fête a commencé]) : c'est une **coordination**. Seule cette seconde situation concerne l'analyse de la phrase complexe.\n3. « Il était fatigué ; il continua **pourtant**. » ou « il **continua**, pourtant, sa route ». L'adverbe peut **se déplacer** dans la proposition : c'est un **adverbe de liaison**, pas une conjonction de coordination (qui, elle, reste toujours entre les deux propositions)."}$exo$::jsonb),
  ('e1bc8318-64df-5245-9fef-fd77e0c21bbb'::uuid, 3, 'redaction', $exo${"titre":"Ce que la juxtaposition fait au récit","consigne":"Analyse le texte selon la méthode du cours, puis interprète les effets.","enonce":"**Texte (inventé pour l'exercice)**\n\n> La porte claqua. Marc se retourna, la lampe tomba, le verre éclata sur le carrelage. Personne ne bougeait. Il avança pourtant vers le couloir, car une voix l'appelait, mais il ne reconnaissait pas cette voix.\n\n1. Analyse la phrase « Marc se retourna, la lampe tomba, le verre éclata sur le carrelage. » : nombre de propositions, relation, rang.\n2. Analyse la dernière phrase : relève chaque outil de liaison, donne sa **nature** (conjonction ou adverbe de liaison) et le **rapport logique** qu'il exprime.\n3. Quel **effet** produit la juxtaposition dans la deuxième phrase, compte tenu du contexte (récit) ?\n4. Compare avec la dernière phrase : que marque le passage à la coordination dans la conduite du personnage ?\n5. Réécris la deuxième phrase avec des coordinations explicites et dis ce qu'on perd.","bareme":[{"critere":"Trois propositions indépendantes juxtaposées par des virgules, de même rang","points":4},{"critere":"« pourtant » adverbe de liaison (opposition), « car » conjonction (cause), « mais » conjonction (opposition)","points":5},{"critere":"Juxtaposition dans un récit : accélération, brutalité, lien implicite laissé au lecteur","points":4},{"critere":"Coordination : raisonnement contrôlé, le personnage reprend la maîtrise, puis doute","points":4},{"critere":"Réécriture correcte et perte de rapidité ou de brutalité expliquée","points":3}],"dureeMin":18,"corrige":"1. Trois verbes conjugués (se retourna, tomba, éclata) : trois propositions **indépendantes**, **juxtaposées** par des **virgules**, **de même rang** ; aucune ne dépend de l'autre.\n2. « **pourtant** » : **adverbe de liaison**, rapport d'**opposition** (malgré l'immobilité générale, il avance). « **car** » : conjonction de **coordination**, rapport de **cause** (une voix l'appelait). « **mais** » : conjonction de **coordination**, rapport d'**opposition** (il ne la reconnaissait pas).\n3. Dans un **récit**, la juxtaposition **accélère** l'action : les gestes s'enchaînent sans temps mort, comme s'ils se produisaient en même temps. Le lien de cause (il se retourne, donc la lampe tombe) reste **implicite** : c'est au lecteur de le reconstituer, ce qui rend la scène **brutale** et confuse, comme la perçoit Marc.\n4. La dernière phrase, coordonnée, **construit un raisonnement** : opposition, cause, nouvelle opposition. Après le choc, le personnage reprend le contrôle et justifie son geste (une voix l'appelait) ; la coordination adversative marque un **raisonnement contrôlé** — puis le « mais » final réintroduit l'inquiétude.\n5. Exemple : « Marc se retourna, **et** la lampe tomba, **puis** le verre éclata sur le carrelage. » On perd la **rapidité** et la **brutalité** : les liens explicites ralentissent la scène et mettent de l'ordre là où il y avait de la confusion."}$exo$::jsonb),
  ('81b236ab-9380-5a11-9761-727d157acd9f'::uuid, 1, 'redaction', $exo${"titre":"Antécédent et fonction du relatif","consigne":"Pour chaque phrase, réponds en une ligne.","enonce":"Pour chaque phrase, relève la **subordonnée relative**, son **antécédent**, puis donne la **fonction du pronom relatif** dans la subordonnée.\n\n1. L'homme qui parle est mon père.\n2. Le livre que je lis est ancien.\n3. La ville dont je viens est au bord de la mer.\n4. Je me souviens du jour où nous sommes partis.\n5. La maison où j'ai grandi a été vendue.\n\nPuis explique la **double fonction** du pronom relatif.","bareme":[{"critere":"Cinq relatives et antécédents justes","points":6},{"critere":"Fonctions justes : sujet, COD, complément du verbe « venir de », CC de temps, CC de lieu","points":10},{"critere":"Double fonction : relier les propositions et occuper une fonction dans la subordonnée","points":4}],"dureeMin":8,"corrige":"1. Relative [qui parle], antécédent **l'homme** ; « qui » est **sujet** de « parle ».\n2. Relative [que je lis], antécédent **le livre** ; « que » est **COD** de « lis ».\n3. Relative [dont je viens], antécédent **la ville** ; « dont » est **complément du verbe** « venir **de** ».\n4. Relative [où nous sommes partis], antécédent **le jour** ; « où » est **complément circonstanciel de temps**.\n5. Relative [où j'ai grandi], antécédent **la maison** ; « où » est **complément circonstanciel de lieu**.\n\nLe pronom relatif a une **double fonction** : il **relie** la subordonnée à la principale **et** il occupe une **fonction dans la subordonnée** (sujet, COD, complément…). La relative entière est **complément de l'antécédent**."}$exo$::jsonb),
  ('81b236ab-9380-5a11-9761-727d157acd9f'::uuid, 2, 'redaction', $exo${"titre":"La virgule change le sens","consigne":"Réponds en rédigeant et en utilisant les termes exacts du cours.","enonce":"1. Compare :\n   - a. Les voyageurs qui avaient un billet sont montés dans le train.\n   - b. Les voyageurs, qui avaient un billet, sont montés dans le train.\n   Nomme le type de chaque relative et explique la différence de **sens** entre les deux phrases.\n2. Dans laquelle des deux phrases peut-on **supprimer** la relative sans changer l'information principale ? Justifie.\n3. Donne la fonction de « **dont** » dans chacune des phrases suivantes : « L'ami **dont** le frère est médecin est venu. » / « Le film **dont** je parle est sorti hier. »\n4. Invente une phrase contenant une relative introduite par un pronom **composé** et donne la fonction de ce pronom.","bareme":[{"critere":"a déterminative (restreint), b explicative (ajoute) ; sens : seuls certains voyageurs / tous","points":7},{"critere":"Relative explicative supprimable, déterminative indispensable","points":4},{"critere":"« dont » complément du nom « frère » ; complément du verbe « parler de »","points":5},{"critere":"Phrase correcte avec pronom composé et fonction juste","points":4}],"dureeMin":11,"corrige":"1. a. Relative **déterminative** (restrictive), **sans virgule** : elle **restreint** l'antécédent. Seuls les voyageurs qui avaient un billet sont montés ; **les autres sont restés** sur le quai.\n   b. Relative **explicative** (appositive), **détachée par des virgules** : elle **ajoute** une information. **Tous** les voyageurs avaient un billet, et tous sont montés.\n   La virgule **change le sens** de la phrase.\n2. On peut supprimer la relative de la phrase **b** (« Les voyageurs sont montés dans le train ») : l'information principale reste la même. Dans la phrase **a**, la relative est **indispensable** : sans elle, on dirait que tous sont montés, ce qui est faux.\n3. « L'ami dont le frère est médecin » : « dont » est **complément du nom** « frère » (le frère **de** l'ami). « Le film dont je parle » : « dont » est **complément du verbe** « parler **de** » (je parle **du** film).\n4. Exemple : « La table **sur laquelle** j'écris est bancale. » — « sur laquelle » est **complément circonstanciel de lieu** de « écris ». Autre exemple accepté : « Le projet **auquel** je pense » (complément du verbe « penser à »)."}$exo$::jsonb),
  ('81b236ab-9380-5a11-9761-727d157acd9f'::uuid, 3, 'redaction', $exo${"titre":"Une longue phrase qui enchâsse","consigne":"Analyse la phrase selon la méthode du cours, puis interprète les effets des relatives.","enonce":"**Phrase (inventée pour l'exercice)**\n\n> Elle revit la maison de son enfance, dont les volets verts ne fermaient plus, le jardin où son père taillait les rosiers qu'il aimait tant, et cette chambre qu'elle n'avait jamais osé rouvrir.\n\n1. Compte les verbes conjugués et donne le nombre de propositions.\n2. Relève **toutes** les relatives. Pour chacune : antécédent, pronom relatif, fonction du pronom.\n3. Montre qu'une relative est **enchâssée** dans une autre relative.\n4. Classe chaque relative : **déterminative** ou **explicative** ? Justifie pour l'une d'elles par la ponctuation.\n5. **Interprétation** : quel effet produit cette accumulation de relatives dans une phrase qui évoque des souvenirs ?","bareme":[{"critere":"Cinq verbes conjugués, cinq propositions (une principale, quatre relatives)","points":3},{"critere":"Quatre relatives avec antécédent et fonction juste du relatif","points":6},{"critere":"« qu'il aimait tant » enchâssée dans « où son père taillait les rosiers »","points":3},{"critere":"Classement justifié (« dont… » explicative détachée par des virgules ; les autres déterminatives)","points":4},{"critere":"Interprétation : enchâsser les informations, retarder, accumuler les précisions comme la mémoire","points":4}],"dureeMin":18,"corrige":"1. Cinq verbes conjugués : **revit**, **fermaient**, **taillait**, **aimait**, **avait osé** (temps composé : un seul verbe ; « rouvrir » est un infinitif). Cinq propositions : la principale [Elle revit la maison…, le jardin…, et cette chambre…] et quatre subordonnées relatives.\n2. [dont les volets verts ne fermaient plus] : antécédent **la maison (de son enfance)** ; « dont » est **complément du nom** « volets » (les volets de la maison).\n   [où son père taillait les rosiers] : antécédent **le jardin** ; « où » est **complément circonstanciel de lieu**.\n   [qu'il aimait tant] : antécédent **les rosiers** ; « que » est **COD** de « aimait ».\n   [qu'elle n'avait jamais osé rouvrir] : antécédent **cette chambre** ; « que » est **COD** de « rouvrir » (le groupe « avait osé rouvrir »).\n3. [qu'il aimait tant] complète « les rosiers », qui appartient à la relative [où son père taillait les rosiers] : c'est un **enchâssement**, une subordonnée à l'intérieur d'une autre.\n4. [dont les volets verts ne fermaient plus] est **explicative** : elle est **détachée par des virgules** et **ajoute** une information sur une maison déjà identifiée (« de son enfance ») ; on pourrait la supprimer. Les trois autres sont **déterminatives** (sans virgule) : elles précisent de quel jardin, de quels rosiers, de quelle chambre il s'agit.\n5. Les relatives **allongent** la phrase et **enchâssent** les informations : chaque lieu en appelle un autre, comme la mémoire qui glisse d'un souvenir à l'autre. Elles **accumulent** les précisions (les volets, le père, les rosiers) et **retardent** l'élément le plus lourd, la chambre jamais rouverte, placée à la fin : l'émotion arrive au terme d'une longue **période**."}$exo$::jsonb),
  ('23693833-c8df-578b-8a58-8d0b46307742'::uuid, 1, 'redaction', $exo${"titre":"Reconnaître une complétive","consigne":"Réponds en une ou deux lignes pour chaque question.","enonce":"1. Pour chaque phrase, relève la subordonnée **complétive** et donne sa **fonction** :\n   - a. Je crois que tu as raison.\n   - b. Qu'il soit venu m'étonne.\n   - c. Mon espoir est qu'il revienne.\n   - d. Je suis certain qu'il viendra.\n   - e. L'idée qu'il parte me déplaît.\n2. Quel **test** simple permet de reconnaître une complétive COD ?\n3. Quel **mode** emploie-t-on après « je veux que » ? après « je sais que » ?","bareme":[{"critere":"Cinq fonctions justes : COD, sujet, attribut, complément de l'adjectif, complément du nom","points":12},{"critere":"Remplacement par « quelque chose »","points":4},{"critere":"Subjonctif après un verbe de volonté, indicatif après un verbe de déclaration ou de savoir","points":4}],"dureeMin":7,"corrige":"1. a. [que tu as raison] : **COD** de « crois » (je crois quelque chose).\n   b. [Qu'il soit venu] : **sujet** de « étonne ».\n   c. [qu'il revienne] : **attribut** du sujet « mon espoir ».\n   d. [qu'il viendra] : **complément de l'adjectif** « certain ».\n   e. [qu'il parte] : **complément du nom** « idée ».\n2. On peut la **remplacer par « quelque chose »** : « Je crois **quelque chose** ».\n3. Après un verbe de **volonté** (« je veux que ») : le **subjonctif** (je veux qu'il vienne). Après un verbe de **déclaration** ou de connaissance (« je sais que ») : l'**indicatif** (je sais qu'il vient)."}$exo$::jsonb),
  ('23693833-c8df-578b-8a58-8d0b46307742'::uuid, 2, 'redaction', $exo${"titre":"Le piège du mot « que »","consigne":"Justifie chaque réponse avec le test du cours.","enonce":"1. Donne la **nature** de « que » dans chaque phrase (pronom relatif, conjonction de subordination, adverbe exclamatif) et justifie :\n   - a. L'idée qu'il a eue est excellente.\n   - b. L'idée qu'il parte me déplaît.\n   - c. Que ce paysage est beau !\n   - d. Je pense que tu mens.\n2. Mets le verbe entre parenthèses au mode qui convient et nomme ce mode :\n   - a. Je pense qu'il (être) sincère.\n   - b. Je ne pense pas qu'il (être) sincère.\n   - c. Il faut que tu (partir).\n3. Nomme la subordonnée de la phrase « Je me demande s'il viendra » et donne sa fonction.","bareme":[{"critere":"Natures justes et test de l'antécédent appliqué (relatif, conjonction, adverbe, conjonction)","points":8},{"critere":"Modes justes : est (indicatif), soit (subjonctif, négation), partes (subjonctif, tournure impersonnelle)","points":7},{"critere":"Interrogative indirecte, COD de « demande »","points":5}],"dureeMin":11,"corrige":"1. a. **Pronom relatif** : il a un **antécédent** (« l'idée ») et une **fonction** (**COD** de « a eue » : il a eu l'idée).\n   b. **Conjonction de subordination** : pas d'antécédent ni de fonction ; elle introduit une **complétive**, complément du nom « idée » (l'idée = qu'il parte). C'est le piège : même nom devant, nature différente.\n   c. **Adverbe exclamatif** : il porte l'intensité.\n   d. **Conjonction de subordination** : pas d'antécédent, elle introduit la complétive COD de « pense ».\n   Test : **chercher un antécédent** ; s'il n'y en a pas, ce n'est pas un relatif.\n2. a. Je pense qu'il **est** sincère : **indicatif** (verbe d'opinion).\n   b. Je ne pense pas qu'il **soit** sincère : **subjonctif** — la **négation** fait basculer au subjonctif.\n   c. Il faut que tu **partes** : **subjonctif** (tournure **impersonnelle**).\n3. [s'il viendra] est une subordonnée **interrogative indirecte**, introduite par « si » ; ce n'est pas une complétive ordinaire, mais elle occupe la même fonction : **COD** de « demande »."}$exo$::jsonb),
  ('23693833-c8df-578b-8a58-8d0b46307742'::uuid, 3, 'redaction', $exo${"titre":"Le mode dit la certitude","consigne":"Analyse les complétives du texte, puis interprète le choix des modes.","enonce":"**Texte (inventé pour l'exercice)** — une mère attend son fils parti en mer.\n\n> Je sais que le bateau est rentré au port. On m'a dit qu'il avait accosté à midi. Je veux qu'il revienne ce soir. Mais je ne crois pas qu'il vienne : je crains qu'il ne m'ait oubliée.\n\n1. Relève les **cinq** subordonnées complétives et donne pour chacune sa **fonction**.\n2. Pour chacune, indique le **mode** du verbe et la raison de ce mode (type de verbe, négation).\n3. Montre que le texte passe de l'**indicatif** au **subjonctif**. Qu'est-ce que ce basculement dit de l'état de la mère ?\n4. Dans la phrase « Je ne crois pas qu'il vienne », que deviendrait le mode si l'on supprimait la négation ? Réécris la phrase.","bareme":[{"critere":"Cinq complétives relevées, toutes COD du verbe principal","points":5},{"critere":"Modes et raisons justes : indicatif (savoir, déclaration), subjonctif (volonté, négation, sentiment)","points":6},{"critere":"Basculement interprété : de la certitude des faits au désir puis au doute et à la crainte","points":6},{"critere":"« Je crois qu'il vient (viendra) » à l'indicatif","points":3}],"dureeMin":16,"corrige":"1. [que le bateau est rentré au port] : **COD** de « sais ». [qu'il avait accosté à midi] : **COD** de « a dit ». [qu'il revienne ce soir] : **COD** de « veux ». [qu'il vienne] : **COD** de « crois ». [qu'il ne m'ait oubliée] : **COD** de « crains ».\n2. « est rentré » : **indicatif**, après un verbe de connaissance (« savoir »). « avait accosté » : **indicatif**, après un verbe de **déclaration** (« dire »). « revienne » : **subjonctif**, après un verbe de **volonté**. « vienne » : **subjonctif**, car la **négation** fait basculer au subjonctif. « ait oubliée » : **subjonctif**, après un verbe de **sentiment** (crainte).\n3. Les deux premières phrases sont à l'**indicatif** : ce sont des **faits** certains (le bateau est rentré, il a accosté). Puis le texte passe au **subjonctif** : la mère **désire**, puis **doute** et **craint**. Le mode dit le **degré de certitude** de celle qui parle : les faits sont sûrs, mais le retour de son fils ne l'est pas, et la peur d'être oubliée s'installe.\n4. Sans négation : « Je crois **qu'il vient** » (ou « qu'il **viendra** ») : le verbe d'opinion à la forme affirmative appelle l'**indicatif**."}$exo$::jsonb),
  ('e30f66ef-4568-58bd-b96b-54ef8abd1d95'::uuid, 1, 'redaction', $exo${"titre":"Nommer le rapport circonstanciel","consigne":"Réponds en une ligne pour chaque phrase.","enonce":"Pour chaque phrase, relève la subordonnée **circonstancielle**, nomme le **rapport** qu'elle exprime et le **mode** du verbe.\n\n1. Quand la nuit tomba, ils rentrèrent.\n2. Il est resté chez lui parce qu'il était malade.\n3. Je t'explique la règle pour que tu la comprennes.\n4. Bien qu'il soit fatigué, il continue.\n5. Il a tant couru qu'il est épuisé.\n6. Rentre avant qu'il fasse nuit.\n\nPuis donne le **test** qui distingue une circonstancielle d'une complétive.","bareme":[{"critere":"Six rapports justes (temps, cause, but, concession, conséquence, temps)","points":9},{"critere":"Six modes justes (indicatif, indicatif, subjonctif, subjonctif, indicatif, subjonctif)","points":7},{"critere":"Test : la circonstancielle est déplaçable et souvent supprimable, la complétive ne bouge pas","points":4}],"dureeMin":8,"corrige":"1. [Quand la nuit tomba] : **temps**, **indicatif**.\n2. [parce qu'il était malade] : **cause**, **indicatif**.\n3. [pour que tu la comprennes] : **but**, **subjonctif** (toujours au subjonctif, car le but n'est pas encore réalisé).\n4. [Bien qu'il soit fatigué] : **concession**, **subjonctif**.\n5. [qu'il est épuisé], avec « tant… que » : **conséquence**, **indicatif**.\n6. [avant qu'il fasse nuit] : **temps**, **subjonctif** (exception : « avant que »).\n\nLa circonstancielle complète la **proposition principale tout entière** : elle est **déplaçable** et souvent **supprimable**. La complétive, elle, **ne bouge pas**."}$exo$::jsonb),
  ('e30f66ef-4568-58bd-b96b-54ef8abd1d95'::uuid, 2, 'redaction', $exo${"titre":"Le système hypothétique","consigne":"Conjugue, nomme la valeur de chaque construction et corrige les phrases fautives.","enonce":"1. À partir de « Si tu (venir), je (être) content », écris les trois constructions du système hypothétique et nomme ce que chacune exprime.\n2. Corrige les phrases fautives et explique la règle :\n   - a. Si j'aurais su, je serais venu.\n   - b. Si tu viendras, je serai content.\n3. Complète en choisissant la construction qui convient et justifie :\n   - a. Je ne suis pas riche ; si je (être) riche, je (voyager) davantage.\n   - b. Il fait beau ; si le soleil (rester), nous (aller) à la plage.","bareme":[{"critere":"Trois constructions justes avec potentiel, irréel du présent, irréel du passé","points":8},{"critere":"Corrections justes (si j'avais su ; si tu viens) et règle : jamais de futur ni de conditionnel après « si »","points":6},{"critere":"Complétions justes et justifiées (irréel du présent : étais / voyagerais ; potentiel : reste / irons)","points":6}],"dureeMin":11,"corrige":"1. **Potentiel** (la chose est possible) : Si tu **viens**, je **serai** content (présent + futur). **Irréel du présent** : Si tu **venais**, je **serais** content (imparfait + conditionnel présent). **Irréel du passé** : Si tu **étais venu**, j'**aurais été** content (plus-que-parfait + conditionnel passé).\n2. a. « Si j'**avais su**, je serais venu. » b. « Si tu **viens**, je serai content. » Règle : après le « si » de condition, **jamais de futur ni de conditionnel** ; le mode se joue dans la **principale**.\n3. a. « si j'**étais** riche, je **voyagerais** davantage » : je ne suis pas riche, la condition est contraire à la réalité présente : **irréel du présent** (imparfait + conditionnel présent).\n   b. « si le soleil **reste**, nous **irons** à la plage » : c'est **possible**, donc **potentiel** (présent + futur)."}$exo$::jsonb),
  ('e30f66ef-4568-58bd-b96b-54ef8abd1d95'::uuid, 3, 'redaction', $exo${"titre":"Circonstancielles et argumentation","consigne":"Analyse les subordonnées du texte en deux temps : nommer, puis interpréter.","enonce":"**Texte (inventé pour l'exercice)** — un personnage se défend devant un juge.\n\n> Bien que les apparences soient contre moi, je suis innocent. Je suis entré dans cette maison parce que la porte était ouverte, et comme personne ne répondait, j'ai cru qu'elle était vide. Si j'avais su qu'on m'accuserait, je ne serais jamais entré. Je parle aujourd'hui pour que vous connaissiez la vérité.\n\n1. Relève les **cinq** subordonnées circonstancielles. Pour chacune : subordonnant, **rapport**, **mode**.\n2. Montre avec un test qu'elles sont bien circonstancielles (applique-le à l'une d'elles).\n3. Nomme la construction de la phrase « Si j'avais su…, je ne serais jamais entré. »\n4. **Interprétation** : que révèlent de la stratégie du locuteur la **concessive** du début, les **causales**, l'**hypothétique** et la **finale** ?","bareme":[{"critere":"Cinq circonstancielles avec subordonnant, rapport et mode justes","points":6},{"critere":"Test du déplacement ou de la suppression appliqué correctement","points":3},{"critere":"Irréel du passé : plus-que-parfait + conditionnel passé","points":3},{"critere":"Interprétation : anticiper l'objection, installer un raisonnement, exprimer le regret, viser un but","points":6},{"critere":"Précision du métalangage","points":2}],"dureeMin":18,"corrige":"1. [Bien que les apparences soient contre moi] : « bien que », **concession**, **subjonctif**. [parce que la porte était ouverte] : « parce que », **cause**, **indicatif**. [comme personne ne répondait] : « comme », **cause**, **indicatif**. [Si j'avais su qu'on m'accuserait] : « si », **condition**, **indicatif** (plus-que-parfait). [pour que vous connaissiez la vérité] : « pour que », **but**, **subjonctif**.\n2. Test du **déplacement** : « Je suis innocent, bien que les apparences soient contre moi. » La subordonnée change de place sans que la phrase soit fausse : elle complète la principale tout entière. On peut aussi la **supprimer** (« Je suis innocent »). Une complétive, elle, ne bouge pas.\n3. C'est le **système hypothétique** à l'**irréel du passé** : plus-que-parfait (« avais su ») dans la subordonnée, **conditionnel passé** (« serais entré ») dans la principale.\n4. La **concessive** montre un locuteur qui **anticipe l'objection** : il reconnaît les apparences avant de les écarter. Les deux **causales** installent un **raisonnement** qui justifie chaque geste (la porte ouverte, le silence). L'**hypothétique à l'irréel du passé** exprime le **regret** : il ne peut plus changer ce qu'il a fait. La **finale** dit le **but** de sa parole, qui n'est pas encore atteint (d'où le subjonctif) : convaincre le juge. Les subordonnées construisent une **plaidoirie**."}$exo$::jsonb),
  ('174f7797-f7e3-5700-b020-cb153fd04493'::uuid, 1, 'redaction', $exo${"titre":"Totale ou partielle ?","consigne":"Réponds en une ligne pour chaque question.","enonce":"Pour chaque question, indique si l'interrogation est **totale** ou **partielle**, puis nomme sa **construction** et son **niveau de langue**.\n\n1. Tu viens ?\n2. Est-ce que tu viens ?\n3. Viens-tu ?\n4. Pierre viendra-t-il ?\n5. Quand viens-tu ?\n6. Pourquoi est-ce que tu pleures ?\n\nPuis donne une réponse possible à la question « Tu ne viens pas ? » si l'on veut dire que l'on vient.","bareme":[{"critere":"Type juste pour les six questions (quatre totales, deux partielles)","points":7},{"critere":"Constructions et niveaux justes (intonation familière, est-ce que courant, inversion et inversion complexe soutenues)","points":9},{"critere":"Réponse « Si »","points":4}],"dureeMin":7,"corrige":"1. **Totale** ; **intonation seule** ; oral, **familier**.\n2. **Totale** ; « **est-ce que** » ; **courant**.\n3. **Totale** ; **inversion** sujet-verbe ; **soutenu**.\n4. **Totale** ; **inversion complexe** (sujet nominal repris par « il ») ; **soutenu**.\n5. **Partielle** (mot interrogatif « quand ») ; inversion ; soutenu.\n6. **Partielle** (mot interrogatif « pourquoi ») ; « est-ce que » ; courant.\n\nUne interrogation totale appelle oui / non / **si**. À une question négative, pour dire qu'on vient, on répond « **Si** » (« Si, je viens »)."}$exo$::jsonb),
  ('174f7797-f7e3-5700-b020-cb153fd04493'::uuid, 2, 'redaction', $exo${"titre":"Vraies et fausses questions","consigne":"Réponds en rédigeant, en suivant les trois étapes du cours.","enonce":"1. Réécris la question « Tu as fini ton travail ? » dans les **trois** constructions possibles, du niveau familier au niveau soutenu.\n2. Analyse chacune des questions suivantes en **trois étapes** (type, construction, valeur) :\n   - a. « Qui ne rêve d'être aimé ? » (dans un discours)\n   - b. « Que faire ? Partir, ou rester ? » (un personnage seul en scène)\n   - c. « À quelle heure part le train ? » (un voyageur au guichet)\n3. Transforme la question rhétorique a en phrase **affirmative** qui dit la même chose.","bareme":[{"critere":"Trois constructions correctes (intonation, est-ce que, inversion : As-tu fini ton travail ?)","points":6},{"critere":"Trois analyses complètes (a partielle, rhétorique ; b partielle et totale, délibération ; c partielle, vraie question)","points":10},{"critere":"Affirmation équivalente : tout le monde rêve d'être aimé","points":4}],"dureeMin":11,"corrige":"1. « Tu as fini ton travail ? » (intonation, **familier**) ; « **Est-ce que** tu as fini ton travail ? » (**courant**) ; « **As-tu** fini ton travail ? » (inversion, **soutenu**).\n2. a. **Partielle** (mot interrogatif « qui ») ; construction sans inversion, le mot interrogatif est sujet ; valeur : question **rhétorique** — elle n'attend pas de réponse, elle **affirme**. C'est une arme de l'argumentation.\n   b. « Que faire ? » : **partielle** (« que »), sans verbe conjugué (infinitif) ; « Partir, ou rester ? » : question sur une alternative. Valeur : **délibération**, question qu'on se pose **à soi-même** ; fréquente dans le monologue théâtral, elle **donne à voir l'hésitation**.\n   c. **Partielle** (« à quelle heure ») ; **inversion** du sujet nominal (« part le train ») ; valeur : **vraie question**, le voyageur attend une information précise.\n3. « **Tout le monde rêve d'être aimé.** »"}$exo$::jsonb),
  ('174f7797-f7e3-5700-b020-cb153fd04493'::uuid, 3, 'redaction', $exo${"titre":"Un monologue qui hésite","consigne":"Analyse les interrogations du monologue, puis interprète leur rôle.","enonce":"**Monologue (inventé pour l'exercice)** — Hélène vient de recevoir une lettre de son frère, qu'elle n'a pas vu depuis dix ans.\n\n> HÉLÈNE, *seule*. — Faut-il lui répondre ? Que lui dire, après tant d'années ? Il a oublié mon anniversaire dix fois ; est-ce que j'ai oublié le sien, moi ? Et qui me reprocherait de me taire ? Personne. Pourtant, qui d'autre que moi lui reste ?\n\n1. Relève les **cinq** questions et, pour chacune, suis les trois étapes : **type**, **construction**, **valeur**.\n2. Quelles questions sont des **délibérations** ? Qu'est-ce qui le montre (situation, destinataire) ?\n3. Repère une **question rhétorique** et reformule-la en affirmation.\n4. **Interprétation** : quel changement de **niveau de langue** remarques-tu dans la troisième question ? Qu'est-ce qu'il révèle ? Comment l'enchaînement des questions construit-il l'hésitation du personnage ?","bareme":[{"critere":"Cinq questions analysées : type et construction justes","points":6},{"critere":"Délibérations identifiées (Faut-il lui répondre ? Que lui dire ?) : personnage seul, questions posées à soi-même","points":4},{"critere":"Question rhétorique repérée et reformulée (personne ne me reprocherait…)","points":3},{"critere":"« Est-ce que » courant et « moi » : colère qui fait irruption ; mouvement entre justification et culpabilité","points":5},{"critere":"Précision de l'analyse","points":2}],"dureeMin":18,"corrige":"1. « Faut-il lui répondre ? » : **totale**, **inversion** (soutenu), **délibération**.\n   « Que lui dire, après tant d'années ? » : **partielle** (« que »), avec un infinitif, **délibération**.\n   « est-ce que j'ai oublié le sien, moi ? » : **totale**, « **est-ce que** » (courant), question **rhétorique** (elle affirme : je ne l'ai pas oublié).\n   « Et qui me reprocherait de me taire ? » : **partielle** (« qui »), **rhétorique** — la réponse « Personne » est donnée aussitôt par Hélène elle-même.\n   « qui d'autre que moi lui reste ? » : **partielle** (« qui »), **rhétorique** : elle affirme que personne d'autre ne lui reste.\n2. « Faut-il lui répondre ? » et « Que lui dire… ? » sont des **délibérations** : Hélène est **seule** en scène, elle se pose les questions **à elle-même** et n'attend de réponse de personne ; elle hésite sur ce qu'elle doit faire.\n3. « Et qui me reprocherait de me taire ? » → « **Personne ne me reprocherait de me taire.** » (ou : « Est-ce que j'ai oublié le sien, moi ? » → « Moi, je n'ai jamais oublié le sien. »)\n4. La troisième question abandonne l'**inversion** soutenue pour « **est-ce que** » et ajoute « moi » en fin de phrase : le niveau devient **plus courant, plus oral**. Il révèle la **rancune** qui fait irruption dans la réflexion. L'enchaînement construit l'hésitation : Hélène **délibère** (répondre ? que dire ?), se **justifie** par des questions rhétoriques (le frère a oublié, personne ne la blâmerait), puis « **Pourtant** » renverse le mouvement : la dernière question rhétorique fait pencher vers la réponse — elle est la seule qui lui reste."}$exo$::jsonb),
  ('2ac12546-9e5b-5341-91d8-6162f898ec21'::uuid, 1, 'redaction', $exo${"titre":"Passer à l'interrogation indirecte","consigne":"Transforme chaque question, puis réponds aux deux questions de cours.","enonce":"1. Transforme chaque question directe en **interrogation indirecte** introduite par « Je me demande… » :\n   - a. Viendra-t-il ?\n   - b. Est-ce qu'elle a compris ?\n   - c. Qu'est-ce qui te fait peur ?\n   - d. Qu'est-ce que tu cherches ?\n   - e. Où vont-ils ?\n2. Quels **signes** de la question disparaissent dans l'interrogation indirecte ?\n3. Quelle est la nature et la fonction de la subordonnée obtenue ?","bareme":[{"critere":"Cinq transformations correctes (si il viendra, si elle a compris, ce qui te fait peur, ce que tu cherches, où ils vont)","points":12},{"critere":"Disparition du point d'interrogation, de l'inversion et de « est-ce que »","points":4},{"critere":"Subordonnée interrogative indirecte, COD du verbe introducteur","points":4}],"dureeMin":7,"corrige":"1. a. Je me demande **s'il viendra**.\n   b. Je me demande **si elle a compris**.\n   c. Je me demande **ce qui** te fait peur.\n   d. Je me demande **ce que** tu cherches.\n   e. Je me demande **où ils vont**.\n2. Disparaissent : le **point d'interrogation**, l'**inversion** du sujet et « **est-ce que** » (remplacé par « si ») ; « qu'est-ce qui » devient « ce qui », « qu'est-ce que » devient « ce que ».\n3. C'est une **subordonnée interrogative indirecte**, **COD** du verbe introducteur (« demande »)."}$exo$::jsonb),
  ('2ac12546-9e5b-5341-91d8-6162f898ec21'::uuid, 2, 'redaction', $exo${"titre":"Rapporter une question au passé","consigne":"Transforme, corrige et justifie chaque réponse par la règle du cours.","enonce":"1. Rapporte chaque question avec « Il m'a demandé… » en appliquant la **concordance** des temps et des personnes :\n   - a. « Où vas-tu ? »\n   - b. « Est-ce que tu as faim ? »\n   - c. « Qu'est-ce que tu lis ? »\n   - d. « Pourquoi pleures-tu ? »\n2. Corrige les phrases fautives et explique l'erreur :\n   - a. Je me demande où est-ce qu'il va.\n   - b. Je me demande où va-t-il.\n   - c. Elle ignore qu'est-ce que tu veux.\n3. Cite **trois** verbes introducteurs de l'interrogation indirecte.","bareme":[{"critere":"Quatre transformations justes avec imparfait et changement de personne (où j'allais, si j'avais faim, ce que je lisais, pourquoi je pleurais)","points":9},{"critere":"Trois corrections justes et erreur expliquée (ni inversion ni « est-ce que » dans l'indirect)","points":8},{"critere":"Trois verbes introducteurs exacts","points":3}],"dureeMin":10,"corrige":"1. a. Il m'a demandé **où j'allais**.\n   b. Il m'a demandé **si j'avais faim**.\n   c. Il m'a demandé **ce que je lisais**.\n   d. Il m'a demandé **pourquoi je pleurais**.\n   Le verbe introducteur est au passé : le présent devient **imparfait** ; « tu » devient « je » (**concordance** des temps et des personnes).\n2. a. « Je me demande **où il va**. » — on ne garde **jamais** « est-ce que » dans l'indirect.\n   b. « Je me demande **où il va**. » — on ne garde **jamais l'inversion** dans l'indirect.\n   c. « Elle ignore **ce que** tu veux. » — « qu'est-ce que » devient « **ce que** ».\n3. **demander**, **savoir**, **se demander**, **ignorer**, **chercher** (trois suffisent)."}$exo$::jsonb),
  ('2ac12546-9e5b-5341-91d8-6162f898ec21'::uuid, 3, 'redaction', $exo${"titre":"Entendre ou effacer la voix du personnage","consigne":"Compare les deux versions, analyse les interrogations, puis interprète.","enonce":"**Deux versions d'un même passage (inventées pour l'exercice)**\n\n> **Version A.** Le médecin s'approcha. « Depuis quand toussez-vous ? Est-ce que vous dormez la nuit ? Qu'est-ce qui vous inquiète ? »\n\n> **Version B.** Le médecin s'approcha. Il demanda à Jeanne depuis quand elle toussait, si elle dormait la nuit, ce qui l'inquiétait.\n\n1. Pour chaque question de la version A, indique le **type** (totale ou partielle) et la **construction**.\n2. Montre comment chaque question a été **transformée** dans la version B (ponctuation, ordre, mots interrogatifs, concordance).\n3. Donne la **nature** et la **fonction** des subordonnées de la version B.\n4. **Interprétation** : quelle version fait **entendre** le personnage ? Dans quelle version le **narrateur** se place-t-il entre le lecteur et la parole ? Quel effet cela produit-il sur la scène ?","bareme":[{"critere":"Trois questions analysées (partielle avec inversion, totale avec est-ce que, partielle avec qu'est-ce qui)","points":4},{"critere":"Transformations expliquées : plus de point d'interrogation ni d'inversion, est-ce que → si, qu'est-ce qui → ce qui, présent → imparfait, vous → elle","points":6},{"critere":"Trois interrogatives indirectes, COD de « demanda »","points":4},{"critere":"Interprétation : direct met la question en scène, indirect efface la voix et crée une distance","points":4},{"critere":"Précision du métalangage","points":2}],"dureeMin":16,"corrige":"1. « Depuis quand toussez-vous ? » : **partielle** (« depuis quand »), **inversion**. « Est-ce que vous dormez la nuit ? » : **totale**, « **est-ce que** ». « Qu'est-ce qui vous inquiète ? » : **partielle** (« qu'est-ce qui »), sans inversion.\n2. Dans la version B, les **guillemets** et les **points d'interrogation** disparaissent, ainsi que l'**inversion** (« toussez-vous » → « elle toussait »). « **Est-ce que** » devient « **si** » ; « **qu'est-ce qui** » devient « **ce qui** » ; « depuis quand » reste **inchangé**. Le verbe introducteur étant au passé, le présent devient **imparfait** (toussez → toussait, dormez → dormait, inquiète → inquiétait) et « vous » devient « elle / l' » : **concordance** des temps et des personnes.\n3. [depuis quand elle toussait], [si elle dormait la nuit], [ce qui l'inquiétait] : trois subordonnées **interrogatives indirectes**, **COD** du verbe introducteur « **demanda** » (juxtaposées entre elles par des virgules).\n4. La version A, au **discours direct**, **met la question en scène** : on **entend** le médecin, sa voix, son rythme rapide. Dans la version B, au **discours indirect**, la voix est **effacée** : le narrateur se place **entre le lecteur et la parole**. La scène devient un résumé plus distant, presque routinier — l'examen est rapporté, non vécu."}$exo$::jsonb),
  ('2db15f5d-3fc8-5ecc-ae8e-9d64fc381800'::uuid, 1, 'redaction', $exo${"titre":"Classer les négations","consigne":"Réponds en une ligne pour chaque phrase.","enonce":"Pour chaque phrase, indique le type de négation : **totale**, **partielle**, **exceptive** (restriction), **lexicale**, ou **ne explétif**. Justifie en une ligne.\n\n1. Il ne vient pas.\n2. Il ne vient jamais le lundi.\n3. Je n'ai que dix euros.\n4. Cette tâche est impossible.\n5. Je crains qu'il ne pleuve.\n6. Il refuse de répondre.","bareme":[{"critere":"Six classements justes","points":12},{"critere":"Justifications justes, notamment ne… que = seulement, et ne explétif qui ne nie rien","points":8}],"dureeMin":7,"corrige":"1. Négation **totale** (« ne… pas ») : elle porte sur **toute** la phrase.\n2. Négation **partielle** : elle ne nie qu'**un élément** (le lundi) ; il vient les autres jours.\n3. Négation **exceptive** « ne… que » : ce n'est **pas une négation** mais une **restriction** — j'ai **seulement** dix euros.\n4. Négation **lexicale** : le sens négatif est **dans le mot** (« im-possible »).\n5. **Ne explétif** : il **ne nie rien** — je crains qu'il pleuve.\n6. Négation **lexicale** : le sens négatif est dans le verbe « **refuser** », sans « ne »."}$exo$::jsonb),
  ('2db15f5d-3fc8-5ecc-ae8e-9d64fc381800'::uuid, 2, 'redaction', $exo${"titre":"Mesurer la portée d'une négation","consigne":"Réponds en justifiant par le sens de chaque phrase.","enonce":"1. Explique la différence de sens entre :\n   - a. Elle ne mange pas de viande.\n   - b. Elle ne mange que de la viande.\n   - c. Elle ne mange plus de viande.\n2. Dans « Il n'a pas lu **tous** les livres », quelle est la **portée** de la négation ? A-t-il lu des livres ?\n3. Pourquoi « ne… que » est-il un **piège** à l'oral ? Explique avec la distinction entre **forme** et **sens**.\n4. Relève les négations de la phrase suivante et dis de quel registre relève leur forme : « Je ne saurais dire ; je sais pas, moi. »","bareme":[{"critere":"a totale (aucune viande), b restriction (seulement de la viande), c négation qui marque un changement (plus maintenant)","points":7},{"critere":"Négation partielle portant sur « tous » : il en a lu certains","points":4},{"critere":"Forme de négation, sens de restriction","points":4},{"critere":"« ne » seul en langue littéraire (ne saurais) ; « ne » tombé à l'oral familier (sais pas)","points":5}],"dureeMin":10,"corrige":"1. a. « ne… pas » : négation **totale** — elle ne mange **aucune** viande.\n   b. « ne… que » : **restriction** — elle mange **seulement** de la viande. Le sens est presque l'inverse de a.\n   c. « ne… plus » : elle en mangeait **avant**, elle n'en mange plus **maintenant**.\n2. La négation est **partielle** : elle porte sur « **tous** », pas sur « lire ». Il a donc lu **certains** livres, mais pas tous.\n3. « Ne… que » a la **forme** d'une négation (deux termes, avec « ne ») et le **sens** d'une **restriction** (« seulement ») : un candidat pressé la classe à tort parmi les négations. C'est le **piège classique**.\n4. « Je **ne** saurais dire » : négation **à un seul terme**, le « ne » subsiste seul — **langue littéraire**, soutenue. « je sais **pas** » : le « ne » est **tombé** — **oral familier**."}$exo$::jsonb),
  ('2db15f5d-3fc8-5ecc-ae8e-9d64fc381800'::uuid, 3, 'redaction', $exo${"titre":"Un portrait par soustraction","consigne":"Relève et classe toutes les négations, puis interprète leur effet.","enonce":"**Texte (inventé pour l'exercice)**\n\n> Le vieux Martin ne sortait plus. Il ne recevait personne, ne lisait rien, ne répondait jamais au facteur. Il n'avait gardé qu'une chaise près de la fenêtre. Les voisins le disaient malheureux, insociable, inutile. Lui ne se plaignait pas.\n\n1. Relève **toutes** les tournures en « ne » + second terme, nomme le second terme et dis pour chacune ce qu'elle nie (l'action entière ou un seul élément) ; repère celle qui n'est pas une négation.\n2. Relève les **négations lexicales** et dis dans quels mots se trouve le sens négatif.\n3. Analyse la phrase « Il n'avait gardé qu'une chaise près de la fenêtre » : type de négation, sens, effet.\n4. **Interprétation** : quel portrait l'accumulation de négations construit-elle ? Oppose le regard des voisins (négations lexicales) à la dernière phrase.","bareme":[{"critere":"Tournures relevées (ne plus, ne personne, ne rien, ne jamais, ne pas, ne que), portée juste, ne… que reconnue comme restriction","points":5},{"critere":"Négations lexicales : malheureux, insociable, inutile (préfixes)","points":3},{"critere":"Exceptive : seulement une chaise, attention resserrée, insistance","points":4},{"critere":"Portrait par soustraction : vide, manque, enfermement ; jugement des voisins qui disqualifie ; dernière phrase qui rend sa dignité","points":6},{"critere":"Précision de l'analyse","points":2}],"dureeMin":18,"corrige":"1. « ne sortait **plus** » : nie l'action de sortir **désormais** (il sortait avant). « ne recevait **personne** » : nie qu'il reçoive **qui que ce soit** (porte sur le complément). « ne lisait **rien** » : porte sur le complément (aucune chose). « ne répondait **jamais** » : porte sur le temps (à aucun moment). « ne se plaignait **pas** » : négation **totale**, sur toute la proposition. « n'avait gardé **qu'**une chaise » : **exceptive** — elle a la forme d'une négation mais c'est une **restriction** (seulement une chaise).\n2. **malheureux** (mal-), **insociable** (in-), **inutile** (in-) : le sens négatif est **dans le mot lui-même**, par son préfixe.\n3. « ne… que » = il avait gardé **seulement** une chaise. La restriction **resserre l'attention sur une seule chose** : la chaise près de la fenêtre, seul reste de sa vie, et seul lien avec le dehors. C'est une **insistance**.\n4. L'accumulation de négations construit un **portrait par soustraction** : Martin est défini par tout ce qu'il ne fait plus — le **vide**, le **manque**, l'**enfermement**. Les **négations lexicales** en série rapportent le jugement des voisins : ils le **disqualifient** (malheureux, insociable, inutile) sans avoir l'air de nier. La dernière phrase, courte, avec « Lui » mis en tête, **oppose** son attitude à leur regard : il ne se plaint pas. La négation lui rend une forme de **dignité** silencieuse."}$exo$::jsonb),
  ('d16dc2d7-40f8-5d2b-a388-3a6d8f725b7d'::uuid, 1, 'redaction', $exo${"titre":"La méthode en quatre étapes","consigne":"Réponds en une ou deux phrases par question.","enonce":"1. Combien de points vaut la question de grammaire à l'oral du bac, et à quel moment est-elle posée ?\n2. Cite **dans l'ordre** les **quatre étapes** de la méthode et, pour chacune, l'erreur à éviter.\n3. Laquelle de ces étapes est la plus souvent oubliée ? Pourquoi est-elle décisive ?\n4. Quel conseil donne le cours si l'on n'est pas sûr de tout ?","bareme":[{"critere":"2 points sur 20, après l'explication linéaire, sur une phrase du texte","points":4},{"critere":"Quatre étapes dans l'ordre (relire, identifier, nommer, interpréter) avec leurs erreurs","points":10},{"critere":"Interpréter : fait la différence entre 1 et 2 points ; ne jamais inventer","points":6}],"dureeMin":7,"corrige":"1. Elle vaut **2 points sur 20**. Elle est posée **après l'explication linéaire**, sur une phrase du texte expliqué.\n2. **1. Relire** la phrase **en entier**, à voix haute — erreur : analyser un fragment. **2. Identifier** : compter les verbes conjugués, repérer les subordonnants, délimiter les propositions — erreur : se lancer sans compter. **3. Nommer** précisément : nature, fonction (et pour un relatif, sa double fonction) — erreur : rester vague. **4. Interpréter** : que produit cette construction dans ce texte ? — erreur : l'oublier.\n3. L'**interprétation** est l'étape qu'on oublie ; c'est elle qui fait la différence **entre 1 et 2 points**, car elle montre que la grammaire **sert l'explication**.\n4. **Ne jamais inventer** : mieux vaut **deux propositions justes sur trois** qu'une étiquette fausse pour tout."}$exo$::jsonb),
  ('d16dc2d7-40f8-5d2b-a388-3a6d8f725b7d'::uuid, 2, 'redaction', $exo${"titre":"Rédiger une réponse d'oral complète","consigne":"Rédige ta réponse comme tu la dirais à l'examinateur, en suivant les quatre étapes.","enonce":"**Extrait (inventé pour l'exercice)** — dans un roman, une jeune femme découvre une lettre.\n\n> Elle comprit que tout était fini lorsqu'elle lut la dernière ligne.\n\n**Question de l'examinateur** : « Analysez la phrase suivante. »\n\n1. Rédige ta réponse complète en suivant les **quatre étapes** de la méthode (relire, identifier, nommer, interpréter).\n2. Voici la réponse d'un candidat : « Il y a une subordonnée avec que et une autre avec lorsque. Elles sont subordonnées. » Dis ce qui lui manque pour avoir 2 points.","bareme":[{"critere":"Identification : trois verbes conjugués, trois propositions","points":4},{"critere":"Nomination précise : principale, complétive COD de « comprit », circonstancielle de temps","points":6},{"critere":"Interprétation pertinente de la construction dans le texte","points":5},{"critere":"Critique de la réponse du candidat : vague, pas de compte, pas de fonctions, pas d'interprétation","points":5}],"dureeMin":12,"corrige":"1. Réponse attendue :\n- **Relire** : « Elle comprit que tout était fini lorsqu'elle lut la dernière ligne. »\n- **Identifier** : « Cette phrase compte **trois verbes conjugués** — comprit, était, lut — donc **trois propositions**. Les mots subordonnants sont **que** et **lorsque**. »\n- **Nommer** : [Elle comprit] est la **principale**. [que tout était fini] est une subordonnée **conjonctive complétive**, introduite par la conjonction « que », **COD** du verbe « comprit » (elle comprit quelque chose). [lorsqu'elle lut la dernière ligne] est une subordonnée **circonstancielle de temps**, introduite par « lorsque », à l'**indicatif** ; elle est déplaçable (« Lorsqu'elle lut la dernière ligne, elle comprit… »).\n- **Interpréter** : la principale et la complétive disent la révélation (« tout était fini »), et la circonstancielle de temps la situe **à l'instant précis** de la dernière ligne : la phrase fait coïncider la fin de la lettre et la fin de l'histoire d'amour. Placer la temporelle en fin de phrase retarde le moment de la découverte.\n2. Il manque : le **compte des verbes conjugués** ; la **principale** ; le **métalangage exact** (« conjonctive complétive », « circonstancielle de temps ») ; les **fonctions** (COD de « comprit », complément de la principale) ; et surtout l'**interprétation**. « Une subordonnée avec que » est justement l'exemple de formulation vague que le cours déconseille."}$exo$::jsonb),
  ('d16dc2d7-40f8-5d2b-a388-3a6d8f725b7d'::uuid, 3, 'redaction', $exo${"titre":"Trois questions d'examinateur sur un même texte","consigne":"Réponds à chaque question comme à l'oral, en appliquant la méthode complète, étape d'interprétation comprise.","enonce":"**Texte (inventé pour l'exercice)** — un père parle à son fils qui va partir.\n\n> Je ne te demande rien. Pars, puisque tu le veux. Mais sais-tu seulement ce que tu quittes ? Je voudrais que tu reviennes, un jour, si la ville ne te garde pas.\n\n1. « **Analysez la négation** » dans « Je ne te demande rien ».\n2. « **Transformez cette phrase interrogative** » : mets « sais-tu seulement ce que tu quittes ? » au discours indirect, avec « Il lui demanda… ». Justifie chaque changement.\n3. « **Quel est le mode employé, et pourquoi ?** » dans « Je voudrais que tu reviennes ».\n4. « **Analysez la phrase suivante** » : « Pars, puisque tu le veux. »\n5. Pour chacune des quatre réponses, ajoute l'**interprétation** qui relie la grammaire au sens du texte.","bareme":[{"critere":"Négation « ne… rien » : portée et effet dans l'aveu du père","points":4},{"critere":"Transformation juste (s'il savait seulement ce qu'il quittait) avec disparition de l'inversion, « si », concordance et personnes","points":4},{"critere":"Subjonctif dans la complétive COD de « voudrais », verbe de volonté","points":4},{"critere":"Deux propositions : principale à l'impératif, circonstancielle de cause « puisque », indicatif","points":4},{"critere":"Interprétations pertinentes pour chaque réponse","points":4}],"dureeMin":20,"corrige":"1. « ne… rien » : négation à deux termes ; « rien » porte sur le complément (le père ne demande **aucune chose**). Interprétation : il se refuse à retenir son fils, mais cette négation absolue est aussi une **pudeur** : il ne dit pas ce qu'il voudrait — ce que la dernière phrase révélera.\n2. « Il lui demanda **s'il savait seulement ce qu'il quittait**. » Changements : plus de **point d'interrogation** ni d'**inversion** (« sais-tu » → « il savait ») ; une interrogation totale est introduite par « **si** » ; « ce que tu quittes » garde « ce que » ; le verbe introducteur au passé impose l'**imparfait** et les personnes changent (tu → il). La subordonnée est une **interrogative indirecte**, COD de « demanda ». Interprétation : au direct, la question est une question **rhétorique** chargée de reproche (tu ne le sais pas) ; à l'indirect, la voix du père est effacée et le reproche perd sa force.\n3. [que tu reviennes] est une subordonnée **conjonctive complétive**, **COD** de « voudrais ». Mode : **subjonctif**, car elle dépend d'un verbe de **volonté**. Interprétation : le retour n'est pas un fait mais un **désir**, dont rien ne garantit la réalisation ; le mode dit l'incertitude du père.\n4. Deux verbes conjugués (pars, veux) : deux propositions. [Pars] est la **principale**, à l'**impératif**, sujet sous-entendu. [puisque tu le veux] est une subordonnée **circonstancielle de cause**, introduite par « puisque », à l'**indicatif**. Interprétation : le père accepte en donnant l'ordre de partir, mais la cause présente la décision comme **celle du fils** : il ne la partage pas.\n5. Ensemble : négation, question rhétorique et subjonctif montrent un père qui dit renoncer mais laisse entendre, par la grammaire même, qu'il espère le retour."}$exo$::jsonb),
  ('9d4097ae-07e6-5820-b3be-74ab409c3761'::uuid, 1, 'redaction', $exo${"titre":"Nature et fonction","consigne":"Donne la fonction de chaque mot ou groupe en gras, avec le test qui la justifie.","enonce":"1. Explique la différence entre la **nature** et la **fonction** d'un mot.\n2. Donne la fonction de chaque élément en gras :\n   - a. **Le chat** dort.\n   - b. Il mange **une pomme**.\n   - c. Elle parle **à son frère**.\n   - d. Ce chemin semble **dangereux**.\n   - e. **Le soir**, nous lisons.\n   - f. Une nuit **noire** tombait.\n   - g. Paris, **capitale de la France**, est très visitée.\n   - h. Le livre **de Pierre** est sur la table.","bareme":[{"critere":"Nature = ce qu'un mot est ; fonction = rôle dans la phrase ; un mot change de fonction, jamais de nature","points":4},{"critere":"Huit fonctions justes (sujet, COD, COI, attribut du sujet, CC de temps, épithète, apposition, complément du nom)","points":16}],"dureeMin":8,"corrige":"1. La **nature** est ce qu'un mot **est** (nom, adjectif, verbe…) : une classe grammaticale fixe. La **fonction** est le **rôle** qu'il joue dans la phrase. Un même mot **change de fonction**, **jamais de nature**.\n2. a. **Sujet** de « dort » (c'est le chat qui dort).\n   b. **COD** de « mange » (il mange quoi ? une pomme, sans préposition).\n   c. **COI** de « parle » (à qui ? avec préposition).\n   d. **Attribut du sujet** « ce chemin », après le verbe d'état « semble ».\n   e. **Complément circonstanciel de temps** : déplaçable et supprimable.\n   f. **Épithète** de « nuit » : adjectif accolé au nom, sans verbe.\n   g. **Apposition** à « Paris » : détachée par des virgules, elle désigne la même réalité.\n   h. **Complément du nom** « livre », introduit par la préposition « de »."}$exo$::jsonb),
  ('9d4097ae-07e6-5820-b3be-74ab409c3761'::uuid, 2, 'redaction', $exo${"titre":"Épithète, attribut, apposition","consigne":"Justifie chaque réponse par un test ou une règle du cours.","enonce":"1. Donne la fonction de l'adjectif « **heureuse** » dans chaque phrase et justifie :\n   - a. Une femme heureuse chantait.\n   - b. Cette femme est heureuse.\n   - c. Heureuse, la femme chantait.\n   - d. Cette femme paraît heureuse.\n2. Dans « Il pense **à son avenir** » et « Il prépare **son avenir** », quelle est la fonction de chaque groupe en gras ? Quel test fait la différence ?\n3. Le même mot « **matin** » a-t-il la même fonction dans « Le matin est calme » et « Il part le matin » ? Qu'est-ce que cela montre ?","bareme":[{"critere":"a épithète, b et d attribut du sujet (verbes d'état), c apposition (détachée)","points":8},{"critere":"COI (préposition « à ») / COD (sans préposition) avec le test des questions","points":6},{"critere":"Sujet / CC de temps : même nature (nom), fonctions différentes","points":6}],"dureeMin":10,"corrige":"1. a. **Épithète** de « femme » : adjectif accolé au nom, **pas de verbe d'état**.\n   b. **Attribut du sujet** : après le verbe d'état « **est** » ; on ne peut pas le supprimer sans changer le sens.\n   c. **Apposition** à « la femme » : l'adjectif est **détaché par une virgule** et se rapporte à la même réalité.\n   d. **Attribut du sujet** : « **paraître** » est un verbe d'état.\n2. « à son avenir » : **COI** de « pense » — on pose « **à quoi** ? », le complément est introduit par une **préposition**. « son avenir » : **COD** de « prépare » — on pose « **quoi** ? » après le verbe, **sans préposition**.\n3. Non. Dans « Le matin est calme », « matin » est **sujet** de « est ». Dans « Il part le matin », « le matin » est **complément circonstanciel de temps** (déplaçable : « Le matin, il part »). Le mot reste un **nom** : sa **nature** ne change pas, sa **fonction**, si."}$exo$::jsonb),
  ('9d4097ae-07e6-5820-b3be-74ab409c3761'::uuid, 3, 'redaction', $exo${"titre":"Ce que les fonctions font au style","consigne":"Analyse les fonctions demandées, puis interprète leur effet dans le texte.","enonce":"**Texte (inventé pour l'exercice)**\n\n> Au bout de la jetée, dans la lumière grise de l'aube, se tenait une silhouette. C'était Anna, la fille du gardien, immobile, trempée, silencieuse. Elle regardait la mer froide et lointaine. La mer restait muette.\n\n1. Donne la fonction de : a. « Au bout de la jetée » ; b. « dans la lumière grise de l'aube » ; c. « une silhouette » ; d. « la fille du gardien » ; e. « immobile, trempée, silencieuse » ; f. « froide et lointaine » ; g. « muette ».\n2. Dans la première phrase, que remarques-tu sur la **place** des compléments circonstanciels et du sujet ?\n3. Montre la différence de fonction entre « froide et lointaine » et « muette ». Quel test l'établit ?\n4. **Interprétation** : quels effets produisent les compléments circonstanciels en tête, l'apposition et la série d'adjectifs détachés ? Montre que la grammaire décrit ici ce que fait le style.","bareme":[{"critere":"Sept fonctions justes (CC de lieu, CC du cadre, sujet inversé, apposition, appositions, épithètes, attribut du sujet)","points":7},{"critere":"CC en tête et sujet placé après le verbe, en fin de phrase","points":3},{"critere":"Épithètes accolées sans verbe / attribut après le verbe d'état « restait »","points":3},{"critere":"Interprétation : cadre installé avant l'action, mise en relief et ralentissement par l'apposition, portrait par accumulation","points":5},{"critere":"Précision du métalangage","points":2}],"dureeMin":18,"corrige":"1. a. **Complément circonstanciel de lieu** de « se tenait ». b. **Complément circonstanciel** de « se tenait » : il précise le cadre (la lumière et le moment de l'aube ; on accepte temps, lieu ou manière si c'est justifié) ; il est déplaçable et supprimable. c. **Sujet** de « se tenait », **inversé**. d. **Apposition** à « Anna » : détachée par une virgule, elle désigne la même personne. e. Adjectifs **en apposition** à « Anna » (détachés par des virgules). f. **Épithètes** de « mer », accolées au nom sans verbe d'état. g. **Attribut du sujet** « la mer », après le verbe d'état « **restait** ».\n2. Les deux compléments circonstanciels sont placés **en tête** de phrase ; le verbe vient ensuite et le **sujet**, « une silhouette », est rejeté **à la fin**, après le verbe.\n3. « froide et lointaine » sont **épithètes** : accolés au nom « mer », **sans verbe**. « muette » est **attribut du sujet** : il suit le verbe d'état « restait » ; on ne peut pas le supprimer (« La mer restait » n'a plus le même sens).\n4. Les **compléments circonstanciels en tête** **installent un cadre** (lieu, lumière) **avant l'action** : le lecteur découvre le décor, puis seulement la silhouette, qui apparaît en fin de phrase comme on la distinguerait dans la brume. L'**apposition** « la fille du gardien » et les trois adjectifs détachés **ralentissent** la phrase et **mettent en relief** le personnage : le portrait se construit par **accumulation**, sans action. Les épithètes de la mer et l'attribut « muette » font de la mer un personnage fermé, qui ne répond pas. Nommer les fonctions permet ainsi de **décrire ce que le style fait** : poser un décor, retarder l'apparition, figer une attente."}$exo$::jsonb),
  ('2de5a0dc-2104-526b-877b-6a5959161c61'::uuid, 1, 'redaction', $exo${"titre":"Situer Le Chevalier de la charrette","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. Qui a écrit *Le Chevalier de la charrette*, vers quelle date, et pour qui ? Explique ce que cette personne a fourni à l'auteur, d'après le prologue.\n2. Sous quelle **forme** le roman est-il écrit, et comment était-il reçu par son public ?\n3. Que signifie d'abord le mot « **roman** » au Moyen Âge ?\n4. Résume en deux phrases l'**enlèvement** qui lance l'intrigue : qui enlève qui, et où ?\n5. Qui a achevé le roman ?","bareme":[{"critere":"Chrétien de Troyes, entre 1177 et 1181 environ, pour Marie de Champagne qui fournit la matière et le sen","points":6},{"critere":"Environ 7 000 octosyllabes à rimes plates, destinés à être lus à voix haute","points":4},{"critere":"Roman = récit en langue romane (le français) et non en latin","points":3},{"critere":"Méléagant, fils de Bademagu, enlève Guenièvre au royaume de Gorre, d'où nul ne revient ; achèvement par Godefroi de Leigni","points":7}],"dureeMin":8,"corrige":"1. Le roman est écrit par **Chrétien de Troyes**, clerc lettré de Champagne, **entre 1177 et 1181 environ**. Il répond à une **commande** de **Marie de Champagne**, fille d'Aliénor d'Aquitaine : selon le prologue, elle lui a donné la **matière** (l'histoire) et le **sen** (le sens) ; lui y a mis son travail.\n\n2. Le roman compte **environ 7 000 octosyllabes à rimes plates**. Il était destiné à être **lu à voix haute**, devant une cour.\n\n3. Au Moyen Âge, un « roman » est d'abord un récit écrit en **langue romane**, c'est-à-dire en **français**, et **non en latin**, la langue des clercs.\n\n4. **Méléagant**, fils du roi **Bademagu**, défie la cour d'Arthur et **enlève la reine Guenièvre**. Il l'emmène au **royaume de Gorre**, **d'où nul ne revient**.\n\n5. Chrétien laisse l'achèvement à un autre clerc, **Godefroi de Leigni**, qui l'annonce dans les derniers vers."}$exo$::jsonb),
  ('2de5a0dc-2104-526b-877b-6a5959161c61'::uuid, 2, 'redaction', $exo${"titre":"Deux pas avant la charrette","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour le sujet, à la manière d'une traduction en prose du roman)**\n\n> Le chevalier allait à pied, car il avait perdu son cheval. Il rejoignit une charrette que menait un nain et lui demanda s'il avait vu passer la reine. « Monte, répondit le nain, et demain tu sauras ce qu'elle est devenue. » Le chevalier s'arrêta. Il savait qu'on promenait dans ces charrettes les voleurs et les meurtriers, et que celui qui y montait perdait pour toujours son honneur. Il fit deux pas sans monter. Puis il sauta dans la charrette, sans plus rien regarder que la route devant lui.\n\n1. Situe ce passage dans l'intrigue : que s'est-il passé avant, et que cherche le chevalier ?\n2. Pourquoi monter dans la charrette est-il une **honte** ? Cite le texte.\n3. Relève la phrase qui marque l'**hésitation**. Quelle conséquence aura-t-elle plus tard dans le roman ?\n4. Le héros n'est pas nommé : pourquoi ce choix est-il important dans l'œuvre ? Quand apprend-on son nom ?","bareme":[{"critere":"Situation : après l'enlèvement de Guenièvre par Méléagant, chevalier sans nom qui a perdu son cheval et cherche des nouvelles de la reine","points":5},{"critere":"Honte expliquée avec citation : charrette d'infamie réservée aux condamnés, perte de l'honneur","points":5},{"critere":"« Il fit deux pas sans monter » relevé ; reproche de Guenièvre et accueil glacé","points":5},{"critere":"Anonymat expliqué (il se reconnaît à ses actes) ; nom révélé au milieu du roman, pendant le combat contre Méléagant","points":5}],"dureeMin":12,"corrige":"1. Le passage suit l'**enlèvement de la reine Guenièvre** par **Méléagant**, qui l'a emmenée au royaume de Gorre. Un **chevalier sans nom**, qui a **perdu son cheval**, poursuit la reine : il veut **avoir des nouvelles d'elle**, et le nain lui en promet s'il monte.\n\n2. La charrette est une **charrette d'infamie**, **réservée aux condamnés** : « on promenait dans ces charrettes les voleurs et les meurtriers ». Y monter, c'est être traité en criminel : « celui qui y montait perdait pour toujours son honneur ». Pour un chevalier, dont toute la valeur tient à l'honneur, c'est la pire humiliation.\n\n3. « **Il fit deux pas sans monter.** » C'est l'hésitation, **l'espace de deux pas**, entre l'honneur et l'amour. Plus tard, Guenièvre réserve au chevalier un **accueil glacé** et lui **reproche ces deux pas d'hésitation** : aux yeux de la dame, l'amour n'aurait pas dû hésiter une seconde.\n\n4. Le héros reste **sans nom** : il se fait **reconnaître par ses actes** avant de l'être par son nom. Le lecteur le découvre par ce qu'il accepte et accomplit pour la reine. Son nom, **Lancelot du Lac**, n'est révélé qu'**au milieu du roman**, **pendant le combat contre Méléagant**, quand une jeune fille le demande à la reine.\n\nValoriser : l'idée que la **honte acceptée** ouvre le **chemin d'initiation** (plus il s'humilie par amour, plus il devient invincible)."}$exo$::jsonb),
  ('2de5a0dc-2104-526b-877b-6a5959161c61'::uuid, 3, 'redaction', $exo${"titre":"Plus il s'humilie, plus il est invincible","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, organisé et appuyé sur des épisodes précis de l'œuvre.","enonce":"**Phrase à expliquer**\n\n> « L'ordre du récit est un chemin d'initiation : plus Lancelot s'humilie par amour, plus il devient invincible. »\n\nDans un paragraphe argumenté d'une vingtaine de lignes, **explique et illustre** cette phrase. Tu t'appuieras :\n- sur **au moins trois épisodes** du roman (humiliations et épreuves) ;\n- sur la comparaison de Lancelot avec **deux autres personnages** (Gauvain, Méléagant, Keu ou Bademagu) ;\n- sur la place de la **révélation du nom** dans le récit.","bareme":[{"critere":"Idée d'initiation expliquée : l'humiliation acceptée par amour conduit à la victoire","points":5},{"critere":"Trois épisodes exacts et commentés (charrette, épreuves, Pont de l'Épée, tournoi au pire puis au mieux, victoire sur Méléagant)","points":6},{"critere":"Comparaison juste avec deux personnages (Gauvain non amoureux qui échoue, Méléagant contre-modèle, Keu vantard, Bademagu loyal)","points":5},{"critere":"Place du nom au milieu du roman expliquée ; paragraphe organisé et bien rédigé","points":4}],"dureeMin":20,"corrige":"Éléments attendus pour un paragraphe organisé :\n\n**L'idée.** Le roman suit un **chemin d'initiation** : Lancelot accepte l'humiliation par amour pour Guenièvre, et chaque abaissement le rend plus fort. Sa force ne vient pas de son rang ou de son nom, mais de sa **soumission totale à sa dame**.\n\n**Les épisodes.**\n- **La charrette** : il accepte de monter dans la **charrette d'infamie** réservée aux condamnés, après avoir **hésité l'espace de deux pas** ; il perd son honneur aux yeux du monde, mais c'est ce geste qui le met sur la route de la reine.\n- **Les épreuves** : le **lit périlleux**, le **gué défendu**, la **dalle du cimetière** qu'il est **seul à soulever**.\n- **Le Pont de l'Épée** : il traverse la lame **mains et pieds nus** et s'y blesse : la souffrance acceptée lui ouvre le royaume de Gorre.\n- **Le tournoi** : sur ordre de la reine, il combat **« au pire »** et se couvre de honte, puis **« au mieux »** et **triomphe** : l'épisode résume tout le roman.\n- **La fin** : délivré de sa tour par la **sœur de Méléagant**, il revient à la cour et **tue Méléagant** en combat singulier.\n\n**Les autres personnages.** **Gauvain**, neveu d'Arthur, est un chevalier parfait mais **pas amoureux** : il choisit le **Pont sous l'eau** et **échoue** là où Lancelot réussit. **Méléagant**, orgueilleux et sans loyauté, est le **contre-modèle** : il ne s'humilie jamais et finit vaincu. **Keu**, le sénéchal **vantard**, est vaincu dès le début. **Bademagu**, roi sage et loyal, montre que la vraie noblesse est la loyauté.\n\n**Le nom.** Le héros n'est nommé qu'**au milieu du roman**, pendant le combat contre Méléagant : il a d'abord dû **se faire reconnaître par ses actes**. Le nom vient **récompenser** le parcours, comme une étape de l'initiation.\n\n**Conclusion possible.** L'humiliation n'est pas une faiblesse : elle est la **preuve** de l'amour, et l'amour est la **source de la prouesse**."}$exo$::jsonb),
  ('a59f559e-cc8e-568b-9d19-4fa841c8e4bd'::uuid, 1, 'redaction', $exo${"titre":"Le code de la fin'amor","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. Qu'est-ce que la **fin'amor** ? Qui l'a chantée d'abord, et qu'en fait Chrétien de Troyes ?\n2. Cite **quatre règles** de l'amour courtois et illustre chacune par un élément précis du *Chevalier de la charrette*.\n3. Le parcours s'intitule « le roman et l'**invention** de l'amour ». Explique les **deux sens** du mot « invention » ici.","bareme":[{"critere":"Fin'amor définie (amour raffiné), troubadours du Midi, transposée par Chrétien dans le récit","points":5},{"critere":"Quatre règles exactes illustrées par l'œuvre (dame supérieure, épreuves, secret, amour qui ennoblit, adultère)","points":10},{"critere":"Deux sens d'« invention » : l'amour trouve ses règles, le roman découvre qu'il peut en faire son sujet","points":5}],"dureeMin":8,"corrige":"1. La **fin'amor** est l'amour **« raffiné »** chanté par les **troubadours du Midi**. Chrétien de Troyes la **transporte dans le récit** : l'amour devient le **sujet d'un roman**.\n\n2. Règles (quatre parmi) :\n- La dame est **supérieure** à l'amant : Guenièvre est **reine**, Lancelot la **sert** comme un vassal son seigneur.\n- L'amour passe par des **épreuves** : la charrette, le Pont de l'Épée, le tournoi.\n- L'amour doit rester **secret** : la nuit d'amour est cachée ; le sang sur les draps trahit, mais c'est **Keu** qu'on accuse.\n- L'amour **ennoblit** : il rend Lancelot **meilleur chevalier que tous**.\n- L'amour est souvent **adultère** : la reine est l'**épouse d'Arthur**.\n\n3. « Invention » a deux sens : l'amour **trouve ses règles** (service, attente, épreuve, secret) ; et le roman **découvre** qu'il peut **faire de l'amour son sujet**. Ces règles nourrissent le roman sentimental **jusqu'à aujourd'hui**."}$exo$::jsonb),
  ('a59f559e-cc8e-568b-9d19-4fa841c8e4bd'::uuid, 2, 'redaction', $exo${"titre":"Le peigne de la reine","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour le sujet, à la manière d'une traduction en prose du roman)**\n\n> Au bord d'une fontaine, le chevalier aperçut un peigne oublié sur une pierre. Entre ses dents restaient quelques cheveux d'or. La demoiselle qui l'accompagnait lui apprit qu'ils étaient ceux de la reine. Alors il pâlit, et il serait tombé de cheval si elle ne l'avait retenu. Il ôta les cheveux du peigne, un à un, avec plus de respect qu'un pèlerin n'en montre devant les reliques d'un saint, et il les cacha contre sa poitrine, entre sa chemise et son cœur. Je ne vous dirai pas combien de fois il les baisa : vous me prendriez pour un menteur.\n\n1. Quelles **règles de l'amour courtois** ce passage met-il en scène ? Appuie-toi sur deux éléments du texte.\n2. Analyse la comparaison avec les **reliques** : que devient l'amour pour Lancelot ?\n3. Relève la dernière phrase. Qui parle, à qui ? Quel trait de l'écriture du roman y reconnais-tu, et quel est son effet ?\n4. Un lecteur d'aujourd'hui peut-il trouver ce passage excessif ? Réponds en quelques lignes.","bareme":[{"critere":"Règles courtoises repérées et citées (dame supérieure et vénérée, amour qui fait souffrir, secret du geste caché)","points":5},{"critere":"Comparaison analysée : l'amour devient une religion, la dame est vénérée comme une sainte","points":5},{"critere":"Narrateur qui intervient et s'adresse à son public ; effet de connivence, d'humour, lecture à voix haute","points":6},{"critere":"Réponse personnelle nuancée : sommet de l'amour ou excès, parfois avec humour","points":4}],"dureeMin":12,"corrige":"1. Le passage montre la **supériorité de la dame** : la simple vue de ses cheveux fait **pâlir** le chevalier, qui « serait tombé de cheval » ; il la vénère de loin. Il montre aussi le **secret** : il **cache** les cheveux « contre sa poitrine, entre sa chemise et son cœur ». L'amour agit sur le corps comme une **épreuve** : il fait défaillir le héros.\n\n2. En comparant son geste au respect d'un pèlerin devant les **reliques d'un saint**, le texte fait de l'amour une **religion** : la reine est vénérée comme une sainte, ses cheveux deviennent des objets sacrés. C'est l'épisode du **peigne**, où l'amour se transforme en culte.\n\n3. « Je ne vous dirai pas combien de fois il les baisa : vous me prendriez pour un menteur. » C'est le **narrateur** qui parle, et il s'adresse **à son public** (« vous »). Le conteur **commente** et **s'excuse de ne pas tout dire** : c'est un trait du roman, fait pour une **lecture à voix haute** devant une cour. Effet : **connivence** avec l'auditoire, **humour** discret qui souligne l'excès de la passion tout en la célébrant.\n\n4. Réponse personnelle attendue et nuancée : un lecteur moderne peut trouver **excessive** cette adoration (un chevalier qui défaille pour des cheveux) ; mais le roman lui-même y met une pointe d'**humour** par la voix du narrateur. On peut y lire un **sommet** de l'amour courtois ou une **limite** : c'est la question que pose aussi le tournoi « au pire »."}$exo$::jsonb),
  ('a59f559e-cc8e-568b-9d19-4fa841c8e4bd'::uuid, 3, 'redaction', $exo${"titre":"L'amour rend-il Lancelot meilleur ou esclave ?","consigne":"Rédige l'introduction complète puis le plan détaillé d'une dissertation (deux ou trois parties, deux arguments illustrés par partie).","enonce":"**Sujet de dissertation**\n\n> Dans *Le Chevalier de la charrette*, l'amour rend-il Lancelot **meilleur** ou **esclave** ?\n\n1. Rédige une **introduction** complète : amorce, présentation de l'œuvre et du parcours, reformulation du sujet et **problématique**, annonce du plan.\n2. Rédige le **plan détaillé** : deux ou trois parties, chacune avec deux arguments, chaque argument illustré par un **épisode précis** de l'œuvre.\n3. Rédige une phrase de **conclusion** qui répond clairement à la question.","bareme":[{"critere":"Introduction complète : amorce, œuvre et parcours situés, problématique qui fait tension, annonce du plan","points":5},{"critere":"Partie sur l'amour qui ennoblit, arguments illustrés par des épisodes exacts","points":5},{"critere":"Partie sur la soumission et la perte de liberté, arguments illustrés (charrette, tournoi au pire, reproche des deux pas)","points":5},{"critere":"Dépassement ou nuance (intériorité, humour du narrateur, héros d'un genre nouveau) et conclusion nette","points":5}],"dureeMin":20,"corrige":"**1. Introduction possible.**\n*Amorce* : depuis les troubadours, l'amour est chanté comme un service rendu à une dame. *Présentation* : vers 1180, **Chrétien de Troyes** écrit pour **Marie de Champagne** *Le Chevalier de la charrette*, où **Lancelot** se soumet entièrement à la reine **Guenièvre** ; l'œuvre s'inscrit dans le parcours **« le roman et l'invention de l'amour »**. *Problématique* : cet amour, qui fait du héros le meilleur des chevaliers, ne le prive-t-il pas aussi de sa liberté ? *Annonce* : nous verrons que l'amour grandit Lancelot, puis qu'il l'asservit, avant de montrer que cette tension fait de lui un héros d'un genre nouveau.\n\n**2. Plan détaillé.**\n**I. L'amour rend Lancelot meilleur.**\n- L'amour **ennoblit** et donne la prouesse : Lancelot réussit les épreuves (lit périlleux, dalle du cimetière, **Pont de l'Épée**) là où **Gauvain**, qui n'est pas amoureux, échoue.\n- L'amour donne la force de tout supporter : blessé sur le Pont de l'Épée, il avance par **foi dans l'amour** ; il **triomphe** au tournoi « au mieux » et **tue Méléagant**.\n\n**II. Mais l'amour fait de lui un esclave.**\n- Il perd son honneur social : il monte dans la **charrette d'infamie** ; **Raison** conseille de refuser, **Amour** l'ordonne.\n- Il obéit sans limite : au tournoi, il combat **« au pire »** et se couvre de honte sur un simple ordre ; la reine lui reproche **deux pas d'hésitation** et le reçoit froidement. Il sert sa dame **comme un vassal** son seigneur.\n\n**III. Un héros nouveau, libre dans sa soumission.**\n- La soumission est **choisie** : le **débat intérieur** Raison/Amour montre une **conscience** ; le chevalier doute, hésite, souffre — il a une **intériorité**.\n- Le roman garde une distance : le **narrateur** commente, parfois avec **humour** ; la soumission peut se lire comme un sommet ou comme une limite.\n\n**3. Conclusion possible.** L'amour rend Lancelot à la fois **meilleur et esclave** : il gagne la prouesse en perdant sa liberté, et c'est ce paradoxe, voulu, qui fait naître le héros de roman.\n\nAccepter tout plan cohérent en deux parties (meilleur / esclave) avec une conclusion nuancée."}$exo$::jsonb),
  ('76478891-1853-5caf-94b3-d058e678f570'::uuid, 1, 'redaction', $exo${"titre":"Situer Pot-Bouille","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. En quelle année paraît *Pot-Bouille* ? À quel cycle appartient-il, et quel est le sous-titre de ce cycle ? Quel rang y occupe le roman ?\n2. De quel mouvement **Zola** est-il le chef de file ? Quel texte théorique a-t-il écrit, et en quelle année ?\n3. Que signifie le titre « **pot-bouille** », et que veut montrer Zola en le choisissant ?\n4. Où se déroule l'essentiel du roman ?\n5. Que devient **Octave Mouret** dans le roman suivant du cycle ?","bareme":[{"critere":"1882, Les Rougon-Macquart, « histoire naturelle et sociale d'une famille sous le Second Empire », dixième volume","points":6},{"critere":"Naturalisme, Le Roman expérimental (1880)","points":4},{"critere":"Titre expliqué : la cuisine ordinaire du ménage, l'envers de la vie domestique","points":4},{"critere":"Immeuble neuf de la rue de Choiseul à Paris ; Octave patron d'Au Bonheur des Dames (1883)","points":6}],"dureeMin":7,"corrige":"1. *Pot-Bouille* paraît en **1882**. C'est le **dixième volume** des ***Rougon-Macquart***, l'**« histoire naturelle et sociale d'une famille sous le Second Empire »**, que Zola écrit en vingt romans ; chaque roman explore un **milieu** — ici, la **bourgeoisie**.\n\n2. Zola (1840-1902) est le chef de file du **naturalisme** ; il a théorisé le **roman expérimental** en **1880**.\n\n3. « Pot-bouille », c'est la **cuisine ordinaire du ménage**, le **quotidien du foyer**. Par ce titre, Zola annonce qu'il va montrer **l'envers** de la vie domestique bourgeoise.\n\n4. L'essentiel du roman se déroule dans un **immeuble neuf de la rue de Choiseul**, à **Paris**, avec ses étages, ses locataires et ses domestiques.\n\n5. Octave Mouret deviendra le **patron d'*Au Bonheur des Dames*** (1883)."}$exo$::jsonb),
  ('76478891-1853-5caf-94b3-d058e678f570'::uuid, 2, 'redaction', $exo${"titre":"Le salon Josserand","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour le sujet, à la manière de Zola)**\n\n> Au salon, Mme Josserand poussa sa fille vers le jeune Vabre. « Souris donc, souffla-t-elle, et parle-lui de musique. » Berthe sourit, et parla de musique, qu'elle n'aimait pas. Dans un coin, M. Josserand regardait sa fille sans rien dire ; il pensait aux copies qu'il ferait encore cette nuit, sous la lampe, pour payer la robe neuve. Sur le palier, M. Gourd, raide dans sa redingote, veillait à ce que personne ne fît de bruit : la maison était une maison honnête.\n\n1. Présente les quatre personnages du passage et ce que chacun **représente** dans le roman.\n2. Quel « **marché** » se joue dans ce salon ? Que deviendra, dans l'intrigue, le projet de Mme Josserand, et comment tournera ce mariage ?\n3. Relis la dernière phrase. Qu'est-ce qu'elle révèle du rôle de M. Gourd et de l'immeuble ?","bareme":[{"critere":"Quatre personnages présentés avec justesse (mère qui chasse le mari, fille élevée pour paraître, père honnête épuisé, concierge gardien de la respectabilité)","points":8},{"critere":"Marché au mariage expliqué ; Berthe épouse Auguste Vabre puis devient la maîtresse d'Octave, scandale étouffé","points":6},{"critere":"Dernière phrase analysée : la façade respectable, un gardien qui surveille tout et ne voit rien de ce qui compte","points":6}],"dureeMin":12,"corrige":"1. - **Mme Josserand** : la mère qui **chasse le mari** pour ses filles, faute de fortune ; elle pousse Berthe et lui dicte son attitude (« Souris donc »).\n- **Berthe** : **élevée pour se vendre au mariage**, elle ne sait que **paraître** : elle parle d'une musique « qu'elle n'aimait pas ».\n- **M. Josserand** : le **père honnête**, qui **s'épuise la nuit à des travaux de copie** pour **tenir le rang** (« pour payer la robe neuve ») ; il se tait.\n- **M. Gourd** : le **concierge**, **gardien de la respectabilité** de la maison.\n\n2. Le salon est un **marché au mariage** : la fille est présentée comme une marchandise, la mère négocie, le père paie. Le projet réussit : **Berthe épouse Auguste Vabre**. Mais le mariage tourne mal : Berthe devient la **maîtresse d'Octave Mouret** ; le mari les surprend : **scandale**, menace de duel, **étouffé**.\n\n3. « La maison était une maison honnête » : M. Gourd veille au **bruit**, c'est-à-dire aux **apparences**, pas à la morale. Il **surveille tout** mais **ne voit rien de ce qui compte** : les calculs du salon lui échappent. La phrase montre la **façade** respectable de l'immeuble, derrière laquelle se cachent l'argent et les mensonges ; elle annonce la fin, où l'immeuble retrouve sa façade **comme si rien ne s'était passé**."}$exo$::jsonb),
  ('76478891-1853-5caf-94b3-d058e678f570'::uuid, 3, 'redaction', $exo${"titre":"L'immeuble, personnage principal","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, organisé et appuyé sur des éléments précis de l'œuvre.","enonce":"**Phrase à discuter**\n\n> « Le personnage principal n'est pas Octave : c'est l'immeuble. »\n\nDans un paragraphe argumenté d'une vingtaine de lignes, montre en quoi cette affirmation se justifie. Tu t'appuieras :\n- sur le **rôle d'Octave Mouret** (ce qu'il cherche, ce qu'il réussit, ce qu'il permet au lecteur) ;\n- sur **au moins quatre autres personnages** de l'immeuble et ce qu'ils représentent ;\n- sur la **construction de l'intrigue**, jusqu'à la fin du roman.","bareme":[{"critere":"Rôle d'Octave nuancé : ambitieux qui réussit par les femmes, mais surtout regard qui fait découvrir l'immeuble","points":5},{"critere":"Quatre personnages exacts et ce qu'ils représentent (Josserand, Berthe, Duveyrier, Campardon, Gourd, Mauduit, les bonnes)","points":6},{"critere":"Intrigue en fils multiples (mariage, adultère, héritage Vabre, drame d'Adèle) et fin où la façade se referme","points":5},{"critere":"Paragraphe organisé, conclusion sur l'immeuble comme organisme et image de la bourgeoisie","points":4}],"dureeMin":20,"corrige":"Éléments attendus :\n\n**Octave, un fil parmi d'autres.** **Octave Mouret**, vingt-deux ans, arrive de Plassans et veut **réussir par les femmes**. Il échoue auprès de Valérie et de Mme Hédouin, séduit **Marie Pichon**, devient l'amant de **Berthe**, et finit par **épouser Mme Hédouin**, devenue veuve. Mais il sert surtout de **regard** : le lecteur découvre la maison avec lui, comme un nouveau venu.\n\n**Tout un immeuble de personnages.** Chaque étage cache une histoire : **Mme Josserand** chasse le mari pour ses filles, **M. Josserand** s'épuise en copies pour tenir le rang, **Berthe** ne sait que paraître ; **Duveyrier**, magistrat austère, entretient une maîtresse ; **Campardon** vit entre sa femme et sa cousine Gasparine ; **M. Gourd** garde la respectabilité ; l'**abbé Mauduit** sait tout et couvre tout ; les **bonnes** (Adèle, Lisa, Julie) savent tout des maîtres. Aucun ne domine : c'est l'ensemble qui compte.\n\n**Une intrigue en réseau.** Les fils s'entrecroisent dans le même lieu : le **mariage** de Berthe et d'Auguste Vabre, l'**adultère** et son scandale étouffé, l'**héritage** du vieux Vabre qui déchire la famille — et se révèle bien moindre que prévu —, le **drame caché** d'**Adèle**, qui accouche seule sous les toits et abandonne l'enfant. À la **fin**, l'immeuble retrouve sa **façade** respectable, **comme si rien ne s'était passé** : c'est lui qui survit à toutes les histoires.\n\n**Conclusion.** Zola décrit l'immeuble **comme un organisme**, **étage par étage** : il concentre la bourgeoisie parisienne et en fait le vrai sujet du roman. Octave n'en est que le guide."}$exo$::jsonb),
  ('20664e53-03cd-5433-b1b0-3580f3e8a7bd'::uuid, 1, 'redaction', $exo${"titre":"Les rouages de la maison","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. Le parcours s'intitule « **dévoiler les rouages de la société** ». Explique le sens de « dévoiler » et de « rouages ».\n2. Qu'est-ce que l'immeuble **montre**, et qu'est-ce qu'il **cache** ? Donne deux oppositions.\n3. Cite les **cinq rouages** que le roman met au jour et donne pour chacun un exemple tiré de l'œuvre.","bareme":[{"critere":"Dévoiler = lever un voile ; rouages = mécanismes cachés qui font tourner la machine","points":4},{"critere":"Deux oppositions exactes (grand escalier / escalier de service et cour, salons / chambres et dettes, façade / vie réelle)","points":4},{"critere":"Cinq rouages (argent, mariage, adultère, religion, domination sociale) chacun illustré par un exemple exact","points":12}],"dureeMin":8,"corrige":"1. **Dévoiler**, c'est **lever un voile**, montrer ce qui était caché. Les **rouages** sont les **mécanismes cachés** qui font tourner une machine. Zola fait les deux : il montre l'envers de la société bourgeoise et en explique le fonctionnement.\n\n2. L'immeuble **montre** le **grand escalier** (faux marbre, tapis, chauffage, silence), les **salons** et leurs réceptions, la **façade** d'une maison « honnête ». Il **cache** l'**escalier de service** et la **cour intérieure**, les chambres, les **dettes**, les **maîtresses**, la vie réelle des locataires.\n\n3. Les cinq rouages :\n- **L'argent** : on se marie pour une dot, on se déchire pour l'**héritage du vieux Vabre**, on vit au-dessus de ses moyens pour paraître (M. Josserand et ses copies de nuit).\n- **Le mariage** : un **marché** ; **Berthe** est élevée pour plaire et marier.\n- **L'adultère** : partout et **toléré tant qu'il ne se voit pas** (Duveyrier, Campardon, Berthe et Octave).\n- **La religion** : l'**abbé Mauduit** connaît les fautes et aide à **sauver les apparences**.\n- **La domination sociale** : les **bonnes**, logées sous les toits, travaillent, souffrent et savent tout (le drame d'**Adèle**)."}$exo$::jsonb),
  ('20664e53-03cd-5433-b1b0-3580f3e8a7bd'::uuid, 2, 'redaction', $exo${"titre":"La cour des bonnes","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour le sujet, à la manière de Zola)**\n\n> Le matin, dès que les maîtres étaient sortis, les fenêtres des cuisines s'ouvraient sur la cour. Lisa criait à Julie que Madame avait encore reçu « son cousin » pendant que Monsieur était au Palais. Adèle, penchée sur son évier, riait sans bien comprendre. Une odeur d'eaux grasses montait jusqu'aux toits. Et quand, à midi, le grand escalier reprenait son silence de chapelle, avec son tapis rouge et ses portes d'acajou, on aurait juré que rien de tout cela n'existait. Ah ! c'était vraiment une maison bien tenue.\n\n1. Relève deux éléments qui appartiennent à ce que l'immeuble **cache** et deux qui appartiennent à ce qu'il **montre**. Quelle image de l'immeuble ce contraste construit-il ?\n2. Quel rôle les **bonnes** jouent-elles ici et dans l'ensemble du roman ?\n3. Analyse la dernière phrase : quel procédé reconnais-tu, qui parle, et quel est l'effet ?\n4. Quel(s) **rouage(s)** de la société ce passage dévoile-t-il ?","bareme":[{"critere":"Relevé juste (cour, cuisines, cris, eaux grasses / grand escalier, silence, tapis, acajou) et image de la façade qui cache","points":5},{"critere":"Bonnes analysées comme le vrai chœur du roman, qui crie les secrets des maîtres","points":4},{"critere":"Dernière phrase : discours indirect libre et ironie, contraste entre les grands mots et la réalité","points":7},{"critere":"Rouages identifiés (adultère toléré tant qu'il ne se voit pas, domination sociale)","points":4}],"dureeMin":12,"corrige":"1. Ce que l'immeuble **cache** : la **cour** et les **fenêtres des cuisines**, les **cris** des bonnes, les secrets (« son cousin »), « une odeur d'eaux grasses ». Ce qu'il **montre** : le **grand escalier**, son « **silence de chapelle** », le **tapis rouge**, les **portes d'acajou**. Le contraste construit l'image d'une **coupe d'immeuble** : un décor respectable devant, la vie réelle derrière ; **le décor n'est là que pour cacher**.\n\n2. Les **bonnes** **crient les secrets des maîtres** d'une fenêtre à l'autre : elles **savent tout**. Elles forment le **vrai chœur du roman**, qui commente l'action et révèle ce que la façade dissimule. Dans l'ensemble du roman, elles sont aussi les victimes de la **domination sociale** : logées sous les toits, elles travaillent et souffrent (Adèle accouchera seule).\n\n3. « Ah ! c'était vraiment une maison bien tenue. » L'exclamation fait entendre la voix des habitants, **sans guillemets ni verbe introducteur** : c'est le **discours indirect libre**. Mais placée après la cour, les eaux grasses et les adultères, la phrase est **ironique** : elle joue sur le **contraste entre les grands mots** (maison « bien tenue », honnête) **et les actes**. Le narrateur semble seulement observer, mais le **montage** de la scène est déjà un **jugement**.\n\n4. Le passage dévoile **l'adultère**, partout et **toléré tant qu'il ne se voit pas** (« Madame » et « son cousin » pendant que « Monsieur » est au Palais), et la **domination sociale** : les domestiques, reléguées à la cour, portent la vérité que les maîtres cachent."}$exo$::jsonb),
  ('20664e53-03cd-5433-b1b0-3580f3e8a7bd'::uuid, 3, 'redaction', $exo${"titre":"Le rire affaiblit-il la critique ?","consigne":"Rédige l'introduction complète puis le plan détaillé d'une dissertation (deux ou trois parties, deux arguments illustrés par partie).","enonce":"**Sujet de dissertation**\n\n> Dans *Pot-Bouille*, le rire affaiblit-il la critique de la société bourgeoise ?\n\n1. Rédige une **introduction** complète : amorce, présentation de l'œuvre et du parcours, problématique, annonce du plan.\n2. Rédige le **plan détaillé** : deux ou trois parties, deux arguments par partie, chacun illustré par un **passage ou un personnage** précis.\n3. Rédige une phrase de **conclusion** qui répond clairement à la question.","bareme":[{"critere":"Introduction complète : Zola, 1882, naturalisme, parcours « dévoiler les rouages », problématique et annonce","points":5},{"critere":"Partie qui reconnaît la part de farce et ce qu'elle pourrait adoucir, avec exemples exacts","points":5},{"critere":"Partie qui montre que le rire rend la critique plus cruelle (ironie, ridicule qui détruit les apparences), avec exemples","points":6},{"critere":"Nuance finale (le rire qui gêne, la scène d'Adèle, la fin) et conclusion nette","points":4}],"dureeMin":20,"corrige":"**1. Introduction possible.**\n*Amorce* : le roman naturaliste prétend observer la société comme un savant. *Présentation* : dans ***Pot-Bouille*** (**1882**), dixième volume des *Rougon-Macquart*, **Zola** fait de l'immeuble de la rue de Choiseul la coupe de la bourgeoisie parisienne ; l'œuvre illustre le parcours **« dévoiler les rouages de la société »**. *Problématique* : la satire, qui vire souvent à la farce, désamorce-t-elle la dénonciation ou la rend-elle plus redoutable ? *Annonce* : le rire semble d'abord adoucir la critique ; mais il la rend en réalité plus cruelle, jusqu'à nous gêner d'avoir ri.\n\n**2. Plan détaillé.**\n**I. Un rire qui paraît alléger la critique.**\n- La **satire** vire à la **farce** : le **salon Josserand**, la chasse au mari, la mère qui pousse sa fille, font sourire comme une comédie.\n- Les personnages ressemblent à des types comiques : **Duveyrier**, austère en public, avec sa maîtresse ; **M. Gourd**, qui surveille tout et ne voit rien ; le lecteur rit des hypocrites plutôt que de s'indigner.\n\n**II. En réalité, le rire rend la critique plus cruelle.**\n- L'**ironie** joue sur le **contraste entre les grands mots** (morale, honneur, famille) **et les actes** : le ridicule **détruit les apparences** mieux qu'un sermon (le **mariage de Berthe**, où la cérémonie masque les calculs ; l'**abbé Mauduit**, qui couvre tout).\n- Le **montage** des scènes et le **discours indirect libre** font entendre les personnages sans commentaire : ils se condamnent eux-mêmes. Le roman fit **scandale** : on accusa Zola de **salir la bourgeoisie** — preuve que la critique portait.\n\n**III. Un rire qui finit par gêner.**\n- **On rit, puis on est gêné d'avoir ri** : la **cour des bonnes**, drôle et crue, révèle la domination sociale ; l'**accouchement d'Adèle**, seule dans sa chambre pendant que la maison dort, est la scène la plus crue et ne fait plus rire.\n- La **fin** : tout recommence, les bonnes concluent que toutes les maisons se valent ; le rire laisse place au constat d'une société qui ne change pas.\n\n**3. Conclusion possible.** Le rire n'affaiblit pas la critique : il la rend **plus cruelle**, parce que le **ridicule détruit les apparences**, et plus efficace, parce qu'il gêne le lecteur complice.\n\nAccepter tout plan cohérent (deux parties : oui / non) avec des exemples exacts."}$exo$::jsonb),
  ('2e10827d-367a-5f04-a676-cca5b50cae1b'::uuid, 1, 'redaction', $exo${"titre":"Situer Pluie et vent sur Télumée Miracle","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. Qui a écrit *Pluie et vent sur Télumée Miracle*, et en quelle année ? Dans quel lieu et à quelle époque le roman se déroule-t-il ?\n2. Quelles sont les **deux parties** du roman et ce que chacune raconte ? Nomme les femmes de la lignée.\n3. Qui raconte, **d'où** et **à quel moment de sa vie** ? Quel type de récit est-ce ?\n4. Explique le **titre** : que désignent « pluie et vent », et pourquoi « Miracle » ?","bareme":[{"critere":"Simone Schwarz-Bart, 1972 ; Guadeloupe rurale (Fond-Zombi, canne), première moitié du XXe siècle","points":5},{"critere":"« Présentation des miens » (Minerve, Toussine / Reine Sans Nom, Victoire) et « Histoire de ma vie »","points":6},{"critere":"Télumée âgée, depuis son jardin, au soir de sa vie : récit rétrospectif à la première personne","points":5},{"critere":"Pluie et vent = les épreuves ; Miracle = surnom reçu au terme de sa vie","points":4}],"dureeMin":8,"corrige":"1. Le roman est écrit par **Simone Schwarz-Bart** (1938-2023), romancière guadeloupéenne, et paraît en **1972**. Il se déroule dans la **Guadeloupe rurale** — les mornes, les champs de **canne à sucre**, des villages comme **Fond-Zombi** — dans la **première moitié du XXe siècle**, un siècle après l'**abolition de l'esclavage** (1848).\n\n2. **« Présentation des miens »** raconte la **lignée** : l'aïeule **Minerve**, affranchie ; sa fille **Toussine**, qu'on appellera **Reine Sans Nom** ; puis **Victoire**, la mère de Télumée. **« Histoire de ma vie »** raconte la vie de **Télumée** elle-même, de l'enfance à la vieillesse.\n\n3. C'est **Télumée** qui raconte, **âgée**, **depuis son jardin**, **au soir de sa vie**. C'est un **récit rétrospectif à la première personne**.\n\n4. La **pluie et le vent** désignent les **épreuves** traversées. « **Miracle** » est le **surnom** que Télumée reçoit **au terme de sa vie**, quand elle est restée debout après tout ce qu'elle a vécu."}$exo$::jsonb),
  ('2e10827d-367a-5f04-a676-cca5b50cae1b'::uuid, 2, 'redaction', $exo${"titre":"Télumée dans son jardin","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour le sujet, à la manière du roman)**\n\n> Aujourd'hui, assise dans mon jardin, je regarde les nuages passer au-dessus du morne, et je repense à tout ce chemin. Quand j'étais petite, à Fond-Zombi, ma grand-mère Reine Sans Nom me disait qu'une femme doit être comme une barque sur la mer : la vague la soulève, la vague la couche, mais elle revient toujours droite. Man Cia, elle, me montrait les herbes qui soignent et me parlait des esprits qui rôdent la nuit. J'ai servi chez les autres, j'ai été aimée, j'ai été chassée, j'ai porté mon deuil ; et me voilà, debout.\n\n1. Qui parle, d'où et à quel moment de sa vie ? Relève **deux indices** et nomme le type de récit.\n2. Que transmettent à Télumée **Reine Sans Nom** et **Man Cia** ? Appuie-toi sur le texte et sur le cours.\n3. La phrase « J'ai servi chez les autres, j'ai été aimée, j'ai été chassée, j'ai porté mon deuil » résume une vie. Relie chacun de ces quatre moments à un **épisode du roman** et à un **personnage**.\n4. Montre que la dernière phrase éclaire le **titre** du roman.","bareme":[{"critere":"Narratrice âgée, dans son jardin, au soir de sa vie ; indices relevés ; récit rétrospectif à la première personne","points":4},{"critere":"Transmission : Reine Sans Nom apprend à tenir debout ; Man Cia transmet les plantes et les esprits","points":5},{"critere":"Quatre moments reliés à l'œuvre (servante chez les Desaragne, bonheur avec Elie, Elie qui la chasse, mort d'Amboise lors d'une grève)","points":7},{"critere":"« Me voilà, debout » relié aux épreuves (pluie et vent) et au surnom Miracle","points":4}],"dureeMin":12,"corrige":"1. C'est **Télumée**, **âgée**, qui parle **depuis son jardin**, **au soir de sa vie**. Indices : « **Aujourd'hui, assise dans mon jardin** », « je **repense** à tout ce chemin », « **Quand j'étais petite** ». C'est un **récit rétrospectif à la première personne**.\n\n2. **Reine Sans Nom**, sa grand-mère, qui l'élève à Fond-Zombi, lui apprend à **tenir debout dans le malheur** : l'image de la barque qui « revient toujours droite » dit cette force. **Man Cia**, l'amie de sa grand-mère, **femme de savoir et de mystère**, lui transmet les **secrets des plantes** (« les herbes qui soignent ») et **des esprits**.\n\n3. - « J'ai servi chez les autres » : Télumée est **servante** chez les **Desaragne**, une famille de Blancs créoles qui la méprisent.\n- « J'ai été aimée » : son premier amour, **Elie**, et une **vie heureuse** avec lui.\n- « J'ai été chassée » : Elie, **sans travail**, sombre dans l'**amertume** et la **violence**, et **la chasse**.\n- « J'ai porté mon deuil » : **Amboise**, l'homme doux et sage avec qui elle vit, **meurt lors d'une grève** des travailleurs de la canne.\n\n4. « **Et me voilà, debout.** » Les épreuves sont la **pluie et le vent** du titre ; Télumée les a traversées **sans être couchée**. C'est cette force, et sa bonté, qui lui valent le surnom de **Télumée Miracle** : une femme qui tombe et **se relève**."}$exo$::jsonb),
  ('2e10827d-367a-5f04-a676-cca5b50cae1b'::uuid, 3, 'redaction', $exo${"titre":"Une lignée de femmes debout","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, organisé et appuyé sur des éléments précis de l'œuvre.","enonce":"**Phrase à expliquer**\n\n> « Le livre tient dans une lignée de femmes debout : chacune transmet à la suivante l'art de ne pas se laisser détruire. »\n\nDans un paragraphe argumenté d'une vingtaine de lignes, **explique et illustre** cette phrase. Tu t'appuieras :\n- sur la **construction** du roman en deux parties ;\n- sur **au moins trois femmes** du roman et ce qu'elles transmettent ;\n- sur **au moins deux épreuves** de Télumée et sur la manière dont elle se relève.","bareme":[{"critere":"Construction expliquée : « Présentation des miens » avant « Histoire de ma vie », la lignée comme fondation","points":5},{"critere":"Trois femmes exactes et leur transmission (Minerve, Reine Sans Nom, Victoire, Man Cia)","points":5},{"critere":"Deux épreuves exactes de Télumée et la manière dont elle se relève (Desaragne, Elie, Amboise, Sonore, pardon)","points":6},{"critere":"Paragraphe organisé et conclusion sur la force transmise plutôt que la victime","points":4}],"dureeMin":20,"corrige":"Éléments attendus :\n\n**La construction.** Le roman s'ouvre sur **« Présentation des miens »** avant **« Histoire de ma vie »** : avant de raconter sa propre vie, Télumée présente sa **lignée**. Le livre affirme ainsi qu'on ne se tient pas debout seule : la force se **reçoit** de celles qui précèdent.\n\n**Les femmes de la lignée.** L'aïeule **Minerve**, **affranchie**, porte la mémoire de l'esclavage et de la liberté conquise. Sa fille **Toussine** devient **Reine Sans Nom** : elle incarne la **force**, la **dignité** et la **transmission** ; c'est elle qui élève Télumée à Fond-Zombi et lui apprend à **tenir debout dans le malheur**. **Victoire**, la mère, confie sa fille à la grand-mère. **Man Cia**, l'amie de Reine Sans Nom, transmet les **secrets des plantes et des esprits**.\n\n**Les épreuves et la relève.** Télumée est **servante** chez les **Desaragne**, qui la méprisent ; son premier amour, **Elie**, sombre dans l'amertume et la **violence** et la **chasse** : elle **s'effondre**, puis **se relève**. Elle vit avec **Amboise**, qui **meurt lors d'une grève** des travailleurs de la canne. Elle élève une enfant, **Sonore**, qui finit par partir. À la fin, elle **pardonne** à un homme qui lui voulait du mal : on l'appelle alors **Télumée Miracle**.\n\n**Conclusion.** Télumée est la **somme** des femmes qui l'ont précédée ; ce qu'elles lui transmettent n'est pas une richesse, mais **l'art de ne pas se laisser détruire**. C'est pourquoi le roman **célèbre une force** plutôt qu'il ne plaint une victime."}$exo$::jsonb),
  ('815518bf-d3ac-5661-a43c-b417504ea851'::uuid, 1, 'redaction', $exo${"titre":"Tisser les mémoires, habiter le monde","consigne":"Réponds à chaque question par deux ou trois phrases complètes, avec le vocabulaire du cours.","enonce":"1. Explique le sens des deux verbes du parcours, « **tisser** » et « **habiter** », appliqués au roman.\n2. Le roman fait passer **quatre mémoires**. Nomme-les et dis comment chacune se transmet.\n3. Cite **trois manières** dont Télumée « habite le monde », avec un exemple du roman pour chacune.","bareme":[{"critere":"Tisser = relier des fils (vies, générations, récits) ; habiter = trouver sa place dans un monde qui ne vous a pas été donné","points":5},{"critere":"Quatre mémoires exactes et leur transmission (esclavage, familiale, orale, du corps)","points":8},{"critere":"Trois manières d'habiter le monde illustrées (un lieu, une dignité, tenir debout, le pardon)","points":7}],"dureeMin":8,"corrige":"1. **Tisser**, c'est **relier des fils** : les vies, les générations, les récits. Le roman fait ce qu'il raconte : la première partie, sur la lignée, montre que Télumée est la **somme** des femmes qui l'ont précédée. **Habiter le monde**, c'est **trouver sa place dans un monde qui ne vous a pas été donné**.\n\n2. - La mémoire de l'**esclavage** : **Minerve**, l'aïeule, a connu l'**affranchissement** ; la **hiérarchie coloniale** survit chez les Desaragne.\n- La mémoire **familiale** : la **lignée des femmes Lougandor**, racontée avant la vie de Télumée.\n- La mémoire **orale** : les **contes**, les **proverbes**, les **chants** que Reine Sans Nom transmet le soir.\n- La mémoire **du corps** : les **gestes** du travail, des soins, des plantes.\n\n3. Trois manières parmi :\n- **Un lieu** : le jardin, la case, le morne ; la nature est un **refuge** et une force.\n- **Une dignité** : face au mépris des maîtres, Reine Sans Nom lui apprend qu'on peut être **pauvre sans être abaissé**.\n- **Tenir debout** dans la joie comme dans le malheur : l'image de la femme **droite, que le vent ne couche pas**.\n- **Le pardon** : à la fin, Télumée **accompagne jusqu'à la mort un homme qui lui voulait du mal** ; elle refuse que la haine l'emporte."}$exo$::jsonb),
  ('815518bf-d3ac-5661-a43c-b417504ea851'::uuid, 2, 'redaction', $exo${"titre":"Chez les Desaragne","consigne":"Lis le passage, puis réponds aux questions en rédigeant et en citant le texte.","enonce":"**Texte (inventé pour le sujet, à la manière du roman)**\n\n> Chez les Desaragne, je lavais, je repassais, je servais à table sans lever les yeux. Un soir, Madame posa sa tasse et dit, comme on parle du temps qu'il fait, que les gens de ma couleur n'avaient ni mémoire ni lendemain, et qu'ils vivaient au jour le jour, sans rien bâtir. Je continuai d'essuyer les verres. En moi, j'entendais la voix de Reine Sans Nom : « Derrière la montagne, il y a encore la montagne ; on ne s'assoit pas, on marche. » Ma main ne trembla pas. Ce soir-là, je sus qu'on pouvait me prendre ma peine, mais pas ma tête.\n\n1. Quelle **mémoire** survit dans les paroles de Madame Desaragne ? Montre que son propos est démenti par le roman lui-même.\n2. Comment Télumée répond-elle au mépris ? Relève deux éléments du texte et nomme l'attitude.\n3. Relève la phrase qui fait entendre la **parole transmise** par Reine Sans Nom. Quelle mémoire représente-t-elle, et quel procédé d'écriture du roman illustre-t-elle ?\n4. Quel est l'effet de la **première personne rétrospective** dans ce passage ?","bareme":[{"critere":"Hiérarchie coloniale et mémoire de l'esclavage identifiées ; propos démenti par un roman qui tisse la mémoire de la lignée","points":5},{"critere":"Dignité intérieure : geste qui continue, main qui ne tremble pas, dernière phrase relevée","points":5},{"critere":"Parole de Reine Sans Nom relevée : mémoire orale, proverbe et image, saveur de la parole","points":5},{"critere":"Effet de la première personne rétrospective (la sagesse de l'âge éclaire la jeunesse)","points":5}],"dureeMin":12,"corrige":"1. Les paroles de Madame Desaragne font entendre la **hiérarchie coloniale**, héritée de l'**esclavage** : les descendants d'esclaves y sont jugés inférieurs, sans passé ni avenir. Le roman **dément** ce propos : il **tisse les mémoires** — la lignée des femmes Lougandor, Minerve affranchie, les contes transmis — et montre que Télumée est la **somme** des femmes qui l'ont précédée. Elle a une mémoire, et elle **bâtit** une vie.\n\n2. Télumée répond par la **dignité intérieure**, non par la violence : « **Je continuai d'essuyer les verres** », « **Ma main ne trembla pas** ». La dernière phrase le dit : « on pouvait me prendre ma peine, mais pas ma tête » — on peut être **pauvre sans être abaissé**, comme le lui a appris Reine Sans Nom.\n\n3. « **Derrière la montagne, il y a encore la montagne ; on ne s'assoit pas, on marche.** » C'est la **mémoire orale** : les **proverbes** que Reine Sans Nom transmet. Le procédé illustre l'écriture du roman : **proverbes et images** qui gardent au récit la **saveur de la parole** ; l'image dit aussi l'art de **tenir debout**.\n\n4. La **première personne rétrospective** (« Ce soir-là, **je sus** ») fait parler une femme **âgée** qui se souvient : la **sagesse de l'âge éclaire** la jeune servante. Le lecteur partage l'humiliation de l'intérieur, mais aussi la leçon que la narratrice en a tirée."}$exo$::jsonb),
  ('815518bf-d3ac-5661-a43c-b417504ea851'::uuid, 3, 'redaction', $exo${"titre":"La souffrance détruit-elle l'individu ?","consigne":"Rédige l'introduction complète puis le plan détaillé d'une dissertation (deux ou trois parties, deux arguments illustrés par partie).","enonce":"**Sujet de dissertation**\n\n> *Pluie et vent sur Télumée Miracle* montre-t-il que la souffrance détruit l'individu ?\n\n1. Rédige une **introduction** complète : amorce, présentation de l'œuvre et du parcours, problématique, annonce du plan.\n2. Rédige le **plan détaillé** : deux ou trois parties, deux arguments par partie, chacun illustré par un **passage** ou un **personnage** précis.\n3. Rédige une phrase de **conclusion** qui répond clairement à la question.","bareme":[{"critere":"Introduction complète : Simone Schwarz-Bart, 1972, parcours « tisser les mémoires, habiter le monde », problématique et annonce","points":5},{"critere":"Partie qui montre la réalité de la souffrance et ce qu'elle détruit (Elie, la chute, Desaragne, Amboise)","points":5},{"critere":"Partie sur la résilience et la transmission (Reine Sans Nom, tenir debout, dignité, pardon)","points":6},{"critere":"Rôle de l'écriture ou de la voix âgée, et conclusion nette","points":4}],"dureeMin":20,"corrige":"**1. Introduction possible.**\n*Amorce* : raconter une vie de misère, c'est risquer d'écrire l'histoire d'une victime. *Présentation* : dans ***Pluie et vent sur Télumée Miracle*** (**1972**), **Simone Schwarz-Bart** fait parler une vieille femme de **Guadeloupe**, qui raconte sa vie et celle des femmes de sa lignée ; l'œuvre illustre le parcours **« tisser les mémoires, habiter le monde »**. *Problématique* : les épreuves traversées par Télumée la brisent-elles, ou font-elles d'elle une femme debout ? *Annonce* : la souffrance est bien réelle et détruit parfois ; mais le roman montre surtout une force transmise, que la voix de la narratrice célèbre.\n\n**2. Plan détaillé.**\n**I. Une souffrance réelle, qui peut détruire.**\n- La **misère** et le **mépris** : servante chez les **Desaragne**, Télumée subit les paroles blessantes de la maîtresse ; la hiérarchie coloniale survit.\n- La souffrance détruit certains personnages : **Elie**, sans travail, sombre dans l'**amertume** et la **violence** — un amour qui se défait sous le poids de la misère ; Télumée elle-même **s'effondre**. **Amboise meurt** lors d'une grève.\n\n**II. Mais la souffrance ne détruit pas Télumée : elle se relève.**\n- La **transmission** : **Reine Sans Nom**, qui s'est **relevée** après la mort de sa fille dans un incendie, lui apprend à **tenir debout** ; la femme **droite, que le vent ne couche pas**.\n- La **dignité** et le **pardon** : face aux Desaragne, elle **garde sa dignité intérieure** ; à la fin, elle **accompagne jusqu'à la mort un homme qui lui voulait du mal** et devient **Télumée Miracle**. La **résilience** est le sujet du livre.\n\n**III. Une voix qui transforme la souffrance en chant.**\n- La **première personne rétrospective** : la **sagesse de l'âge** éclaire l'enfance ; la vieille femme dans son **jardin** unit l'expérience, la mémoire et le **pardon**.\n- Les **proverbes**, les **contes** et les **phrases amples et rythmées** font du roman un **chant** : la parole transmise est une arme contre la destruction.\n\n**3. Conclusion possible.** Non : le roman ne nie pas la souffrance, mais il montre qu'elle **ne détruit pas** qui a reçu l'art de **se relever** ; il **ne pleure pas, il célèbre une force**.\n\nAccepter tout plan cohérent (deux parties : oui / non) avec des exemples exacts."}$exo$::jsonb),
  ('a59ef4f3-f0c7-5230-8106-8bf6135b041a'::uuid, 1, 'redaction', $exo${"titre":"Les critères d'un régime démocratique","consigne":"Réponds à chaque question en quelques lignes, en utilisant le vocabulaire du cours.","enonce":"1. Donne l'origine grecque du mot **démocratie** et explique-la.\n2. Cite les **cinq critères** d'un régime démocratique et, pour chacun, ce qu'il exige.\n3. Beaucoup de régimes autoritaires organisent des élections. Quel est alors, selon le cours, le **critère décisif** qui distingue une démocratie ?","bareme":[{"critere":"Étymologie juste : dêmos (le peuple) et kratos (le pouvoir)","points":4},{"critere":"Cinq critères cités (élections, séparation des pouvoirs, État de droit, libertés, pluralisme) avec leur exigence","points":10},{"critere":"Critère décisif : la possibilité réelle de perdre le pouvoir et de le céder (alternance)","points":6}],"dureeMin":7,"corrige":"1. Démocratie vient du grec **dêmos**, le peuple, et **kratos**, le pouvoir : c'est le **pouvoir du peuple**.\n2. Les cinq critères :\n- des **élections** libres, pluralistes, régulières, au suffrage universel ;\n- la **séparation des pouvoirs** (exécutif, législatif, judiciaire ne se confondent pas), idée de **Montesquieu** ;\n- l'**État de droit** : tous, gouvernants compris, sont soumis à la loi, et une juridiction peut censurer la loi ;\n- les **libertés fondamentales** : expression, presse, réunion, association, conscience ;\n- le **pluralisme** : une opposition reconnue et l'alternance possible.\n3. Le critère décisif n'est pas la tenue d'élections mais la **possibilité réelle de perdre le pouvoir et de le céder** : un régime où le camp au pouvoir ne peut pas perdre n'est pas une démocratie, même s'il vote."}$exo$::jsonb),
  ('a59ef4f3-f0c7-5230-8106-8bf6135b041a'::uuid, 2, 'redaction', $exo${"titre":"Trois régimes à identifier","consigne":"Identifie le type de chaque régime puis juge si le pays de Valdorie est une démocratie, en justifiant avec les critères du cours.","enonce":"**Document 1 — Trois constitutions (pays imaginaires)**\n\n| Pays | Le parlement peut-il renverser le gouvernement ? | Le parlement peut-il être dissous ? |\n| Pays A | Non | Non |\n| Pays B | Oui | Oui |\n| Pays C | Oui, devant l'assemblée ; un président élu au suffrage universel dispose de pouvoirs propres | Oui |\n\n**Document 2 — La Valdorie**\n\n> En Valdorie, le président est réélu tous les cinq ans avec plus de 90 % des voix. Le principal parti d'opposition a été interdit, les journaux indépendants ont fermé, et les juges de la cour suprême sont révoqués dès qu'ils annulent une loi.\n\n1. À quel type de régime (parlementaire, présidentiel, semi-présidentiel) correspond chaque pays du document 1 ? Donne un exemple réel pour chacun.\n2. La Valdorie organise des élections. Est-ce une démocratie ? Appuie-toi sur au moins trois critères du cours.","bareme":[{"critere":"Pays A présidentiel (États-Unis), B parlementaire (Royaume-Uni ou Allemagne), C semi-présidentiel (France)","points":7},{"critere":"Critères manquants identifiés : pluralisme, libertés de la presse, État de droit / indépendance de la justice","points":8},{"critere":"Conclusion : élections sans possibilité réelle de perdre le pouvoir, donc pas une démocratie","points":5}],"dureeMin":11,"corrige":"1. **Pays A** : le gouvernement n'est pas renversable et le parlement n'est pas dissoluble → **régime présidentiel** (les **États-Unis**).\n**Pays B** : gouvernement renversable, parlement dissoluble → **régime parlementaire** (le **Royaume-Uni**, l'**Allemagne**).\n**Pays C** : gouvernement responsable devant l'Assemblée, parlement dissoluble, président aux pouvoirs propres → **régime semi-présidentiel** (la **France** depuis 1962).\n2. La Valdorie n'est **pas une démocratie**, malgré ses élections :\n- **pluralisme** absent : l'opposition est interdite, l'alternance est impossible ;\n- **libertés fondamentales** bafouées : la presse indépendante a disparu ;\n- **État de droit** détruit : les juges qui censurent la loi sont révoqués, les gouvernants ne sont plus soumis au droit ; la **séparation des pouvoirs** n'existe plus.\nLe score de 90 % n'est pas une preuve de démocratie : le critère décisif est la **possibilité réelle de perdre le pouvoir et de le céder**, ce que la Valdorie exclut. Elle ressemble à ce que le cours appelle un régime autoritaire qui organise des élections."}$exo$::jsonb),
  ('a59ef4f3-f0c7-5230-8106-8bf6135b041a'::uuid, 3, 'redaction', $exo${"titre":"Voter suffit-il à être une démocratie ?","consigne":"Rédige une réponse organisée (introduction, deux ou trois parties, conclusion) en t'appuyant sur le document et sur le cours.","enonce":"**Document — Un rapport imaginaire sur l'état des démocraties**\n\n> « Dans le pays étudié, les élections ont toujours lieu à la date prévue et plusieurs partis s'y présentent. Mais en dix ans, le gouvernement a placé ses proches à la tête de la télévision publique, réduit l'indépendance des juges et restreint le financement des associations critiques. L'opposition peut encore se présenter, mais elle n'a plus accès aux grands médias. »\n\n**Sujet.** « Organiser des élections suffit-il à faire une démocratie ? »\n\nTu montreras ce que sont les critères d'une démocratie, tu qualifieras le régime décrit par le document, et tu expliqueras pourquoi les formes directe et participative complètent la démocratie représentative.","bareme":[{"critere":"Critères de la démocratie présentés et reliés au sujet","points":5},{"critere":"Régime du document qualifié d'illibéral, avec les contre-pouvoirs affaiblis relevés dans le texte","points":5},{"critere":"Les trois formes (directe, représentative, participative) définies avec un exemple chacune","points":4},{"critere":"Idée d'érosion : la démocratie n'est pas un acquis irréversible","points":3},{"critere":"Réponse organisée, avec une conclusion qui répond clairement au sujet","points":3}],"dureeMin":18,"corrige":"**Introduction** : démocratie = pouvoir du peuple (dêmos, kratos). Les élections en sont une condition, mais beaucoup de régimes autoritaires en organisent.\n\n**I. Les élections, une condition nécessaire mais pas suffisante.** Elles doivent être libres, pluralistes, régulières, au suffrage universel. S'y ajoutent la séparation des pouvoirs (Montesquieu), l'État de droit (gouvernants soumis à la loi, loi censurable par une juridiction), les libertés fondamentales et le pluralisme. Le critère décisif : la possibilité réelle de **perdre le pouvoir** et de le céder.\n\n**II. Le document : un régime illibéral.** Les élections sont maintenues et plusieurs partis s'y présentent, mais la presse (télévision publique confiée à des proches), la justice (indépendance réduite) et les contre-pouvoirs (associations critiques) sont affaiblis ; l'opposition n'a plus accès aux médias, donc l'alternance devient théorique. C'est la définition du **régime illibéral** : il conserve les élections en affaiblissant presse, justice et contre-pouvoirs. Le cours note depuis une quinzaine d'années une **érosion** des démocraties.\n\n**III. Au-delà du vote : faire vivre la démocratie.** Démocratie **directe** (les citoyens décident : Athènes, référendum, Landsgemeinde suisses) ; **représentative** (des élus décident : tous les grands États) ; **participative** (les citoyens associés entre deux élections : budgets participatifs, conventions citoyennes). Ces formes rapprochent les citoyens de la décision.\n\n**Conclusion** : non, voter ne suffit pas ; sans libertés, pluralisme et État de droit, l'élection devient une façade. La démocratie n'est **pas un acquis irréversible**."}$exo$::jsonb),
  ('aebabe0c-6a7d-5b05-93fa-a0661d8e1ab8'::uuid, 1, 'redaction', $exo${"titre":"Les institutions de la démocratie athénienne","consigne":"Complète le tableau puis réponds à la question en quelques lignes.","enonce":"1. Recopie et complète le tableau des institutions d'Athènes au Ve siècle avant notre ère.\n\n| L'institution | Sa composition et son mode de désignation | Son rôle |\n| Ecclésia | … | … |\n| Boulê | … | … |\n| Héliée | … | … |\n| Stratèges | … | … |\n\n2. Pourquoi les Athéniens jugeaient-ils le **tirage au sort** plus démocratique que l'élection ? Pourquoi les stratèges font-ils exception ?","bareme":[{"critere":"Tableau juste pour l'Ecclésia, la Boulê, l'Héliée et les stratèges","points":12},{"critere":"Tirage au sort : chance égale pour chacun, l'élection favorisant notables et orateurs","points":5},{"critere":"Exception des stratèges : compétence militaire, donc élus","points":3}],"dureeMin":8,"corrige":"1.\n- **Ecclésia** : tous les citoyens, réunis une quarantaine de fois par an sur la Pnyx ; elle **vote les lois, la guerre, les traités**.\n- **Boulê** : **500 membres tirés au sort** ; elle **prépare les débats** de l'Ecclésia.\n- **Héliée** : des **jurés tirés au sort** ; c'est le **tribunal populaire**.\n- **Stratèges** : magistrats **élus** (les autres magistrats sont tirés au sort) ; ils **commandent** l'armée.\n2. Le tirage au sort donne à **chacun une chance égale**, alors que l'élection favorise les **notables et les orateurs**. Les stratèges sont élus parce que la **compétence militaire ne s'improvise pas** : Périclès l'a été quinze années de suite."}$exo$::jsonb),
  ('aebabe0c-6a7d-5b05-93fa-a0661d8e1ab8'::uuid, 2, 'redaction', $exo${"titre":"Qui vote sur la Pnyx ?","consigne":"Pour chaque habitant d'Athènes présenté, dis s'il peut voter à l'Ecclésia en justifiant avec le cours, puis réponds aux questions.","enonce":"**Situation.** Nous sommes à Athènes en 440 avant notre ère. Voici quatre habitants (personnages inventés).\n\n- **Nikias**, fils d'un père et d'une mère athéniens, cordonnier pauvre, majeur.\n- **Philè**, fille d'un père et d'une mère athéniens.\n- **Képhalos**, né à Athènes d'une famille venue de Syracuse il y a trois générations ; il paie l'impôt et sert dans l'armée.\n- **Dion**, né d'un père athénien et d'une mère corinthienne.\n\n1. Qui, parmi ces quatre personnes, peut voter à l'Ecclésia ? Justifie chaque cas.\n2. Nikias est pauvre. Quel mécanisme lui permet de siéger ? Explique son but.\n3. Nikias trouve qu'un orateur est devenu trop puissant. Quel mécanisme peut-il utiliser ?","bareme":[{"critere":"Nikias citoyen ; Philè exclue comme femme ; Képhalos métèque sans droit de vote","points":8},{"critere":"Dion exclu par la loi de Périclès de 451 (père et mère athéniens)","points":4},{"critere":"Misthophorie : indemnité qui permet aux plus pauvres de siéger","points":4},{"critere":"Ostracisme : exil de dix ans décidé par vote","points":4}],"dureeMin":10,"corrige":"1.\n- **Nikias** peut voter : né de père **et** de mère athéniens, c'est un **citoyen** ; sa pauvreté ne l'exclut pas.\n- **Philè** ne vote pas : les **femmes** sont exclues de la citoyenneté **quelle que soit leur naissance**.\n- **Képhalos** ne vote pas : c'est un **métèque**, un étranger libre installé parfois depuis des générations ; il paie l'impôt et sert à l'armée **sans voter**.\n- **Dion** ne vote pas : depuis la loi de **Périclès en 451**, il faut être né de père **et** de mère athéniens ; sa mère est corinthienne.\n2. La **misthophorie** est une **indemnité de participation** : elle compense la journée de travail perdue, pour que **les plus pauvres puissent siéger**.\n3. L'**ostracisme** : les citoyens votent pour **exiler dix ans** un citoyen jugé trop puissant. (Si l'orateur a fait une proposition illégale, la *graphê paranomôn* permet aussi de le poursuivre.)"}$exo$::jsonb),
  ('aebabe0c-6a7d-5b05-93fa-a0661d8e1ab8'::uuid, 3, 'redaction', $exo${"titre":"Athènes, une démocratie directe mais limitée","consigne":"Rédige un développement organisé en deux parties, avec une introduction et une conclusion. Utilise les données chiffrées fournies.","enonce":"**Données.** En Attique au Ve siècle avant notre ère : environ **300 000 habitants**, dont **40 000 citoyens** au plus.\n\n**Sujet.** « Athènes au Ve siècle : un modèle de démocratie ? »\n\n1. Calcule la part approximative des citoyens dans la population de l'Attique.\n2. Montre en quoi Athènes invente une démocratie **directe** et donne réellement le pouvoir aux citoyens (institutions, tirage au sort, isêgoria, mécanismes de contrôle).\n3. Montre que cette participation repose sur une **exclusion massive**, et explique pourquoi il faut tenir ensemble les deux constats.","bareme":[{"critere":"Calcul juste : 40 000 / 300 000, soit environ 13 %","points":3},{"critere":"Démocratie directe : Ecclésia, Boulê, Héliée, tirage au sort, isêgoria","points":6},{"critere":"Mécanismes : misthophorie, ostracisme, graphê paranomôn","points":4},{"critere":"Exclus : femmes, métèques, esclaves, loi de 451 ; lien entre esclavage et disponibilité des citoyens","points":5},{"critere":"Conclusion nuancée qui tient ensemble modèle et exclusion","points":2}],"dureeMin":18,"corrige":"1. 40 000 ÷ 300 000 ≈ 0,133, soit **environ 13 %** des habitants (au plus).\n\n**Introduction** : Athènes invente au Ve siècle un régime où les citoyens décident eux-mêmes, sans représentants ; elle est invoquée comme modèle depuis vingt-cinq siècles.\n\n**I. Une démocratie directe et intense.** L'**Ecclésia**, réunissant tous les citoyens une quarantaine de fois par an sur la Pnyx, vote lois, guerre et traités. La **Boulê** (500 membres tirés au sort) prépare les débats, l'**Héliée** (jurés tirés au sort) rend la justice. Le **tirage au sort** donne à chacun une chance égale ; seuls les **stratèges** sont élus, pour leur compétence militaire. L'**isêgoria** donne à tout citoyen le droit égal à la parole. Des mécanismes protègent le régime : la **misthophorie** permet aux pauvres de siéger, l'**ostracisme** exile dix ans un citoyen trop puissant, la **graphê paranomôn** poursuit l'auteur d'une proposition illégale.\n\n**II. Une participation fondée sur l'exclusion.** Environ 13 % seulement des habitants sont citoyens. Sont exclus les **femmes** (quelle que soit leur naissance), les **métèques** (étrangers libres qui paient l'impôt et servent à l'armée sans voter) et les **esclaves**, très nombreux, dont le travail **rend possible la disponibilité des citoyens**. En **451**, Périclès restreint encore la citoyenneté : il faut être né de père et de mère athéniens.\n\n**Conclusion** : Athènes est à la fois un **modèle** de participation et un régime d'**exclusion massive** ; les deux constats vont ensemble, car la participation des uns reposait sur le travail des exclus."}$exo$::jsonb),
  ('1ff1cc71-c548-5cba-bfb5-b82dfdea55f5'::uuid, 1, 'redaction', $exo${"titre":"Trois révolutions, trois textes","consigne":"Complète le tableau puis définis les deux notions demandées.","enonce":"1. Recopie et complète le tableau.\n\n| Le pays | Les dates de la révolution | Le texte fondateur | Le régime institué |\n| Angleterre | … | … | … |\n| États-Unis | … | … | … |\n| France | … | … | … |\n\n2. Définis le **mandat représentatif**.\n3. Définis le **suffrage censitaire**.","bareme":[{"critere":"Tableau juste pour l'Angleterre, les États-Unis et la France","points":12},{"critere":"Mandat représentatif : l'élu représente la Nation entière et n'est pas révocable","points":4},{"critere":"Suffrage censitaire : vote réservé à ceux qui paient un certain niveau d'impôt","points":4}],"dureeMin":8,"corrige":"1.\n- **Angleterre** : 1642-1649 puis **1688** ; le **Bill of Rights** (1689) ; une **monarchie parlementaire** : le roi ne peut lever d'impôt ni suspendre les lois sans le Parlement.\n- **États-Unis** : 1776-1791 ; la **Déclaration d'indépendance** (1776), la **Constitution de 1787**, le Bill of Rights de 1791 ; un régime **présidentiel et fédéral**, avec des *checks and balances*.\n- **France** : 1789-1792 ; la **Déclaration des droits de l'homme et du citoyen** ; une monarchie constitutionnelle en 1791 puis la **République** en 1792.\n2. **Mandat représentatif** : l'élu représente **la Nation entière**, pas seulement ses électeurs, et il **n'est pas révocable** en cours de mandat.\n3. **Suffrage censitaire** : le droit de vote est **réservé à ceux qui paient un certain niveau d'impôt** (le cens) ; il est la règle presque partout à l'époque."}$exo$::jsonb),
  ('1ff1cc71-c548-5cba-bfb5-b82dfdea55f5'::uuid, 2, 'redaction', $exo${"titre":"Le député et ses électeurs","consigne":"Lis la situation et réponds à chaque question en t'appuyant sur les principes consacrés par les révolutions.","enonce":"**Situation (imaginaire), France, 1791.** Les électeurs d'un canton de Bretagne écrivent à leur député : « Nous vous avons élu ; vous voterez donc contre la loi sur les grains, sinon nous vous retirerons votre mandat. » Le député répond qu'il votera selon ce qu'il juge bon pour le pays.\n\n1. Quel principe le député invoque-t-il ? Explique-le.\n2. Les électeurs peuvent-ils le révoquer ? Justifie.\n3. Dans quelle forme de démocratie le peuple ferait-il lui-même la loi ? Comment **Sieyès** distingue-t-il cette forme du gouvernement représentatif ?\n4. Le cours affirme que le choix représentatif « n'est pas un pis-aller d'échelle ». Explique cette idée.","bareme":[{"critere":"Mandat représentatif : l'élu représente la Nation entière","points":5},{"critere":"Pas de révocation en cours de mandat","points":4},{"critere":"Distinction de Sieyès : le peuple fait la loi / il choisit qui la fera","points":6},{"critere":"Idée d'un choix politique et non d'une contrainte de taille","points":5}],"dureeMin":11,"corrige":"1. Le député invoque le **mandat représentatif** : l'élu représente **la Nation entière**, non ses seuls électeurs ; il décide selon l'intérêt général et ne reçoit pas d'instructions de son canton. Il s'appuie aussi sur la **souveraineté nationale** : le pouvoir vient du peuple pris comme un tout.\n2. **Non** : dans le mandat représentatif, l'élu **n'est pas révocable en cours de mandat**. Les électeurs pourront seulement ne pas le réélire.\n3. C'est la **démocratie** au sens de Sieyès (la démocratie directe) : le peuple **fait la loi** lui-même. Dans le **gouvernement représentatif**, il **choisit qui la fera**.\n4. On pourrait croire que la représentation n'existe que parce qu'un grand pays ne peut pas réunir tous ses citoyens. Le cours souligne au contraire qu'il s'agit d'un **choix politique** assumé : Sieyès préfère que la loi soit faite par des représentants. Le modèle consacré par les révolutions est donc **représentatif et non direct** par principe."}$exo$::jsonb),
  ('1ff1cc71-c548-5cba-bfb5-b82dfdea55f5'::uuid, 3, 'redaction', $exo${"titre":"Des révolutions démocratiques ?","consigne":"Rédige un développement organisé (introduction, deux parties, conclusion) qui mobilise précisément les trois révolutions.","enonce":"**Sujet.** « Les révolutions anglaise, américaine et française ont-elles fondé la démocratie ? »\n\nTu montreras d'abord ce que ces révolutions consacrent (principes, textes, régimes), puis leurs limites. Tu expliqueras enfin le sens de la phrase du cours : « L'universalité proclamée met un siècle et demi à se réaliser. »","bareme":[{"critere":"Principes consacrés : souveraineté nationale, mandat représentatif, constitution écrite et déclaration de droits, séparation des pouvoirs","points":6},{"critere":"Exemples précis des trois pays (Bill of Rights 1689, Constitution de 1787, Déclaration de 1789, République de 1792)","points":5},{"critere":"Limites : suffrage censitaire, exclusion des femmes, esclavage maintenu aux États-Unis et rétabli en France en 1802","points":5},{"critere":"Nuance : suffrage universel masculin de la Convention, première sans lendemain ; écart entre principe et réalité","points":4}],"dureeMin":18,"corrige":"**Introduction** : entre le XVIIe et le XVIIIe siècle, trois révolutions imposent un modèle nouveau : le peuple est souverain mais gouverne par des représentants.\n\n**I. Ce que les révolutions consacrent.**\n- **Angleterre** : le **Bill of Rights** (1689) fonde une monarchie parlementaire ; le roi ne peut lever l'impôt ni suspendre les lois sans le Parlement.\n- **États-Unis** : la Déclaration d'indépendance, la **Constitution de 1787** (première constitution écrite d'un grand État), régime présidentiel et fédéral avec *checks and balances*.\n- **France** : la **Déclaration des droits de l'homme et du citoyen** (1789), monarchie constitutionnelle (1791) puis **République** (1792).\nPrincipes : **souveraineté nationale** (le pouvoir vient du peuple, non de Dieu ni de la naissance), **mandat représentatif**, **constitution écrite et déclaration de droits** qui bornent le pouvoir, **séparation des pouvoirs** (Montesquieu, Locke). Le modèle est **représentatif** par choix (Sieyès).\n\n**II. Des limites qui contredisent l'universalité proclamée.**\n- **Suffrage censitaire** presque partout.\n- **Exclusion des femmes** partout.\n- **Esclavage** maintenu aux États-Unis, **rétabli en France en 1802**.\nLa Convention française, élue au **suffrage universel masculin** en 1792, est une première **sans lendemain immédiat**.\n\n**Conclusion** : ces révolutions fondent les **principes** de la démocratie représentative, pas encore sa **réalité** ; les droits proclamés pour tous mettront un siècle et demi à s'étendre effectivement à tous."}$exo$::jsonb),
  ('308e0606-d47f-55d7-8fc0-ac9ac7701666'::uuid, 1, 'redaction', $exo${"titre":"Les trois périls selon Tocqueville","consigne":"Réponds à chaque question en quelques lignes précises.","enonce":"1. Quel ouvrage Tocqueville tire-t-il de son voyage aux États-Unis en **1831** ? Que cherche-t-il en Amérique ?\n2. Définis les trois périls que Tocqueville voit dans la démocratie :\n   a. la tyrannie de la majorité ;\n   b. l'individualisme ;\n   c. le despotisme doux.\n3. Cite trois remèdes qu'il propose.","bareme":[{"critere":"De la démocratie en Amérique ; il y cherche un avenir (égalisation des conditions), non un modèle","points":4},{"critere":"Définitions justes des trois périls","points":12},{"critere":"Trois remèdes parmi association, presse libre, décentralisation, religion, justice indépendante","points":4}],"dureeMin":8,"corrige":"1. Il en tire **De la démocratie en Amérique**. Il n'y cherche pas un modèle mais **un avenir** : l'**égalisation des conditions** lui paraît irrésistible.\n2.\na. **Tyrannie de la majorité** : là où la majorité fait la loi **et** l'opinion, la minorité n'a **aucun recours** ; la pression est **morale avant d'être physique**.\nb. **Individualisme** : l'égalité détache les hommes et les **replie sur leur cercle privé** ; c'est un **retrait de la vie publique**, pas l'égoïsme.\nc. **Despotisme doux** : un pouvoir « tutélaire, immense » qui ne tyrannise pas mais **infantilise**, prend tout en charge et ôte l'usage de soi-même ; les citoyens y **consentent**.\n3. Remèdes : l'**association**, la **liberté de la presse**, la **décentralisation**, la **religion** comme frein moral, l'**indépendance de la justice**."}$exo$::jsonb),
  ('308e0606-d47f-55d7-8fc0-ac9ac7701666'::uuid, 2, 'redaction', $exo${"titre":"Tocqueville au XXIe siècle","consigne":"Pour chaque situation, identifie le péril décrit par Tocqueville, justifie, puis propose le remède tocquevillien le plus adapté.","enonce":"**Situations imaginaires**\n\n- **A.** Dans la commune de Valbois, plus personne ne se présente au conseil municipal ; les habitants disent : « la politique, ce n'est pas notre affaire, on a assez à faire chez nous ».\n- **B.** Au lycée, Inès défend en classe une opinion très minoritaire. Personne ne la menace, mais elle est ignorée, moquée en ligne, et finit par se taire.\n- **C.** Une application publique décide de tout pour les citoyens : leur orientation, leurs rendez-vous, leurs achats. Les gens s'en disent satisfaits et n'ont plus à choisir.\n\n1. Pour chaque situation, nomme le péril et explique pourquoi.\n2. Pour chaque situation, propose un remède tiré de Tocqueville et explique comment il agirait.","bareme":[{"critere":"A : individualisme, retrait du public","points":4},{"critere":"B : tyrannie de la majorité, pression morale sur la minorité","points":4},{"critere":"C : despotisme doux, pouvoir tutélaire consenti qui infantilise","points":4},{"critere":"Trois remèdes adaptés et justifiés (association, décentralisation, presse, justice…)","points":8}],"dureeMin":12,"corrige":"1.\n- **A** : **individualisme**. Les habitants se replient sur leur cercle privé et se **retirent de la vie publique** : ce n'est pas de l'égoïsme, mais un détachement du public.\n- **B** : **tyrannie de la majorité**. Aucune violence physique, mais une **pression morale** de l'opinion majoritaire qui ne laisse **aucun recours** à la minorité : Inès se tait.\n- **C** : **despotisme doux**. Un pouvoir **tutélaire** prend tout en charge, **infantilise** et ôte l'usage de soi-même ; les citoyens **y consentent** parce qu'il les soulage. Le cours cite justement la délégation croissante à l'administration ou à l'algorithme.\n2. Remèdes :\n- **A** : la **décentralisation** et l'**association** : l'administration locale est une **école pratique de la liberté** ; une association de quartier forme à l'action collective.\n- **B** : la **liberté de la presse** et l'**association** : une minorité qui peut s'exprimer publiquement et se regrouper trouve un recours face à l'opinion dominante (la **justice indépendante** protège aussi ses droits).\n- **C** : l'**association** et la **décentralisation**, qui redonnent aux citoyens l'habitude d'agir eux-mêmes ; car **la liberté ne se conserve pas d'elle-même** : elle demande des institutions et des mœurs."}$exo$::jsonb),
  ('308e0606-d47f-55d7-8fc0-ac9ac7701666'::uuid, 3, 'redaction', $exo${"titre":"Une servitude douce et consentie","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en t'appuyant sur le cours.","enonce":"**Document — Résumé de l'analyse de Tocqueville**\n\n> La menace qui pèse sur les peuples démocratiques ne vient pas d'un tyran : elle vient d'une servitude volontaire, réglée et douce, compatible avec les formes extérieures de la souveraineté populaire.\n\n**Sujet.** « Selon Tocqueville, comment la démocratie peut-elle menacer la liberté, et comment s'en protéger ? »\n\nTu expliqueras ce que Tocqueville admire en Amérique, les trois périls qu'il décrit (en insistant sur le despotisme doux), puis les remèdes qu'il propose. Tu termineras en montrant pourquoi ses concepts restent utiles aujourd'hui.","bareme":[{"critere":"Ce qu'il admire : associations, décentralisation, justice, religion séparée de l'État","points":4},{"critere":"Tyrannie de la majorité et individualisme correctement définis","points":4},{"critere":"Despotisme doux expliqué à partir du document : consenti, tutélaire, compatible avec l'élection","points":5},{"critere":"Remèdes et idée que la liberté demande des institutions et des mœurs","points":4},{"critere":"Actualité : apathie électorale, conformisme, délégation à l'administration ou à l'algorithme","points":3}],"dureeMin":18,"corrige":"**Introduction** : en 1831, Tocqueville voyage aux États-Unis et en tire *De la démocratie en Amérique* ; il y cherche l'avenir de sociétés où l'**égalisation des conditions** est irrésistible.\n\n**I. Ce qu'il admire.** Les **associations** (on s'unit pour tout, ce qui forme à l'action collective et fait contrepoids à l'État), la **décentralisation** (école pratique de la liberté), une **justice** indépendante, une **religion** séparée de l'État qui soutient les mœurs.\n\n**II. Trois périls.** La **tyrannie de la majorité** : la majorité fait la loi et l'opinion, la minorité n'a aucun recours ; la pression est morale. L'**individualisme** : retrait sur le cercle privé, abandon du public. Surtout le **despotisme doux** : un pouvoir tutélaire, immense, qui ne tyrannise pas mais infantilise et prend tout en charge. Comme le dit le document, cette servitude est **volontaire, réglée et douce** et reste compatible avec l'élection : les citoyens y consentent parce qu'ils ont élu ce pouvoir et qu'il les soulage. C'est l'analyse qui a fait la fortune du livre.\n\n**III. Les remèdes.** Association, liberté de la presse, décentralisation, religion comme frein moral, indépendance de la justice. Tocqueville n'est pas pessimiste par principe, mais **la liberté ne se conserve pas d'elle-même** : elle demande des institutions et des mœurs.\n\n**Conclusion** : ses concepts permettent de penser les fragilités actuelles : **apathie électorale**, **conformisme des opinions**, **délégation croissante à l'administration ou à l'algorithme**."}$exo$::jsonb),
  ('4fe99f3e-8635-5257-9720-6903aff3b7a8'::uuid, 1, 'redaction', $exo${"titre":"La chronologie chilienne","consigne":"Associe chaque date à son événement, puis réponds aux questions.","enonce":"1. Associe chaque date à l'événement qui lui correspond et rédige une phrase pour chacun.\n\n| Dates | Événements (dans le désordre) |\n| 1970 | Référendum où le « non » à Pinochet l'emporte |\n| 11 septembre 1973 | Fin de la dictature |\n| 1988 | Élection de Salvador Allende |\n| 1989 | Coup d'État militaire, bombardement de la Moneda |\n| 1990 | Élections libres |\n\n2. Avec quel score Allende l'emporte-t-il ? Pourquoi doit-il être confirmé par le Congrès ?\n3. Pourquoi son élection est-elle une première ?","bareme":[{"critere":"Cinq associations date-événement justes","points":10},{"critere":"36,6 % des voix, sans majorité absolue, d'où la confirmation par le Congrès","points":5},{"critere":"Premier marxiste arrivé au pouvoir par les urnes dans un pays occidental","points":5}],"dureeMin":7,"corrige":"1.\n- **1970** : élection de **Salvador Allende**, candidat de l'Unité populaire (socialistes et communistes).\n- **11 septembre 1973** : **coup d'État** de l'armée dirigée par **Augusto Pinochet** ; le palais de la Moneda est bombardé, Allende y meurt.\n- **1988** : **référendum** où le « non » à Pinochet l'emporte.\n- **1989** : **élections libres**.\n- **1990** : **fin de la dictature**.\n2. Allende obtient **36,6 %** des voix : n'ayant **pas la majorité absolue**, il doit être **confirmé par le Congrès**.\n3. C'est la **première fois qu'un marxiste accède au pouvoir par les urnes dans un pays occidental**."}$exo$::jsonb),
  ('4fe99f3e-8635-5257-9720-6903aff3b7a8'::uuid, 2, 'redaction', $exo${"titre":"Les pressions sur le gouvernement Allende","consigne":"Classe les faits du document, puis explique leurs effets en t'appuyant sur le cours.","enonce":"**Document — Faits relevés au Chili entre 1970 et 1973**\n\n- a. Le cuivre est nationalisé sans indemnisation des compagnies américaines.\n- b. Les salaires sont fortement relevés.\n- c. Les États-Unis bloquent le crédit international et financent l'opposition.\n- d. Les camionneurs font grève en 1972-1973.\n- e. En août 1973, le Congrès déclare le gouvernement hors de la légalité.\n\n1. Parmi ces faits, lesquels sont des **mesures du gouvernement** et lesquels sont des **pressions** contre lui ? Classe les pressions en extérieure, économique et institutionnelle.\n2. Explique les conséquences des mesures a et b.\n3. Pourquoi la grève des camionneurs est-elle si efficace au Chili ?","bareme":[{"critere":"a et b identifiés comme mesures ; c extérieure, d économique, e institutionnelle","points":8},{"critere":"Conséquences : rupture avec les États-Unis ; inflation, pénuries, marché noir","points":7},{"critere":"Pays étiré sur 4 300 km, donc paralysé sans transport routier","points":5}],"dureeMin":10,"corrige":"1. **Mesures du gouvernement** : a (nationalisation du cuivre) et b (hausse des salaires).\n**Pressions** :\n- **extérieure** : c, les **États-Unis** bloquent le crédit international et financent l'opposition (Nixon veut « faire crier l'économie ») ;\n- **économique** : d, la **grève des camionneurs** ;\n- **institutionnelle** : e, le **Congrès**, dominé par l'opposition, déclare le gouvernement hors de la légalité.\n2. La nationalisation du cuivre sans indemnisation provoque la **rupture avec les États-Unis**. La hausse des salaires entraîne une **inflation vertigineuse**, des **pénuries** et un **marché noir**.\n3. Le Chili est un pays **étiré sur 4 300 kilomètres** : sans camions, les marchandises ne circulent plus et le pays est **paralysé**."}$exo$::jsonb),
  ('4fe99f3e-8635-5257-9720-6903aff3b7a8'::uuid, 3, 'redaction', $exo${"titre":"Comment meurt une démocratie : le Chili","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en utilisant des faits et des dates précis.","enonce":"**Sujet.** « Comment une démocratie ancienne et stable comme le Chili a-t-elle pu basculer en trois ans dans une dictature militaire ? »\n\nTu présenteras la situation de départ, puis les mécanismes de l'effondrement, puis le coup d'État et ses suites jusqu'au retour de la démocratie. Tu dégageras en conclusion ce que ce cas enseigne sur la fragilité des démocraties.","bareme":[{"critere":"Point de départ : démocratie solide, élection d'Allende en 1970 à 36,6 %, programme de l'Unité populaire","points":4},{"critere":"Crise économique et pressions extérieure, économique, institutionnelle","points":5},{"critere":"Coup d'État du 11 septembre 1973 et répression (Congrès dissous, partis interdits, arrestations, torture)","points":4},{"critere":"Sortie : référendum de 1988, élections de 1989, fin en 1990, commission Rettig","points":3},{"critere":"Mécanismes généraux dégagés : polarisation, crise, délégitimation des institutions, intervention extérieure, armée présentée comme retour à l'ordre","points":4}],"dureeMin":20,"corrige":"**Introduction** : le Chili est l'une des démocraties les plus solides d'Amérique latine ; il bascule pourtant entre 1970 et 1973.\n\n**I. Une élection légale et un programme de rupture.** En **1970**, **Salvador Allende** (Unité populaire) l'emporte avec **36,6 %**, sans majorité absolue, et est confirmé par le Congrès : premier marxiste élu dans un pays occidental. Il nationalise le **cuivre** sans indemniser les compagnies américaines, nationalise les **banques**, accélère la **réforme agraire** (tensions dans les campagnes), hausse les **salaires** : inflation vertigineuse, pénuries, marché noir.\n\n**II. Les pressions qui font basculer le pays.** Extérieure : les **États-Unis** bloquent le crédit et financent l'opposition. Économique : la **grève des camionneurs** (1972-1973) paralyse un pays de 4 300 km. Institutionnelle : en **août 1973**, le **Congrès** déclare le gouvernement hors de la légalité.\n\n**III. Le coup d'État et la dictature.** Le **11 septembre 1973**, l'armée de **Pinochet** bombarde la Moneda ; Allende y meurt. Congrès dissous, partis interdits, censure, arrestations massives (stade national), torture, exécutions, disparitions. La dictature dure jusqu'en **1990** : référendum de **1988** (victoire du « non »), élections libres en **1989** ; la **commission Rettig** établit plus de 3 000 morts et disparus.\n\n**Conclusion** : une démocratie s'effondre par **polarisation extrême**, **crise économique**, **délégitimation réciproque des institutions**, **intervention extérieure**, puis par le recours à l'armée **présenté comme un rétablissement de l'ordre**."}$exo$::jsonb),
  ('aef00199-1d6e-522f-940d-71ad3a04d772'::uuid, 1, 'redaction', $exo${"titre":"Portugal et Espagne : les dates clés","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"1. Quel est le nom de la dictature portugaise ? Qui l'a fondée et en quelle année ?\n2. Que se passe-t-il au Portugal le **25 avril 1974** ? D'où vient le nom de « révolution des Œillets » ?\n3. Quand meurt **Franco** ? Qui a-t-il désigné pour lui succéder, et quel choix ce successeur fait-il ?\n4. Que se passe-t-il en Espagne le **23 février 1981**, et comment l'événement se termine-t-il ?\n5. Quel événement commun aux deux pays a lieu en **1986** ?","bareme":[{"critere":"Estado Novo fondé par Salazar en 1933","points":4},{"critere":"Coup des officiers presque sans violence, œillets dans les canons","points":4},{"critere":"Mort de Franco le 20 novembre 1975, Juan Carlos qui ouvre le régime","points":4},{"critere":"Tentative de coup d'État militaire, échec grâce au refus public de Juan Carlos","points":4},{"critere":"Entrée des deux pays dans la CEE","points":4}],"dureeMin":7,"corrige":"1. L'**Estado Novo**, fondé par **Salazar** en **1933** (poursuivi par Caetano).\n2. Un **mouvement d'officiers renverse le régime presque sans effusion de sang** ; la population glisse des **œillets dans les canons** des fusils, d'où le nom.\n3. Franco meurt le **20 novembre 1975**, après trente-six ans de dictature. Il a désigné le roi **Juan Carlos**, qui, contre toute attente, **choisit d'ouvrir le régime**.\n4. Une **tentative de coup d'État militaire** ; elle **échoue** grâce au **refus public de Juan Carlos**.\n5. En **1986**, le Portugal et l'Espagne **entrent dans la CEE**."}$exo$::jsonb),
  ('aef00199-1d6e-522f-940d-71ad3a04d772'::uuid, 2, 'redaction', $exo${"titre":"Rupture ou transition négociée ?","consigne":"Classe les événements du document, puis explique les deux voies de sortie de dictature.","enonce":"**Document — Événements (dans le désordre)**\n\n- a. Les Cortès franquistes votent leur propre disparition.\n- b. Des guerres coloniales en Angola, au Mozambique et en Guinée absorbent près de la moitié du budget.\n- c. Des pactes sont signés entre gouvernement, patronat et syndicats.\n- d. Une décolonisation rapide et des nationalisations suivent la chute du régime.\n- e. Une constitution établit une monarchie parlementaire et l'État des autonomies.\n- f. Une loi d'amnistie est votée.\n\n1. Classe chaque événement selon le pays (Portugal ou Espagne) et donne sa date quand le cours la précise.\n2. Explique pourquoi on parle de **rupture** pour le Portugal et de **transition négociée** pour l'Espagne.\n3. Quel problème la loi d'amnistie a-t-elle laissé en suspens ?","bareme":[{"critere":"Portugal : b (depuis 1961), d (1974-1975) ; Espagne : a (1976), c et f (1977), e (1978)","points":8},{"critere":"Rupture : renversement par un mouvement d'officiers","points":4},{"critere":"Transition négociée : réformes votées par les institutions franquistes, Suárez, pactes de la Moncloa","points":5},{"critere":"Crimes du franquisme longtemps sans réponse","points":3}],"dureeMin":11,"corrige":"1.\n- **Portugal** : **b**, les guerres coloniales menées **depuis 1961**, qui épuisent le régime ; **d**, décolonisation rapide et nationalisations en **1974-1975**.\n- **Espagne** : **a**, en **1976**, Adolfo Suárez fait voter par les Cortès franquistes leur propre disparition (loi de réforme politique approuvée par référendum) ; **c**, les **pactes de la Moncloa** et **f**, la **loi d'amnistie**, en **1977** ; **e**, la **Constitution de 1978**.\n2. Au **Portugal**, le régime est **renversé** le 25 avril 1974 par un mouvement d'officiers : c'est une **rupture révolutionnaire**, suivie de tensions entre courants.\nEn **Espagne**, la démocratie naît **de l'intérieur du régime** : le successeur désigné par Franco ouvre le régime, les institutions franquistes votent leur disparition, les partis (communiste compris) sont légalisés, les forces sociales signent des **pactes** : c'est une **transition négociée**.\n3. La loi d'amnistie a laissé **longtemps sans réponse la question des crimes du franquisme** : la sortie de dictature s'est payée d'un compromis."}$exo$::jsonb),
  ('aef00199-1d6e-522f-940d-71ad3a04d772'::uuid, 3, 'redaction', $exo${"titre":"Deux chemins vers la démocratie","consigne":"Rédige une réponse organisée (introduction, deux ou trois parties, conclusion) qui compare précisément les deux pays.","enonce":"**Sujet.** « Le Portugal et l'Espagne (1974-1982) : deux chemins, un même résultat ? »\n\nTu compareras les causes de la sortie de dictature, les étapes et les acteurs, puis tu montreras ce que les deux transitions ont en commun. Tu expliqueras pourquoi le cours présente ce jalon comme « symétrique » du Chili et tu discuteras la phrase : « la sortie de dictature se paie toujours de compromis ».","bareme":[{"critere":"Portugal : Estado Novo usé par les guerres coloniales, 25 avril 1974, constitution de 1976","points":4},{"critere":"Espagne : mort de Franco, Juan Carlos, Suárez, 1977, constitution de 1978, échec du coup de 1981","points":5},{"critere":"Comparaison rupture / transition négociée et résultat commun (démocratie, CEE en 1986)","points":4},{"critere":"Symétrie avec le Chili : avancée contre recul de la démocratie","points":3},{"critere":"Discussion du compromis (loi d'amnistie)","points":4}],"dureeMin":18,"corrige":"**Introduction** : au milieu des années 1970, deux dictatures d'Europe du Sud deviennent des démocraties, par des voies opposées.\n\n**I. Le Portugal : la rupture.** L'**Estado Novo** (Salazar, 1933, puis Caetano) s'épuise dans les **guerres coloniales** menées depuis 1961 (près de la moitié du budget). Le **25 avril 1974**, des officiers le renversent presque sans violence (révolution des **Œillets**). Suivent la décolonisation, des nationalisations et des tensions, puis la **Constitution de 1976**.\n\n**II. L'Espagne : la transition négociée.** **Franco** meurt le 20 novembre 1975 ; **Juan Carlos**, qu'il avait désigné, ouvre le régime. En **1976**, **Adolfo Suárez** fait voter par les Cortès franquistes leur disparition (référendum). En **1977** : légalisation des partis, élections libres, **pactes de la Moncloa**, **loi d'amnistie**. **1978** : monarchie parlementaire et État des autonomies. Le **23 février 1981**, le coup d'État échoue par le refus public du roi.\n\n**III. Un résultat commun, des compromis.** Les deux pays deviennent des démocraties et entrent dans la **CEE en 1986** : il n'y a **pas une seule voie** vers la démocratie. Le jalon est **symétrique du Chili** : là, une démocratie recule vers la dictature ; ici, des dictatures avancent vers la démocratie. Mais la sortie a un prix : en Espagne, la loi d'amnistie laisse longtemps sans réponse les **crimes du franquisme**.\n\n**Conclusion** : un même résultat par deux chemins, chacun fait de compromis dont l'examen ne vient que plus tard."}$exo$::jsonb),
  ('cbd77eac-7f69-57a6-b9e4-534fcd11ef58'::uuid, 1, 'redaction', $exo${"titre":"Les institutions de l'Union et leur légitimité","consigne":"Complète le tableau, puis réponds à la question.","enonce":"1. Recopie et complète le tableau.\n\n| L'institution | Sa composition | Sa légitimité (directe ou indirecte) | Un rôle |\n| Parlement européen | … | … | … |\n| Commission | … | … | … |\n| Conseil de l'Union | … | … | … |\n| Conseil européen | … | … | … |\n\n2. Pourquoi reproche-t-on à la Commission une forme de « technocratie » ?","bareme":[{"critere":"Parlement : élu au suffrage universel direct depuis 1979, légitimité directe, colégifère, vote le budget, censure la Commission","points":5},{"critere":"Commission, Conseil de l'Union, Conseil européen : composition, légitimité indirecte, rôle","points":11},{"critere":"Membres nommés et monopole de l'initiative des textes","points":4}],"dureeMin":8,"corrige":"1.\n- **Parlement européen** : élu au **suffrage universel direct depuis 1979** ; légitimité **directe** ; il **colégifère**, vote le **budget**, investit et peut **censurer la Commission**.\n- **Commission** : membres **nommés** ; légitimité **indirecte** ; elle **propose les textes** et **veille aux traités**.\n- **Conseil de l'Union** : les **ministres des États** ; légitimité **indirecte**, tirée des gouvernements nationaux.\n- **Conseil européen** : les **chefs d'État et de gouvernement** ; légitimité **indirecte** ; il **fixe les orientations**.\n2. La Commission est composée de membres **nommés, non élus**, et c'est pourtant elle qui a l'**initiative des textes** : une institution non élue lance la législation, d'où le reproche de **technocratie**."}$exo$::jsonb),
  ('cbd77eac-7f69-57a6-b9e4-534fcd11ef58'::uuid, 2, 'redaction', $exo${"titre":"Un débat au conseil de la vie lycéenne","consigne":"Corrige chaque affirmation du document si elle est fausse, en justifiant avec le cours, puis réponds à la question 2.","enonce":"**Document — Affirmations entendues lors d'un débat entre élèves (situation imaginaire)**\n\n- a. « À Bruxelles, personne n'est élu par les citoyens. »\n- b. « Les citoyens européens n'ont aucun moyen de faire proposer un texte. »\n- c. « L'Union peut intervenir dans tous les domaines, même quand un État ferait mieux qu'elle. »\n- d. « Aucun pays ne peut quitter l'Union. »\n- e. « Aux élections européennes, on débat surtout de questions nationales. »\n\n1. Pour chaque affirmation, dis si elle est juste ou fausse et justifie.\n2. Une association lycéenne veut que l'Union légifère sur un sujet qui lui tient à cœur. Explique la démarche que le cours lui permet d'engager et ses conditions.","bareme":[{"critere":"a fausse (Parlement élu depuis 1979) ; d fausse (Brexit)","points":6},{"critere":"b fausse (initiative citoyenne) ; c fausse (subsidiarité)","points":6},{"critere":"e juste, reliée au déficit démocratique (absence d'espace public européen)","points":3},{"critere":"Initiative citoyenne : un million de citoyens demandent à la Commission de proposer un texte","points":5}],"dureeMin":12,"corrige":"1.\n- **a. Fausse** : le **Parlement européen** est élu au **suffrage universel direct depuis 1979** ; il a une légitimité directe.\n- **b. Fausse** : l'**initiative citoyenne européenne** permet à **un million de citoyens** de demander à la Commission de proposer un texte.\n- **c. Fausse** : le principe de **subsidiarité** veut que l'Union **n'agisse que si son action est plus efficace que celle des États**.\n- **d. Fausse** : le **Brexit** (2016-2020) a montré **qu'une sortie est possible**.\n- **e. Juste** : l'**abstention** est élevée aux européennes, qui se jouent souvent sur des **enjeux nationaux** ; il n'existe pas de partis véritablement européens, les débats restent nationaux. C'est l'un des éléments du « **déficit démocratique** ».\n2. L'association peut lancer une **initiative citoyenne européenne** : elle doit réunir le soutien d'**un million de citoyens**, qui **demandent à la Commission de proposer un texte**. La Commission garde l'initiative : l'initiative citoyenne est une **demande**, pas un vote de la loi."}$exo$::jsonb),
  ('cbd77eac-7f69-57a6-b9e4-534fcd11ef58'::uuid, 3, 'redaction', $exo${"titre":"Une démocratie sans peuple européen ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) qui discute le sujet.","enonce":"**Sujet.** « L'Union européenne souffre-t-elle d'un déficit démocratique ? »\n\nTu présenteras les institutions et leur légitimité, les critiques regroupées sous le nom de « déficit démocratique », les réponses apportées et les crises traversées. Tu discuteras la question du cours : peut-il y avoir une démocratie sans *demos* ?","bareme":[{"critere":"Légitimités directe et indirecte des institutions correctement présentées","points":4},{"critere":"Quatre critiques : initiative non élue, complexité, abstention, absence d'espace public européen","points":4},{"critere":"Réponses : pouvoirs du Parlement jusqu'à Lisbonne (2009), initiative citoyenne, subsidiarité, Charte","points":4},{"critere":"Crises : référendums de 2005, zone euro, Brexit ; mais décisions communes récentes","points":4},{"critere":"Discussion du demos : obstacle indépassable ou processus en cours","points":4}],"dureeMin":20,"corrige":"**Introduction** : l'UE n'est ni un État fédéral ni une simple organisation internationale ; sa légitimité démocratique fait débat depuis l'origine.\n\n**I. Une légitimité double.** Le **Parlement**, élu au suffrage universel direct depuis **1979**, a une légitimité **directe** (il colégifère, vote le budget, investit et peut censurer la Commission). Commission (membres nommés), Conseil de l'Union (ministres), Conseil européen (chefs d'État et de gouvernement) ont une légitimité **indirecte** ; la Cour de justice assure la primauté du droit.\n\n**II. Les critiques du « déficit démocratique ».** L'**initiative** appartient à une institution non élue ; la **complexité** rend les responsabilités illisibles ; l'**abstention** est élevée aux européennes, jouées sur des enjeux nationaux ; il n'y a **pas d'espace public européen** ni de partis vraiment européens. Les crises le confirment : rejet du traité constitutionnel par référendum en France et aux Pays-Bas (**2005**), poids des créanciers dans des décisions nationales lors de la crise de la zone euro (à partir de **2010**), **Brexit** (2016-2020).\n\n**III. Des réponses réelles.** Extension des pouvoirs du Parlement jusqu'au **traité de Lisbonne (2009)**, **initiative citoyenne** (un million de citoyens), **subsidiarité**, **Charte des droits fondamentaux** contraignante depuis 2009. Et les crises récentes ont conduit à des **décisions communes inédites**, sanitaires et budgétaires.\n\n**Conclusion** : le cœur du problème est l'absence de **demos**, de peuple qui se reconnaisse comme tel. Pour les uns, c'est un **obstacle indépassable** ; pour les autres, un **processus en cours**, comme le fut la construction des nations. Le déficit existe, mais il est discuté et en partie corrigé."}$exo$::jsonb),
  ('a7ba6e59-de87-5b23-acc7-c03187b60974'::uuid, 1, 'redaction', $exo${"titre":"Hard, soft et smart power","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Donne la définition de la **puissance** en relations internationales.\n2. Cite les quatre **attributs traditionnels** de la puissance avec un exemple chacun.\n3. Définis les trois notions de Joseph Nye : **hard power**, **soft power**, **smart power**. Pour chacune, précise son moyen et son coût.","bareme":[{"critere":"Capacité à imposer sa volonté, influencer et résister à l'influence des autres","points":4},{"critere":"Quatre attributs (militaire, économique, démographique et territorial, diplomatique) avec exemples","points":8},{"critere":"Hard, soft et smart power définis avec moyen et coût","points":8}],"dureeMin":8,"corrige":"1. La puissance est la **capacité d'un acteur à imposer sa volonté, à influencer les autres et à résister à leur influence**. Elle se mesure moins à ce qu'un État possède qu'à ce qu'il **obtient**.\n2. Attributs :\n- **militaire** : budget, capacité de projection, arme nucléaire, siège permanent au Conseil de sécurité ;\n- **économique** : PIB, monnaie de réserve, multinationales, technologies ;\n- **démographique et territorial** : population, ressources, contrôle des voies de passage ;\n- **diplomatique** : réseau d'alliances, présence dans les organisations.\n3.\n- **Hard power** : la **contrainte** (force militaire, sanction économique) ; coût **élevé**.\n- **Soft power** : l'**attraction** (culture, valeurs, modèle de société, langue, universités, cinéma) ; coût **faible**, mais il **ne se décrète pas**, il se constate.\n- **Smart power** : l'art de **combiner les deux à propos** ; il suppose du **jugement**."}$exo$::jsonb),
  ('a7ba6e59-de87-5b23-acc7-c03187b60974'::uuid, 2, 'redaction', $exo${"titre":"La politique étrangère de la Norlande","consigne":"Analyse les actions d'un État imaginaire avec les notions du cours.","enonce":"**Document — Une année de politique étrangère en Norlande (pays imaginaire)**\n\n- a. La Norlande impose des sanctions financières à un voisin qui menace ses frontières.\n- b. Elle double le nombre de bourses offertes aux étudiants étrangers dans ses universités.\n- c. Une de ses séries télévisées est regardée dans soixante pays.\n- d. Elle envoie des navires de guerre près d'un détroit disputé, tout en finançant un grand festival culturel dans le pays voisin pour apaiser l'opinion.\n- e. Son gouvernement lance une campagne publicitaire pour « décréter » que la Norlande est admirée partout.\n\n1. Classe les actions a à d en hard power, soft power ou smart power. Justifie.\n2. Pourquoi l'action e risque-t-elle d'échouer ?\n3. Pourquoi le soft power n'est-il pas une « puissance au rabais » ?","bareme":[{"critere":"a hard ; b et c soft ; d smart, avec justification","points":10},{"critere":"e : le soft power ne se décrète pas, il se constate","points":5},{"critere":"Obtenir sans contraindre coûte moins cher et dure plus longtemps","points":5}],"dureeMin":11,"corrige":"1.\n- **a. Hard power** : la **sanction économique** est un moyen de **contrainte**.\n- **b. Soft power** : les **universités** attirent des étudiants qui repartent avec un réseau et une familiarité durables ; c'est l'**attraction**.\n- **c. Soft power** : les **séries** diffusent des représentations et un modèle ; on obtient par l'attraction.\n- **d. Smart power** : la Norlande **combine** la démonstration de force (navires) et l'attraction (festival) ; c'est l'art de doser les deux, qui suppose du **jugement**.\n2. Le soft power **ne se décrète pas** : il **se constate**. On ne peut pas imposer l'admiration par une campagne ; l'attraction naît de ce que les autres trouvent désirable (culture, valeurs, modèle).\n3. Parce qu'**obtenir sans contraindre coûte moins cher et dure plus longtemps** : un pays admiré n'a pas besoin de forcer pour être suivi, alors que la contrainte est coûteuse et suscite la résistance."}$exo$::jsonb),
  ('a7ba6e59-de87-5b23-acc7-c03187b60974'::uuid, 3, 'redaction', $exo${"titre":"La puissance, une affaire d'États ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en mobilisant les notions et les exemples du cours.","enonce":"**Sujet.** « Au XXIe siècle, la puissance est-elle encore une affaire d'États ? »\n\nTu montreras que les États gardent les attributs traditionnels de la puissance, puis que d'autres acteurs pèsent désormais, notamment sur de nouveaux terrains. Tu situeras ta réflexion dans l'évolution du système international (bipolaire, unipolaire, multipolaire).","bareme":[{"critere":"Définition de la puissance et attributs traditionnels des États (dont siège permanent et veto)","points":4},{"critere":"Hard, soft, smart power mobilisés","points":3},{"critere":"Acteurs non étatiques : firmes, OI, ONG, réseaux criminels ou terroristes, plateformes","points":5},{"critere":"Nouveaux terrains : cyberespace, espace, normes, données","points":4},{"critere":"Configurations du système international et conclusion nuancée","points":4}],"dureeMin":18,"corrige":"**Introduction** : la puissance est la capacité d'imposer sa volonté, d'influencer et de résister ; longtemps pensée comme propre aux États.\n\n**I. Les États gardent les attributs de la puissance.** Militaire (budget, projection, nucléaire, **siège permanent au Conseil de sécurité** qui donne un **droit de veto**), économique (PIB, monnaie de réserve), démographique et territorial, diplomatique. Ils usent du **hard power** (contrainte), du **soft power** (attraction, qui ne se décrète pas) et du **smart power** (combinaison).\n\n**II. D'autres acteurs pèsent.** **Firmes multinationales** au chiffre d'affaires supérieur au PIB de nombreux pays ; **organisations internationales** qui produisent des normes ; **ONG** qui font l'agenda et l'opinion ; **réseaux criminels ou terroristes** qui contestent le monopole de la violence ; **plateformes numériques** qui infléchissent des débats publics entiers. Sur les **nouveaux terrains** (**cyberespace**, **espace** extra-atmosphérique, **normes** techniques et juridiques, **données**), un acteur privé peut peser autant qu'un État.\n\n**III. Un système international recomposé.** **Bipolaire** pendant la guerre froide, **unipolaire** après 1991 (moment américain), il est aujourd'hui **multipolaire** : États-Unis, Chine, Union européenne, Russie, Inde, puissances régionales.\n\n**Conclusion** : les États restent les acteurs centraux et les seuls à réunir tous les attributs, mais la puissance n'est plus leur monopole ; elle se partage avec des acteurs non étatiques, surtout sur les nouveaux terrains."}$exo$::jsonb),
  ('a0d16460-b834-519d-b973-89869ef77f63'::uuid, 1, 'redaction', $exo${"titre":"Le déclin de « l'homme malade de l'Europe »","consigne":"Réponds à chaque question en quelques lignes précises.","enonce":"1. Quand l'Empire ottoman atteint-il son apogée, sous quel sultan, et quels espaces contrôle-t-il ?\n2. Cite **quatre causes** du reflux ottoman et, pour chacune, son effet.\n3. Que sont les **capitulations** ? Qu'est-ce que l'Administration de la Dette publique ottomane (1881) ?","bareme":[{"critere":"Apogée au XVIe siècle avec Soliman le Magnifique, espaces cités","points":4},{"critere":"Quatre causes justes avec leur effet","points":10},{"critere":"Capitulations et Dette publique ottomane correctement définies","points":6}],"dureeMin":8,"corrige":"1. Au **XVIe siècle**, sous **Soliman le Magnifique** : Balkans, Anatolie, Proche-Orient, Afrique du Nord, et contrôle des routes entre l'Europe et l'Asie.\n2. Causes (quatre parmi) :\n- l'**échec devant Vienne (1683)** puis des défaites face à l'Autriche et à la Russie → **pertes de territoires** ;\n- le **contournement par les routes maritimes atlantiques** → son **avantage commercial est ruiné** ;\n- le **retard technique et industriel** face à une Europe qui s'industrialise ;\n- la montée des **nationalismes balkaniques** → indépendances de la Grèce (1830), puis Serbie, Roumanie, Bulgarie ;\n- la **dépendance financière**.\n3. Les **capitulations** donnent aux Européens des **privilèges commerciaux et judiciaires** dans l'Empire. L'**Administration de la Dette publique ottomane** (1881) place des **recettes de l'Empire sous contrôle étranger** : c'est la marque de sa dépendance financière."}$exo$::jsonb),
  ('a0d16460-b834-519d-b973-89869ef77f63'::uuid, 2, 'redaction', $exo${"titre":"La Russie après l'URSS","consigne":"Exploite la chronologie et le cours pour répondre aux questions.","enonce":"**Document — Chronologie**\n\n| Date | Événement |\n| Décembre 1991 | Disparition de l'URSS |\n| Années 1990 | Hyperinflation, privatisations, élargissement de l'OTAN, guerre en Tchétchénie |\n| À partir de 2000 | Reprise en main de l'État et des médias |\n| 2008 | Guerre en Géorgie |\n| 2014 | Crimée et Donbass |\n| 2022 | Invasion de l'Ukraine |\n\n1. Que perd la Russie avec la disparition de l'URSS ?\n2. Pourquoi peut-on parler d'« humiliation stratégique » dans les années 1990 ?\n3. Quels instruments la Russie utilise-t-elle à partir de 2000 pour redevenir une puissance ?\n4. Comment qualifier sa stratégie face au déclin, en la comparant à celle de l'Empire ottoman ?","bareme":[{"critere":"Près de la moitié de la population, un quart du territoire, le statut de superpuissance","points":5},{"critere":"Humiliation : effondrement économique, élargissement de l'OTAN, Tchétchénie","points":4},{"critere":"Instruments : État et médias repris en main, rente énergétique, modernisation militaire","points":5},{"critere":"Réaffirmation par la force (2008, 2014, 2022) opposée à la réforme ottomane","points":6}],"dureeMin":11,"corrige":"1. La Russie perd **près de la moitié de sa population**, **un quart de son territoire** et son **statut de superpuissance**.\n2. Dans les années 1990, elle connaît un **effondrement économique** (hyperinflation, privatisations) et voit l'**OTAN s'élargir** vers l'Est, tandis que la **guerre en Tchétchénie** l'enlise : elle subit au lieu de décider, d'où une **humiliation stratégique**.\n3. À partir de 2000 : **reprise en main de l'État et des médias**, usage de la **rente énergétique** (gaz, pétrole) **comme instrument diplomatique**, **modernisation militaire**.\n4. La Russie cherche à se **réaffirmer par la puissance militaire et énergétique** : Géorgie (2008), Crimée et Donbass (2014), invasion de l'Ukraine (2022). L'Empire ottoman, lui, avait tenté de se **réformer en s'européanisant** (Tanzimat, Jeunes-Turcs). Deux réponses opposées au déclin."}$exo$::jsonb),
  ('a0d16460-b834-519d-b973-89869ef77f63'::uuid, 3, 'redaction', $exo${"titre":"Deux déclins, deux réponses","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) qui compare les deux trajectoires.","enonce":"**Sujet.** « Le déclin d'une puissance est-il un effondrement soudain ? L'exemple de l'Empire ottoman et de la Russie post-soviétique. »\n\nTu montreras les causes des deux déclins, les réponses apportées par chacun, et tu dégageras ce que la comparaison enseigne sur la notion de puissance.","bareme":[{"critere":"Déclin ottoman : causes multiples étalées du XVIIe au XIXe siècle","points":5},{"critere":"Réponses ottomanes (Tanzimat, Jeunes-Turcs 1908) et leur échec jusqu'à 1923","points":4},{"critere":"Russie : pertes de 1991, années 1990, réaffirmation depuis 2000","points":5},{"critere":"Comparaison : réforme contre réaffirmation par la force","points":3},{"critere":"Conclusion : un processus long, les réponses pèsent autant que les causes","points":3}],"dureeMin":18,"corrige":"**Introduction** : aucune puissance n'est éternelle ; comparer deux déclins séparés d'un siècle.\n\n**I. L'Empire ottoman : un reflux sur trois siècles.** Apogée au XVIe siècle (Soliman). Puis l'**échec devant Vienne (1683)** et les défaites face à l'Autriche et à la Russie, le **contournement** par les routes atlantiques, le **retard technique et industriel**, les **nationalismes balkaniques** (Grèce 1830, Serbie, Roumanie, Bulgarie), la **dépendance financière** (capitulations, Dette publique ottomane en 1881). Réponse : se **réformer** en s'européanisant (**Tanzimat**, insuffisantes ; **Jeunes-Turcs** en 1908, sans renverser le mouvement). Défaite, traité de Sèvres, guerre d'indépendance (1918-1923) : naissance de la **République turque** de Mustafa Kemal.\n\n**II. La Russie : une chute brutale, une réaffirmation par la force.** En 1991, perte de près de la moitié de la population, d'un quart du territoire et du statut de superpuissance. Années 1990 : effondrement, humiliation stratégique. À partir de 2000 : reprise en main, **rente énergétique**, modernisation militaire, puis la force : Géorgie (2008), Crimée et Donbass (2014), Ukraine (2022).\n\n**III. Ce qu'enseigne la comparaison.** Deux stratégies : **se réformer** (Ottomans) ou **se réaffirmer** (Russie).\n\n**Conclusion** : le déclin est un **processus long**, fait de retards, de dépendances financières, de contestations internes et de recompositions du commerce mondial ; et **les réponses pèsent autant que les causes**."}$exo$::jsonb),
  ('72f69dbc-afe6-5f92-acef-dea0913e18f8'::uuid, 1, 'redaction', $exo${"titre":"Les passages qui commandent le monde","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Pour chacun de ces passages, dis ce qu'il commande : **Ormuz**, **Malacca**, les **canaux de Suez et de Panama**, les **câbles sous-marins**.\n2. Pourquoi les **routes arctiques** deviennent-elles un enjeu ?\n3. Que sont les **nouvelles routes de la soie** ? Quel risque peuvent-elles créer pour les pays partenaires ?","bareme":[{"critere":"Ormuz : pétrole du Golfe ; Malacca : commerce asiatique","points":6},{"critere":"Canaux : leur blocage désorganise le commerce mondial ; câbles : l'essentiel des données","points":6},{"critere":"Routes arctiques rendues praticables par le réchauffement","points":3},{"critere":"Programme chinois d'infrastructures, dépendance par la dette","points":5}],"dureeMin":7,"corrige":"1.\n- **Ormuz** : le **pétrole du Golfe**.\n- **Malacca** : le **commerce asiatique**.\n- **Suez et Panama** : leur **blocage momentané désorganise le commerce mondial**.\n- **Câbles sous-marins** : ils transportent **l'essentiel des données mondiales** ; leur vulnérabilité est devenue un sujet de sécurité.\n2. Le **réchauffement** les rend **praticables** : de nouvelles voies de passage s'ouvrent, donc de nouveaux enjeux de contrôle.\n3. C'est l'instrument chinois de puissance indirecte : **ports, chemins de fer, infrastructures**, qui créent des **liens économiques durables**. Le risque : des **dépendances par la dette** pour les pays partenaires."}$exo$::jsonb),
  ('72f69dbc-afe6-5f92-acef-dea0913e18f8'::uuid, 2, 'redaction', $exo${"titre":"Conseiller une puissance moyenne","consigne":"Tu es conseiller d'un gouvernement imaginaire. Réponds aux questions en t'appuyant sur des exemples du cours.","enonce":"**Situation.** L'Ostrie (pays imaginaire) compte 30 millions d'habitants, n'a qu'une petite armée et ne contrôle aucun détroit. Son gouvernement veut « peser dans le monde sans contraindre personne ».\n\n1. Propose **trois leviers** de puissance indirecte (culture, langue, universités, technologies, normes) et justifie chacun par un exemple ou une idée du cours.\n2. Un ministre propose de miser sur la production de semi-conducteurs. Pourquoi est-ce un levier de puissance ?\n3. Le ministre de l'Économie avertit : « Toute dépendance que nous créons chez les autres peut se retourner contre nous. » Explique cette mise en garde.","bareme":[{"critere":"Trois leviers pertinents justifiés (vague coréenne, universités, langue, normes)","points":9},{"critere":"Semi-conducteurs : production très concentrée, donc elle donne prise","points":4},{"critere":"Relations asymétriques, dépendance mutuelle qui contraint les deux parties","points":7}],"dureeMin":12,"corrige":"1. Leviers possibles (trois attendus) :\n- la **culture** (séries, musique, jeux vidéo) : la **vague coréenne** montre qu'**une puissance moyenne peut y réussir** ;\n- les **universités** : accueillir des étudiants étrangers, qui **repartent avec un réseau et une familiarité durables**, est **l'un des investissements d'influence les plus rentables** ;\n- la **langue** : elle ouvre des marchés et structure les normes et les réseaux universitaires (francophonie, instituts Confucius) ;\n- les **normes** techniques : **celui qui les fixe impose ses choix à tous ceux qui veulent vendre**.\n2. Les semi-conducteurs sont une **technologie critique** dont la **production est très concentrée géographiquement** : celui qui la maîtrise **donne prise** sur tous ceux qui en ont besoin.\n3. Ces formes de puissance créent des relations **asymétriques** durables, mais elles peuvent **se retourner** : une **dépendance mutuelle contraint les deux parties**. Les crises récentes ont montré que les **chaînes d'approvisionnement mondialisées exposent aussi ceux qui les dominent**."}$exo$::jsonb),
  ('72f69dbc-afe6-5f92-acef-dea0913e18f8'::uuid, 3, 'redaction', $exo${"titre":"Peser sans contraindre","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en mobilisant des exemples précis.","enonce":"**Sujet.** « Les formes indirectes de la puissance sont-elles les plus durables ? »\n\nTu étudieras successivement la culture et la langue, les technologies, puis la maîtrise des voies de communication. Tu discuteras ensuite les limites de cette puissance, en t'appuyant sur la notion de dépendance.","bareme":[{"critere":"Culture, langue, universités : exemples (Hollywood, vague coréenne, anglais scientifique)","points":5},{"critere":"Technologies critiques et normes","points":4},{"critere":"Voies de communication : détroits, canaux, câbles, routes arctiques, routes de la soie","points":5},{"critere":"Limites : asymétrie, dépendance mutuelle, chaînes d'approvisionnement","points":4},{"critere":"Conclusion argumentée qui répond au sujet","points":2}],"dureeMin":18,"corrige":"**Introduction** : à côté de la force, des formes de puissance agissent sans coercition ; le cours les dit souvent les plus durables.\n\n**I. Culture et langue.** Cinéma, séries, musique, jeux vidéo diffusent des représentations : **Hollywood**, la **vague coréenne** (réussite d'une puissance moyenne). La langue ouvre marchés, normes et réseaux : l'**anglais domine la publication scientifique** ; francophonie, hispanophonie, instituts Confucius. Les **universités** forment des étudiants qui repartent avec un réseau durable.\n\n**II. Technologies et normes.** **Semi-conducteurs** (production très concentrée), **réseaux** de télécommunication, **intelligence artificielle** (infrastructures de calcul), **terres rares** (transition énergétique). Fixer une **norme** technique, c'est imposer ses choix à tous ceux qui veulent vendre.\n\n**III. Les voies de communication.** Ormuz (pétrole du Golfe), Malacca (commerce asiatique), Bab el-Mandeb, Bosphore ; canaux de Suez et Panama, dont le blocage désorganise le commerce mondial ; **câbles sous-marins** (l'essentiel des données) ; **routes arctiques**. La Chine en fait un instrument avec les **nouvelles routes de la soie** : liens durables, parfois dépendance par la dette.\n\n**IV. Des limites.** Ces relations sont **asymétriques** mais réversibles : une **dépendance mutuelle contraint les deux parties**, et les chaînes d'approvisionnement mondialisées exposent **aussi ceux qui les dominent**.\n\n**Conclusion** : oui, car elles créent attachement et dépendances durables sans coût de la contrainte ; mais cette durabilité a un revers, la dépendance pouvant se retourner."}$exo$::jsonb),
  ('d31479de-cabb-57ee-a6f3-12cce3df08dc'::uuid, 1, 'redaction', $exo${"titre":"Une puissance complète","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Pourquoi dit-on que les États-Unis sont la seule **puissance complète** ?\n2. Donne un élément précis pour chacun des registres de leur puissance : militaire, économique, monétaire, culturel, scientifique.\n3. Quel double avantage le **dollar** leur donne-t-il ?","bareme":[{"critere":"Présents sur tous les registres à la fois","points":4},{"critere":"Un élément juste pour chacun des cinq registres","points":10},{"critere":"Financer leurs déficits et faire de la sanction financière une arme","points":6}],"dureeMin":7,"corrige":"1. Parce qu'ils sont **présents sur tous les registres à la fois** : militaire, économique, monétaire, culturel, scientifique.\n2.\n- **Militaire** : un budget **supérieur à celui des dix pays suivants réunis**, environ 750 bases dans 80 pays, onze porte-avions, l'OTAN.\n- **Économique** : premier ou deuxième PIB mondial, domination des secteurs de pointe.\n- **Monétaire** : le **dollar**, qui représente l'essentiel des réserves de change et des échanges.\n- **Culturel** : cinéma, séries, musique, plateformes, universités, langue.\n- **Scientifique** : dépenses de recherche, brevets, capacité d'attirer les chercheurs du monde entier.\n3. Le dollar leur permet de **financer leurs déficits** et de **faire de la sanction financière une arme**."}$exo$::jsonb),
  ('d31479de-cabb-57ee-a6f3-12cce3df08dc'::uuid, 2, 'redaction', $exo${"titre":"Nuancer un jugement sur l'Amérique","consigne":"Discute l'affirmation du document en trois temps, en t'appuyant sur le cours.","enonce":"**Document — Extrait d'un billet de blog (imaginaire)**\n\n> « Les États-Unis, c'est fini : le monde est désormais multipolaire, donc toutes les grandes puissances se valent. D'ailleurs, les Américains sont trop divisés pour mener une politique étrangère, et la Chine les a déjà remplacés partout. »\n\n1. Relève dans le texte **deux affirmations excessives** et corrige-les avec le cours.\n2. Présente les **limites internes** réelles de la puissance américaine.\n3. Sur quels terrains la **Chine** conteste-t-elle la primauté américaine ? Cite aussi deux autres formes de contestation.","bareme":[{"critere":"Multipolarité ne signifie pas égalité des pôles ; seule puissance réunissant tous les attributs","points":6},{"critere":"Déclin relatif et non fin de la puissance ; Chine contestataire, non remplaçante","points":3},{"critere":"Limites internes : polarisation, inégalités, dette, débat sur l'engagement extérieur","points":6},{"critere":"Terrains chinois et autres contestations (Russie, puissances moyennes, dédollarisation)","points":5}],"dureeMin":12,"corrige":"1. Affirmations excessives :\n- « **toutes les grandes puissances se valent** » : faux, **multipolarité ne signifie pas égalité des pôles** ; les États-Unis restent **la seule puissance qui réunisse tous les attributs**.\n- « **c'est fini** » / « **la Chine les a déjà remplacés** » : la puissance américaine est **relativement moins dominante qu'en 1991**, mais elle n'a pas disparu ; la Chine la **conteste**, elle ne l'a pas remplacée.\n2. Limites internes : la **polarisation politique** rend la politique étrangère **moins prévisible** d'une administration à l'autre (d'où le « trop divisés », qui contient une part de vrai) ; les **inégalités** sociales, sanitaires et raciales fragilisent la cohésion ; la **dette publique** est une contrainte budgétaire ; les guerres d'**Irak et d'Afghanistan** ont nourri un débat durable sur l'engagement extérieur.\n3. La Chine conteste sur **presque tous les registres** : commerce, technologies, monnaie, mer de Chine méridionale, influence en Afrique et en Asie. Autres contestations : la **Russie** (l'ordre européen, par la force), les **puissances moyennes** aux politiques plus autonomes, les projets de **dédollarisation** (encore limités)."}$exo$::jsonb),
  ('d31479de-cabb-57ee-a6f3-12cce3df08dc'::uuid, 3, 'redaction', $exo${"titre":"La primauté américaine en question","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Les États-Unis, une puissance toujours dominante mais contestée ? »\n\nTu présenteras les fondements de la puissance américaine et ses moyens d'action, puis ses limites internes et les contestations externes. Tu expliqueras en conclusion pourquoi le cours décrit les États-Unis comme « le principal architecte de l'ordre international issu de 1945 et l'un de ses contestataires occasionnels ».","bareme":[{"critere":"Fondements sur les cinq registres, avec des données précises","points":5},{"critere":"Moyens d'exercice : alliances, présence militaire, sanctions, diplomatie, culture, institutions","points":3},{"critere":"Limites internes","points":4},{"critere":"Contestations externes et nuance multipolarité / égalité","points":4},{"critere":"Explication du double rôle d'architecte et de contestataire","points":4}],"dureeMin":18,"corrige":"**Introduction** : au début des années 2020, les États-Unis sont la seule puissance complète, mais leur position relative se transforme.\n\n**I. Une puissance complète.** Militaire (budget supérieur aux dix suivants réunis, ~750 bases dans 80 pays, onze porte-avions, OTAN), économique (premier ou deuxième PIB, secteurs de pointe), **monétaire** (le dollar finance les déficits et fait de la sanction financière une arme), culturel, scientifique. Ils l'exercent par les alliances, la présence militaire, les sanctions, la diplomatie, l'influence culturelle et leur rôle dans les institutions internationales.\n\n**II. Des fragilités internes.** Polarisation politique (politique étrangère moins prévisible), inégalités, dette publique, débat sur l'engagement extérieur après l'Irak et l'Afghanistan.\n\n**III. Une primauté contestée.** La **Chine** sur presque tous les terrains (commerce, technologies, monnaie, mer de Chine méridionale, Afrique et Asie), la **Russie** par la force, les puissances moyennes, la dédollarisation encore limitée. Leur puissance est **relativement** moins dominante qu'en 1991, mais **multipolarité ne signifie pas égalité des pôles**.\n\n**Conclusion** : ils ont été le **principal architecte** de l'ordre de 1945 (institutions, alliances), mais s'en écartent parfois **au nom de leurs intérêts** : ils en sont aussi des **contestataires occasionnels**. Dominants, donc, mais contestés, y compris par leurs propres choix."}$exo$::jsonb),
  ('3481d305-9ba4-5ea3-af54-f5dfc7910c17'::uuid, 1, 'redaction', $exo${"titre":"Classer les frontières","consigne":"Réponds à chaque question en t'appuyant sur la typologie du cours.","enonce":"1. Définis une **frontière**. Sous quels trois aspects peut-on la considérer ?\n2. Classe chacune de ces frontières (exemples imaginaires) selon son **tracé** :\n   - a. une frontière qui suit une ligne droite de 800 km dans un désert ;\n   - b. une frontière qui suit la ligne de crête d'une montagne ;\n   - c. une frontière qui suit le cours d'un fleuve.\n3. Pourquoi l'expression « frontière naturelle » est-elle **trompeuse** ?","bareme":[{"critere":"Limite d'un territoire souverain ; ligne sur une carte, institution juridique, fait social vécu","points":6},{"critere":"a géométrique ; b et c dites naturelles","points":6},{"critere":"Un fleuve unit les rives ; toute frontière est une construction politique","points":8}],"dureeMin":7,"corrige":"1. Une frontière est la **limite d'un territoire souverain**. Elle est à la fois une **ligne sur une carte**, une **institution juridique** et un **fait social vécu**.\n2.\n- **a** : frontière **géométrique**, tracée à la règle (fréquente en Afrique et en Amérique du Nord).\n- **b** : frontière dite **naturelle** (crête).\n- **c** : frontière dite **naturelle** (fleuve).\n3. Un fleuve n'a rien de naturellement séparateur : il fut longtemps un **axe de circulation qui unit les deux rives**. Si une frontière suit un fleuve, c'est parce qu'**on a décidé** qu'elle le suivrait : une frontière est toujours une **construction politique**."}$exo$::jsonb),
  ('3481d305-9ba4-5ea3-af54-f5dfc7910c17'::uuid, 2, 'redaction', $exo${"titre":"L'îlot de Kerval","consigne":"Lis la situation et réponds en t'appuyant sur le droit de la mer et sur le cours.","enonce":"**Situation (imaginaire).** L'îlot de Kerval est un rocher inhabité de quelques hectares, situé en plein océan à plus de 500 milles de toute autre terre. Deux États s'en disputent la souveraineté ; des gisements de poissons et de minerais se trouvent au fond de la mer alentour.\n\n1. Selon la convention de **Montego Bay (1982)**, jusqu'où s'étendent la **mer territoriale** et la **zone économique exclusive** autour d'un territoire ?\n2. Pourquoi ce rocher, sans habitant, a-t-il une grande valeur stratégique ?\n3. En dehors de la mer, cite deux autres domaines où s'exercent des frontières autres que terrestres, et explique-les.","bareme":[{"critere":"Mer territoriale à 12 milles, ZEE à 200 milles","points":6},{"critere":"La ZEE ouvre des droits sur 200 milles de ressources, d'où l'intérêt des îles modestes","points":7},{"critere":"Frontières aérienne (superposée au sol) et numérique (filtrage, contrôle, localisation des données)","points":7}],"dureeMin":10,"corrige":"1. La **mer territoriale** s'étend à **12 milles** marins, la **zone économique exclusive (ZEE)** à **200 milles**.\n2. Posséder l'îlot ouvre une **ZEE** tout autour : des **droits sur 200 milles de ressources** (pêche, minerais du fond). Comme aucune autre terre n'est à moins de 500 milles, cette zone n'est partagée avec personne. C'est pourquoi le cours souligne l'**intérêt stratégique des îles les plus modestes** : quelques rochers suffisent.\n3.\n- **Frontière aérienne** : l'espace aérien est **superposé à l'espace terrestre** ; survoler un territoire suppose l'accord de l'État.\n- **Frontière numérique** : **contrôle national d'Internet**, **filtrage**, **localisation obligatoire des données** sur le territoire."}$exo$::jsonb),
  ('3481d305-9ba4-5ea3-af54-f5dfc7910c17'::uuid, 3, 'redaction', $exo${"titre":"La mondialisation efface-t-elle les frontières ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) en utilisant les données du document.","enonce":"**Document — Nombre de murs frontaliers dans le monde (d'après le cours)**\n\n| L'époque | Le nombre de murs frontaliers |\n| À la chute du mur de Berlin (1989) | Moins d'une dizaine |\n| Aujourd'hui | Plusieurs dizaines |\n\n**Sujet.** « La mondialisation fait-elle disparaître les frontières ? »\n\nTu utiliseras la typologie des frontières (tracé, origine, fonction), la distinction entre ligne, zone et mur, et les frontières non terrestres.","bareme":[{"critere":"Définition et typologie (tracé, origine, fonction) mobilisées","points":4},{"critere":"Ligne, zone et mur distingués","points":3},{"critere":"Document exploité : multiplication des murs depuis 1989","points":4},{"critere":"Idée de différenciation : ouvertes aux capitaux et marchandises, sélectives pour les personnes selon le passeport","points":5},{"critere":"Frontières maritimes et numériques comme nouveaux enjeux ; conclusion claire","points":4}],"dureeMin":18,"corrige":"**Introduction** : une frontière est la limite d'un territoire souverain ; la mondialisation, par l'intensité des flux, a fait croire à sa disparition.\n\n**I. Des frontières multiples, toujours politiques.** Typologie : par le **tracé** (naturelles ou géométriques), l'**origine** (traité, guerre, décolonisation, référendum), la **fonction** (ouvertes ou fermées, contrôlées ou poreuses, militarisées ou invisibles). Même dite « naturelle », une frontière est une **construction politique**. Elle peut être une **ligne** nette, une **zone** de transition où l'autorité s'estompe, ou un **mur**, la matérialisation la plus brutale de la ligne.\n\n**II. Le paradoxe : plus de flux, plus de murs.** Le document montre qu'on est passé de **moins d'une dizaine** de murs en 1989 à **plusieurs dizaines** aujourd'hui. Les frontières s'étendent aussi : **maritimes** (ZEE de 200 milles, qui rend stratégiques des îles minuscules), **aériennes**, **numériques** (filtrage, localisation des données).\n\n**III. Une frontière différenciée.** La mondialisation n'efface pas les frontières : elle les **différencie**. Elles sont **très ouvertes aux capitaux et aux marchandises**, **sélectives pour les personnes**, et **d'autant plus selon le passeport** que l'on détient.\n\n**Conclusion** : non ; la mondialisation transforme la fonction des frontières plus qu'elle ne les supprime, et elle en crée de nouvelles."}$exo$::jsonb),
  ('f0431fa1-bb0a-5633-b3cd-60c7b6283216'::uuid, 1, 'redaction', $exo${"titre":"Quatre moments du traçage","consigne":"Complète le tableau puis réponds à la question.","enonce":"1. Recopie et complète le tableau.\n\n| Le moment | Sa date | Ce qu'il pose |\n| Traités de Westphalie | … | … |\n| Conférence de Berlin | … | … |\n| Traités de l'après-guerre | 1919-1920 | … |\n| Décolonisation | Années 1960 | … |\n\n2. Pourquoi le droit des peuples à disposer d'eux-mêmes, énoncé par Wilson, était-il **inapplicable à la lettre** ?","bareme":[{"critere":"Westphalie 1648 : souveraineté territoriale exclusive","points":4},{"critere":"Berlin 1884-1885 : partage de l'Afrique sans consultation, tracés géométriques","points":4},{"critere":"1919-1920 : droit des peuples ; décolonisation : uti possidetis juris","points":6},{"critere":"Peuplements mêlés : impossible de faire coïncider peuples et frontières","points":6}],"dureeMin":8,"corrige":"1.\n- **Westphalie**, **1648** : la **souveraineté territoriale exclusive**, acte de naissance du système international moderne.\n- **Berlin**, **1884-1885** : le **partage de l'Afrique** entre Européens, **sans consultation** ni connaissance des réalités locales, d'où des **tracés géométriques** et des **peuples coupés**.\n- **1919-1920** : le **droit des peuples à disposer d'eux-mêmes**, énoncé par Wilson.\n- **Décolonisation** : l'**uti possidetis juris** : les nouveaux États **héritent des frontières coloniales**.\n2. Parce que là où les **peuplements sont mêlés**, aucune ligne ne peut séparer proprement les peuples : toute frontière laisse des minorités de l'autre côté."}$exo$::jsonb),
  ('f0431fa1-bb0a-5633-b3cd-60c7b6283216'::uuid, 2, 'redaction', $exo${"titre":"Le différend du Val d'Ardène","consigne":"Analyse la situation imaginaire avec les outils du cours.","enonce":"**Situation (imaginaire).** Deux États voisins, l'Orsanie et la Belmorie, se disputent le Val d'Ardène.\n\n- Une rivière y fournit l'eau d'irrigation des deux pays.\n- Une population de langue belmorienne vit du côté orsanien de la frontière actuelle.\n- Un monastère, présenté comme le « berceau de la nation » belmorienne, se trouve dans la vallée.\n- La frontière actuelle a été fixée par un traité que la Belmorie n'a jamais reconnu.\n\n1. Identifie les **quatre facteurs** qui rendent ce tracé conflictuel. Justifie chacun.\n2. Présente **quatre moyens** de régler le différend, en précisant leur nature.\n3. Que risque-t-il de se passer si aucun moyen n'aboutit ? Donne un exemple réel cité par le cours.","bareme":[{"critere":"Quatre facteurs : ressource (eau), population partagée, valeur symbolique, absence de reconnaissance","points":8},{"critere":"Quatre moyens : négociation, médiation, Cour internationale de justice, référendum d'autodétermination","points":8},{"critere":"Conflit installé, avec un exemple (Cachemire, Sahara occidental, Chypre, Ukraine)","points":4}],"dureeMin":12,"corrige":"1.\n- **Ressource** : la rivière fournit l'**eau** d'irrigation des deux pays.\n- **Population partagée** : une **minorité** belmorienne vit de l'autre côté de la frontière.\n- **Valeur symbolique** : le monastère est présenté comme un **berceau national revendiqué**.\n- **Absence de reconnaissance** : le tracé n'est **admis que par une partie**, l'Orsanie.\n2.\n- La **négociation** bilatérale : moyen **politique**.\n- La **médiation** : un **tiers facilite** l'accord.\n- La **Cour internationale de justice** : moyen **juridictionnel**.\n- Un **référendum d'autodétermination** : la population décide (exemple : le **Soudan du Sud en 2011**).\n3. Faute d'accord, **le conflit s'installe** durablement : **Cachemire**, **Sahara occidental**, **Chypre**, la ligne de contrôle en **Ukraine**. Une frontière n'existe pleinement que si les autres l'**acceptent**."}$exo$::jsonb),
  ('f0431fa1-bb0a-5633-b3cd-60c7b6283216'::uuid, 3, 'redaction', $exo${"titre":"La stabilité contre la justice du tracé","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) qui discute l'arbitrage de 1964.","enonce":"**Document — La décision de l'OUA (d'après le cours)**\n\n> En 1964, l'Organisation de l'unité africaine choisit de conserver les frontières héritées de la colonisation, non parce que ces frontières seraient justes, mais parce que les rouvrir toutes provoquerait des guerres en chaîne.\n\n**Sujet.** « Faut-il conserver des frontières que l'on sait arbitraires ? »\n\nTu expliqueras d'où viennent ces frontières, les raisons du choix de 1964, puis ses limites. Tu montreras que tracer une frontière est un acte politique.","bareme":[{"critere":"Origine : conférence de Berlin, partage sans consultation, peuples coupés","points":4},{"critere":"Uti possidetis juris défini et relié à la décolonisation","points":4},{"critere":"Argument de la stabilité (guerres en chaîne) expliqué","points":4},{"critere":"Limites : facteurs de conflit, frontières non reconnues, conflits installés","points":4},{"critere":"Frontière comme acte politique et relation ; conclusion nuancée","points":4}],"dureeMin":18,"corrige":"**Introduction** : tracer une frontière désigne un « nous » et un « eux », attribue des ressources et engage des générations. En Afrique, les frontières héritées de la colonisation sont reconnues arbitraires.\n\n**I. Des frontières nées du partage colonial.** À la **conférence de Berlin (1884-1885)**, les Européens se partagent l'Afrique sans consulter les populations ni connaître les réalités locales : tracés **géométriques**, **peuples coupés**. À la décolonisation (années 1960), le principe de l'**uti possidetis juris** fait hériter les nouveaux États des frontières coloniales.\n\n**II. Le choix de la stabilité.** L'OUA l'assume en **1964** : rouvrir toutes les frontières **provoquerait des guerres en chaîne**. Elle arbitre en faveur de la **stabilité** contre la **justice** du tracé. Le précédent de 1919-1920 montre d'ailleurs qu'aucun tracé ne satisfait tout le monde quand les peuplements sont mêlés.\n\n**III. Un choix qui ne règle pas tout.** Un tracé reste conflictuel s'il touche des **ressources**, une **population partagée**, un lieu à **valeur symbolique**, ou s'il n'est **pas reconnu** par une partie. Certains différends sont réglés (négociation, médiation, Cour internationale de justice, référendum comme au **Soudan du Sud en 2011**), d'autres s'installent.\n\n**Conclusion** : conserver des frontières arbitraires peut être le moindre mal ; mais une frontière n'est pas qu'un tracé, c'est une **relation** qui n'existe pleinement que si les autres l'**acceptent**."}$exo$::jsonb),
  ('638a15ae-409b-5dc1-b3b9-1aec4c03969b'::uuid, 1, 'redaction', $exo${"titre":"Reconnaître un État","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Qu'est-ce qu'un **État de facto** ? Cite deux exemples donnés par le cours.\n2. Pourquoi la reconnaissance d'un État est-elle un **acte politique** et non un simple constat ? Appuie-toi sur le cas du **Kosovo**.\n3. Cite les **quatre fonctions** d'une frontière et ce que chacune assure.","bareme":[{"critere":"État de facto : territoire, population, administration mais pas de reconnaissance ; deux exemples","points":6},{"critere":"Reconnaissance politique : regard des autres, contentieux internes (Kosovo)","points":6},{"critere":"Protection, identité, régulation, fiscalité, avec leur contenu","points":8}],"dureeMin":7,"corrige":"1. Un **État de facto** a un **territoire**, une **population** et une **administration**, mais **pas de reconnaissance** internationale. Exemples : **Somaliland**, **Transnistrie**, **Ossétie du Sud**, Haut-Karabagh avant 2023.\n2. Les critères matériels ne suffisent pas : il faut le **regard des autres**. Chaque État décide de reconnaître ou non, notamment **en fonction de ses propres contentieux internes** : le **Kosovo** est reconnu par une centaine d'États et refusé par d'autres.\n3.\n- **Protection** : sécurité, contrôle des entrées.\n- **Identité** : la désignation d'un « nous ».\n- **Régulation** : normes, sanitaire, migrations.\n- **Fiscalité** : douanes, impôts, redistribution."}$exo$::jsonb),
  ('638a15ae-409b-5dc1-b3b9-1aec4c03969b'::uuid, 2, 'redaction', $exo${"titre":"Ouvrir à l'intérieur, fermer à l'extérieur","consigne":"Explique le paradoxe de Schengen puis analyse les situations du document.","enonce":"**Document — Quatre situations**\n\n- a. Une infirmière vit en France et travaille chaque jour de l'autre côté de la frontière, dans un hôpital d'une eurorégion.\n- b. Une entreprise numérique enregistre ses bénéfices dans le pays où l'impôt est le plus faible, sans y avoir d'activité réelle.\n- c. Au printemps 2020, des postes-frontières fermés depuis des années sont réactivés en quelques jours.\n- d. Après le Brexit, des contrôles réapparaissent entre le Royaume-Uni et ses voisins européens.\n\n1. Explique la phrase du cours : « Ouvrir à l'intérieur, c'est fermer davantage à l'extérieur. »\n2. Pour chaque situation, dis si elle illustre le **dépassement** ou le **retour** des frontières, et quelle notion du cours elle montre.","bareme":[{"critere":"Schengen : contrôles intérieurs supprimés, frontière extérieure renforcée, bases de données, agence de garde-frontières","points":6},{"critere":"a : dépassement, coopération transfrontalière","points":3},{"critere":"b : dépassement, flux immatériels et question de la fiscalité","points":4},{"critere":"c et d : retour des frontières (pandémie, Brexit)","points":7}],"dureeMin":11,"corrige":"1. **Schengen** supprime les **contrôles aux frontières intérieures**. Mais une frontière ouverte n'est pas abolie : cette ouverture suppose une **frontière extérieure renforcée**, des **bases de données communes** et une **agence de garde-frontières**. Plus on circule librement à l'intérieur, plus on contrôle à l'entrée.\n2.\n- **a** : **dépassement** ; c'est la **coopération transfrontalière** (eurorégions, bassins de vie partagés, services communs, travailleurs frontaliers).\n- **b** : **dépassement** ; les **flux immatériels** (capitaux, données) ignorent largement les frontières, d'où la question de la **régulation** et de la **fiscalité**.\n- **c** : **retour** ; lors de la **pandémie**, des frontières que l'on croyait effacées **se referment en quelques jours**.\n- **d** : **retour** ; le **Brexit** réinstalle une frontière **là où elle avait disparu**."}$exo$::jsonb),
  ('638a15ae-409b-5dc1-b3b9-1aec4c03969b'::uuid, 3, 'redaction', $exo${"titre":"Murs ou monde sans frontières ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) qui ne se contente pas de choisir un camp.","enonce":"**Sujet.** « Les frontières en débat : faut-il les établir ou les dépasser ? »\n\nTu montreras que certains veulent établir de nouvelles frontières (question de la reconnaissance), que d'autres veulent les dépasser, et que les frontières font aujourd'hui leur retour. Tu conclus en expliquant pourquoi le thème invite à raisonner en termes de **fonctions** de la frontière.","bareme":[{"critere":"Reconnaissance : États de facto, Kosovo, acte politique","points":4},{"critere":"Dépassement : Schengen, coopération transfrontalière, flux immatériels","points":4},{"critere":"Paradoxe de la frontière extérieure renforcée","points":3},{"critere":"Retour des frontières : migrations, sécurité, Brexit, pandémie","points":4},{"critere":"Quatre fonctions et idée d'arbitrage entre elles","points":5}],"dureeMin":18,"corrige":"**Introduction** : les frontières sont contestées de deux façons opposées : certains veulent en établir de nouvelles, d'autres les dépasser.\n\n**I. Établir des frontières : la reconnaissance.** Un État n'existe pleinement qu'une fois **reconnu**. Les **États de facto** (Somaliland, Transnistrie, Ossétie du Sud, Haut-Karabagh avant 2023) ont territoire, population et administration sans reconnaissance. Le **Kosovo**, reconnu par une centaine d'États, montre qu'on reconnaît aussi selon ses propres contentieux : c'est un **acte politique**.\n\n**II. Dépasser les frontières.** Intégration régionale (**Schengen**, marché unique, libre circulation), **coopération transfrontalière** (eurorégions, travailleurs frontaliers), **flux immatériels** (capitaux, données) qui posent la question de la régulation et de la fiscalité. Mais ouvrir à l'intérieur, c'est **fermer davantage à l'extérieur** : frontière extérieure renforcée, bases de données, agence de garde-frontières.\n\n**III. Le retour des frontières.** Rétablissement temporaire de contrôles lors des crises migratoires, barrières face aux crises sécuritaires, **Brexit**, **pandémie** qui referme les frontières en quelques jours.\n\n**Conclusion** : il ne s'agit pas de choisir entre un monde de murs et un monde sans frontières. La frontière remplit plusieurs **fonctions** (protection, identité, régulation, fiscalité), et **chaque projet d'ouverture ou de fermeture arbitre entre elles**."}$exo$::jsonb),
  ('5298ff3e-5d98-5251-85c5-066eab561735'::uuid, 1, 'redaction', $exo${"titre":"L'effet frontière","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Définis l'**effet frontière**.\n2. Pour chacune de ces activités, dis quel **écart** entre les deux côtés de la frontière elle exploite :\n   - a. une station-service juste de l'autre côté de la frontière ;\n   - b. un travailleur qui habite en France et travaille au Luxembourg ;\n   - c. une *maquiladora* mexicaine ;\n   - d. un réseau de contrebande.\n3. Que se passerait-il si les deux côtés d'une frontière étaient identiques ?","bareme":[{"critere":"Définition : l'écart de législation, fiscalité, salaires ou prix crée de l'activité","points":5},{"critere":"a prix/fiscalité ; b salaires ; c salaires mexicains et accès au marché américain ; d régimes juridiques","points":10},{"critere":"Ni flux, ni activité, ni intérêt à traverser : l'asymétrie fait la frontière vivante","points":5}],"dureeMin":7,"corrige":"1. L'**effet frontière** : la différence de **législation**, de **fiscalité**, de **salaires** ou de **prix** entre deux pays **crée de l'activité parce que la frontière existe**.\n2.\n- **a** : l'écart de **prix et de fiscalité** (carburant).\n- **b** : l'écart de **salaires**.\n- **c** : les **salaires mexicains** **et** l'**accès au marché américain**.\n- **d** : l'écart entre deux **régimes juridiques**.\n3. Il n'y aurait **ni flux, ni activité, ni intérêt à traverser** : c'est l'**asymétrie** qui rend la frontière vivante. La frontière **crée de la ressource** en même temps qu'elle sépare."}$exo$::jsonb),
  ('5298ff3e-5d98-5251-85c5-066eab561735'::uuid, 2, 'redaction', $exo${"titre":"Une journée de frontalière","consigne":"Lis le témoignage et réponds en t'appuyant sur le cours.","enonce":"**Document — Témoignage imaginaire de Sonia, 34 ans**\n\n> « J'habite en Lorraine et je travaille à Luxembourg, comme des dizaines de milliers de personnes. Je gagne plus qu'en France, mais c'est compliqué : je dois déclarer mes revenus dans deux pays, mon diplôme d'aide-soignante n'a pas été reconnu tout de suite. L'autre jour, une ambulance appelée d'un village voisin, mais de l'autre côté de la frontière, a dû attendre des secours de son propre pays, plus éloignés. Et personne ne sait vraiment combien nous sommes à faire ce trajet. »\n\n1. Dans quelle région transfrontalière vit Sonia ? Qu'intègre cette région ?\n2. Quel effet frontière explique son choix de travailler au Luxembourg ?\n3. Relève dans le témoignage **quatre obstacles** typiques des régions transfrontalières et donne leur conséquence.\n4. Qui peut agir pour lever ces obstacles ?","bareme":[{"critere":"La Grande Région autour du Luxembourg : transports, emploi, équipements","points":4},{"critere":"Écart de salaires","points":3},{"critere":"Quatre obstacles : fiscalité et social, diplômes, secours bloqués, statistiques, avec conséquences","points":9},{"critere":"Acteurs à plusieurs niveaux : États, régions, communes, entreprises, associations, habitants","points":4}],"dureeMin":12,"corrige":"1. La **Grande Région**, autour du Luxembourg ; elle intègre **transports, emploi, équipements**.\n2. L'écart de **salaires** : on gagne plus au Luxembourg qu'en France.\n3. Obstacles :\n- **régimes fiscaux et sociaux différents** (revenus déclarés dans deux pays) → **situations personnelles complexes** ;\n- **diplôme non reconnu** → **marché du travail cloisonné** ;\n- **secours bloqués à la ligne** (l'ambulance attend des secours plus éloignés) → **délais absurdes** ;\n- **statistiques incompatibles** (« personne ne sait combien nous sommes ») → **on ne sait pas mesurer le bassin de vie**.\n4. La frontière est gérée **à plusieurs niveaux** : **États, régions, communes, entreprises, associations, habitants**. C'est un espace de **négociation permanente**, où **le local pèse souvent plus que le national**."}$exo$::jsonb),
  ('5298ff3e-5d98-5251-85c5-066eab561735'::uuid, 3, 'redaction', $exo${"titre":"La frontière, une ressource ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) avec des exemples précis.","enonce":"**Sujet.** « La frontière sépare-t-elle seulement, ou crée-t-elle aussi de la ressource ? »\n\nTu t'appuieras sur l'effet frontière, les régions transfrontalières et leurs obstacles, les métropoles frontalières, et la question des acteurs qui gèrent ces espaces.","bareme":[{"critere":"Effet frontière avec au moins trois activités (commerces, travail frontalier, maquiladoras, trafics)","points":5},{"critere":"Régions transfrontalières : Grande Région, Öresund, Rhin supérieur","points":4},{"critere":"Obstacles qui rappellent la séparation","points":4},{"critere":"Métropoles frontalières (Ciudad Juárez et El Paso, Bâle, Genève)","points":3},{"critere":"Gestion multiniveau et idée d'asymétrie qui fait la frontière vivante","points":4}],"dureeMin":18,"corrige":"**Introduction** : une frontière n'est pas seulement une limite ; c'est un espace habité, avec ses activités, ses métiers et ses paysages.\n\n**I. Une ressource née de l'écart.** L'**effet frontière** : commerces frontaliers, stations-service, pharmacies, tabac exploitent l'écart de **prix et de fiscalité** ; le **travail frontalier** exploite l'écart de **salaires** (Luxembourg, Suisse, Allemagne, Tijuana vers San Diego) ; les **maquiladoras** combinent salaires mexicains et accès au marché américain ; contrebande et passeurs exploitent l'écart des **régimes juridiques**.\n\n**II. Des espaces intégrés mais encore séparés.** La **Grande Région** (transports, emploi, équipements), l'**Öresund** (un pont et un bassin d'emploi commun entre Danemark et Suède), le **Rhin supérieur** (trois pays, des institutions dédiées). Mais la séparation demeure : régimes fiscaux et sociaux différents, diplômes non reconnus, secours bloqués à la ligne, statistiques incompatibles.\n\n**III. La frontière vécue et négociée.** Dans les métropoles frontalières (**Ciudad Juárez et El Paso**, **Bâle** au contact de trois pays, **Genève** dont le bassin d'emploi déborde en France), la frontière est une donnée quotidienne gérée par des accords spécifiques, par **États, régions, communes, entreprises, associations, habitants** : le local pèse souvent plus que le national.\n\n**Conclusion** : la frontière sépare **et** crée de la ressource ; c'est l'**asymétrie** qui la rend vivante : sans différence, ni flux ni activité."}$exo$::jsonb),
  ('332f8093-06a0-56f5-9723-000b0452caad'::uuid, 1, 'redaction', $exo${"titre":"Schengen, Frontex, Dublin","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Pour chaque élément, donne sa date et ce qu'il fait : l'espace **Schengen**, **Frontex**, les accords de **Dublin**.\n2. Quelle différence juridique y a-t-il entre un **demandeur d'asile** et un **migrant économique** ?\n3. Sur quel texte repose le droit d'asile ?","bareme":[{"critere":"Schengen (1985, appliqué en 1995), Frontex (2004), Dublin (1990) avec leur rôle","points":10},{"critere":"Asile : droit individuel protégé par le droit international ; migrant économique : politiques nationales","points":6},{"critere":"Convention de Genève de 1951","points":4}],"dureeMin":7,"corrige":"1.\n- **Schengen** : **1985**, appliqué en **1995** ; il **supprime les contrôles aux frontières intérieures** (y compris pour quatre pays hors Union).\n- **Frontex** : **2004** ; agence européenne de garde-frontières, elle **appuie les États sur la frontière extérieure**.\n- **Dublin** : **1990**, révisés ; le **premier pays d'entrée** est responsable de l'examen d'une demande d'asile.\n2. Le **demandeur d'asile** sollicite une protection au titre d'un **droit individuel** garanti par le **droit international**. Le **migrant économique** relève des **politiques nationales d'immigration**. Les deux catégories se recouvrent dans les faits, **pas en droit**.\n3. La **convention de Genève de 1951**."}$exo$::jsonb),
  ('332f8093-06a0-56f5-9723-000b0452caad'::uuid, 2, 'redaction', $exo${"titre":"Qui examine la demande d'Amanuel ?","consigne":"Applique les règles du cours à la situation, puis explique la faille du système.","enonce":"**Situation (imaginaire).** Amanuel, 22 ans, fuit l'Érythrée en 2015. Il traverse la Méditerranée, débarque en Italie, puis rejoint son cousin en Allemagne, où il dépose une demande d'asile.\n\n1. Selon les accords de **Dublin**, quel pays est responsable de l'examen de sa demande ? Pourquoi ?\n2. Amanuel est-il un demandeur d'asile ou un migrant économique ? Sur quel fondement juridique ?\n3. Explique pourquoi la règle de Dublin fait peser la charge sur certains pays. Lesquels ?\n4. Pourquoi les mécanismes de répartition n'ont-ils jamais fonctionné durablement ? Quelle tentative de réponse a été adoptée en 2024 ?","bareme":[{"critere":"L'Italie, premier pays d'entrée","points":4},{"critere":"Demandeur d'asile, convention de Genève de 1951, droit individuel","points":4},{"critere":"Charge sur les pays d'entrée (Grèce, Italie, Espagne, Malte), du seul fait de la géographie","points":6},{"critere":"Désaccord politique sur la solidarité ; Pacte sur la migration et l'asile de 2024","points":6}],"dureeMin":12,"corrige":"1. L'**Italie** : selon Dublin, le **premier pays d'entrée** dans l'Union est responsable de l'examen de la demande, même si Amanuel la dépose en Allemagne.\n2. En demandant l'asile, Amanuel est un **demandeur d'asile** : il sollicite une protection fondée sur la **convention de Genève de 1951**, un **droit individuel** protégé par le droit international.\n3. La règle concentre les demandes sur les **pays d'entrée** — **Grèce, Italie, Espagne, Malte** — en raison de **leur seule position géographique** au bord de la Méditerranée. En 2015, plus d'un million de personnes arrivent, fuyant principalement la Syrie, l'Afghanistan et l'Érythrée.\n4. Ce n'est pas une difficulté technique mais un **désaccord politique** sur **ce que les États se doivent les uns aux autres** : la solidarité. Le **Pacte sur la migration et l'asile (2024)** tente de refonder l'équilibre entre **responsabilité des pays d'entrée** et **solidarité des autres**."}$exo$::jsonb),
  ('332f8093-06a0-56f5-9723-000b0452caad'::uuid, 3, 'redaction', $exo${"titre":"L'Union européenne face aux migrations","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Frontières internes, frontière externe : un dispositif européen qui organise et complique la question migratoire ? »\n\nTu présenteras le dispositif, sa faille, la crise de 2015 et ses suites, en veillant à ne pas confondre les catégories juridiques. Tu termineras par le coût humain et les débats qu'il suscite.","bareme":[{"critere":"Dispositif : Schengen, Frontex, Dublin, bases de données","points":4},{"critere":"Faille : charge sur les pays d'entrée, échec de la répartition, désaccord politique","points":4},{"critere":"Crise de 2015 et effets durables, Pacte de 2024","points":4},{"critere":"Distinction demandeur d'asile / migrant économique correctement faite","points":4},{"critere":"Coût humain en Méditerranée et débats (sauvetage, aide, externalisation)","points":4}],"dureeMin":18,"corrige":"**Introduction** : l'UE a supprimé ses frontières intérieures tout en construisant une frontière extérieure commune : cette combinaison organise et complique la question migratoire.\n\n**I. Le dispositif.** **Schengen** (1985, appliqué en 1995) supprime les contrôles intérieurs ; **Frontex** (2004) appuie les États sur la frontière extérieure ; **Dublin** (1990) rend le **premier pays d'entrée** responsable de la demande d'asile ; des **bases de données communes** enregistrent entrées et demandes.\n\n**II. La faille et la crise.** Dublin fait peser la charge sur les pays d'entrée (Grèce, Italie, Espagne, Malte) du seul fait de leur géographie. La **répartition** n'a jamais fonctionné durablement : c'est un **désaccord politique** sur la solidarité. En **2015**, plus d'un million d'arrivées (Syrie, Afghanistan, Érythrée) : contrôles intérieurs rétablis, accords avec des pays tiers pour retenir les départs, durcissement général de l'asile. Le **Pacte de 2024** cherche un nouvel équilibre responsabilité/solidarité.\n\n**III. Des catégories et un coût humain.** Le **demandeur d'asile** relève de la **convention de Genève de 1951** (droit individuel) ; le **migrant économique**, des **politiques nationales**. Elles se recouvrent dans les faits, pas en droit. La **Méditerranée** est la route la plus meurtrière du monde : plusieurs dizaines de milliers de disparus depuis 2014. Débats : opérations de **sauvetage**, **criminalisation de l'aide**, **externalisation** du contrôle vers des pays où les droits ne sont pas garantis.\n\n**Conclusion** : le dispositif organise la circulation mais concentre la charge ; sa réforme bute sur la solidarité entre États."}$exo$::jsonb),
  ('10d0d34b-991c-550a-8b67-6ca4f6aa0525'::uuid, 1, 'redaction', $exo${"titre":"De Gutenberg au Petit Journal","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Qui met au point l'imprimerie à caractères mobiles, et vers quelle date ?\n2. Cite les **trois premiers effets** de l'imprimerie présentés par le cours et explique-les.\n3. Associe chaque date à son événement : **1631**, **1789**, **1881**.","bareme":[{"critere":"Gutenberg, vers 1450","points":3},{"critere":"Réforme, censure, stabilisation des savoirs, expliquées","points":9},{"critere":"1631 Gazette de Renaudot ; 1789 libre communication des pensées ; 1881 loi sur la liberté de la presse","points":8}],"dureeMin":7,"corrige":"1. **Gutenberg**, **vers 1450**.\n2.\n- La **Réforme** : les thèses de Luther, traduites en allemand, circulent **en quelques semaines** dans tout l'Empire.\n- La **censure** : les pouvoirs réagissent par les privilèges d'impression, les autorisations préalables, l'index des livres interdits.\n- La **stabilisation des savoirs** : un texte imprimé est **identique partout**, ce qui rend possibles la comparaison, la critique et la science moderne.\n3.\n- **1631** : la **Gazette** de **Théophraste Renaudot**, hebdomadaire proche du pouvoir.\n- **1789** : la Déclaration proclame la **libre communication des pensées et des opinions** ; des centaines de titres paraissent.\n- **1881** : la **loi sur la liberté de la presse** supprime l'autorisation préalable ; elle est encore en vigueur."}$exo$::jsonb),
  ('10d0d34b-991c-550a-8b67-6ca4f6aa0525'::uuid, 2, 'redaction', $exo${"titre":"Le secret d'un journal à un sou","consigne":"Réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (imaginaire).** Paris, 1890. Un imprimeur explique à son neveu : « Notre quotidien se vend moins cher qu'il ne nous coûte, et pourtant nous gagnons de l'argent. Le matin, le train l'emporte dans toute la France ; les dépêches d'hier soir y sont déjà. »\n\n1. Comment le journal peut-il être vendu **en dessous de son coût** ?\n2. Cite les **cinq conditions** qui permettent, à la fin du XIXe siècle, l'essor d'une presse de masse, et ce que chacune apporte.\n3. Quelle conséquence ce modèle économique a-t-il sur le **contenu** des journaux ?","bareme":[{"critere":"Grâce à la publicité","points":4},{"critere":"Rotatives et papier bon marché, alphabétisation, chemin de fer, télégraphe, publicité","points":10},{"critere":"Dépendance à l'audience : fait divers, feuilleton, sensationnel","points":6}],"dureeMin":10,"corrige":"1. Grâce à la **publicité** : les annonceurs paient, ce qui permet de **vendre le journal en dessous de son coût**.\n2.\n- Les **rotatives** et le **papier bon marché** : le **tirage de masse**.\n- L'**alphabétisation** par les lois scolaires : le **lectorat**.\n- Le **chemin de fer** : la **diffusion** (« le train l'emporte »).\n- Le **télégraphe** : l'**information rapide** (« les dépêches d'hier soir »).\n- La **publicité** : vendre en dessous du coût.\n*Le Petit Journal* dépasse ainsi le million d'exemplaires.\n3. Un journal financé par la publicité **dépend de son audience** : il privilégie le **fait divers**, le **feuilleton** et le **sensationnel** autant que l'information."}$exo$::jsonb),
  ('10d0d34b-991c-550a-8b67-6ca4f6aa0525'::uuid, 3, 'redaction', $exo${"titre":"Quatre siècles d'écrit imprimé","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « De l'imprimerie à la presse à grand tirage : comment la circulation de l'écrit transforme-t-elle le rapport entre information et pouvoir (vers 1450 - fin du XIXe siècle) ? »\n\nTu organiseras ta réflexion autour des questions que pose le cours : qui **contrôle** la diffusion, qui la **finance**, comment un pouvoir tente de la **limiter**, et ce que change chaque **élargissement** du public.","bareme":[{"critere":"Imprimerie : changement d'échelle, Réforme, stabilisation des savoirs","points":4},{"critere":"Contrôle et censure : privilèges, autorisations, index, Gazette proche du pouvoir","points":4},{"critere":"Conquête de la liberté : 1789, régimes du XIXe, loi de 1881","points":4},{"critere":"Presse de masse : conditions, Petit Journal, publicité et dépendance à l'audience","points":5},{"critere":"Réponse organisée autour des quatre questions","points":3}],"dureeMin":18,"corrige":"**Introduction** : vers **1450**, l'imprimerie de **Gutenberg** change l'échelle de la circulation des idées : ce qu'un copiste mettait un an à produire s'imprime en centaines d'exemplaires.\n\n**I. Un pouvoir nouveau que les autorités veulent contrôler.** Les thèses de **Luther** circulent en quelques semaines : l'imprimé sert la **Réforme**. Il **stabilise les savoirs** (texte identique partout). Les pouvoirs répondent par la **censure** : privilèges d'impression, autorisations préalables, index. En **1631**, la **Gazette** de Renaudot est **proche du pouvoir** : contrôler, c'est aussi publier soi-même.\n\n**II. La conquête de la liberté.** En **1789**, la Déclaration proclame la libre communication des pensées ; des centaines de titres paraissent. Au XIXe siècle, la liberté est reprise et rendue selon les régimes. La loi de **1881** supprime l'autorisation préalable.\n\n**III. La presse de masse et la question du financement.** Rotatives, papier bon marché, alphabétisation, chemin de fer, télégraphe et publicité font de la presse le **premier média de masse** (*Le Petit Journal*, plus d'un million d'exemplaires) et le principal espace du débat public. Mais qui **finance** oriente : la publicité rend le journal dépendant de l'audience (fait divers, feuilleton, sensationnel).\n\n**Conclusion** : chaque **élargissement du public** accroît la puissance de l'écrit et renouvelle la question de son contrôle ; ces questions traversent tout le thème."}$exo$::jsonb),
  ('3dc7ee2e-2bd3-54a2-8c12-e641600a2c49'::uuid, 1, 'redaction', $exo${"titre":"La radio et la télévision en dates","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Cite trois **apports** de la radio par rapport à la presse écrite.\n2. Associe chaque date à son événement : **1933**, **1940**, **1981**, **1982**, **1987**.\n3. Que révèle le débat télévisé **Kennedy-Nixon** de 1960 ?","bareme":[{"critere":"Immédiateté, accès sans l'écrit, proximité","points":6},{"critere":"Cinq dates associées correctement","points":10},{"critere":"L'apparence à l'écran pèse plus que les arguments","points":4}],"dureeMin":7,"corrige":"1. L'**immédiateté** (l'information n'attend plus l'imprimerie) ; l'**accès sans l'écrit** (elle touche ceux que la presse n'atteignait pas, analphabètes compris) ; la **proximité** (une voix s'adresse à chacun).\n2.\n- **1933** : début des **causeries au coin du feu** de Roosevelt.\n- **1940** : l'**Appel du 18 juin** du général de Gaulle, et Radio Londres (1940-1944).\n- **1981** : les **radios libres** sont autorisées en France.\n- **1982** : fin du **monopole d'État** sur la télévision, création d'une autorité de régulation, autorisation des télévisions privées.\n- **1987** : **privatisation de TF1**.\n3. Que l'**apparence à l'écran pèse plus que les arguments**."}$exo$::jsonb),
  ('3dc7ee2e-2bd3-54a2-8c12-e641600a2c49'::uuid, 2, 'redaction', $exo${"titre":"Quatre moments télévisés","consigne":"Explique ce que chaque moment révèle, puis relie-les aux effets des médias de masse.","enonce":"**Document — Quatre moments de l'histoire de la télévision**\n\n- a. 1960 : débat Kennedy-Nixon.\n- b. Années 1960-1970 : la guerre du Vietnam entre dans les foyers.\n- c. 1989 : chute du mur de Berlin.\n- d. 1991 : guerre du Golfe.\n\n1. Pour chaque moment, explique ce qu'il révèle d'après le cours.\n2. Le cours cite quatre **effets** des médias de masse : simultanéité, personnalisation, format, concentration. Associe à chacun un des moments ci-dessus ou un exemple du cours, et explique.\n3. Pourquoi l'image a-t-elle une « force d'évidence » ? Quel danger le moment d révèle-t-il ?","bareme":[{"critere":"Quatre moments correctement expliqués","points":8},{"critere":"Quatre effets définis et illustrés","points":8},{"critere":"Ce qu'on voit paraît vrai ; image en direct la moins vérifiée","points":4}],"dureeMin":12,"corrige":"1.\n- **a** : l'**apparence** pèse plus que les arguments.\n- **b** : la **première guerre télévisée**.\n- **c** : un événement **suivi en direct**.\n- **d** : l'information devient un **flux permanent**, et l'image en direct s'impose **au moment où elle est le moins vérifiée**.\n2.\n- **Simultanéité** : un même événement vécu ensemble par des millions de personnes (**c**, la chute du Mur en direct).\n- **Personnalisation** : la vie politique se joue sur la **présence à l'écran** (**a**).\n- **Format** : temps de parole, formule, rythme imposent leurs contraintes au contenu (le flux continu de **d**).\n- **Concentration** : les médias de masse **coûtent cher**, d'où la question de la **propriété** et de l'**indépendance des rédactions** (en France, monopole d'État et ORTF au service du pouvoir jusqu'en 1982, puis privatisation de TF1 en 1987).\n3. L'image donne l'impression de voir directement : **ce qu'on voit paraît vrai**. La guerre du Golfe montre le danger : l'image en direct s'impose **avant toute vérification**."}$exo$::jsonb),
  ('3dc7ee2e-2bd3-54a2-8c12-e641600a2c49'::uuid, 3, 'redaction', $exo${"titre":"La voix, l'image et le pouvoir","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Au XXe siècle, la radio et la télévision ont-elles servi le pouvoir ou la liberté de l'information ? »\n\nTu montreras les usages politiques de la radio, le contrôle puis la libéralisation de l'audiovisuel en France, et les effets de la télévision sur l'information et la vie politique.","bareme":[{"critere":"Radio : apports et usages (Roosevelt, propagande totalitaire, Appel du 18 juin, Radio Londres)","points":5},{"critere":"Monopole d'État, ORTF, puis 1981-1982-1987","points":4},{"critere":"Télévision : force de l'image et moments clés","points":4},{"critere":"Effets : simultanéité, personnalisation, format, concentration","points":4},{"critere":"Conclusion nuancée : un même outil au service des deux","points":3}],"dureeMin":18,"corrige":"**Introduction** : au XXe siècle, l'information s'entend, puis se voit ; chaque support modifie le rapport au pouvoir.\n\n**I. La radio, outil de pouvoir et de liberté.** Dès les années 1920, elle apporte l'immédiateté, touche ceux que l'écrit n'atteignait pas, s'adresse à chacun. Les **causeries** de Roosevelt (à partir de 1933) ; la **propagande** totalitaire diffuse des postes à bas prix pour toucher chaque foyer ; mais aussi l'**Appel du 18 juin** et **Radio Londres** (1940-1944), voix de la liberté. En France, les **radios libres** ne sont autorisées qu'en **1981**.\n\n**II. La télévision, longtemps sous contrôle.** Généralisée dans les années 1960, elle ajoute l'**image** et sa force d'évidence. Jusqu'en **1982**, **monopole d'État** : le journal télévisé est contrôlé, l'ORTF sert le pouvoir. En 1982, autorité de régulation et télévisions privées ; en **1987**, privatisation de TF1.\n\n**III. Des effets profonds.** Kennedy-Nixon (1960) : l'apparence prime ; Vietnam : première guerre télévisée ; chute du Mur en direct ; guerre du Golfe (1991) : flux permanent, image la moins vérifiée. **Simultanéité**, **personnalisation** de la vie politique, contraintes du **format**, **concentration** qui pose la question de la propriété et de l'indépendance des rédactions.\n\n**Conclusion** : ces médias ont servi tour à tour le pouvoir et la liberté ; leur coût et la force de l'image font de leur propriété et de leur régulation un enjeu durable."}$exo$::jsonb),
  ('1dc8244c-1c84-5ca7-a8df-beed9c703000'::uuid, 1, 'redaction', $exo${"titre":"D'ARPANET au Web","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. De quel projet Internet est-il issu, et pourquoi le réseau a-t-il été conçu **décentralisé** ?\n2. Qui invente le **World Wide Web**, où et quand ? Quels sont ses trois éléments ?\n3. Définis : **bulle de filtres**, **infobésité**, **viralité**.","bareme":[{"critere":"ARPANET, projet de recherche militaire américain ; fonctionner si un nœud est détruit","points":5},{"critere":"Tim Berners-Lee, au CERN, 1989-1991 ; liens hypertextes, adresses, navigateur","points":6},{"critere":"Trois définitions justes","points":9}],"dureeMin":7,"corrige":"1. D'**ARPANET**, un **projet de recherche militaire américain** de la fin des années 1960 (premiers nœuds reliés en **1969**). Il est **décentralisé** pour **continuer de fonctionner si l'un de ses nœuds est détruit**.\n2. **Tim Berners-Lee**, au **CERN**, en **1989-1991** : **liens hypertextes**, **adresses**, **navigateur**.\n3.\n- **Bulle de filtres** (ou chambre d'écho) : on est surtout exposé à **ce qui confirme** ses convictions ; la contradiction se raréfie.\n- **Infobésité** : l'**abondance** d'informations rend **le tri plus difficile que la recherche**.\n- **Viralité** : ce qui circule est **ce qui fait réagir**, non ce qui est vérifié."}$exo$::jsonb),
  ('1dc8244c-1c84-5ca7-a8df-beed9c703000'::uuid, 2, 'redaction', $exo${"titre":"Le fil d'actualité de Maël","consigne":"Analyse la situation avec les notions du cours.","enonce":"**Situation (imaginaire).** Maël, 16 ans, s'informe uniquement par une application gratuite. Son fil lui montre surtout des vidéos qui vont dans le sens de ce qu'il pense déjà. Une rumeur sur un prétendu scandale y a été partagée des milliers de fois en une heure, avant d'être démentie le lendemain. Sa grand-mère, elle, n'a pas de smartphone ; son cousin en a un mais croit tout ce qu'il lit.\n\n1. Qui compose le fil de Maël ? Quel effet décrit par le cours reconnais-tu ?\n2. Pourquoi l'application est-elle gratuite ? Sur quoi repose son modèle ?\n3. Pourquoi la rumeur s'est-elle diffusée plus vite que le démenti ?\n4. La grand-mère et le cousin illustrent deux niveaux de **fracture numérique**. Lesquels ? Lequel est, selon le cours, la véritable fracture ?","bareme":[{"critere":"Individualisation, flux composé par l'algorithme ; bulle de filtres","points":5},{"critere":"Gratuité apparente financée par la publicité, l'attention et les données","points":5},{"critere":"Viralité : circule ce qui fait réagir, non ce qui est vérifié","points":4},{"critere":"Fracture matérielle (grand-mère) et cognitive (cousin), la seconde étant la véritable","points":6}],"dureeMin":12,"corrige":"1. Chacun compose son flux, mais c'est largement l'**algorithme** qui le compose pour lui (**individualisation**). Maël est dans une **bulle de filtres** (chambre d'écho) : il est surtout exposé à ce qui confirme ses convictions.\n2. C'est une **gratuité apparente** : le service est **financé par la publicité**, donc par l'**attention** et les **données** des utilisateurs.\n3. Par **viralité** : ce qui circule est **ce qui fait réagir**, non ce qui est vérifié. Le démenti, moins spectaculaire, circule moins. L'enjeu n'est plus l'accès à l'information mais sa **hiérarchisation** et sa **vérification**, que le lecteur doit en partie assurer lui-même.\n4. La grand-mère illustre la fracture **matérielle** (équipement, réseau, très inégaux selon l'âge, les revenus, les régions). Le cousin illustre la fracture **cognitive** : la **capacité à se servir du réseau de façon critique**. C'est **la seconde** qui constitue la véritable fracture."}$exo$::jsonb),
  ('1dc8244c-1c84-5ca7-a8df-beed9c703000'::uuid, 3, 'redaction', $exo${"titre":"Plus d'accès, moins d'information ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Internet a-t-il rendu l'information plus libre ou plus difficile à maîtriser ? »\n\nTu retraceras les grandes étapes du réseau, puis tu montreras ce qu'il change et les effets qu'il produit. Tu expliqueras en conclusion le « renversement décisif » décrit par le cours.","bareme":[{"critere":"Étapes : ARPANET 1969, TCP/IP, Web 1989-1991, web social, Internet mobile et plateformes","points":4},{"critere":"Apports : immédiateté, mondialisation, fin du monopole des médias","points":4},{"critere":"Individualisation, algorithme, gratuité apparente","points":3},{"critere":"Effets : bulle de filtres, infobésité, viralité, désinformation organisée","points":5},{"critere":"Renversement : de l'accès à la hiérarchisation et la vérification ; fracture cognitive","points":4}],"dureeMin":18,"corrige":"**Introduction** : né d'un réseau militaire, Internet est devenu l'espace public mondial.\n\n**I. D'un réseau militaire aux plateformes.** **ARPANET** (premiers nœuds en **1969**), réseau décentralisé ; protocoles **TCP/IP** et ouverture aux universités (années 1970-1980) ; **World Wide Web** de Tim Berners-Lee au CERN (**1989-1991**) ; ouverture au public et essor commercial (années 1990) ; **web social** où chacun produit (années 2000) ; **Internet mobile** et **plateformes** devenues points d'accès principaux (années 2010).\n\n**II. Une information plus libre.** **Immédiateté et mondialisation** ; **fin du monopole des médias** : n'importe qui peut publier, et des événements que des régimes voulaient cacher ont été documentés.\n\n**III. Une information plus difficile à maîtriser.** **Individualisation** : l'algorithme compose le flux. **Gratuité apparente** financée par la publicité, donc l'attention et les données. **Bulle de filtres**, **infobésité**, **viralité**, **désinformation organisée**, y compris des campagnes coordonnées par des États.\n\n**Conclusion** : le **renversement décisif** : l'enjeu n'est plus l'**accès**, devenu presque illimité, mais la **hiérarchisation** et la **vérification** ; ce que le journalisme apportait par sa fonction éditoriale doit en partie être assuré par le lecteur. D'où l'importance de la fracture **cognitive**, plus que matérielle."}$exo$::jsonb),
  ('84e3cf31-af07-5f97-a91b-d66c68789873'::uuid, 1, 'redaction', $exo${"titre":"L'affaire Dreyfus en dates","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"1. De quoi le capitaine **Alfred Dreyfus** est-il accusé en **1894**, et quel sort subit-il ?\n2. Que découvre le colonel **Picquart** en **1896** ?\n3. Que se passe-t-il le **13 janvier 1898** ? Donne le journal, l'auteur et le titre.\n4. Que se passe-t-il pour Dreyfus en **1899** puis en **1906** ?","bareme":[{"critere":"Accusé d'avoir livré des documents à l'Allemagne ; condamné, dégradé, déporté à l'île du Diable","points":5},{"critere":"Le véritable auteur du bordereau est Esterhazy","points":4},{"critere":"Zola publie « J'accuse… ! » dans L'Aurore","points":6},{"critere":"Grâce en 1899, réhabilitation et réintégration en 1906","points":5}],"dureeMin":7,"corrige":"1. Officier alsacien et juif, il est accusé d'avoir **livré des documents à l'Allemagne** ; condamné sur une pièce mince, il est **dégradé publiquement** et **déporté à l'île du Diable**.\n2. Que le véritable auteur du bordereau est le **commandant Esterhazy**.\n3. **Émile Zola** publie dans **L'Aurore**, à la une, une lettre ouverte au président de la République, **« J'accuse… ! »**, titre choisi par Clemenceau.\n4. En **1899**, Dreyfus est **gracié** ; en **1906**, il est **réhabilité** et **réintégré dans l'armée**."}$exo$::jsonb),
  ('84e3cf31-af07-5f97-a91b-d66c68789873'::uuid, 2, 'redaction', $exo${"titre":"La stratégie de Zola","consigne":"Explique la démarche de Zola et ce que l'affaire révèle, en t'appuyant sur le cours.","enonce":"**Document — Données sur « J'accuse… ! »**\n\n| Le fait | Le détail |\n| Date | 13 janvier 1898 |\n| Journal | L'Aurore |\n| Tirage du jour | 300 000 exemplaires |\n| Contexte | Esterhazy vient d'être acquitté |\n\n1. Pourquoi Zola **nomme-t-il** les responsables dans sa lettre, alors qu'il sait qu'il s'expose à un procès en diffamation ?\n2. Quelle a été l'issue pour Zola ?\n3. Montre que la presse a joué dans l'affaire un rôle dans **les deux sens**.\n4. Quel groupe social apparaît à cette occasion ? D'où vient le mot ?","bareme":[{"critere":"Provoquer un procès pour forcer un débat contradictoire public","points":6},{"critere":"Condamné, exil à Londres","points":3},{"critere":"L'Aurore contre La Libre Parole de Drumont : calomnie antisémite et fausses preuves","points":7},{"critere":"Les intellectuels, Manifeste des intellectuels de janvier 1898","points":4}],"dureeMin":11,"corrige":"1. Il **cherche** le procès : en nommant les responsables, il s'expose **sciemment** à la diffamation, car le procès **forcera un débat contradictoire public**, alors que l'état-major vient d'étouffer l'affaire en faisant acquitter Esterhazy.\n2. Zola est **condamné** et **s'exile à Londres**.\n3. La presse est une **puissance politique** : *L'Aurore* (300 000 exemplaires ce jour-là) impose un sujet, structure deux camps et fait basculer l'opinion. Mais elle est aussi le lieu de la **calomnie** : *La Libre Parole* de **Drumont** déverse un antisémitisme d'une violence extrême et **fabrique de fausses preuves**.\n4. Les **intellectuels** : le mot prend son sens actuel avec le **« Manifeste des intellectuels »** de janvier 1898."}$exo$::jsonb),
  ('84e3cf31-af07-5f97-a91b-d66c68789873'::uuid, 3, 'redaction', $exo${"titre":"La presse, puissance à double tranchant","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion) appuyé sur des faits précis.","enonce":"**Sujet.** « Que nous apprend l'affaire Dreyfus sur la liberté de la presse ? »\n\nTu rappelleras les faits, puis tu montreras le rôle de la presse dans les deux camps et ses effets sur la société française. Tu discuteras en conclusion l'idée du cours : la liberté de la presse « n'est pas un instrument neutre, mais elle est la condition pour que l'erreur puisse être corrigée ».","bareme":[{"critere":"Faits : 1894, 1896, acquittement d'Esterhazy en janvier 1898","points":4},{"critere":"« J'accuse… ! » et la stratégie du procès","points":4},{"critere":"Calomnie : La Libre Parole, antisémitisme, fausses preuves","points":4},{"critere":"Effets : intellectuels, France divisée, 1899, 1906, loi de 1905","points":4},{"critere":"Discussion de la conclusion du cours","points":4}],"dureeMin":18,"corrige":"**Introduction** : l'affaire Dreyfus montre la presse à son maximum de puissance, dans les deux sens.\n\n**I. Une erreur judiciaire étouffée.** En **1894**, Alfred Dreyfus, officier alsacien et juif, est condamné pour avoir livré des documents à l'Allemagne, sur une pièce mince ; dégradé, déporté à l'île du Diable. En **1896**, Picquart découvre que le coupable est **Esterhazy** ; en janvier **1898**, l'état-major le fait acquitter.\n\n**II. La presse qui démasque.** Le **13 janvier 1898**, Zola publie **« J'accuse… ! »** dans *L'Aurore* (300 000 exemplaires), nomme les responsables et cherche le procès pour obtenir un **débat contradictoire**. Condamné, il s'exile à Londres. Le « **Manifeste des intellectuels** » fait naître les intellectuels au sens actuel.\n\n**III. La presse qui calomnie.** *La Libre Parole* de **Drumont** diffuse un antisémitisme d'une violence extrême et fabrique de fausses preuves. La **France se divise** jusque dans les familles (dessin de Caran d'Ache, « ils en ont parlé »).\n\n**IV. L'issue.** Grâce en **1899**, réhabilitation et réintégration en **1906** ; l'affaire nourrit la **loi de séparation de 1905**.\n\n**Conclusion** : la **même liberté** a permis la campagne de calomnie **et** son démenti. Elle n'est pas neutre, mais sans elle, Zola n'aurait pu publier et l'erreur n'aurait pas été corrigée."}$exo$::jsonb),
  ('0a392ab1-c353-5406-a982-3f8b6b94ef86'::uuid, 1, 'redaction', $exo${"titre":"Les textes de la liberté d'information","consigne":"Complète le tableau puis réponds à la question.","enonce":"1. Recopie et complète le tableau.\n\n| La date | Le texte | Ce qu'il pose |\n| 1789 | … | … |\n| 1881 | … | … |\n| 1948 | … | … |\n| 1950 | … | … |\n\n2. Cite deux **compléments contemporains** qui protègent l'information et ce qu'ils protègent.","bareme":[{"critere":"1789 article 11 et 1881 loi sur la presse, avec leur contenu","points":8},{"critere":"1948 article 19 et 1950 article 10 de la CEDH, avec leur contenu","points":7},{"critere":"Deux compléments (sources, lanceurs d'alerte, accès aux documents, régulation)","points":5}],"dureeMin":8,"corrige":"1.\n- **1789** : Déclaration des droits de l'homme, **article 11** : « La libre communication des pensées et des opinions est un des droits les plus précieux de l'homme », sauf abus définis par la loi.\n- **1881** : **loi sur la liberté de la presse** : fin de l'**autorisation préalable** et du **cautionnement** ; responsabilité **a posteriori** devant les tribunaux, directeur de publication identifié.\n- **1948** : Déclaration universelle, **article 19** : chercher, recevoir et répandre les informations, **sans considération de frontières**.\n- **1950** : Convention européenne des droits de l'homme, **article 10** : un droit **justiciable devant une cour**.\n2. Deux parmi : la **protection des sources** (loi de 2010), sans laquelle personne ne parle à un journaliste ; le statut des **lanceurs d'alerte** (Europe, 2019), qui protège celui qui révèle de l'intérieur ; le **droit d'accès aux documents administratifs** (vérifiabilité de l'action publique) ; les autorités de **régulation** de l'audiovisuel et du numérique."}$exo$::jsonb),
  ('0a392ab1-c353-5406-a982-3f8b6b94ef86'::uuid, 2, 'redaction', $exo${"titre":"Publier ou non ?","consigne":"Pour chaque situation, identifie la limite ou la protection du cours qui s'applique et justifie.","enonce":"**Situations imaginaires**\n\n- **A.** Un site publie des photos d'une chanteuse prises à son insu chez elle.\n- **B.** Un journal révèle, grâce à une employée, qu'une entreprise pollue une rivière ; la police demande au journaliste le nom de l'employée.\n- **C.** Un blog appelle à attaquer les habitants d'un quartier en raison de leur origine.\n- **D.** Une entreprise attaque un journaliste d'investigation dans cinq procès successifs, qu'elle sait ne pas pouvoir gagner.\n- **E.** Un ministre veut interdire lui-même, par arrêté, un article qu'il juge « diffamatoire ».\n\n1. Pour chaque situation, nomme la limite légitime ou la protection en jeu et explique.\n2. Pourquoi, selon le cours, ces limites posent-elles une difficulté ?","bareme":[{"critere":"A : vie privée et droit à l'image ; C : incitation à la haine et à la violence","points":5},{"critere":"B : protection des sources et statut de lanceur d'alerte","points":4},{"critere":"D : procédure-bâillon","points":3},{"critere":"E : c'est au juge et non à l'administration de décider","points":4},{"critere":"Limites légitimes mais invoquées par les pouvoirs pour restreindre","points":4}],"dureeMin":12,"corrige":"1.\n- **A** : limite légitime de la **vie privée** et du **droit à l'image** : elle protège l'intimité.\n- **B** : **protection des sources** (loi de 2010) : le journaliste n'a pas à livrer le nom, car sans cette protection **personne ne parle à un journaliste** ; l'employée peut relever du statut de **lanceur d'alerte** (2019).\n- **C** : limite de l'**incitation à la haine et à la violence** : elle protège l'ordre public et les personnes visées.\n- **D** : **procédure-bâillon** : une action en justice destinée à **épuiser** un journaliste plutôt qu'à obtenir gain de cause.\n- **E** : la **diffamation** est une limite légitime, mais c'est au **juge**, et non à l'**administration**, d'en décider ; depuis 1881, la responsabilité s'apprécie **a posteriori** devant les tribunaux.\n2. Ces limites sont **légitimes**, mais ce sont **exactement celles qu'un pouvoir invoque quand il veut restreindre** ; d'où la nécessité que le juge décide."}$exo$::jsonb),
  ('0a392ab1-c353-5406-a982-3f8b6b94ef86'::uuid, 3, 'redaction', $exo${"titre":"Une liberté conquise et réversible","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « La liberté de l'information est-elle définitivement acquise ? »\n\nTu montreras comment elle a été conquise, quelles protections la complètent et quelles limites elle connaît. Tu t'appuieras sur l'état des lieux actuel pour discuter la phrase : « La liberté de l'information se mesure moins aux textes qu'à ce qu'il est effectivement possible de publier. »","bareme":[{"critere":"Étapes juridiques 1789, XIXe siècle, 1881, 1948, 1950","points":5},{"critere":"Compléments contemporains","points":3},{"critere":"Limites légitimes et rôle du juge","points":4},{"critere":"Procédés actuels de restriction : fausses nouvelles, bâillons, surveillance, concentration","points":5},{"critere":"Discussion de la phrase et conclusion","points":3}],"dureeMin":20,"corrige":"**Introduction** : la liberté de l'information n'a pas été donnée : elle a été conquise texte après texte, et reste réversible.\n\n**I. Une conquête lente.** **1789**, article 11 : libre communication des pensées, sauf abus définis par la loi. Au XIXe siècle, la liberté est accordée, retirée, restaurée (monarchie de Juillet et Second Empire la restreignent fortement). **1881** : fin de l'autorisation préalable et du cautionnement, responsabilité a posteriori. **1948**, article 19 (sans considération de frontières) ; **1950**, article 10 de la CEDH, droit justiciable. Compléments : protection des sources (2010), lanceurs d'alerte (2019), accès aux documents administratifs, régulation.\n\n**II. Des limites légitimes, mais ambiguës.** Diffamation et injure, incitation à la haine, vie privée, secret défense et de l'instruction, protection des mineurs. Ce sont exactement celles qu'un pouvoir invoque pour restreindre : c'est au **juge**, non à l'administration, d'en décider.\n\n**III. Une liberté menacée aujourd'hui.** Lois sur les « **fausses nouvelles** » utilisées contre l'opposition ; **procédures-bâillons** contre les journalistes d'investigation ; **surveillance** des communications, qui tarit les sources ; **concentration** des médias entre peu de propriétaires.\n\n**Conclusion** : les textes sont nécessaires mais ne suffisent pas ; la liberté réelle se mesure à **ce qu'il est effectivement possible de publier**. Elle n'est donc jamais définitivement acquise."}$exo$::jsonb),
  ('2ccd9285-da40-506f-91db-a2670cdb1779'::uuid, 1, 'redaction', $exo${"titre":"Propagande et censure au XXe siècle","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Qu'appelle-t-on le **« bourrage de crâne »** pendant la guerre de 1914-1918 ? Quelle conséquence a-t-il eue ?\n2. Cite **quatre procédés** de la propagande des régimes totalitaires.\n3. Sous l'Occupation, quels moyens d'information ont Vichy et l'occupant d'une part, la Résistance d'autre part ?","bareme":[{"critere":"Minimiser les pertes, ridiculiser l'ennemi, promettre la victoire ; défiance des combattants","points":6},{"critere":"Quatre procédés : ministère de la Propagande, monopole, culte du chef, réécriture du passé","points":8},{"critere":"Presse autorisée et Radio-Paris / presse clandestine et Radio Londres","points":6}],"dureeMin":8,"corrige":"1. Le **bourrage de crâne** : **minimiser les pertes**, **ridiculiser l'ennemi**, **promettre la victoire prochaine**. Il nourrit une **défiance durable des combattants envers la presse**.\n2. Un **ministère de la Propagande** qui coordonne presse, radio, cinéma et affiche ; le **monopole** de l'information (toute publication indépendante disparaît) ; le **culte du chef** (mise en scène des masses) ; la **réécriture du passé** (photographies retouchées, manuels réécrits).\n3. **Vichy et l'occupant** : la presse autorisée, contrôlée, et **Radio-Paris**, allemande. **La Résistance** : la **presse clandestine** (*Combat*, *Libération*, *Défense de la France*) et **Radio Londres**."}$exo$::jsonb),
  ('2ccd9285-da40-506f-91db-a2670cdb1779'::uuid, 2, 'redaction', $exo${"titre":"La photographie retouchée","consigne":"Analyse le document décrit, puis élargis avec le cours.","enonce":"**Document — Deux versions d'une même photographie (description d'un cas imaginaire inspiré de pratiques réelles)**\n\n> Sur la version de 1930, le dirigeant d'un régime totalitaire pose entouré de quatre compagnons. Sur la version publiée en 1938, dans un manuel scolaire, il n'en reste que deux : les deux autres, tombés en disgrâce, ont été effacés.\n\n1. Quel procédé de propagande ce document illustre-t-il ? Explique-le.\n2. Explique la formule qu'Orwell tire de ces pratiques dans *1984* : contrôler le passé, c'est contrôler l'avenir.\n3. Pendant la guerre froide, quels moyens permettent de contourner le contrôle de l'information à l'Est, et comment les régimes réagissent-ils ?\n4. En quoi le **Watergate** montre-t-il un autre rapport entre journalisme et pouvoir ?","bareme":[{"critere":"Réécriture du passé : disgraciés effacés des photographies et manuels","points":5},{"critere":"Formule d'Orwell expliquée : la propagande refait ce qui a eu lieu","points":5},{"critere":"Radios internationales, samizdats ; brouillage","points":5},{"critere":"Watergate : enquête du Washington Post, démission de Nixon, contre-pouvoir","points":5}],"dureeMin":12,"corrige":"1. La **réécriture du passé** : les régimes totalitaires **retouchent les photographies** pour faire disparaître les **disgraciés** et **réécrivent les manuels**.\n2. La propagande totalitaire **ne se contente pas de mentir sur le présent : elle refait ce qui a eu lieu**. Qui décide de ce qui s'est passé impose sa légitimité et oriente ce que les gens croiront et feront : **contrôler le passé, c'est contrôler l'avenir**.\n3. Les **radios internationales** émettent par-delà le **rideau de fer** ; les **samizdats** sont recopiés à la main et diffusés clandestinement. Les régimes de l'Est répondent par le **brouillage** systématique des émissions.\n4. Aux États-Unis, l'enquête du *Washington Post* sur le **Watergate** (1972-1974) mène à la **démission de Nixon** : le journalisme agit comme un **contre-pouvoir** face au plus haut sommet de l'État (comme avec les **Pentagon Papers** en 1971)."}$exo$::jsonb),
  ('2ccd9285-da40-506f-91db-a2670cdb1779'::uuid, 3, 'redaction', $exo${"titre":"Contrôler l'information au XXe siècle","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Au XXe siècle, l'information entre contrôle étatique et liberté. »\n\nTu montreras les formes du contrôle (guerre, totalitarisme, Occupation, guerre froide), puis les résistances et contre-pouvoirs. Tu expliqueras en conclusion pourquoi le cours invite à ne pas croire ces mécanismes « réservés au passé ».","bareme":[{"critere":"Propagande de guerre 1914-1918 et bourrage de crâne","points":3},{"critere":"Totalitarismes : quatre procédés et formule d'Orwell","points":5},{"critere":"Occupation : Vichy, Radio-Paris ; Résistance, presse clandestine, Radio Londres ; Libération","points":4},{"critere":"Guerre froide et contre-pouvoir journalistique (Pentagon Papers, Watergate)","points":4},{"critere":"Mécanismes actuels : censure, propriété, désinformation, surveillance","points":4}],"dureeMin":20,"corrige":"**Introduction** : le XXe siècle est celui des médias de masse, et donc de leur captation par les États.\n\n**I. Les formes du contrôle.** Dès **1914-1918** : censure préalable, bureaux de presse, images officielles, **bourrage de crâne**, qui nourrit la défiance des combattants. Les **totalitarismes** : ministère de la Propagande, monopole, culte du chef, **réécriture du passé** (photographies retouchées) ; Orwell : contrôler le passé, c'est contrôler l'avenir. Sous l'**Occupation**, presse autorisée et contrôlée, **Radio-Paris** allemande. Pendant la **guerre froide**, **brouillage** des radios occidentales à l'Est.\n\n**II. Résistances et contre-pouvoirs.** La **Résistance** : *Combat*, *Libération*, *Défense de la France*, **Radio Londres** ; à la Libération, les journaux compromis sont interdits et leurs biens transférés à des titres issus de la Résistance. À l'Est, les **samizdats**. Aux États-Unis, les **Pentagon Papers** (1971) publiés malgré le gouvernement, le **Watergate** (1972-1974) qui mène à la démission de Nixon.\n\n**Conclusion** : les formes ont changé, les **mécanismes demeurent** : censure directe, contrôle par la **propriété**, campagnes de **désinformation**, **surveillance**. Il faut savoir les reconnaître aujourd'hui."}$exo$::jsonb),
  ('8d788dd8-54b3-52c5-9fde-a04e5307cc41'::uuid, 1, 'redaction', $exo${"titre":"Deux glaives et un sacre","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Explique la **théorie des deux glaives** : domaine et détenteur de chacun. Quelle question reste ouverte ?\n2. Où le roi de France est-il **sacré** ? Que fait ce rite, et qu'impose-t-il en retour au roi ?\n3. Pourquoi le sacre de **Charlemagne** en 800 crée-t-il une **dépendance mutuelle** ?","bareme":[{"critere":"Spirituel (salut, Église) et temporel (gouvernement, princes) ; lequel prime","points":7},{"critere":"Reims ; roi par la grâce de Dieu ; protéger l'Église, rendre la justice, défendre les faibles","points":7},{"critere":"Légitimité tenue du pape, protection du pape tenue de l'empereur","points":6}],"dureeMin":8,"corrige":"1. Le glaive **spirituel** a pour domaine le **salut des âmes** et appartient à l'**Église** ; le glaive **temporel** a pour domaine le **gouvernement des hommes** et appartient aux **princes**. Reste à savoir **lequel prime** : les papes disent que le spirituel commande, les empereurs qu'ils tiennent leur pouvoir directement de Dieu.\n2. À **Reims**, oint de l'huile de la Sainte Ampoule. Le rite fait le roi **par la grâce de Dieu** : son pouvoir n'est plus seulement héréditaire ou militaire, il est **consacré**. En retour, il doit **protéger l'Église**, **rendre la justice**, **défendre les faibles**.\n3. Couronné par le pape **Léon III**, l'empereur **tient sa légitimité du pape** ; mais le pape **tient sa protection de l'empereur** : chacun a besoin de l'autre."}$exo$::jsonb),
  ('8d788dd8-54b3-52c5-9fde-a04e5307cc41'::uuid, 2, 'redaction', $exo${"titre":"Qui nomme les évêques ?","consigne":"Réponds en t'appuyant sur le cours et en citant les acteurs et les dates.","enonce":"1. Quelle est la question posée par la **querelle des Investitures** ? Pourquoi est-elle si importante ?\n2. Qui s'y affrontent ? Quel épisode célèbre en est resté ?\n3. Comment le **concordat de Worms** (1122) règle-t-il la question ?\n4. En France, qui finit par nommer les évêques, et par quel texte ? Comment appelle-t-on ce système ?","bareme":[{"critere":"Qui du pape ou de l'empereur nomme les évêques ; évêques aussi grands seigneurs temporels","points":6},{"critere":"Grégoire VII contre Henri IV ; Canossa","points":4},{"critere":"Investiture spirituelle par l'Église, temporelle par l'empereur","points":4},{"critere":"Le roi, par le concordat de Bologne (1516) ; gallicanisme","points":6}],"dureeMin":10,"corrige":"1. La question : **qui nomme les évêques, le pape ou l'empereur ?** Elle est capitale car les évêques sont aussi de **grands seigneurs temporels** : les nommer, c'est contrôler des terres et des hommes.\n2. Le pape **Grégoire VII** et l'empereur **Henri IV** ; l'épisode fameux est l'**humiliation de Canossa**.\n3. Le **concordat de Worms** partage : l'**investiture spirituelle** revient à l'**Église**, l'**investiture temporelle** à l'**empereur**.\n4. En France, le **roi** obtient la **nomination des évêques** par le **concordat de Bologne (1516)**. C'est le **gallicanisme** : une Église catholique, mais largement contrôlée par le pouvoir royal."}$exo$::jsonb),
  ('8d788dd8-54b3-52c5-9fde-a04e5307cc41'::uuid, 3, 'redaction', $exo${"titre":"Pouvoir et religion, distincts mais inséparables","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Au Moyen Âge, le pouvoir politique et le pouvoir religieux sont-ils séparés ? »\n\nTu montreras que les deux pouvoirs sont distincts en théorie, qu'ils s'appuient l'un sur l'autre et se disputent la primauté, puis que l'État royal français affirme progressivement son autorité sur l'Église. Tu expliqueras en conclusion pourquoi la séparation moderne est un « aboutissement » et non un « point de départ ».","bareme":[{"critere":"Deux glaives et question de la primauté","points":4},{"critere":"Dépendance mutuelle : sacre de Reims, Charlemagne en 800","points":4},{"critere":"Conflits : querelle des Investitures, Canossa, Worms 1122","points":4},{"critere":"Place de l'Église dans la société et montée de l'État royal (1303, 1438, 1516, gallicanisme)","points":5},{"critere":"Conclusion : séparation arrachée à des siècles d'imbrication","points":3}],"dureeMin":18,"corrige":"**Introduction** : dans l'Occident médiéval, pouvoirs politique et religieux sont **distincts mais inséparables**.\n\n**I. Deux pouvoirs distincts.** La théorie des **deux glaives** : le **spirituel** (salut des âmes, l'Église) et le **temporel** (gouvernement des hommes, les princes). Mais lequel prime ? Les papes disent le spirituel, les empereurs qu'ils tiennent leur pouvoir de Dieu.\n\n**II. Imbriqués et rivaux.** Le **sacre** à Reims fait le roi **par la grâce de Dieu**, en échange de devoirs (protéger l'Église, rendre la justice, défendre les faibles). Le sacre de **Charlemagne (800)** par Léon III inaugure la dépendance mutuelle. La **querelle des Investitures** oppose Grégoire VII à Henri IV (Canossa) ; le **concordat de Worms (1122)** partage l'investiture. L'Église encadre la société : baptême, mariage, funérailles, calendrier et cloches, enseignement et universités, hôpitaux, et dispose de sa **justice** et de la **dîme**.\n\n**III. L'affirmation de l'État royal.** Au XIIIe siècle, le roi est « **empereur en son royaume** » ; en **1303**, Philippe le Bel fait arrêter Boniface VIII ; **1438**, Pragmatique Sanction de Bourges ; **1516**, concordat de Bologne : le roi nomme les évêques. C'est le **gallicanisme**.\n\n**Conclusion** : non, ils ne sont pas séparés : ils sont distincts, imbriqués et rivaux. La séparation moderne est un **aboutissement**, arraché à des siècles d'imbrication."}$exo$::jsonb),
  ('eea5f740-409f-5eac-8f7f-26f9913398a0'::uuid, 1, 'redaction', $exo${"titre":"Les réformes d'Atatürk","consigne":"Associe chaque date à sa réforme, puis réponds aux questions.","enonce":"1. Associe chaque date à la réforme correspondante et explique-la en une phrase : **1923**, **1924**, **1926**, **1928**, **1934**, **1937**.\n2. Qu'est-ce que le **Diyanet** ? Quel est son rôle ?","bareme":[{"critere":"Six dates associées et expliquées correctement","points":14},{"critere":"Diyanet : nomme les imams, rédige les prêches, gère les mosquées","points":6}],"dureeMin":8,"corrige":"1.\n- **1923** : Mustafa Kemal, dit **Atatürk**, proclame la **République**.\n- **1924** : **abolition du califat**, fermeture des écoles coraniques, création du **Diyanet**.\n- **1926** : **code civil inspiré du code suisse** : mariage civil, interdiction de la polygamie, égalité successorale.\n- **1928** : l'**alphabet latin** remplace l'arabe, ce qui coupe d'un coup l'accès aux textes anciens.\n- **1934** : **droit de vote et d'éligibilité des femmes**, avant plusieurs pays européens.\n- **1937** : la **laïcité** est inscrite dans la **Constitution**.\n2. Le **Diyanet** est l'institution d'État qui administre la religion : il **nomme les imams**, **rédige les prêches** et **gère les mosquées**."}$exo$::jsonb),
  ('eea5f740-409f-5eac-8f7f-26f9913398a0'::uuid, 2, 'redaction', $exo${"titre":"Laïcité turque, laïcité française","consigne":"Lis l'échange imaginaire, corrige-le et explique la différence entre les deux modèles.","enonce":"**Document — Échange entre deux élèves (imaginaire)**\n\n> **Hugo** : « La Turquie d'Atatürk a fait exactement comme la France de 1905 : elle a séparé l'État et la religion. »\n> **Selin** : « Oui, et depuis, la laïcité turque n'a jamais bougé. »\n\n1. Pourquoi l'affirmation de Hugo est-elle inexacte ? Explique ce que fait le modèle kémaliste et donne un exemple institutionnel.\n2. Pourquoi l'affirmation de Selin est-elle fausse ? Appuie-toi sur au moins trois faits datés.\n3. Quel rôle l'**armée** a-t-elle joué dans l'histoire de la laïcité turque ?","bareme":[{"critere":"Le kémalisme ne sépare pas mais contrôle la religion par l'État (Diyanet)","points":7},{"critere":"Évolutions : AKP depuis 2002, levée de l'interdiction du foulard, 2016, Sainte-Sophie 2020","points":7},{"critere":"Armée garante de l'héritage kémaliste : 1960, 1971, 1980, 1997","points":6}],"dureeMin":12,"corrige":"1. Le modèle kémaliste **ne sépare pas** l'État et la religion : il la **contrôle par l'État**. Le **Diyanet**, créé en 1924, **nomme les imams, rédige les prêches et gère les mosquées**. En France, depuis 1905, l'État **ne reconnaît, ne salarie ni ne subventionne aucun culte** : c'est la différence décisive.\n2. La laïcité turque a beaucoup évolué :\n- depuis **2002**, l'**AKP**, parti conservateur d'inspiration islamique, gouverne durablement ; place croissante du religieux dans l'espace public et l'enseignement, **levée de l'interdiction du foulard** ;\n- en **2016**, après la tentative de coup d'État, le **pouvoir de l'armée est fortement réduit** ;\n- en **2020**, **Sainte-Sophie est reconvertie en mosquée**.\n3. L'armée s'est longtemps considérée comme **garante de l'héritage kémaliste** : elle est intervenue en **1960**, **1971**, **1980**, et par un « **coup d'État postmoderne** » en **1997**, contre des gouvernements jugés trop religieux."}$exo$::jsonb),
  ('eea5f740-409f-5eac-8f7f-26f9913398a0'::uuid, 3, 'redaction', $exo${"titre":"Une sécularisation imposée d'en haut","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « La Turquie, une sécularisation autoritaire et réversible ? »\n\nTu partiras de la situation de l'Empire ottoman, puis tu présenteras les réformes kémalistes et la nature du modèle, avant d'étudier le tournant contemporain. En conclusion, tu montreras ce que ce cas apprend sur la comparaison entre modèles de sécularisation.","bareme":[{"critere":"Point de départ : sultan-calife, loi religieuse, régime du millet","points":4},{"critere":"Réformes kémalistes datées (1923 à 1937)","points":5},{"critere":"Nature du modèle : contrôle et non séparation ; différence avec la France","points":4},{"critere":"Armée gardienne puis tournant (AKP, 2016, 2020)","points":4},{"critere":"Conclusion : sécularisation ni linéaire ni irréversible, préciser le modèle comparé","points":3}],"dureeMin":20,"corrige":"**Introduction** : la Turquie offre le cas d'une sécularisation **autoritaire**, décidée d'en haut en quelques années, puis remise en cause ; un contrepoint au modèle français.\n\n**I. Le point de départ ottoman.** Le sultan est aussi **calife**, chef spirituel des musulmans sunnites ; la **loi religieuse** régit le statut personnel (mariage, héritage, filiation) ; le **millet** donne aux communautés non musulmanes une autonomie juridique, dans une position subordonnée.\n\n**II. Les réformes kémalistes.** République (**1923**) ; abolition du **califat**, fermeture des écoles coraniques, création du **Diyanet** (**1924**) ; **code civil** inspiré du code suisse (**1926**) ; **alphabet latin** (**1928**) ; calendrier grégorien, réforme vestimentaire, dissolution des confréries ; vote des femmes (**1934**) ; **laïcité** dans la Constitution (**1937**). Mais le modèle **contrôle** la religion au lieu de la séparer : le Diyanet nomme les imams et rédige les prêches. L'**armée**, gardienne du régime, intervient en 1960, 1971, 1980 et 1997.\n\n**III. Un modèle remis en cause.** Depuis **2002**, l'AKP gouverne : religieux plus présent dans l'espace public et l'enseignement, levée de l'interdiction du foulard. Après **2016**, l'armée perd son pouvoir. En **2020**, Sainte-Sophie redevient mosquée.\n\n**Conclusion** : la sécularisation **n'est ni linéaire ni irréversible** et prend des formes très différentes (séparation, contrôle étatique, religion d'État, neutralité bienveillante) : comparer suppose de préciser **de quel modèle** on parle."}$exo$::jsonb),
  ('f5d38137-c0d3-56c0-97e8-e9a143bad32f'::uuid, 1, 'redaction', $exo${"titre":"Quatre modèles de relation","consigne":"Complète le tableau, puis réponds aux questions.","enonce":"1. Recopie et complète le tableau des modèles de relation entre États et religions.\n\n| Le modèle | Son principe | Un exemple |\n| Séparation | … | … |\n| Religion d'État | … | … |\n| Reconnaissance de cultes | … | … |\n| Contrôle étatique | … | … |\n\n2. Définis la **liberté de conscience**.\n3. Quels textes internationaux la garantissent ?","bareme":[{"critere":"Quatre modèles avec principe et exemple justes","points":12},{"critere":"Croire, ne pas croire, changer de conviction et le manifester","points":4},{"critere":"Article 18 de la Déclaration de 1948, article 9 de la CEDH","points":4}],"dureeMin":8,"corrige":"1.\n- **Séparation** : l'État **ne reconnaît, ne salarie ni ne subventionne aucun culte**, mais en garantit le libre exercice ; la **France depuis 1905** (les États-Unis, d'un autre type).\n- **Religion d'État** : un **culte officiel** ; le **Royaume-Uni** (le souverain gouverne l'Église anglicane), le Danemark, les États du Golfe.\n- **Reconnaissance de cultes** : l'État **organise et finance** ; l'**Allemagne** (impôt d'Église collecté par l'État), le régime concordataire d'**Alsace-Moselle**.\n- **Contrôle étatique** : l'État **administre le religieux** ; la **Turquie kémaliste**, la **Chine**.\n2. La liberté de conscience est le droit de **croire**, de **ne pas croire**, de **changer de conviction** et de **le manifester**.\n3. L'**article 18** de la Déclaration universelle de **1948** et l'**article 9** de la **Convention européenne des droits de l'homme**."}$exo$::jsonb),
  ('f5d38137-c0d3-56c0-97e8-e9a143bad32f'::uuid, 2, 'redaction', $exo${"titre":"Neutralité de l'agent, liberté de l'usager","consigne":"Applique les règles de la laïcité française à chaque situation et justifie.","enonce":"**Situations imaginaires (en France)**\n\n- **A.** Au guichet d'une mairie, un agent porte un signe religieux visible pendant son service.\n- **B.** Une personne qui vient chercher un passeport dans cette mairie porte un signe religieux.\n- **C.** Une commune veut verser un salaire au responsable d'un lieu de culte de la ville.\n- **D.** À Strasbourg, des ministres du culte sont rémunérés dans le cadre d'un régime particulier.\n\n1. Pour chaque situation, dis si elle est conforme au cadre du cours et justifie.\n2. Explique pourquoi la laïcité française n'est « ni l'effacement du religieux ni son hostilité ».","bareme":[{"critere":"A non conforme : l'agent public est tenu à la neutralité","points":4},{"critere":"B conforme : l'usager est libre de manifester ses convictions, sous réserve de l'ordre public","points":4},{"critere":"C non conforme : la loi de 1905 interdit de salarier un culte","points":4},{"critere":"D : régime concordataire d'Alsace-Moselle","points":3},{"critere":"Neutralité de l'État qui garantit la liberté de tous","points":5}],"dureeMin":11,"corrige":"1.\n- **A** : **non conforme**. L'**agent public** est tenu à la **neutralité** dans l'exercice de ses fonctions.\n- **B** : **conforme**. L'**usager** est **libre de manifester ses convictions** dans l'espace public, **sous réserve de l'ordre public**.\n- **C** : **non conforme**. Depuis **1905**, la République **ne reconnaît, ne salarie ni ne subventionne aucun culte**.\n- **D** : **conforme** à un régime particulier : l'**Alsace-Moselle** relève du **régime concordataire** (modèle de reconnaissance de cultes), qui subsiste.\n2. La laïcité française ne vise pas à faire disparaître les religions ni à les combattre : c'est la **neutralité de l'État** qui **garantit la liberté de tous**. L'État ne favorise aucun culte, mais garantit leur **libre exercice** et la liberté de chacun de croire ou de ne pas croire."}$exo$::jsonb),
  ('f5d38137-c0d3-56c0-97e8-e9a143bad32f'::uuid, 3, 'redaction', $exo${"titre":"Le religieux, marqueur ou cause des conflits ?","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion).","enonce":"**Sujet.** « Liberté de conscience et enjeux géopolitiques : la religion est-elle la cause des conflits où elle apparaît ? »\n\nTu présenteras la liberté de conscience et sa protection, la diversité des modèles de relation entre États et religions, puis les enjeux géopolitiques du religieux. Tu expliqueras le « piège à éviter » décrit par le cours.","bareme":[{"critere":"Liberté de conscience définie ; articles 18 et 9, droit d'en changer refusé dans plusieurs États","points":4},{"critere":"Quatre modèles avec exemples","points":4},{"critere":"Enjeux : conflits, minorités persécutées, acteurs transnationaux, ressource identitaire","points":5},{"critere":"Piège : la religion comme marqueur mobilisé sur des enjeux de terre, pouvoir, ressources, mémoire","points":5},{"critere":"Conclusion qui répond au sujet","points":2}],"dureeMin":18,"corrige":"**Introduction** : la liberté de conscience est le droit de croire, de ne pas croire, de changer de conviction et de le manifester.\n\n**I. Une liberté garantie, inégalement.** L'**article 18** de la Déclaration de 1948 et l'**article 9** de la CEDH la garantissent, **y compris le droit de changer de religion**, qui reste refusé dans plusieurs États. Sa mise en œuvre dépend des modèles : **séparation** (France depuis 1905 ; États-Unis, sans religion d'État mais avec une forte visibilité du religieux), **religion d'État** (Royaume-Uni, Danemark, États du Golfe), **reconnaissance de cultes** (Allemagne, Alsace-Moselle), **contrôle étatique** (Turquie kémaliste, Chine).\n\n**II. Les enjeux géopolitiques du religieux.** Des **conflits** où l'appartenance religieuse recoupe des enjeux territoriaux (Proche-Orient, Balkans, Cachemire, Sahel) ; des **minorités persécutées** sur plusieurs continents ; des **acteurs transnationaux** (le **Saint-Siège**, sujet de droit international ; l'Organisation de la coopération islamique ; des mouvements mondialisés) ; le religieux comme **ressource identitaire** instrumentalisée par des pouvoirs en quête de légitimité.\n\n**III. Le piège à éviter.** Lire un conflit comme **purement religieux** est presque toujours une erreur : la religion y est le plus souvent un **marqueur d'identité** mobilisé sur des enjeux de **terre**, de **pouvoir**, de **ressources** ou de **mémoire**.\n\n**Conclusion** : la religion est rarement la cause unique ; il faut **démêler** ces dimensions plutôt que de les confondre."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
